import React, { useState, ChangeEvent } from 'react';
import { Staff } from '../../types';
import { UserCircleIcon, CheckCircleIcon, UploadIcon } from '../../components/icons/DummyIcons';
import { LoaderIcon } from '../../components/icons/LoaderIcon';
import { PhoneInput } from '../../components/ui/PhoneInput';
import { EmailInput } from '../../components/ui/EmailInput';
import { useAuth } from '../../context/AuthContext';
import { uploadFile } from '../../services/storageService';

interface ProfileSettingsProps {
    currentStaff: Staff;
    onUpdateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
}

export const ProfileSettings: React.FC<ProfileSettingsProps> = ({ currentStaff, onUpdateStaff }) => {
    const { updateCurrentUser } = useAuth();
    const [profileData, setProfileData] = useState({ 
        fullName: currentStaff.fullName, 
        email: currentStaff.email, 
        phone: currentStaff.phone || '' 
    });
    const [profilePhotoPreview, setProfilePhotoPreview] = useState<string | null>(currentStaff.photo || null);
    const [profileSaveStatus, setProfileSaveStatus] = useState<'idle' | 'saving' | 'success' | 'error'>('idle');
    const [profileSaveMessage, setProfileSaveMessage] = useState('');

    const handleProfileFormChange = (e: ChangeEvent<HTMLInputElement>) => {
        setProfileData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleProfilePhotoChange = async (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            try {
                const url = await uploadFile(file, `staff/${currentStaff.id}/profile/${file.name}`);
                await onUpdateStaff(currentStaff.id, { photo: url });
                updateCurrentUser({ photo: url });
                setProfilePhotoPreview(url); 
            } catch (error) {
                alert("Failed to upload photo.");
            }
        }
    };

    const handleSaveProfile = async () => {
        setProfileSaveStatus('saving');
        try {
            await onUpdateStaff(currentStaff.id, profileData);
            updateCurrentUser(profileData);
            setProfileSaveStatus('success');
            setProfileSaveMessage('Profile updated!');
            setTimeout(() => setProfileSaveStatus('idle'), 3000);
        } catch (error) {
            setProfileSaveStatus('error');
        }
    };

    return (
        <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
            <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Edit Your Profile</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
                <div className="md:col-span-1 flex flex-col items-center">
                    {profilePhotoPreview ? (
                        <img src={profilePhotoPreview} alt="Profile" className="w-32 h-32 rounded-full object-cover mb-4 border-4 border-gray-100 dark:border-gray-700 shadow-sm" />
                    ) : (
                        <div className="w-32 h-32 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center mb-4 border-4 border-gray-100 dark:border-gray-700"><UserCircleIcon className="w-20 h-20 text-gray-400 dark:text-gray-500" /></div>
                    )}
                    <label htmlFor="photo-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors">
                        Change Photo
                        <input id="photo-upload" name="photo" type="file" className="sr-only" onChange={handleProfilePhotoChange} accept="image/*" />
                    </label>
                </div>
                <div className="md:col-span-2 space-y-4">
                    <div>
                        <label className="text-gray-700 dark:text-gray-300 font-medium">Full Name</label>
                        <input type="text" name="fullName" value={profileData.fullName} onChange={handleProfileFormChange} className="w-full mt-1 p-2.5 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 transition-all outline-none" />
                    </div>
                        <div>
                        <EmailInput label="Email" name="email" value={profileData.email} onChange={(val) => setProfileData(prev => ({...prev, email: val}))} />
                    </div>
                        <div>
                        <PhoneInput label="Phone" name="phone" value={profileData.phone} onChange={(val) => setProfileData(prev => ({...prev, phone: val}))} />
                    </div>
                    <div className="flex justify-end items-center gap-3 mt-4 pt-4 border-t dark:border-gray-700">
                        {profileSaveMessage && <span className="text-sm font-medium text-green-600 dark:text-green-400 flex items-center gap-1"><CheckCircleIcon className="w-4 h-4" /> {profileSaveMessage}</span>}
                        <button onClick={handleSaveProfile} disabled={profileSaveStatus === 'saving'} className="flex items-center gap-2 bg-blue-600 text-white font-bold py-2.5 px-6 rounded-lg hover:bg-blue-700 shadow-md active:scale-95 transition-all disabled:opacity-50">
                            {profileSaveStatus === 'saving' && <LoaderIcon className="w-4 h-4 animate-spin" />} Update Profile
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { CompanySettings as CompanySettingsType } from '../../types';
import { PhotoIcon, UploadIcon } from '../../components/icons/DummyIcons';
import { LoaderIcon } from '../../components/icons/LoaderIcon';
import { uploadFile } from '../../services/storageService';

interface CompanySettingsProps {
    companySettings: CompanySettingsType;
    setCompanySettings: (value: React.SetStateAction<CompanySettingsType>) => Promise<void>;
}

export const CompanySettings: React.FC<CompanySettingsProps> = ({ companySettings, setCompanySettings }) => {
    const [companyData, setCompanyData] = useState({ name: companySettings.name });
    const [appLogoLightPreview, setAppLogoLightPreview] = useState<string | null>(companySettings.appLogoLight || null);
    const [appLogoDarkPreview, setAppLogoDarkPreview] = useState<string | null>(companySettings.appLogoDark || null);
    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'success' | 'error'>('idle');

    const handleLogoUpload = async (file: File, type: keyof CompanySettingsType, previewSetter: React.Dispatch<React.SetStateAction<string | null>>) => {
        try {
            const url = await uploadFile(file, `system/branding/${type}/${file.name}`);
            setCompanySettings(prev => ({ ...prev, [type]: url }));
            const reader = new FileReader();
            reader.onloadend = () => previewSetter(reader.result as string);
            reader.readAsDataURL(file);
        } catch (error) {
            alert(`Failed to upload logo.`);
        }
    };

    const handleSaveCompanySettings = async () => {
        setSaveStatus('saving');
        try {
            await setCompanySettings(prev => ({ ...prev, name: companyData.name }));
            setSaveStatus('success');
            setTimeout(() => setSaveStatus('idle'), 3000);
        } catch (error) {
            setSaveStatus('error');
        }
    };

    return (
        <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
            <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Company Profile</h2>
            <div className="space-y-6">
                <div>
                    <label className="text-gray-700 dark:text-gray-300 font-semibold">Application Name</label>
                    <input type="text" value={companyData.name} onChange={e => setCompanyData({name: e.target.value})} className="w-full mt-1 p-2.5 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="text-gray-700 dark:text-gray-300 font-semibold">App Logo (Light)</label>
                        <div className="flex items-center gap-4 mt-2">
                            <div className="w-16 h-16 border rounded-lg p-2 bg-gray-50 dark:bg-gray-900 flex items-center justify-center overflow-hidden">
                                {appLogoLightPreview ? <img src={appLogoLightPreview} className="max-h-full max-w-full object-contain" alt="App Logo Light" /> : <PhotoIcon className="w-8 h-8 text-gray-300" />}
                            </div>
                            <label className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border rounded-lg text-sm hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors flex items-center gap-2">
                                <UploadIcon className="w-4 h-4"/> Upload
                                <input type="file" className="sr-only" onChange={(e) => e.target.files?.[0] && handleLogoUpload(e.target.files[0], 'appLogoLight', setAppLogoLightPreview)} />
                            </label>
                        </div>
                    </div>
                    <div>
                        <label className="text-gray-700 dark:text-gray-300 font-semibold">App Logo (Dark)</label>
                        <div className="flex items-center gap-4 mt-2">
                            <div className="w-16 h-16 border rounded-lg p-2 bg-gray-900 flex items-center justify-center overflow-hidden">
                                {appLogoDarkPreview ? <img src={appLogoDarkPreview} className="max-h-full max-w-full object-contain" alt="App Logo Dark" /> : <PhotoIcon className="w-8 h-8 text-gray-300" />}
                            </div>
                            <label className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border rounded-lg text-sm hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors flex items-center gap-2">
                                <UploadIcon className="w-4 h-4"/> Upload
                                <input type="file" className="sr-only" onChange={(e) => e.target.files?.[0] && handleLogoUpload(e.target.files[0], 'appLogoDark', setAppLogoDarkPreview)} />
                            </label>
                        </div>
                    </div>
                </div>
                <div className="flex justify-end pt-4 gap-3 border-t dark:border-gray-700">
                    <button onClick={handleSaveCompanySettings} disabled={saveStatus === 'saving'} className="flex items-center gap-2 bg-blue-600 text-white font-bold py-2.5 px-6 rounded-lg hover:bg-blue-700 shadow-md transition-all active:scale-95 disabled:opacity-50">
                        {saveStatus === 'saving' && <LoaderIcon className="w-4 h-4 animate-spin" />} Save System Branding
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Role, Staff, AppModuleName } from '../../types';
import { APP_MODULES } from '../../data/mockData';
import { PlusCircleIcon, ShieldCheckIcon, XMarkIcon } from '../../components/icons/DummyIcons';
import { usePermissions } from '../../context/DataContext';

interface RolesManagerProps {
    roles: Role[];
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    staff: Staff[];
}

export const RolesManager: React.FC<RolesManagerProps> = ({ roles, setRoles, staff }) => {
    const { rolePermissions, updateRolePermission, initRolePermissions } = usePermissions();
    const [selectedRole, setSelectedRole] = useState<Role | null>(roles[0] || null);
    const [isRoleModalOpen, setRoleModalOpen] = useState(false);
    const [editingRole, setEditingRole] = useState<Role | null>(null);
    const [newRoleData, setNewRoleData] = useState({ name: '', description: '' });

    const handlePermissionChange = async (moduleId: AppModuleName, permission: string, value: boolean) => {
        if (!selectedRole) return;
        await updateRolePermission(selectedRole.id, moduleId, permission, value);
    };

    const handleSaveRole = async (e: React.FormEvent) => {
        e.preventDefault();
        const roleData = newRoleData;
        if (editingRole) {
            setRoles(prev => prev.map(r => r.id === editingRole.id ? { ...editingRole, ...roleData } : r));
        } else {
            const newRoleId = roleData.name;
            const newRole: Role = { id: newRoleId, ...roleData };
            setRoles(prev => [...prev, newRole]); 
            await initRolePermissions(newRoleId);
        }
        setRoleModalOpen(false);
        setEditingRole(null);
        setNewRoleData({ name: '', description: '' });
    };

    // Removed unused handleDeleteRole or implemented if needed in UI (currently not in rendered JSX of original)

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-1 bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center mb-4">
                    <h2 className="font-bold text-lg text-gray-800 dark:text-white">Roles</h2>
                    <button onClick={() => { setEditingRole(null); setRoleModalOpen(true); }} className="text-sm font-bold text-blue-600 hover:text-blue-800 flex items-center gap-1 transition-colors">
                        <PlusCircleIcon className="w-4 h-4" /> New Role
                    </button>
                </div>
                <div className="space-y-2">
                    {roles.map(role => (
                        <button key={role.id} onClick={() => setSelectedRole(role)} className={`w-full text-left p-3 rounded-xl transition-all ${selectedRole?.id === role.id ? 'bg-blue-600 text-white shadow-lg' : 'hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-300'}`}>
                            <h3 className={`font-bold ${selectedRole?.id === role.id ? 'text-white' : 'text-gray-900 dark:text-white'}`}>{role.name}</h3>
                            <p className={`text-xs ${selectedRole?.id === role.id ? 'text-blue-100' : 'text-gray-500'}`}>{role.description}</p>
                        </button>
                    ))}
                </div>
            </div>
            <div className="lg:col-span-2 bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                {selectedRole ? (
                    <div>
                        <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4 border-b pb-4">{selectedRole.name} Module Access Control</h2>
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="text-left text-gray-400 font-bold uppercase text-[10px] tracking-widest">
                                    <th className="py-3">Module Name</th><th className="text-center">View</th><th className="text-center">Create</th><th className="text-center">Edit</th><th className="text-center">Delete</th><th className="text-center">Approve</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                {APP_MODULES.map(module => {
                                    const permissions = rolePermissions.find(rp => rp.roleId === selectedRole.id && rp.moduleId === module.id)?.permissions || { view: false, create: false, edit: false, delete: false, approve: false };
                                    return (
                                        <tr key={module.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/20 transition-colors">
                                            <td className="py-4 font-bold text-gray-700 dark:text-gray-200">{module.name}</td>
                                            {['view', 'create', 'edit', 'delete', 'approve'].map((key) => (
                                                <td key={key} className="text-center py-2">
                                                    <input type="checkbox" className="form-checkbox h-4.5 w-4.5 rounded text-blue-600 bg-gray-100 border-gray-300 focus:ring-blue-500 cursor-pointer"
                                                        checked={permissions[key as keyof typeof permissions]}
                                                        onChange={(e) => handlePermissionChange(module.id as AppModuleName, key, e.target.checked)} />
                                                </td>
                                            ))}
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="text-center py-20 text-gray-400 opacity-50 flex flex-col items-center">
                        <ShieldCheckIcon className="w-16 h-16 mb-2" />
                        <p className="font-bold">Select a role to manage access permissions</p>
                    </div>
                )}
            </div>

            {isRoleModalOpen && (
                <div className="fixed inset-0 bg-black/60 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
                    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md border border-gray-200 dark:border-gray-700 overflow-hidden">
                        <form onSubmit={handleSaveRole}>
                            <div className="flex justify-between items-center p-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">{editingRole ? 'Update System Role' : 'Define New System Role'}</h3>
                                <button type="button" onClick={() => setRoleModalOpen(false)} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                            </div>
                            <div className="p-6 space-y-5">
                                <div><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1.5">Official Role Title</label><input type="text" value={newRoleData.name} onChange={e => setNewRoleData({...newRoleData, name: e.target.value})} className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-900 dark:text-white font-bold transition-all focus:ring-2 focus:ring-blue-500 outline-none" required placeholder="e.g. Sales Director" /></div>
                                <div><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1.5">Role Responsibility Description</label><textarea value={newRoleData.description} onChange={e => setNewRoleData({...newRoleData, description: e.target.value})} className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-900 dark:text-white text-sm transition-all focus:ring-2 focus:ring-blue-500 outline-none" required rows={3} placeholder="Brief summary of duties..." /></div>
                            </div>
                            <div className="p-5 bg-gray-50 dark:bg-gray-900 flex justify-end gap-3 rounded-b-lg border-t dark:border-gray-700">
                                <button type="button" onClick={() => setRoleModalOpen(false)} className="px-5 py-2.5 text-sm font-bold text-gray-500 hover:text-gray-800 transition-colors">Discard</button>
                                <button type="submit" className="bg-blue-600 text-white py-2.5 px-6 rounded-lg font-black uppercase tracking-widest text-sm shadow-md hover:shadow-lg transition-all active:scale-95">Save Role</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { Staff, Role } from '../../types';
import { PlusCircleIcon, PencilIcon, TrashIcon, EyeIcon } from '../../components/icons/DummyIcons';
import { Badge } from '../../components/ui/Badge';
import UserFormModal from '../../components/UserFormModal';
import { registerStaffAccount, normalizeEmail } from '../../services/authService';
import { useStaff } from '../../hooks/useAppData';

interface StaffManagerProps {
    staff: Staff[];
    roles: Role[];
    onUpdateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
    onViewStaffActivity: (staff: Staff) => void;
    setActionFeedback: React.Dispatch<React.SetStateAction<{ type: 'success' | 'error', message: string } | null>>;
}

const RolePill: React.FC<{ role?: Role }> = ({ role }) => {
    return <span className={`px-2 py-1 text-xs font-semibold rounded-full border bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-800`}>{role ? role.name : 'Unknown Role'}</span>
}

export const StaffManager: React.FC<StaffManagerProps> = ({ staff, roles, onUpdateStaff, onViewStaffActivity, setActionFeedback }) => {
    const { deleteStaff } = useStaff();
    const [isStaffModalOpen, setStaffModalOpen] = useState(false);
    const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
    const [staffToDelete, setStaffToDelete] = useState<Staff | null>(null);
    const [isSavingStaff, setIsSavingStaff] = useState(false);

    const handleSaveStaff = async (staffData: Partial<Staff>) => {
        setIsSavingStaff(true);
        setActionFeedback(null);
        try {
            if (editingStaff) {
                await onUpdateStaff(editingStaff.id, staffData);
                setActionFeedback({ type: 'success', message: 'Staff account updated successfully.' });
            } else {
                await registerStaffAccount({
                    email: normalizeEmail(staffData.email!),
                    password: staffData.password!,
                    fullName: staffData.fullName!,
                    roleId: staffData.roleId!,
                    phone: staffData.phone
                });
                setActionFeedback({ type: 'success', message: 'New staff account created successfully.' });
            }
            setStaffModalOpen(false);
            setEditingStaff(null);
        } catch (error: any) {
            console.error("Staff save error:", error);
            const errMsg = error.message || 'System failed to synchronize account.';
            setActionFeedback({ type: 'error', message: errMsg });
            alert(`Error: ${errMsg}`);
        } finally {
            setIsSavingStaff(false);
        }
    }

    const confirmDeleteStaff = async () => {
        if (!staffToDelete) return;
        try {
            await deleteStaff(staffToDelete.id);
            setActionFeedback({ type: 'success', message: 'Staff account removed.' });
            setStaffToDelete(null);
        } catch (error) {
            alert("Failed to delete staff account.");
        }
    };

    return (
        <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
            <div className="flex flex-wrap justify-between items-center mb-6 gap-4">
                <h2 className="font-bold text-xl text-gray-800 dark:text-white">Staff Management</h2>
                <button onClick={() => {setEditingStaff(null); setStaffModalOpen(true);}} className="bg-blue-600 text-white font-black uppercase tracking-widest text-xs py-3 px-6 rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-md hover:shadow-lg transition-all active:scale-95">
                    <PlusCircleIcon className="w-5 h-5" /> Register New Account
                </button>
            </div>
            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-50 dark:bg-gray-900 text-gray-500 border-b dark:border-gray-700">
                        <tr>
                            <th className="px-4 py-4 font-black uppercase tracking-widest text-[10px]">Staff Member</th>
                            <th className="px-4 py-4 font-black uppercase tracking-widest text-[10px]">Role / Department</th>
                            <th className="px-4 py-4 font-black uppercase tracking-widest text-[10px]">Account Status</th>
                            <th className="px-4 py-4 font-black uppercase tracking-widest text-[10px] text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                        {staff.map(member => (
                            <tr key={member.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors">
                                <td className="px-4 py-4 flex items-center gap-4">
                                    {member.photo ? <img src={member.photo} className="w-10 h-10 rounded-full object-cover border-2 border-white dark:border-gray-700 shadow-sm" alt={member.fullName}/> : <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-300 flex items-center justify-center font-black text-sm">{member.initials}</div>}
                                    <div>
                                        <div className="font-bold text-gray-900 dark:text-white">{member.fullName}</div>
                                        <div className="text-xs text-gray-500 font-medium">{member.email}</div>
                                    </div>
                                </td>
                                <td className="px-4 py-4">
                                    <RolePill role={roles.find(r => r.id === member.roleId)} />
                                </td>
                                <td className="px-4 py-4">
                                    <Badge variant={member.status === 'Active' ? 'success' : 'danger'}>{member.status}</Badge>
                                </td>
                                <td className="px-4 py-4 text-right">
                                    <div className="flex justify-end gap-1">
                                        <button onClick={() => onViewStaffActivity(member)} className="p-2 text-gray-400 hover:text-blue-600 transition-colors" title="Activity Logs"><EyeIcon className="w-5 h-5"/></button>
                                        <button onClick={() => { setEditingStaff(member); setStaffModalOpen(true); }} className="p-2 text-gray-400 hover:text-indigo-600 transition-colors" title="Edit Profile"><PencilIcon className="w-5 h-5"/></button>
                                        <button onClick={() => setStaffToDelete(member)} className="p-2 text-gray-400 hover:text-red-600 transition-colors" title="Delete Account"><TrashIcon className="w-5 h-5"/></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <UserFormModal 
                isOpen={isStaffModalOpen}
                onClose={() => { setStaffModalOpen(false); setEditingStaff(null); }}
                onSave={handleSaveStaff}
                editingUser={editingStaff}
                roles={roles}
            />

            {staffToDelete && (
                <div className="fixed inset-0 bg-black/60 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
                    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl max-w-sm w-full p-8 border border-gray-200 dark:border-gray-700 animate-in zoom-in duration-200">
                        <div className="flex items-center justify-center w-16 h-16 mx-auto bg-red-100 dark:bg-red-900/30 rounded-full mb-6">
                            <TrashIcon className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-black text-center text-gray-900 dark:text-white mb-2 uppercase tracking-tight">Delete Account?</h3>
                        <p className="text-center text-sm text-gray-500 dark:text-gray-400 mb-8 leading-relaxed">You are about to remove <strong>{staffToDelete.fullName}</strong>. Access will be revoked immediately and this action is permanent.</p>
                        <div className="flex flex-col gap-3">
