    roles: Role[];
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    onViewStaffActivity: (staff: Staff) => void;
    companySettings: CompanySettingsType;
    setCompanySettings: (value: React.SetStateAction<CompanySettingsType>) => Promise<void>;
    onUpdateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
}

const SettingsPage: React.FC<SettingsPageProps> = ({ currentStaff, staff, roles, setRoles, onViewStaffActivity, companySettings, setCompanySettings, onUpdateStaff }) => {

    const [activeTab, setActiveTab] = useState('profile');
    const [actionFeedback, setActionFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff.roleId), [currentStaff, roles]);
    const canManageStaff = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);
    const canManageCompany = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);

    // Clear feedback after timeout
    useEffect(() => {
        if (actionFeedback) {
            const timer = setTimeout(() => setActionFeedback(null), 5000);
            return () => clearTimeout(timer);
        }
    }, [actionFeedback]);

    const tabs = [
        { id: 'profile', name: 'My Profile', icon: <UserCircleIcon className="w-5 h-5" /> },
        { id: 'company', name: 'Company Settings', icon: <BuildingLibraryIcon className="w-5 h-5" />, disabled: !canManageCompany },
        { id: 'roles', name: 'Roles & Permissions', icon: <ShieldCheckIcon className="w-5 h-5" />, disabled: !canManageStaff },
        { id: 'staff', name: 'Staff Accounts', icon: <UsersIcon className="w-5 h-5" />, disabled: !canManageStaff },
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white">System Settings</h1>
                {actionFeedback && (
                    <div className={`flex items-center gap-3 px-4 py-2 rounded-lg border animate-in fade-in slide-in-from-top-4 duration-300 ${actionFeedback.type === 'success' ? 'bg-green-50 border-green-200 text-green-800 dark:bg-green-900/20 dark:border-green-800 dark:text-green-300' : 'bg-red-50 border-red-200 text-red-800 dark:bg-red-900/20 dark:border-red-800 dark:text-red-300'}`}>
                        {actionFeedback.type === 'success' ? <CheckCircleIcon className="w-5 h-5" /> : <XMarkIcon className="w-5 h-5" />}
                        <span className="text-sm font-bold">{actionFeedback.message}</span>
                        <button onClick={() => setActionFeedback(null)} className="ml-2 p-1 hover:bg-black/5 dark:hover:bg-white/5 rounded">
                            <XMarkIcon className="w-4 h-4 opacity-50" />
                        </button>
                    </div>
                )}
            </div>

            <div className="flex border-b border-gray-200 dark:border-gray-700 overflow-x-auto scrollbar-hide">
                {tabs.map(tab => !tab.disabled && (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-2 px-6 py-3 font-semibold transition-all whitespace-nowrap ${activeTab === tab.id ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white'}`}>
                        {tab.icon} {tab.name}
                    </button>
                ))}
            </div>

            {activeTab === 'profile' && (
                <ProfileSettings 
                    currentStaff={currentStaff} 
                    onUpdateStaff={onUpdateStaff} 
                />
            )}

            {activeTab === 'company' && canManageCompany && (
                <CompanySettings 
                    companySettings={companySettings} 
                    setCompanySettings={setCompanySettings} 
                />
            )}

            {activeTab === 'roles' && canManageStaff && (
                <RolesManager 
                    roles={roles} 
                    setRoles={setRoles} 
                    staff={staff} 
                />
            )}

            {activeTab === 'staff' && canManageStaff && (
                <StaffManager 
                    staff={staff} 
                    roles={roles} 
                    onUpdateStaff={onUpdateStaff} 
                    onViewStaffActivity={onViewStaffActivity} 
                    setActionFeedback={setActionFeedback}
                />
            )}
        </div>
    );
};

export default SettingsPage;

import { useMemo } from 'react';
import { Client, Property, Invoice } from '../types';

export const useDashboardAnalytics = (clients: Client[], properties: Property[], invoices: Invoice[]) => {
    // -- Derived Stats Data --
    const statsData = useMemo(() => {
        const totalClients = clients.length;
        const activeProcesses = clients.filter(c => c.stage !== 'COMP').length;
        const completedDeals = clients.filter(c => c.stage === 'COMP').length;
        const totalRevenue = clients.reduce((acc, client) => acc + client.payment.paid, 0);
        const pendingPayments = invoices.filter(i => i.status === 'Pending' || i.status === 'Overdue').length;
        const availablePlots = properties.reduce((acc, prop) => {
            const totalPlots = prop.inventory.reduce((sum, inv) => sum + inv.count, 0);
            const plotsSold = prop.inventory.reduce((sum, inv) => sum + inv.sold, 0);
            return acc + (totalPlots - plotsSold);
        }, 0);

        return { totalClients, activeProcesses, completedDeals, totalRevenue, pendingPayments, availablePlots };
    }, [clients, properties, invoices]);

    // -- Chart Data Preparation --

    // 1. Revenue Trend (Monthly)
    const revenueData = useMemo(() => {
        const monthlyRevenue: Record<string, number> = {};

        clients.forEach(client => {
            if(client.payment && client.payment.paymentHistory) {
                client.payment.paymentHistory.forEach(txn => {
                    if (txn.date && (txn.status === 'Success' || !txn.status)) {
                        const month = txn.date.substring(0, 7); // YYYY-MM
                        if (month.match(/^\d{4}-\d{2}$/)) {
                             monthlyRevenue[month] = (monthlyRevenue[month] || 0) + txn.amount;
                        }
                    }
                });
            }
        });

        return Object.entries(monthlyRevenue)
            .map(([date, amount]) => ({
                name: new Date(date).toLocaleDateString('en-US', { month: 'short', year: '2-digit' }),
                dateStr: date, // for sorting
                revenue: amount
            }))
            .sort((a, b) => a.dateStr.localeCompare(b.dateStr))
            .slice(-6); // Last 6 active months
    }, [clients]);

    // 2. Client Growth (Monthly Registrations)
    const growthData = useMemo(() => {
        const monthlyGrowth: Record<string, number> = {};

        clients.forEach(client => {
            if (client.regDate) {
                const month = client.regDate.substring(0, 7);
                if (month.match(/^\d{4}-\d{2}$/)) {
                    monthlyGrowth[month] = (monthlyGrowth[month] || 0) + 1;
                }
            }
        });

        return Object.entries(monthlyGrowth)
            .map(([date, count]) => ({
                name: new Date(date).toLocaleDateString('en-US', { month: 'short', year: '2-digit' }),
                dateStr: date,
                clients: count
            }))
            .sort((a, b) => a.dateStr.localeCompare(b.dateStr))
            .slice(-6);
    }, [clients]);

    // 3. Process Status Distribution
    const statusData = useMemo(() => {
        const stageCounts: Record<string, number> = {};

        clients.forEach(client => {
            const stage = client.stage || 'Unknown';
            stageCounts[stage] = (stageCounts[stage] || 0) + 1;
        });

        const STAGE_LABELS: Record<string, string> = {
            'REG': 'Registration',
            'PAYM': 'Payment',
            'IND': 'Indenture',
            'COMP': 'Completed'
        };

        const data = Object.entries(stageCounts).map(([stage, count]) => ({
            name: STAGE_LABELS[stage] || stage,
            value: count
        }));

        return data.filter(d => d.value > 0);
    }, [clients]);

    return { statsData, revenueData, growthData, statusData };
};

