                                            <p className="text-[10px] text-gray-500">{(file.size / 1024).toFixed(1)} KB</p>
                                        </div>
                                    </div>
                                    <a href={file.url} download className="p-2 text-gray-400 hover:text-blue-600"><ArrowDownTrayIcon className="w-4 h-4" /></a>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

