                        </tr>
                    </Thead>
                    <Tbody>
                        {inventory.map((inv, idx) => (
                            <Tr key={idx}>
                                <Td>{inv.size}</Td>
                                <Td>
                                    {isEditMode ? (
                                        <input 
                                            type="number" 
                                            value={inv.count} 
                                            onChange={(e) => handleUpdate(idx, 'count', Number(e.target.value))}
                                            className="w-16 p-1 border rounded bg-white dark:bg-gray-950 dark:border-gray-700 dark:text-white" 
                                        />
                                    ) : inv.count}
                                </Td>
                                <Td>{inv.sold}</Td>
