                                    {isEditMode ? (
                                        <input 
                                            type="text" 
                                            value={(inv as any).zone || ''} 
                                            onChange={(e) => handleUpdate(idx, 'zone', e.target.value)}
                                            className="w-full p-1 border rounded bg-white dark:bg-gray-950 dark:border-gray-700 dark:text-white" 
                                        />
                                    ) : ((inv as any).zone || '—')}
                                </Td>
