  };

  const handleUpdateLocal = (updates: Partial<Property>) => {
      setLocalPropData(prev => prev ? { ...prev, ...updates } : null);
  }

  if (viewingProperty && localPropData) {
    return (
      <div className="space-y-6 animate-in fade-in duration-300">
