              <Button icon={<PencilSquareIcon className="w-4 h-4" />} onClick={() => setIsEditMode(true)} className="flex-1">
                Amendment
              </Button>
            ) : (
              <Button variant="success" icon={<CheckCircleIcon className="w-4 h-4" />} onClick={handleSaveAmendment} className="flex-1">
                Save Changes
              </Button>
            )}
