                <PlotIdentifierConfig 
                    property={localPropData} 
                    isEditMode={isEditMode} 
                    onChange={handleUpdateLocal} 
                />
            </div>

            <InventoryTable 
                inventory={localPropData.inventory} 
                isEditMode={isEditMode} 
                onChange={(inv) => handleUpdateLocal({ inventory: inv })} 
            />
