import React, { useMemo } from 'react';
import { Client } from '../../types';
import { Card } from '../ui/Card';

interface QualificationCardProps {
    client: Client;
}

export const QualificationCard: React.FC<QualificationCardProps> = ({ client }) => {
    const qualification = useMemo(() => {
        if (!client) return { isQualified: false, percentage: 0, status: 'N/A' };
        const total = client.payment.total || 1;
        const paid = client.payment.paid || 0;
        const percentage = (paid / total) * 100;
        const isQualified = percentage >= 70;
        return {
            percentage: Math.round(percentage),
            isQualified,
            status: isQualified ? 'Qualified (≥70%)' : 'Provisionally Flagged (<70%)'
        };
    }, [client]);

    return (
        <Card title="Qualification Detail" className="lg:col-span-1">
            <div className="text-center space-y-4">
                <p className="text-[10px] font-black uppercase text-gray-400">Payment Status</p>
                <p className={`text-lg font-bold ${qualification.isQualified ? 'text-green-600' : 'text-amber-600'}`}>{qualification.status}</p>
                <div className="w-full bg-gray-200 h-2 rounded-full overflow-hidden">
                    <div className={`h-full ${qualification.isQualified ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${qualification.percentage}%` }}></div>
                </div>
            </div>
        </Card>
    );
};

