                                    <p className="text-[10px] text-gray-500 mt-1 italic">Hold Ctrl/Cmd to select multiple staff members.</p>
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase mb-1.5">Subject Line*</label>
                                <input 
