                                        <div>
                                            <h3 className="font-bold text-gray-900 dark:text-white">{selectedMessage.senderName}</h3>
                                            <p className="text-[10px] text-gray-500 uppercase tracking-tighter">{new Date(selectedMessage.timestamp).toLocaleString()}</p>
                                        </div>
