rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- Helper Functions ---

    function isUserAuthenticated() {
      return request.auth != null;
    }

    function getRole() {
      let userDocPath = /databases/$(database)/documents/user/$(request.auth.uid);
      return exists(userDocPath) ? get(userDocPath).data.roleId : null;
    }

    function isCEO() {
      return isUserAuthenticated() && getRole() == 'CEO';
    }

    function can(module, action) {
      let role = getRole();
      let permDocPath = /databases/$(database)/documents/role_permissions/$(role);

      return role != null && 
             exists(permDocPath) && 
             get(permDocPath).data.modules[module][action] == true;
    }

    // --- Collection Rules ---

    match /settings/{docId} {
      allow read: if true; 
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /user/{userId} {
      // Allow reading own profile even if role isn't loaded yet
      allow read: if isUserAuthenticated() && (request.auth.uid == userId || isCEO() || can('Settings', 'view'));

      // CRITICAL FIX: Allow self-creation for the bootstrap flow to work
      allow create: if isUserAuthenticated() && (request.auth.uid == userId);

      allow update: if isUserAuthenticated() && (request.auth.uid == userId || isCEO() || can('Settings', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Settings', 'delete'));
    }

    match /roles/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /role_permissions/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /activity_logs/{logId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Settings', 'view'));
      allow create: if isUserAuthenticated();
      allow update, delete: if false;
    }

    match /clients/{clientId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Clients', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Clients', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Clients', 'delete'));
    }

    match /leads/{leadId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'delete'));
    }

    match /properties/{propertyId} {
      allow read: if isUserAuthenticated(); 
      allow create: if isUserAuthenticated() && (isCEO() || can('CEO Hub', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('CEO Hub', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('CEO Hub', 'delete'));
    }

    match /invoices/{invoiceId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Account Management', 'view') || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Account Management', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Account Management', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Account Management', 'delete'));
    }

    match /promotions/{promoId} {
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated() && (isCEO() || can('Promotions', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Promotions', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Promotions', 'delete'));
    }

    match /amendments/{docId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Clients', 'edit'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Clients', 'approve')); 
      allow delete: if isUserAuthenticated() && (isCEO() || can('Clients', 'delete'));
    }

    match /milestones/{milestoneId} {
      allow read, write: if isUserAuthenticated();
    }

    match /internal_mails/{mailId} {
      // Participants field contains senderId and recipientIds
      // We check if the requesting user is in the participants array OR is the CEO
      allow read: if isUserAuthenticated() && (request.auth.uid in resource.data.participants || isCEO());

      // Allow sending (create) if authenticated.
      allow create: if isUserAuthenticated();

      // Allow updates (read receipts, soft delete) if participant
      allow update: if isUserAuthenticated() && (request.auth.uid in resource.data.participants || isCEO());

      // Only sender or CEO can permanently delete
      allow delete: if isUserAuthenticated() && (request.auth.uid == resource.data.senderId || isCEO());
    }
  }
}

import { db } from './firebase';
import { collection, addDoc, updateDoc, doc, deleteDoc, onSnapshot, query, where, arrayUnion } from 'firebase/firestore';
import { InternalMail } from '../types';

const MAILS_COL = 'internal_mails';

export const sendInternalMail = async (mailData: Omit<InternalMail, 'id'>) => {
    // Ensure participants array is populated for querying
    const participants = Array.from(new Set([mailData.senderId, ...mailData.recipientIds]));

    await addDoc(collection(db, MAILS_COL), {
        ...mailData,
        participants,
        timestamp: new Date().toISOString() // Server time ideally, but ISO string works for this app scale
    });
};

export const listenToInbox = (userId: string, onUpdate: (mails: InternalMail[]) => void) => {
    // Query mails where the user is a participant (sender or recipient)
    // Removed orderBy to bypass the need for a composite index on (participants, timestamp).
    // Sorting is performed client-side.
    const q = query(
        collection(db, MAILS_COL),
        where('participants', 'array-contains', userId)
    );

    return onSnapshot(q, (snapshot) => {
        const mails = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as InternalMail));
        // Client-side sort by timestamp descending
        mails.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        onUpdate(mails);
    }, (error) => {
        console.error("Error listening to mails:", error);
    });
};

export const markMailRead = async (mailId: string, userId: string) => {
    const ref = doc(db, MAILS_COL, mailId);
    await updateDoc(ref, {
        readBy: arrayUnion(userId)
    });
};

export const toggleMailDeleteStatus = async (mailId: string, isDeleted: boolean) => {
    const ref = doc(db, MAILS_COL, mailId);
    await updateDoc(ref, { isDeleted });
};

export const permanentlyDeleteMail = async (mailId: string) => {
    await deleteDoc(doc(db, MAILS_COL, mailId));
};

