rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- Helper Functions ---

    function isUserAuthenticated() {
      return request.auth != null;
    }

    function getRole() {
      let userDocPath = /databases/$(database)/documents/user/$(request.auth.uid);
      return exists(userDocPath) ? get(userDocPath).data.roleId : null;
    }

    function isCEO() {
      return isUserAuthenticated() && getRole() == 'CEO';
    }

    function can(module, action) {
      let role = getRole();
      let permDocPath = /databases/$(database)/documents/role_permissions/$(role);

      return role != null && 
             exists(permDocPath) && 
             get(permDocPath).data.modules[module][action] == true;
    }

    // --- Collection Rules ---

    match /settings/{docId} {
      allow read: if true; 
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /user/{userId} {
      // Allow reading own profile even if role isn't loaded yet
      allow read: if isUserAuthenticated() && (request.auth.uid == userId || isCEO() || can('Settings', 'view'));

      // RESTRICTED: Only CEO or Settings Creators can create users. Self-creation blocked.
      allow create: if isUserAuthenticated() && (isCEO() || can('Settings', 'create'));

      allow update: if isUserAuthenticated() && (request.auth.uid == userId || isCEO() || can('Settings', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Settings', 'delete'));
    }

    match /roles/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /role_permissions/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /activity_logs/{logId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Settings', 'view'));
      allow create: if isUserAuthenticated();
      allow update, delete: if false;
    }

    match /clients/{clientId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Clients', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Clients', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Clients', 'delete'));
    }

    match /leads/{leadId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'delete'));
    }

    match /properties/{propertyId} {
      allow read: if isUserAuthenticated(); 
      allow create: if isUserAuthenticated() && (isCEO() || can('CEO Hub', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('CEO Hub', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('CEO Hub', 'delete'));
    }

    match /invoices/{invoiceId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Account Management', 'view') || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Account Management', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Account Management', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Account Management', 'delete'));
    }

    match /promotions/{promoId} {
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated() && (isCEO() || can('Promotions', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Promotions', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Promotions', 'delete'));
    }

    match /amendments/{docId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Clients', 'edit'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Clients', 'approve')); 
      allow delete: if isUserAuthenticated() && (isCEO() || can('Clients', 'delete'));
    }

    match /milestones/{milestoneId} {
      allow read, write: if isUserAuthenticated();
    }

    match /internal_mails/{mailId} {
      // Participants field contains senderId and recipientIds
      // We check if the requesting user is in the participants array OR is the CEO
      allow read: if isUserAuthenticated() && (request.auth.uid in resource.data.participants || isCEO());

      // Allow sending (create) if authenticated.
      allow create: if isUserAuthenticated();

      // Allow updates (read receipts, soft delete) if participant
      allow update: if isUserAuthenticated() && (request.auth.uid in resource.data.participants || isCEO());

      // Only sender or CEO can permanently delete
      allow delete: if isUserAuthenticated() && (request.auth.uid == resource.data.senderId || isCEO());
    }
  }
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Staff } from '../types';
import { useActivityLogs } from '../hooks/useAppData';
import { auth, db } from '../services/firebase';
// @ts-ignore
import { signInWithEmailAndPassword, signOut, onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc, setDoc, serverTimestamp, updateDoc } from 'firebase/firestore';
import { normalizeEmail } from '../services/authService';

interface AuthContextType {
    currentStaff: Staff | null;
    login: (email: string, password: string) => Promise<{ success: boolean; message: string }>;
    logout: () => Promise<void>;
    updateCurrentUser: (updates: Partial<Staff>) => void;
    isAuthenticated: boolean;
    loading: boolean;
    sessionStatus: 'idle' | 'authenticating' | 'resolving_profile' | 'bootstrapping' | 'ready' | 'error';
    authError: string | null;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { addActivityLog } = useActivityLogs();
    const [currentStaff, setCurrentStaff] = useState<Staff | null>(null);
    const [loading, setLoading] = useState(true);
    const [sessionStatus, setSessionStatus] = useState<'idle' | 'authenticating' | 'resolving_profile' | 'bootstrapping' | 'ready' | 'error'>('idle');
    const [authError, setAuthError] = useState<string | null>(null);

    // Step 2: Profile Resolution (Soft Gate)
    const resolveUserProfile = async (firebaseUser: any) => {
        try {
            setSessionStatus('resolving_profile');
            const userRef = doc(db, "user", firebaseUser.uid);
            const userSnap = await getDoc(userRef);

            if (userSnap.exists()) {
                const userData = userSnap.data() as Staff;

                // SYNC FIX: Update lastLogin in Firestore to track activity
                const now = new Date().toISOString();
                try {
                    await updateDoc(userRef, { lastLogin: now });
                } catch (e) {
                    console.warn("Could not update lastLogin timestamp", e);
                }

                setCurrentStaff({ ...userData, lastLogin: now });
                setSessionStatus('ready');
            } else {
                // ENFORCEMENT: Self-creation (Bootstrap) is disabled.
                // Accounts must be pre-created by an Administrator/CEO.
                console.error("Profile Resolution Error: User document not found.");
                setAuthError("Access Denied: Your account profile is missing. Please contact the System Administrator.");
                setSessionStatus('error');
            }
        } catch (error: any) {
            console.error("Profile Resolution Error:", error);
            setAuthError(`Authorization Error: ${error.message}`);
            setSessionStatus('error');
            // CRITICAL: We do NOT signOut() here. We stay in 'error' status for the UI to handle.
        }
    };

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: any) => {
            if (firebaseUser) {
                await resolveUserProfile(firebaseUser);
            } else {
                setCurrentStaff(null);
                setSessionStatus('idle');
            }
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const login = async (email: string, password: string) => {
        setAuthError(null);
        setSessionStatus('authenticating');
        try {
            const normalizedEmail = normalizeEmail(email);
            // Step 1: Authentication Phase (Hard Identity Gate)
            await signInWithEmailAndPassword(auth, normalizedEmail, password);
            // The onAuthStateChanged observer handles the rest of the flow.
            return { success: true, message: 'Identity verified. Resolving session...' };
        } catch (error: any) {
            let message = 'Access denied. Please check your credentials.';
            if (error.code === 'auth/invalid-credential' || error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password') {
                message = 'Incorrect email or password.';
            } else if (error.code === 'auth/network-request-failed') {
                message = 'Connection error. Please check your internet.';
            }

            setAuthError(message);
            setSessionStatus('error');
            return { success: false, message };
        }
    };

    const logout = async () => {
        if (currentStaff) {
            try {
                addActivityLog('Logout', `User ${currentStaff.fullName} ended session.`, currentStaff.id);
            } catch (e) {}
        }
        setSessionStatus('idle');
        setAuthError(null);
        await signOut(auth);
        setCurrentStaff(null);
    };

    const updateCurrentUser = (updates: Partial<Staff>) => {
        if (currentStaff) {
            setCurrentStaff({ ...currentStaff, ...updates });
        }
    };

    return (
        <AuthContext.Provider value={{
            currentStaff,
            login,
            logout,
            updateCurrentUser,
            isAuthenticated: !!auth.currentUser,
            loading,
            sessionStatus,
            authError
        }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import React, { useState } from 'react';
import { Client } from '../../types';
import { XMarkIcon } from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';

interface RecordPaymentModalProps {
    isOpen: boolean;
    onClose: () => void;
    client: Client;
    onSave: (paymentData: any) => Promise<void>;
}

export const RecordPaymentModal: React.FC<RecordPaymentModalProps> = ({ isOpen, onClose, client, onSave }) => {
    const [amount, setAmount] = useState('');
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>('Land');
    const [isProcessing, setIsProcessing] = useState(false);
    const [error, setError] = useState<string | null>(null);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        // Validation
        const val = parseFloat(amount);
        if (isNaN(val) || val <= 0) {
            setError("Please enter a valid payment amount greater than zero.");
            return;
        }
        if (!receiptNumber.trim()) {
            setError("A valid receipt number is required for the audit trail.");
            return;
        }

        setIsProcessing(true);
        try {
            // Trigger the parent's save function and wait for confirmation
            await onSave({
                amount: val,
                method,
                receiptNumber: receiptNumber.trim(),
                type,
                date: new Date().toISOString().split('T')[0]
            });

            // On success, close the modal
            onClose();
        } catch (err: any) {
            console.error("Payment Posting Failed:", err);
            setError(err.message || "Failed to post transaction. Please verify connection and try again.");
        } finally {
            setIsProcessing(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/60 z-[100] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-md p-0 overflow-hidden shadow-2xl animate-in zoom-in duration-200">
                <form onSubmit={handleSubmit}>
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900">
                        <div className="flex flex-col">
                            <h3 className="font-bold text-gray-900 dark:text-white uppercase tracking-tight">Record New Payment</h3>
                            <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">{client.name}</p>
                        </div>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><XMarkIcon className="w-6 h-6"/></button>
                    </div>
                    <div className="p-6 space-y-4 bg-white dark:bg-gray-800">
                        {error && (
                            <div className="p-3 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded text-xs text-red-700 dark:text-red-300 font-bold uppercase">
                                {error}
                            </div>
                        )}
                        <Input 
                            label="Amount (GHC)*" 
                            type="number" 
                            step="0.01"
                            value={amount} 
                            onChange={e => setAmount(e.target.value)} 
                            disabled={isProcessing}
                            required 
                        />
                        <Select 
                            label="Payment Method*" 
                            value={method} 
                            onChange={e => setMethod(e.target.value as any)} 
                            disabled={isProcessing}
                            required
                        >
                            <option>Bank Transfer</option>
                            <option>MoMo</option>
                            <option>Cash</option>
                            <option>Cheque</option>
                            <option>Other</option>
                        </Select>
                        <Select 
                            label="Transaction Type*" 
                            value={type} 
                            onChange={e => setType(e.target.value as any)} 
                            disabled={isProcessing}
                            required
                        >
                            <option value="Land">Land Payment</option>
                            <option value="Indenture">Indenture/Documentation</option>
                            <option value="Commission">Commission Payout</option>
                        </Select>
                        <Input 
                            label="Receipt / Reference Number*" 
                            value={receiptNumber} 
                            onChange={e => setReceiptNumber(e.target.value)} 
                            disabled={isProcessing}
                            placeholder="e.g. REC-102938"
                            required 
                        />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <Button type="button" variant="secondary" onClick={onClose} disabled={isProcessing}>Cancel</Button>
                        <Button 
                            type="submit" 
                            variant="success" 
                            className="font-black uppercase tracking-widest text-xs"
                            isLoading={isProcessing}
                        >
                            Post Transaction
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    DocumentTextIcon,
    ChartBarIcon
} from '../components/icons/DummyIcons';
import { Button } from '../components/ui/Button';
import { Select } from '../components/ui/Input';
import { FinancialReportsView } from '../components/FinancialReportsView';
import { NotificationCenter } from '../components/NotificationCenter';
import { AccountOverview } from '../components/account/AccountOverview';
import { AccountHistory } from '../components/account/AccountHistory';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useProperties, useMilestones } from '../hooks/useAppData';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect?: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
  overrideClientId?: number | null;
  isEmbedded?: boolean;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage, overrideClientId = null, isEmbedded = false
}) => {
  const { properties } = useProperties();
  const { saveMilestone } = useMilestones();
  const { openModal } = useModal();
  const [viewMode, setViewMode] = useState<'list' | 'alerts' | 'reports'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(overrideClientId);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');

  useEffect(() => {
    if (overrideClientId !== null) {
      setSelectedClientId(overrideClientId);
    }
  }, [overrideClientId]);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (selectedClientId || clientForInvoice?.id))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);

  const canMakePayment = useMemo(() => {
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  const originalPricePerPlot = useMemo(() => {
    if (!selectedClient) return 0;
    const matchingProperty = properties.find(p => p.location === selectedClient.location);
    return matchingProperty ? matchingProperty.price : 0;
  }, [selectedClient, properties]);

  const discountAmount = selectedClient?.payment.promoDetails ? (originalPricePerPlot * 0.1) : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land';
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async () => {
    if (!selectedClient) return;
    setIsSaving(true);
    try {
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: installmentOption,
                total: priceAfterDiscount,
                balance: priceAfterDiscount - selectedClient.payment.paid
            }
        };
        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    try {
        const newTransaction: PaymentTransaction = { 
            ...paymentData, 
            id: `TXN-${Date.now()}`, 
            status: 'Success' 
        };

        const newPaid = client.payment.paid + newTransaction.amount;
        const newBalance = client.payment.balance - newTransaction.amount;

        const updatedClient = {
            ...client,
            payment: {
                ...client.payment,
                paymentHistory: [...client.payment.paymentHistory, newTransaction],
                paid: newPaid,
                balance: newBalance,
            }
        };

        // Step 1: Persist to DB
        await onSaveClient(updatedClient);

        // Step 2: Milestone Logic
        if (newBalance <= 0) {
            await saveMilestone({
                clientId: client.id,
                milestoneCode: 'PLR',
                dateCompleted: new Date().toISOString().split('T')[0],
                notes: 'Full payment for land received.'
            });
        }

        if (paymentData.type === 'Indenture') {
            await saveMilestone({
                clientId: client.id,
                milestoneCode: 'PFI',
                dateCompleted: new Date().toISOString().split('T')[0],
                notes: 'Payment for indenture documents received.'
            });
        }

        // Step 3: Success Feedback
        alert('Payment recorded successfully');

    } catch (error) {
        console.error("handleRecordPayment error:", error);
        throw new Error("Financial update failed. Please check system logs.");
    }
  };

  const openPaymentModal = () => {
      if(selectedClient) {
          openModal(MODAL_TYPES.RECORD_PAYMENT, {
              client: selectedClient,
              onSave: (data: any) => handleRecordPayment(selectedClient, data)
          });
      }
  };

  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  if (viewMode === 'reports') return <FinancialReportsView onBack={() => setViewMode('list')} clients={clients} staffList={[]} />;

  return (
    <div className={`flex flex-col ${isEmbedded ? 'h-auto' : 'h-[calc(100vh-120px)]'} space-y-6`}>
      {!isEmbedded && (
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
