export const generateWeeklySalesMetrics = (leads: Lead[], clients: Client[]) => {
    const now = new Date();
    const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

    const newLeads = leads.filter(l => new Date(l.createdAt) >= oneWeekAgo);
    const contactedLeads = newLeads.filter(l => {
        if (l.comments.length === 0) return false;
        const creationTime = new Date(l.createdAt).getTime();
        const contactTime = new Date(l.comments[0].date).getTime();
        return (contactTime - creationTime) < 24 * 60 * 60 * 1000;
    });

    let totalCashFromSales = 0;
    let adGeneratedCash = 0;

    clients.forEach(c => {
        c.payment.paymentHistory.forEach(txn => {
            if (new Date(txn.date) >= oneWeekAgo) {
                totalCashFromSales += txn.amount;
                // Simplified ad detection: assumes 'WhatsApp' or 'Facebook' source leads to ad cash
                if (c.officeUse.salesRep === 'Ad Campaign' || leads.find(l => l.phone === c.phone)?.source === 'Facebook') {
                    adGeneratedCash += txn.amount;
                }
            }
        });
    });

    return {
        newLeads: newLeads.length,
        contactedWithin24h: contactedLeads.length,
        totalSalesCash: totalCashFromSales,
        adGeneratedCash,
        weekLabel: `Week ${getWeekNumber(now)} - ${now.getFullYear()}`
    };
};

export const generateWeeklyAccountsMetrics = (clients: Client[]) => {
    const now = new Date();
    const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

    let totalConfirmedCash = 0;
    const transactions: any[] = [];

    clients.forEach(c => {
        c.payment.paymentHistory.forEach(txn => {
            if (new Date(txn.date) >= oneWeekAgo) {
                totalConfirmedCash += txn.amount;
                transactions.push({ ...txn, clientName: c.name });
            }
        });
    });

    return {
        totalConfirmedCash,
        transactions,
        walletBalances: {
            opening: totalConfirmedCash * 0.8, // Simulation
            closing: totalConfirmedCash * 1.2  // Simulation
        }
    };
};

function getWeekNumber(d: Date) {
    d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    var yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    var weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return weekNo;
}

