import LeavePage from './pages/team/LeavePage';
import EventsPage from './pages/team/EventsPage';
import AnnouncementsPage from './pages/team/AnnouncementsPage';

import { DataProvider, usePermissions } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { ModalProvider } from './context/ModalContext';
import { ModalManager } from './components/ModalManager';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { 
    useClients, useProperties, useInvoices, useStaff, useLeads, 
    usePromotions, useActivityLogs, useRoles, useAmendments, useCompanySettings 
} from './hooks/useAppData';
import { LoaderIcon } from './components/icons/LoaderIcon';
import { ShieldCheckIcon } from './components/icons/DummyIcons';

const queryClient = new QueryClient();

const AuthenticatedApp: React.FC = () => {
    const { clients, saveClient, deleteClient } = useClients();
    const { properties, saveProperty } = useProperties();
    const { invoices, saveInvoice } = useInvoices();
    const { staff, updateStaff } = useStaff(); 
    const { leads, saveLead, deleteLead } = useLeads();
    const { promotions, savePromotion, deletePromotion } = usePromotions();
    const { activityLogs, addActivityLog } = useActivityLogs();
    const { roles, setRoles } = useRoles();
    const { amendments, setAmendmentList } = useAmendments();
    const { companySettings, setCompanySettings } = useCompanySettings();
    const { rolePermissions } = usePermissions();

    const { currentStaff, logout } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);
        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });
        return userPermissions;
    }, [currentStaff, rolePermissions]);

    const hasAccessToDashboard = useMemo(() => {
        return !!staffPermissions['Dashboard']?.view;
    }, [staffPermissions]);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    if (!hasAccessToDashboard && activePage === 'Dashboard') {
        return (
            <Layout 
                activePage={activePage} 
                setActivePage={handleSetPage} 
                currentStaff={currentStaff!} 
                onLogout={logout}
                staffPermissions={staffPermissions}
                companySettings={companySettings}
            >
                <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-8 bg-white dark:bg-gray-800 rounded-2xl border-2 border-dashed border-gray-100 dark:border-gray-700">
                    <div className="w-20 h-20 bg-amber-50 dark:bg-amber-900/20 rounded-full flex items-center justify-center mb-6">
                        <ShieldCheckIcon className="w-10 h-10 text-amber-600" />
                    </div>
                    <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Pending Configuration</h2>
                    <p className="mt-2 text-gray-500 dark:text-gray-400 max-w-md">Your identity is verified, but your specific role access permissions are not yet configured. Please contact the System Administrator to finalize your account setup.</p>
                </div>
            </Layout>
        );
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard': return <Dashboard />;
            case 'Clients': return <ClientsPage clients={clients} onSaveClient={saveClient} onDeleteClient={deleteClient} properties={properties} milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]} onClientSelect={(client) => handleSetPage('Client Details', client)} setActivePage={handleSetPage} setClientForInvoice={setClientForInvoice} invoices={invoices} addActivityLog={handleAddActivityLog} />;
            case 'Client Details': return <ClientDetailPage client={pageContext} properties={properties} onBack={() => handleSetPage('Clients')} currentStaff={currentStaff!} roles={roles} setActivePage={handleSetPage} />;
            case 'Account Management': return <AccountManagementPage clients={clients} onSaveClient={saveClient} invoices={invoices} onSaveInvoice={saveInvoice} clientForInvoice={clientForInvoice} setClientForInvoice={setClientForInvoice} receiptPattern={null} setReceiptPattern={() => {}} setReceiptAlerts={() => {}} currentStaff={currentStaff!} roles={roles} setActivePage={handleSetPage} />;
            case 'Leads & Follow-Ups': return <LeadsManagementPage onSaveLead={saveLead} onDeleteLead={deleteLead} clients={clients} onSaveClient={saveClient} staffList={staff} roles={roles} properties={properties} milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]} currentStaff={currentStaff!} addActivityLog={handleAddActivityLog} />;
            case 'Mailing': return <MailingPage />;
            case 'Leave': return <LeavePage />;
            case 'Events': return <EventsPage />;
            case 'Announcements': return <AnnouncementsPage />;
            case 'Settings': return <SettingsPage currentStaff={currentStaff!} staff={staff} roles={roles} setRoles={setRoles} onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)} companySettings={companySettings} setCompanySettings={setCompanySettings} onUpdateStaff={updateStaff} />;
            case 'CEO Hub': return <CEOHub setActivePage={handleSetPage} properties={properties} clients={clients} invoices={invoices} staff={staff} roles={roles} onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)} addActivityLog={handleAddActivityLog} />;
            case 'Weekly Compliance Audit': return <WeeklyAuditPage />;
            case 'Properties': return <PropertiesPage properties={properties} currentStaff={currentStaff!} initialProperty={pageContext} onBack={() => handleSetPage('Purchase & Sale Management')} />;
            case 'New Land Acquisition': return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
            case 'Purchase & Sale Management': return <PurchaseSaleManagementPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} currentStaff={currentStaff!} setActivePage={handleSetPage} />;
            case 'Promotions': return <PromotionsPage promotions={promotions} onSavePromotion={savePromotion} onDeletePromotion={deletePromotion} properties={properties} showForm={true} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
            case 'Administration': return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Human Resources': return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts': return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot': return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation': return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings': return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form': return <AmendmentFormPage client={pageContext} onBack={() => handleSetPage('Client Details', pageContext)} onSave={async (data, updatedClient) => { setAmendmentList(prev => [data, ...prev]); await saveClient(updatedClient); handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`); alert('Amendment processed successfully!'); handleSetPage('Client Details', updatedClient); }} currentStaff={currentStaff!} />;
            case 'Analytics & Reports': return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports': return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity': return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Support': return <SupportPage />;
            default: return <Dashboard />;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff!} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
            <ModalManager />
        </Layout>
    );
};

const AppContent: React.FC = () => {
    const { loading, sessionStatus, currentStaff, login, authError } = useAuth();
    const { companySettings } = useCompanySettings();

    useEffect(() => {
        if (companySettings.name) {
            document.title = `${companySettings.name} - Enterprise Dashboard`;
        }
        if (companySettings.favicon) {
            let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
            if (!link) {
                link = document.createElement('link');
                link.rel = 'icon';
                document.getElementsByTagName('head')[0].appendChild(link);
            }
            link.href = companySettings.favicon;
        }
    }, [companySettings.name, companySettings.favicon]);

    if (loading || sessionStatus === 'authenticating' || sessionStatus === 'resolving_profile' || sessionStatus === 'bootstrapping') {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-950">
                <LoaderIcon className="w-12 h-12 text-blue-600 animate-spin mb-4" />
                <p className="text-sm font-bold text-gray-400 uppercase tracking-widest animate-pulse">
                    {sessionStatus === 'bootstrapping' ? 'Initializing profile...' : 'Authorizing access...'}
                </p>
            </div>
        );
    }

    if (!currentStaff) {
        return (
            <LoginPage 
                onLogin={login} 
                companySettings={companySettings} 
                externalError={authError} 
            />
        );
    }

    return <AuthenticatedApp />;
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <ModalProvider>
                    <AuthProvider>
                        <DataProvider>
                            <AppContent />
                        </DataProvider>
                    </AuthProvider>
                </ModalProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

import React, { useState, useMemo } from 'react';
import { XIcon } from './icons/XIcon';
import { 
  HomeIcon, 
  UsersIcon, 
  Cog6ToothIcon, 
  ChevronDownIcon, 
  DocumentPlusIcon, 
  BriefcaseIcon, 
  UserGroupIcon, 
  CalendarDaysIcon, 
  BookOpenIcon, 
  MegaphoneIcon, 
  ArrowRightOnRectangleIcon, 
  QuestionMarkCircleIcon, 
  ShieldCheckIcon, 
  AcademicCapIcon, 
  FaimLogoIcon, 
  TagIcon, 
  EnvelopeIcon,
  ChartBarIcon
} from './icons/DummyIcons';
import { PermissionSet, CompanySettings } from '../types';
import { useData } from '../context/DataContext';
import { useAuth } from '../context/AuthContext';

interface SidebarProps {
  isMobileOpen: boolean;
  onMobileClose: () => void;
  isDesktopCollapsed: boolean;
  activePage: string;
  setActivePage: (page: string) => void;
  staffPermissions: { [key: string]: PermissionSet };
  companySettings: CompanySettings;
  onLogout: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  isMobileOpen, 
  onMobileClose,
  isDesktopCollapsed,
  activePage,
  setActivePage,
  staffPermissions,
  companySettings,
  onLogout
}) => {
  const [openMenus, setOpenMenus] = useState<Record<string, boolean>>({
    'Client Management': true,
    'Team': true
  });
  const [logoError, setLogoError] = useState(false);

  const { internalMails } = useData();
  const { currentStaff } = useAuth();

  const unreadMails = useMemo(() => {
      if (!currentStaff) return 0;
      return internalMails.filter(m => 
          m.recipientIds.includes(currentStaff.id) && 
          !m.readBy.includes(currentStaff.id) && 
          !m.isDeleted && 
          !m.isDraft
      ).length;
  }, [internalMails, currentStaff]);

  const toggleMenu = (name: string) => {
    setOpenMenus(prev => ({ ...prev, [name]: !prev[name] }));
  };

  const handleNavClick = (pageName: string) => {
    setActivePage(pageName);
    onMobileClose();
  };

  const allNavItems = [
    { name: 'Dashboard', icon: <HomeIcon />, href: '#', moduleId: 'Dashboard' },
    {
      name: 'Client Management',
      icon: <UsersIcon />,
      moduleId: 'Clients',
      subItems: [
        { name: 'Clients', icon: <UserGroupIcon />, href: '#', moduleId: 'Clients' },
        { name: 'Account Management', icon: <DocumentPlusIcon />, href: '#', moduleId: 'Account Management' },
      ],
    },
    {
      name: 'Team',
      icon: <BriefcaseIcon />,
      moduleId: 'Team',
      subItems: [
        { name: 'Leads & Follow-Ups', icon: <UsersIcon />, href: '#', moduleId: 'Leads Management' },
        { name: 'Mailing', icon: <EnvelopeIcon />, href: '#', moduleId: 'Internal Mailing', badge: unreadMails },
        { name: 'Weekly Compliance Audit', icon: <ShieldCheckIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Leave', icon: <CalendarDaysIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Events', icon: <BookOpenIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Announcements', icon: <MegaphoneIcon />, href: '#', moduleId: 'Administration' },
      ],
    },
    { name: 'Promotions', icon: <TagIcon />, href: '#', moduleId: 'Promotions' },
    { name: 'Administration', icon: <ShieldCheckIcon />, href: '#', moduleId: 'Administration'},
    { name: 'CEO Hub', icon: <AcademicCapIcon />, href: '#', moduleId: 'CEO Hub' },
    { name: 'Support', icon: <QuestionMarkCircleIcon />, href: '#', moduleId: 'Settings' },
    { name: 'Settings', icon: <Cog6ToothIcon />, href: '#', moduleId: 'Settings' },
  ];

  const visibleNavItems = allNavItems.filter(item => staffPermissions[item.moduleId]?.view).map(item => {
      if (item.subItems) {
          return {
              ...item,
              subItems: item.subItems.filter(subItem => staffPermissions[subItem.moduleId]?.view)
          };
      }
      return item;
  }).filter(item => !item.subItems || item.subItems.length > 0);

  const sidebarLogo = companySettings.appLogoDark || companySettings.appLogoLight || companySettings.logo;

  const sidebarContent = (
    <>
      <div className="flex flex-col items-center justify-center p-4 h-24 border-b border-gray-800 flex-shrink-0">
          {(sidebarLogo && !logoError) ? (
            <img 
              key={sidebarLogo} 
              src={sidebarLogo} 
              alt={`${companySettings.name} Logo`} 
              className="w-12 h-12 object-contain"
              onError={() => setLogoError(true)}
            />
          ) : (
            <FaimLogoIcon className="w-10 h-10 text-white" />
          )}
          {!isDesktopCollapsed && (
            <h1 className="text-xl font-bold tracking-wider text-white mt-2">
              {companySettings.name.split(' ')[0]}<span className="text-blue-400">.</span>
            </h1>
          )}
        <button onClick={onMobileClose} className="md:hidden absolute top-5 right-4 text-gray-400 hover:text-white">
          <XIcon className="w-6 h-6" />
        </button>
      </div>
      <nav className="flex-grow p-2 overflow-y-auto">
        <ul>
          {visibleNavItems.map((item) => (
            <li key={item.name}>
              {item.subItems ? (
                <>
                  <button
                    onClick={() => toggleMenu(item.name)}
                    className={`flex items-center justify-between w-full gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                      activePage === item.name || item.subItems.some(sub => sub.name === activePage || (sub.name === 'Clients' && activePage === 'Client Details'))
                        ? 'text-white'
                        : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-6 h-6">{item.icon}</span>
                      {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                    </div>
                    {!isDesktopCollapsed && (
                      <ChevronDownIcon className={`w-5 h-5 transition-transform ${openMenus[item.name] ? 'rotate-180' : ''}`} />
                    )}
                  </button>
                  {(!isDesktopCollapsed && openMenus[item.name]) && (
                    <ul className="pl-6">
                      {item.subItems.map((subItem) => (
                        <li key={subItem.name}>
                          <a
                            href={subItem.href}
                            onClick={(e) => { e.preventDefault(); handleNavClick(subItem.name); }}
                            className={`flex items-center justify-between pl-3 pr-4 py-2 my-1 rounded-md transition-colors duration-200 text-sm relative group ${
                              activePage === subItem.name || (subItem.name === 'Clients' && activePage === 'Client Details')
                                ? 'bg-blue-600 text-white shadow-lg'
                                : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                            }`}
                          >
                            <div className="flex items-center gap-3">
                              <span className="w-6 h-6">{subItem.icon}</span>
                              <span className="font-medium">{subItem.name}</span>
                            </div>
                            {subItem.badge !== undefined && subItem.badge > 0 && (
                                <span className="bg-red-500 text-white text-[10px] font-black px-1.5 py-0.5 rounded-full ring-2 ring-gray-900 group-hover:ring-gray-800 transition-all animate-pulse">
                                    {subItem.badge}
                                </span>
                            )}
                          </a>
                        </li>
                      ))}
                    </ul>
                  )}
                </>
              ) : (
                <a
                  href={item.href}
                  onClick={(e) => { e.preventDefault(); handleNavClick(item.name); }}
                  className={`flex items-center gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                    activePage === item.name
                      ? 'bg-blue-600 text-white shadow-lg'
                      : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                  }`}
                >
                  <span className="w-6 h-6">{item.icon}</span>
                  {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                </a>
              )}
            </li>
          ))}

          {/* Standalone Log Out Button */}
          <li>
            <button
              onClick={onLogout}
              className="flex items-center w-full gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 hover:bg-red-900/20 text-red-400 hover:text-red-300"
            >
              <span className="w-6 h-6">
                <ArrowRightOnRectangleIcon />
              </span>
              {!isDesktopCollapsed && <span className="font-bold">Log Out</span>}
            </button>
          </li>
        </ul>
      </nav>
    </>
  );

  return (
    <>
      <div
        className={`fixed inset-0 z-40 bg-black bg-opacity-50 transition-opacity md:hidden ${
          isMobileOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={onMobileClose}
      ></div>
      <aside
        className={`fixed inset-y-0 left-0 z-50 flex flex-col bg-gray-900 text-white w-64 transform transition-transform duration-300 ease-in-out md:hidden ${
          isMobileOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {sidebarContent}
      </aside>
      <aside className={`hidden md:flex flex-col bg-gray-900 text-white transition-all duration-300 ease-in-out ${isDesktopCollapsed ? 'w-20' : 'w-64'}`}>
        {sidebarContent}
      </aside>
    </>
  );
};

export default Sidebar;

import React from 'react';
import { Staff, ActivityLog } from '../types';
import { ArrowLeftIcon, ClockIcon, EyeIcon, PencilIcon, PlusCircleIcon, TrashIcon, DocumentDuplicateIcon, ShieldCheckIcon } from '../components/icons/DummyIcons';

interface StaffActivityPageProps {
  staffMember: Staff;
  logs: ActivityLog[];
  onBack: () => void;
}

const LogIcon: React.FC<{ type: ActivityLog['type'] }> = ({ type }) => {
    // FIX: Added 'Compliance' to iconMap to satisfy Record<ActivityLogType, React.ReactNode>
    const iconMap: Record<ActivityLog['type'], React.ReactNode> = {
        'Login': <ArrowLeftIcon className="w-5 h-5 text-white -rotate-90" />,
        'Logout': <ArrowLeftIcon className="w-5 h-5 text-white rotate-90" />,
        'Create': <PlusCircleIcon className="w-5 h-5 text-white" />,
        'Update': <PencilIcon className="w-5 h-5 text-white" />,
        'Delete': <TrashIcon className="w-5 h-5 text-white" />,
        'View': <EyeIcon className="w-5 h-5 text-white" />,
        'Import': <DocumentDuplicateIcon className="w-5 h-5 text-white" />,
        'Compliance': <ShieldCheckIcon className="w-5 h-5 text-white" />,
    };
    // FIX: Added 'Compliance' to colorMap to satisfy Record<ActivityLogType, string>
    const colorMap: Record<ActivityLog['type'], string> = {
        'Login': 'bg-green-500',
        'Logout': 'bg-gray-500',
        'Create': 'bg-blue-500',
        'Update': 'bg-yellow-500',
        'Delete': 'bg-red-500',
        'View': 'bg-purple-500',
        'Import': 'bg-indigo-500',
        'Compliance': 'bg-amber-600',
    };
    return (
        <div className={`absolute -left-[21px] top-1 w-10 h-10 rounded-full flex items-center justify-center ${colorMap[type]}`}>
            {iconMap[type]}
        </div>
    );
}

// FIX: Changed prop from 'user' to 'staffMember' to match the props interface.
const UserActivityPage: React.FC<StaffActivityPageProps> = ({ staffMember, logs, onBack }) => {
  return (
    <div className="space-y-6">
      <div>
        <button 
          onClick={onBack} 
          className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 transition-colors"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          Back
        </button>
      </div>

      <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <div className="flex flex-col sm:flex-row items-start gap-6">
            <div className="w-24 h-24 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold text-4xl flex-shrink-0">
                {staffMember.initials}
            </div>
            <div className="flex-grow">
                <h1 className="text-3xl font-bold text-gray-800">{staffMember.fullName}</h1>
                <p className="text-gray-500 mt-1">Activity Log</p>
            </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <h3 className="text-lg font-semibold text-gray-800 mb-4">Recent Activities</h3>
        <div className="relative pl-6 border-l-2 border-gray-200">
            {logs.sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).map(log => (
                <div key={log.id} className="mb-8 relative">
                     <LogIcon type={log.type} />
                    <div className="ml-8">
                        <div className="flex items-center justify-between">
                            <p className="text-sm font-semibold text-gray-800">
                                {log.type} Event
                            </p>
                            <p className="text-xs text-gray-400 flex items-center gap-1">
                                <ClockIcon className="w-3 h-3" />
                                {new Date(log.timestamp).toLocaleString()}
                            </p>
                        </div>
                        <p className="mt-1 text-sm text-gray-600">{log.description}</p>
                    </div>
                </div>
            ))}
             {logs.length === 0 && (
                <p className="text-sm text-gray-500">No activity history recorded for this user.</p>
            )}
        </div>
    </div>
    </div>
  );
};

export default UserActivityPage;

import React from 'react';
import { Staff, ActivityLog } from '../types';
import { ArrowLeftIcon, ClockIcon, EyeIcon, PencilIcon, PlusCircleIcon, TrashIcon, UserCircleIcon, ArrowTrendingUpIcon, DocumentDuplicateIcon, ShieldCheckIcon } from '../components/icons/DummyIcons';

