                    </Card>

                    {/* Compliance Variance */}
                    <Card title="Installment Compliance & Variance Analysis" className="p-0 overflow-hidden">
                        <TableContainer className="border-0 shadow-none rounded-none">
                            <table className="w-full text-sm">
                                <Thead>
