interface AnalyticalQueryModalProps {
    isOpen: boolean;
    onClose: () => void;
    clients: Client[];
}

export const AnalyticalQueryModal: React.FC<AnalyticalQueryModalProps> = ({ isOpen, onClose, clients }) => {
    const { sendMail } = useData();
    const [selectedIds, setSelectedIds] = useState<number[]>([]);
    const [search, setSearch] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);
    const [reportView, setReportView] = useState(false);

    const filteredClients = useMemo(() => 
        clients.filter(c => c.name.toLowerCase().includes(search.toLowerCase()))
    , [clients, search]);

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const toggleSelection = (id: number) => {
        setSelectedIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
    };

    const handleGenerate = () => {
        if (selectedIds.length === 0) {
            alert("Requirement: Please select at least one client dossier to query.");
            return;
        }
        setIsGenerating(true);
        setTimeout(() => {
            setIsGenerating(false);
            setReportView(true);
        }, 800);
    };

    const handleMailAudit = async () => {
        if (selectedIds.length === 0) return;

        const auditedClients = clients.filter(c => selectedIds.includes(c.id));
        const body = `Analytical Audit Summary generated on ${new Date().toLocaleDateString()}\n\n` + 
                     auditedClients.map(c => `- ${c.name}: Balance ${formatCurrency(c.payment.balance)} (Status: ${c.status})`).join('\n');

        try {
            await sendMail({
                subject: `FINANCIAL AUDIT: ${auditedClients.length} Client Dossiers`,
                body,
                recipientIds: [], // User will pick recipients in compose
                groupIds: ['ROLE_CEO'],
                attachments: [],
                timestamp: new Date().toISOString(),
                readBy: [],
                isDraft: true
            });
            alert("Audit summary drafted in Internal Mail.");
        } catch (e) {
            alert("Mail distribution failed.");
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-5xl p-0 overflow-hidden shadow-2xl border border-indigo-500/30 flex flex-col max-h-[90vh]">
                <div className="p-5 border-b border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center shrink-0">
                    <div>
                        <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Analytical Client Audit</h3>
                        <p className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Executive Deep Dive Utility</p>
                    </div>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><XMarkIcon className="w-6 h-6" /></button>
                </div>

                {!reportView ? (
                    <div className="flex flex-col h-full overflow-hidden">
                        <div className="p-6 bg-white dark:bg-gray-800 border-b border-gray-100 dark:border-gray-700">
                            <div className="relative">
                                <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                                <input 
                                    type="text" 
                                    placeholder="Search client database..."
