import React, { useState, useMemo } from 'react';
import { Client, Property } from '../../types';
import { XMarkIcon, PrinterIcon, PaperAirplaneIcon, InformationCircleIcon, BuildingLibraryIcon } from '../icons/DummyIcons';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../ui/Table';
import { useData } from '../../context/DataContext';

interface AccountStatementModalProps {
    isOpen: boolean;
    onClose: () => void;
    client: Client;
    properties: Property[];
}

export const AccountStatementModal: React.FC<AccountStatementModalProps> = ({ isOpen, onClose, client, properties }) => {
    const { sendMail } = useData();
    const [startDate, setStartDate] = useState(() => {
        const d = new Date();
        d.setMonth(0); d.setDate(1); // Default Jan 1st of current year
        return d.toISOString().split('T')[0];
    });
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [showWitness, setShowWitness] = useState(true);
    const [isMailing, setIsMailing] = useState(false);

    const propertyInfo = useMemo(() => 
        properties.find(p => p.location === client.location)
    , [properties, client.location]);

    const filteredHistory = useMemo(() => {
        const start = new Date(startDate);
        const end = new Date(endDate);
        return client.payment.paymentHistory.filter(txn => {
            const txnDate = new Date(txn.date);
            return txnDate >= start && txnDate <= end;
        }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    }, [client.payment.paymentHistory, startDate, endDate]);

    // Financial Calculation Logic
    const ledger = useMemo(() => {
        let runningBalance = client.payment.total;
        const entries = [];

        // Initial Entry (Initial Purchase Value)
        entries.push({
            date: client.regDate,
            description: 'INITIAL PURCHASE VALUE',
            debit: client.payment.total,
            credit: 0,
            balance: runningBalance
        });

        // Map Payments
        client.payment.paymentHistory.forEach(txn => {
            runningBalance -= txn.amount;
            entries.push({
                date: txn.date,
                description: `${txn.method.toUpperCase()} PAYMENT (RECEIPT: ${txn.receiptNumber})`,
                debit: 0,
                credit: txn.amount,
                balance: runningBalance
            });
        });

        return entries;
    }, [client]);

    const periodCredit = useMemo(() => 
        filteredHistory.reduce((s, t) => s + t.amount, 0)
    , [filteredHistory]);

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const handlePrint = () => {
        window.print();
    };

    const handleSendMail = async () => {
        setIsMailing(true);
        try {
            await sendMail({
                subject: `Financial Statement: ${client.name} - ${new Date().toLocaleDateString()}`,
                body: `Attached is the generated financial account statement for ${client.name} for the period ${startDate} to ${endDate}.\n\nTotal Paid in Period: ${formatCurrency(periodCredit)}\nOutstanding Balance: ${formatCurrency(client.payment.balance)}`,
                recipientIds: [], // Management will choose in compose
                groupIds: ['ROLE_CEO'],
                attachments: [], // In real world, would attach a PDF blob
                timestamp: new Date().toISOString(),
                readBy: [],
                isDraft: true
            });
            alert("Statement draft created in Internal Mailing system.");
        } finally {
            setIsMailing(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md overflow-hidden">
            <Card className="w-full max-w-5xl h-[95vh] p-0 flex flex-col shadow-2xl border border-indigo-500/30 overflow-hidden">
                {/* Header / Query Controls */}
                <div className="p-4 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 flex flex-wrap items-center justify-between gap-4 print:hidden shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Period</span>
                            <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="text-xs p-1 rounded border border-gray-200 dark:bg-gray-800" />
                            <span className="text-gray-400">→</span>
                            <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="text-xs p-1 rounded border border-gray-200 dark:bg-gray-800" />
                        </div>
                        <label className="flex items-center gap-2 cursor-pointer">
                            <input type="checkbox" checked={showWitness} onChange={e => setShowWitness(e.target.checked)} className="rounded" />
                            <span className="text-xs text-gray-600 dark:text-gray-400 font-bold uppercase">Show Witness Details</span>
                        </label>
                    </div>
                    <div className="flex gap-2">
                        <Button variant="secondary" size="sm" icon={<PrinterIcon className="w-4 h-4" />} onClick={handlePrint}>Print / Export</Button>
                        <Button variant="secondary" size="sm" icon={<PaperAirplaneIcon className="w-4 h-4 -rotate-45" />} onClick={handleSendMail} isLoading={isMailing}>Internal Dispatch</Button>
                        <button onClick={onClose} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"><XMarkIcon className="w-6 h-6 text-gray-400" /></button>
                    </div>
                </div>

                {/* THE STATEMENT (Printable Area) */}
                <div id="printable-statement" className="flex-grow bg-white dark:bg-gray-950 p-8 md:p-12 overflow-y-auto scrollbar-thin text-black dark:text-gray-200">
                    <div className="max-w-4xl mx-auto space-y-10">

                        {/* Section I: Identity */}
                        <div className="flex justify-between items-start border-b-2 border-black dark:border-gray-700 pb-6">
                            <div className="space-y-4">
                                <div className="flex items-center gap-3">
                                    <BuildingLibraryIcon className="w-12 h-12 text-indigo-600" />
                                    <div>
                                        <h1 className="text-2xl font-black tracking-tighter uppercase">FAIM Legacy ERP</h1>
                                        <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Real Estate Financial Services</p>
                                    </div>
                                </div>
                                <div className="text-xs space-y-1">
                                    <p className="font-black text-indigo-600 uppercase tracking-widest">Account Holder</p>
                                    <p className="text-lg font-bold">{client.name}</p>
                                    <p className="text-gray-500 max-w-xs">{client.location || 'N/A'}</p>
                                    {showWitness && <p className="text-gray-400 italic">Witness: {client.witness.name || 'Not Applicable'}</p>}
                                </div>
                            </div>
                            <div className="text-right space-y-2">
                                <h2 className="text-xl font-black uppercase tracking-tight">Statement</h2>
                                <div className="text-xs space-y-1 font-medium">
                                    <p className="text-gray-400 uppercase text-[9px] font-black">Reference ID</p>
                                    <p className="font-mono bg-gray-100 dark:bg-gray-900 px-2 py-0.5 rounded">{client.initials}-{client.id.toString().padStart(4, '0')}</p>
                                    <p className="text-gray-400 uppercase text-[9px] font-black mt-2">Statement Period</p>
                                    <p>{startDate} to {endDate}</p>
                                </div>
                            </div>
                        </div>

                        {/* Section II: Land & Contract Details */}
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 p-6 bg-gray-50 dark:bg-gray-900/50 rounded-2xl border border-gray-100 dark:border-gray-800">
                            <div className="space-y-1">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Asset Location</span>
                                <p className="text-xs font-bold truncate">{client.location}</p>
                            </div>
                            <div className="space-y-1">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Inventory Ref</span>
                                <p className="text-xs font-bold">{client.plot}</p>
                            </div>
                            <div className="space-y-1">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Price / Plot</span>
                                <p className="text-xs font-bold">{formatCurrency(propertyInfo?.price || 0)}</p>
                            </div>
                            <div className="space-y-1">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Plan Option</span>
                                <p className="text-xs font-bold uppercase">{client.payment.planType}</p>
                            </div>
                        </div>

                        {/* Section III: Transaction Ledger */}
                        <div className="space-y-4">
                            <h3 className="text-sm font-black uppercase tracking-widest border-l-4 border-black dark:border-white pl-3 py-1">Transactional History</h3>
                            <TableContainer className="border-0 shadow-none bg-transparent">
                                <table className="w-full text-xs text-left border-collapse">
                                    <Thead>
                                        <tr className="border-b border-black dark:border-gray-700">
                                            <Th className="px-2 py-3 bg-transparent text-black dark:text-white">Date</Th>
                                            <Th className="px-2 py-3 bg-transparent text-black dark:text-white">Description</Th>
                                            <Th className="px-2 py-3 bg-transparent text-black dark:text-white text-right">Debit (Dr)</Th>
                                            <Th className="px-2 py-3 bg-transparent text-black dark:text-white text-right">Credit (Cr)</Th>
                                            <Th className="px-2 py-3 bg-transparent text-black dark:text-white text-right">Balance</Th>
                                        </tr>
                                    </Thead>
                                    <Tbody>
                                        {ledger.map((entry, idx) => {
                                            const entryDate = new Date(entry.date);
                                            const isQueried = entryDate >= new Date(startDate) && entryDate <= new Date(endDate);

                                            return (
                                                <Tr key={idx} className={`border-b border-gray-100 dark:border-gray-800 ${isQueried ? '' : 'opacity-25 grayscale'}`}>
                                                    <Td className="px-2 py-4 font-mono">{entry.date}</Td>
                                                    <Td className="px-2 py-4 font-bold uppercase tracking-tight">{entry.description}</Td>
                                                    <Td className="px-2 py-4 text-right">{entry.debit > 0 ? formatCurrency(entry.debit) : ''}</Td>
                                                    <Td className="px-2 py-4 text-right text-green-600 font-bold">{entry.credit > 0 ? formatCurrency(entry.credit) : ''}</Td>
                                                    <Td className="px-2 py-4 text-right font-black">{formatCurrency(entry.balance)}</Td>
                                                </Tr>
                                            );
                                        })}
                                        {ledger.length === 0 && (
                                            <Tr><Td colSpan={5} className="py-20 text-center text-gray-400 italic">No transactional data recorded.</Td></Tr>
                                        )}
                                    </Tbody>
                                </table>
                            </TableContainer>
                        </div>

                        {/* Section IV: Performance Summary */}
                        <div className="flex flex-col md:flex-row gap-8 pt-6 border-t-2 border-black dark:border-gray-700">
                            <div className="flex-grow space-y-4">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-400">Account Summary Indicators</h4>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="p-4 bg-gray-50 dark:bg-gray-900 rounded-xl">
                                        <p className="text-[9px] font-black text-gray-400 uppercase mb-1">Total Paid (Life)</p>
                                        <p className="text-lg font-black text-green-600">{formatCurrency(client.payment.paid)}</p>
                                    </div>
                                    <div className="p-4 bg-gray-50 dark:bg-gray-900 rounded-xl">
                                        <p className="text-[9px] font-black text-gray-400 uppercase mb-1">Status</p>
                                        <Badge variant={client.payment.balance <= 0 ? 'success' : 'danger'} className="text-[10px] font-black px-3 py-1">
                                            {client.payment.balance <= 0 ? 'COMPLETED' : 'ACTIVE / OWING'}
                                        </Badge>
                                    </div>
                                </div>
                            </div>
                            <div className="md:w-72 bg-black dark:bg-white p-6 rounded-2xl text-white dark:text-black flex flex-col justify-center items-end text-right">
                                <p className="text-[10px] font-black uppercase tracking-widest opacity-60">Balance Outstanding</p>
                                <p className="text-3xl font-black tracking-tighter">{formatCurrency(client.payment.balance)}</p>
                                <p className="text-[10px] mt-4 font-bold opacity-40 italic">Calculated as at {endDate}</p>
                            </div>
                        </div>

                        {/* Footer */}
                        <div className="pt-12 text-center text-[10px] text-gray-400 uppercase font-bold tracking-widest space-y-1">
                            <p>This document constitutes a system-generated audit trail from FAIM Legacy ERP.</p>
                            <p>Official Verification Required for Mortgage or Title Transfer Applications.</p>
                        </div>
                    </div>
                </div>

                <style>{`
                    @media print {
                        body { background: white !important; }
                        #printable-statement { overflow: visible !important; height: auto !important; padding: 0 !important; color: black !important; }
                        #printable-statement .max-w-4xl { max-width: 100% !important; margin: 0 !important; }
                        .fixed, .print\\:hidden, .sidebar, .header, nav, button { display: none !important; }
                        .bg-gray-50 { background-color: #f9fafb !important; }
                        .bg-gray-100 { background-color: #f3f4f6 !important; }
                        .bg-black { background-color: black !important; }
                        .text-white { color: white !important; }
                        .dark { background: white !important; color: black !important; }
                        .dark .bg-gray-900 { background-color: #f9fafb !important; }
                        .dark .text-white { color: black !important; }
                        .dark .border-gray-800 { border-color: #eee !important; }
                        @page { margin: 2cm; size: A4; }
                    }
                `}</style>
            </Card>
        </div>
    );
};

