                                <button 
                                    onClick={() => alert("The 'Link Existing Client' modal would open here to search allClients.")}
                                    className="text-xs font-black text-blue-600 hover:underline flex items-center gap-1 uppercase"
                                >
                                    <PlusCircleIcon className="w-4 h-4" /> Link Existing
                                </button>
                            )}
                        </div>

                        <TableContainer className="border-none shadow-none rounded-none">
                            <table className="w-full text-xs text-left">
