                                                <Td className="px-2 py-3 font-mono opacity-60">{member.initials}-{member.id}</Td>
                                                <Td className="px-2 py-3">
                                                    <Badge variant={member.payment.balance <= 0 ? 'success' : 'warning'}>
                                                        {member.payment.balance <= 0 ? 'Settled' : 'Owing'}
                                                    </Badge>
                                                </Td>
                                                <Td className="px-2 py-3 text-right font-black">
                                                    {formatCurrency(member.payment.balance)}
                                                </Td>
                                                <Td className="px-2 py-3 text-right">
                                                    <div className="flex justify-end gap-1">
                                                        <button onClick={() => setActivePage('Client Details', member)} className="p-1 text-gray-400 hover:text-blue-500 transition-colors" title="View Member"><EyeIcon className="w-4 h-4"/></button>
                                                        {canManageLinks && (
                                                            <button onClick={() => handleDetachMember(member)} className="p-1 text-gray-400 hover:text-red-500 transition-colors" title="Detach Member"><TrashIcon className="w-4 h-4"/></button>
                                                        )}
                                                    </div>
                                                </Td>
                                            </Tr>
                                        ))
                                    ) : (
                                        <Tr>
                                            <Td colSpan={5} className="py-8 text-center text-gray-400 italic">No members linked to this group account yet.</Td>
                                        </Tr>
                                    )}
                                </Tbody>
                            </table>
