          </div>
      )}

      {activeTab === 'milestones' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
              <ClientDocumentationPage clients={[client]} onSaveClient={saveClient} fixedClientId={client.id} />
