}

export const AccountStatementModal: React.FC<AccountStatementModalProps> = ({ isOpen, onClose, client, properties }) => {
    const { sendMail } = useData();
    const { clients: allClients } = useClients(); // Used to fetch linked members

    const [startDate, setStartDate] = useState(() => {
        const d = new Date();
        d.setMonth(0); d.setDate(1); // Default to Jan 1st
        return d.toISOString().split('T')[0];
    });
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [includePlots, setIncludePlots] = useState(true);
    const [includeMembersList, setIncludeMembersList] = useState(false); // New state
    const [isMailing, setIsMailing] = useState(false);

    const isGroup = client.clientType === 'Corporate/Group';

    const linkedMembers = useMemo(() => {
        if (!isGroup) return [];
        return allClients.filter(c => c.companyId === client.id);
    }, [allClients, client.id, isGroup]);

    const propertyInfo = useMemo(() => 
        properties.find(p => p.location === client.location)
    , [properties, client.location]);

    const statementData = useMemo(() => {
        const start = new Date(startDate);
        const end = new Date(endDate);
        const today = new Date();

        const fullHistory = [...client.payment.paymentHistory].sort((a, b) => 
            new Date(a.date).getTime() - new Date(b.date).getTime()
        );

        let runningBalance = client.payment.total;
        const ledgerEntries: any[] = [];
        let totalPaidInPeriod = 0;

        if (fullHistory.length === 0) {
            ledgerEntries.push({
                type: 'Initial Deposit',
                expectedDate: client.regDate,
                actualDate: '',
                amount: 0,
                status: new Date(client.regDate) < today ? 'Overdue' : 'Pending',
                balance: runningBalance
            });
        } else {
            fullHistory.forEach((txn, idx) => {
                runningBalance -= txn.amount;
                const txnDate = new Date(txn.date);
                const rowType = idx === 0 ? 'Initial Deposit' : 'Instalment Payment';

                let status = 'Paid';
                if (txn.status === 'Failed') status = 'Adjustment';
                else if (txn.amount > (client.payment.total / 12)) status = 'Advance';

                if (txnDate >= start && txnDate <= end) {
                    totalPaidInPeriod += txn.amount;
                }

                ledgerEntries.push({
                    type: rowType,
                    expectedDate: client.regDate,
                    actualDate: txn.date,
                    amount: txn.amount,
                    status: status,
                    balance: runningBalance
                });
            });
        }

        return {
            ledgerEntries,
            totalPaidInPeriod,
            closingBalance: runningBalance
        };
    }, [client, startDate, endDate]);

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'Paid': return <Badge variant="success">Paid</Badge>;
            case 'Partial': return <Badge variant="warning">Partial</Badge>;
            case 'Overdue': return <Badge variant="danger">Overdue</Badge>;
            case 'Advance': return <Badge variant="purple">Advance</Badge>;
            default: return <Badge variant="neutral">{status}</Badge>;
        }
    };

    const handlePrint = () => window.print();

    const handleSendMail = async () => {
        setIsMailing(true);
        try {
            await sendMail({
                senderId: '', 
                senderName: '', 
                participants: [],
                subject: `FINANCIAL STATEMENT: ${client.name} - ${new Date().toLocaleDateString()}`,
                body: `Auto-Generated Statement for ${client.name} for the period ${startDate} to ${endDate}.\nTotal Paid: ${formatCurrency(statementData.totalPaidInPeriod)}\nBalance: ${formatCurrency(client.payment.balance)}`,
                recipientIds: [],
                groupIds: ['ROLE_CEO', 'ROLE_ACCOUNTS_HEAD'],
                attachments: [],
                timestamp: new Date().toISOString(),
                readBy: [],
                isDraft: true
            });
            alert("Statement draft sent to Internal Mail.");
        } finally {
            setIsMailing(false);
        }
    };

