            case 'Human Resources': return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts': return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot': return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation': return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings': return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form': return <AmendmentFormPage client={pageContext} onBack={() => handleSetPage('Client Details', pageContext)} onSave={async (data, updatedClient) => { setAmendmentList(prev => [data, ...prev]); await saveClient(updatedClient); handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`); alert('Amendment processed successfully!'); handleSetPage('Client Details', updatedClient); }} currentStaff={currentStaff!} />;
            case 'Analytics & Reports': return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports': return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity': return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Support': return <SupportPage />;
            default: return <Dashboard />;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff!} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
            <ModalManager />
        </Layout>
    );
};

const AppContent: React.FC = () => {
    const { loading, sessionStatus, currentStaff, login, authError } = useAuth();
    const { companySettings } = useCompanySettings();

    // Effect to update favicon and page title
    useEffect(() => {
        if (companySettings.name) {
            document.title = `${companySettings.name} - Enterprise Dashboard`;
        }
        if (companySettings.favicon) {
            let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
            if (!link) {
                link = document.createElement('link');
                link.rel = 'icon';
                document.getElementsByTagName('head')[0].appendChild(link);
            }
            link.href = companySettings.favicon;
        }
    }, [companySettings.name, companySettings.favicon]);

    // Application Lifecycle Guard
    if (loading || sessionStatus === 'authenticating' || sessionStatus === 'resolving_profile' || sessionStatus === 'bootstrapping') {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-950">
                <LoaderIcon className="w-12 h-12 text-blue-600 animate-spin mb-4" />
                <p className="text-sm font-bold text-gray-400 uppercase tracking-widest animate-pulse">
                    {sessionStatus === 'bootstrapping' ? 'Initializing profile...' : 'Authorizing access...'}
                </p>
            </div>
        );
    }

    // Auth Error or Missing Profile Gating
    if (!currentStaff) {
        return (
            <LoginPage 
                onLogin={login} 
                companySettings={companySettings} 
                externalError={authError} 
            />
        );
    }

    return <AuthenticatedApp />;
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <ModalProvider>
                    <AuthProvider>
                        <DataProvider>
                            <AppContent />
                        </DataProvider>
                    </AuthProvider>
                </ModalProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Client, Milestone, Property, Invoice, ActivityLog, Staff } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { VariableSizeList as List } from 'react-window';
import { useClients, useStaff } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';
import { useData } from '../context/DataContext';
import { useAuth } from '../context/AuthContext';

// Modular Imports
import { ClientListHeader } from '../components/clients/ClientListHeader';
import { ClientFilters } from '../components/clients/ClientFilters';
import { ClientTableHead } from '../components/clients/ClientTableHead';
import { ClientsList } from '../components/clients/ClientsList';

interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string, context?: any) => void;
    setClientForInvoice: (client: Client | null) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (formData: FormData): boolean => {
    const requiredFields: (keyof FormData)[] = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    for (const field of requiredFields) {
        if (!formData[field] || String(formData[field]).trim() === '') return false;
    }
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);
    const { sendMail } = useData();
    const { staff } = useStaff();
    const { currentStaff } = useAuth();

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [deletedClientInfo, setDeletedClientInfo] = useState<{ name: string; timeoutId: ReturnType<typeof setTimeout> } | null>(null);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    // Virtualization State
    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});

    // --- SCROLL ANIMATION LOGIC ---
    const [scrollOffset, setScrollOffset] = useState(0);
    const MAX_SCROLL = 80;

    const handleScroll = ({ scrollOffset: offset }: { scrollOffset: number }) => {
        setScrollOffset(Math.min(offset, MAX_SCROLL));
    };

    const headerOpacity = Math.max(0, 1 - scrollOffset / (MAX_SCROLL * 0.8));
    const headerHeight = Math.max(0, 48 - (scrollOffset / MAX_SCROLL) * 48);
    const controlsTranslate = (scrollOffset / MAX_SCROLL) * -52;

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const handleDeleteClick = useCallback((clientId: number) => {
        const client = clients.find(c => c.id === clientId);
        if (client) setClientToDelete(client);
    }, [clients]);

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);
            const timeoutId = setTimeout(() => setDeletedClientInfo(null), 3000);
            setDeletedClientInfo({ name: clientToDelete.name, timeoutId });
            setClientToDelete(null);
        }
    };

    const createClientObject = (formData: FormData, id: number, existingClient?: Client | null): Client => {
        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();
        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;
        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }
        const isComplete = isClientDataComplete(formData);

        const clientType = (formData as any).clientType || 'Individual';

        const baseClient = existingClient || {
            id: id, 
            clientType,
            status: 'Active Client' as const, 
            stage: milestones[0]?.acronym || 'N/A',
            payment: { total: baseTotal, paid: 0, balance: baseTotal, dueDate: 'N/A', planType: 'N/A', promoDetails: promoDetails, paymentHistory: [], installments: [] },
            interactions: [], documentation: { status: 'Pending' },
            officeUse: { commission: { type: 'Percentage', amount: 0, status: 'Pending' } }
        };
        return {
            ...baseClient, id, 
            clientType, 
            name: fullName, surname: formData.surname, otherNames: formData.otherNames, initials,
            regDate: formData.paymentDate, email: formData.email, phone: formData.telephone, dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'], location: formData.location, plot: formData.plotNumber, photo: formData.photo,
            propertyType: formData.propertyType, plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: { placeOfWork: formData.placeOfWork, profession: formData.profession, position: formData.position },
            witness: { name: formData.witnessName, address: formData.witnessAddress, phone: formData.witnessPhone },
            nextOfKin: { name: formData.kinName, phone: formData.kinPhone, relationship: formData.kinRelationship, email: formData.kinEmail, address: formData.kinAddress },
            indenture: { name: formData.indentureName, address: formData.indentureAddress },
            officeUse: { ...baseClient.officeUse, salesRep: formData.salesRep, salesManager: formData.salesManager, accountsHead: formData.accountsHead, clerk: formData.clerk },
            isComplete, filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClientAndRedirect = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            const isNewClient = !editingClient;
            const newId = editingClient ? editingClient.id : (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

            if (!newId) {
                alert("Error: Client ID could not be generated. Please retry.");
                return;
            }

            let photoUrl = formData.photo;
            if (files?.photo) photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId, editingClient);

            const savedClient = await onSaveClient(newClient);

            if (!savedClient) {
                alert("Error: Client data not saved correctly.");
                return;
            }

            // TRIGGER: Notification to Chief Accountant (Head of Accounts)
            // Rule: Only if actor is Front Desk Executive and this is a NEW client entry
            if (isNewClient && currentStaff?.roleId === 'Front Desk Executive') {
                const chiefAccountants = staff.filter(s => s.roleId === 'Chief Accountant');

                if (chiefAccountants.length > 0) {
                    await sendMail({
                        senderId: currentStaff.id,
                        senderName: currentStaff.fullName,
                        recipientIds: chiefAccountants.map(s => s.id),
                        groupIds: [], 
                        subject: 'ACTION REQUIRED: New Client Ledger Initialization',
                        body: `A new client record has been created and requires financial setup.\n\nClient: ${savedClient.name}\nReference: ${savedClient.initials}-${savedClient.id}\nProperty: ${savedClient.location}\n\nPlease proceed to Account Management to initialize the financial commitment and payment plan for this account.\n\nDate Registered: ${new Date().toLocaleString()}`,
                        attachments: [],
                        timestamp: new Date().toISOString(),
                        readBy: [currentStaff.id],
                        isDraft: false,
                        isDeleted: false,
                        targetPage: 'Account Management',
                        targetContext: savedClient
                    });
                } else {
                    // Log undelivered notification for CEO oversight
                    addActivityLog('Update', `System Warning: No Chief Accountant found to receive onboarding notification for client ${savedClient.name}.`);
                }
            }

            setClientFormOpen(false);
            addActivityLog(editingClient ? 'Update' : 'Create', `Processed client: ${savedClient.name}`);

            // Auto-Redirect to Client Details
            onClientSelect(savedClient);

        } catch (error) { 
            console.error("Save failed:", error);
            alert("Failed to save client."); 
        }
    };

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            <div className="bg-gray-100 dark:bg-gray-950 z-20 flex-shrink-0 transition-all duration-300 ease-out"
                 style={{ transform: `translateY(${controlsTranslate}px)` }}>

                <ClientListHeader 
                    clientCount={clients.length} 
                    hasNextPage={hasNextPage} 
                    onImportClick={() => setImportWizardOpen(true)}
                    onNewClientClick={() => { setEditingClient(null); setClientFormOpen(true); }}
                    headerOpacity={headerOpacity}
                    headerHeight={headerHeight}
                />

                <ClientFilters 
                    searchTerm={searchTerm} 
                    onSearchChange={setSearchTerm} 
                    isLoading={isLoading} 
                    properties={properties} 
                />

                <ClientTableHead />
            </div>

            <ClientsList 
                clients={clients}
                onViewDetails={onClientSelect}
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }}
                onDelete={handleDeleteClick}
                milestones={milestones}
                expandedIds={expandedIds}
                toggleExpand={toggleExpand}
                onScroll={handleScroll}
                listRef={listRef}
            />

            {hasNextPage && !debouncedSearchTerm && (
                <div className="py-3 text-center border-t border-gray-200 dark:border-gray-800 flex-shrink-0">
                    <button 
                        onClick={() => fetchNextPage()} 
                        disabled={isFetchingNextPage}
                        className="text-blue-600 dark:text-blue-400 text-xs font-black uppercase tracking-widest hover:underline disabled:opacity-50"
                    >
                        {isFetchingNextPage ? 'Loading...' : 'Load More Results'}
                    </button>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={() => { setClientFormOpen(false); setEditingClient(null); }}
                onSave={handleSaveClientAndRedirect}
                onSaveAndPay={handleSaveClientAndRedirect}
                properties={properties}
                editingClient={editingClient}
                clients={clients}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={() => {}}
                requiredHeaders={requiredCsvHeaders}
                sampleHeaders=""
                sampleData=""
                wizardTitle="Import Client Data"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                // FIX: Changed setDeleteClient to setClientToDelete to fix the missing name error on line 277.
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />
        </div>
    );
};

export default ClientsPage;

import React, { useState, useRef, useEffect } from 'react';
import { MenuIcon } from './icons/MenuIcon';
import { BellIcon, MagnifyingGlassIcon, ArrowRightOnRectangleIcon, EnvelopeIcon, CheckCircleIcon } from './icons/DummyIcons';
import { Staff } from '../types';
import { ROLES } from '../data/mockData';
import ThemeToggle from './ThemeToggle';

export interface HeaderNotification {
    id: string;
    title: string;
    description: string;
    timestamp: string;
    type: 'mail' | 'alert';
    targetPage: string;
    targetContext?: any;
}

interface HeaderProps {
  onMobileMenuToggle: () => void;
  onDesktopToggle: () => void;
  isDesktopCollapsed: boolean;
  currentStaff: Staff;
  onLogout: () => void;
  setActivePage: (page: string, context?: any) => void;
  notifications?: HeaderNotification[];
  unreadMailsCount?: number; // New prop for mail indicator
}

const Header: React.FC<HeaderProps> = ({ 
    onMobileMenuToggle, 
    onDesktopToggle, 
    isDesktopCollapsed, 
    currentStaff, 
    onLogout, 
    setActivePage,
    notifications = [],
    unreadMailsCount = 0
}) => {
  const [isProfileOpen, setProfileOpen] = useState(false);
  const [isNotifOpen, setNotifOpen] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);
  const profileRef = useRef<HTMLDivElement>(null);

  const staffRole = ROLES.find(r => r.id === currentStaff.roleId)?.name || 'Staff';

  // Close dropdowns when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
            setNotifOpen(false);
        }
        if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
            setProfileOpen(false);
        }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleNotificationClick = (n: HeaderNotification) => {
      setActivePage(n.targetPage, n.targetContext);
      setNotifOpen(false);
  };

  return (
    <header className="flex items-center justify-between h-20 px-4 sm:px-6 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-30 transition-colors duration-200">
      {/* Mobile Menu Button & Search */}
      <div className="flex items-center gap-4">
        <button
          onClick={onMobileMenuToggle}
          className="md:hidden text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white"
          aria-label="Open sidebar"
        >
          <MenuIcon className="w-6 h-6" />
        </button>

        <button
          onClick={onDesktopToggle}
          className="hidden md:block text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white transition-colors"
          aria-label={isDesktopCollapsed ? "Expand sidebar" : "Collapse sidebar"}
        >
          <MenuIcon className="w-6 h-6" />
        </button>

        <div className="hidden md:block relative">
           <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500" />
            <input
                type="text"
                placeholder="Search..."
                className="bg-gray-100 dark:bg-gray-900 border border-transparent dark:border-gray-700 rounded-lg pl-10 pr-4 py-2 w-64 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
            />
        </div>
      </div>

      {/* Right side icons and profile */}
      <div className="flex items-center gap-4">
        <ThemeToggle />

        {/* Internal Mail Icon - UX Enhancement */}
        <button 
            onClick={() => setActivePage('Mailing')}
            title="Mail"
            className={`relative p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors group ${unreadMailsCount > 0 ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}
        >
            <EnvelopeIcon className="w-6 h-6" />
            {unreadMailsCount > 0 && (
                <span className="absolute top-1 right-1 flex h-4 w-4">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-4 w-4 bg-blue-600 text-[9px] text-white items-center justify-center font-bold">
                        {unreadMailsCount > 99 ? '99+' : unreadMailsCount}
                    </span>
                </span>
            )}
        </button>

        {/* Notification Bell */}
        <div className="relative" ref={notifRef}>
            <button 
                onClick={() => setNotifOpen(!isNotifOpen)}
                title="Notifications"
                className="relative text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
            >
                <BellIcon className="w-6 h-6" />
                {notifications.length > 0 && (
                    <span className="absolute top-1 right-1 flex h-4 w-4">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[9px] text-white items-center justify-center font-bold">
                            {notifications.length > 9 ? '9+' : notifications.length}
                        </span>
                    </span>
                )}
            </button>

            {/* Notification Dropdown */}
            {isNotifOpen && (
                <div className="absolute right-0 mt-2 w-80 bg-white dark:bg-gray-800 rounded-xl shadow-2xl py-2 z-50 border border-gray-100 dark:border-gray-700 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="px-4 py-2 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
                        <h3 className="font-bold text-gray-900 dark:text-white text-sm">Notifications</h3>
                        <span className="text-[10px] bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-300 px-2 py-0.5 rounded-full font-bold">
                            {notifications.length} Pending
                        </span>
                    </div>
                    <div className="max-h-80 overflow-y-auto scrollbar-thin">
                        {notifications.length === 0 ? (
                            <div className="p-6 text-center">
                                <CheckCircleIcon className="w-10 h-10 mx-auto text-gray-300 mb-2" />
                                <p className="text-sm text-gray-500">All caught up!</p>
                            </div>
                        ) : (
                            notifications.slice(0, 5).map((n) => (
                                <button 
                                    key={n.id}
                                    onClick={() => handleNotificationClick(n)}
                                    className="w-full text-left p-3 hover:bg-gray-50 dark:hover:bg-gray-700/50 border-b border-gray-50 dark:border-gray-700 last:border-0 flex gap-3 transition-colors group"
                                >
                                    <div className={`mt-1 w-2 h-2 rounded-full flex-shrink-0 ${n.type === 'alert' ? 'bg-red-500' : 'bg-blue-500'}`} />
                                    <div>
                                        <p className="text-sm font-bold text-gray-800 dark:text-gray-200 group-hover:text-blue-600 dark:group-hover:text-blue-400 truncate w-60">
                                            {n.title}
                                        </p>
                                        <p className="text-xs text-gray-500 dark:text-gray-400 line-clamp-2 leading-tight">
                                            {n.description}
                                        </p>
                                        <p className="text-[10px] text-gray-400 mt-1 font-mono">
                                            {new Date(n.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                        </p>
                                    </div>
                                </button>
                            ))
                        )}
                    </div>
                    {notifications.length > 0 && (
                        <div className="px-4 py-2 border-t border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/50 text-center">
                            <button 
                                onClick={() => { setActivePage('Account Management'); setNotifOpen(false); }}
                                className="text-xs font-bold text-blue-600 hover:text-blue-800 dark:hover:text-blue-400 uppercase tracking-widest"
                            >
                                View All Alerts
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>

        {/* Profile Dropdown */}
        <div className="relative" ref={profileRef}>
             <button onClick={() => setProfileOpen(!isProfileOpen)} className="flex items-center gap-3 cursor-pointer">
                 {currentStaff.photo ? (
                    <img src={currentStaff.photo} alt="Profile" className="w-10 h-10 rounded-full object-cover border-2 border-gray-200 dark:border-gray-600" />
                 ) : (
                    <div className="w-10 h-10 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold border-2 border-transparent">
                        {currentStaff.initials}
                    </div>
                 )}
                <div className="hidden sm:block text-left">
                    <p className="text-sm font-semibold text-gray-800 dark:text-white">{currentStaff.fullName}</p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">{staffRole}</p>
                </div>
            </button>
             {isProfileOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-md shadow-lg py-1 z-50 ring-1 ring-black ring-opacity-5 dark:ring-gray-700 animate-in fade-in slide-in-from-top-2 duration-200">
                    <button onClick={() => { setActivePage('Settings'); setProfileOpen(false); }} className="w-full text-left block px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">Profile</button>
                    <button onClick={onLogout} className="w-full text-left flex items-center gap-2 px-4 py-2 text-sm text-red-700 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20">
                       <ArrowRightOnRectangleIcon className="w-5 h-5" /> Sign Out
                    </button>
                </div>
            )}
        </div>
      </div>
    </header>
  );
};

export default Header;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Sidebar from './Sidebar';
import Header, { HeaderNotification } from './Header';
import { Staff, PermissionSet, CompanySettings } from '../types';
import { useData } from '../context/DataContext';
import { useClients, useRoles } from '../hooks/useAppData';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { ToastNotification } from './ui/ToastNotification';

interface LayoutProps {
    children: React.ReactNode;
    activePage: string;
    setActivePage: (page: string, context?: any) => void;
    currentStaff: Staff;
    onLogout: () => void;
    staffPermissions: { [key: string]: PermissionSet };
    companySettings: CompanySettings;
}

const Layout: React.FC<LayoutProps> = ({ children, activePage, setActivePage, currentStaff, onLogout, staffPermissions, companySettings }) => {
    const [isMobileSidebarOpen, setMobileSidebarOpen] = useState(false);
    const [isDesktopSidebarCollapsed, setDesktopSidebarCollapsed] = useState(false);

    // Data Hooks for Notifications
    const { internalMails } = useData();
    const { clients } = useClients(); // Needed for triggers
    const { roles } = useRoles(); // Needed to map Role Name

    const systemAlerts = useNotificationTriggers(clients);

    // -- Global Notification Aggregation --
    const headerNotifications = useMemo(() => {
        const aggregated: HeaderNotification[] = [];
        const userRoleName = roles.find(r => r.id === currentStaff.roleId)?.name;

        // 1. Filter System Alerts by Role
        const myAlerts = systemAlerts.filter(alert => alert.recipientRole === userRoleName && !alert.isRead);
        myAlerts.forEach(alert => {
            aggregated.push({
                id: alert.id,
                title: alert.title,
                description: alert.message,
                timestamp: alert.timestamp,
                type: 'alert',
                targetPage: 'Account Management',
                targetContext: null 
            });
        });

        // 2. Filter Unread Mails
        const myMails = internalMails.filter(m => 
            m.recipientIds.includes(currentStaff.id) && 
            !m.readBy.includes(currentStaff.id) && 
            !m.isDeleted
        );
        myMails.forEach(mail => {
            aggregated.push({
                id: mail.id,
                title: mail.subject,
                description: mail.body.length > 80 ? `${mail.body.substring(0, 80)}...` : mail.body,
                timestamp: mail.timestamp,
                type: 'mail',
                // Support deep links from system-generated mails
                targetPage: mail.targetPage || 'Mailing',
                targetContext: mail.targetContext || null
            });
        });

        // Sort by newest
        return aggregated.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [systemAlerts, internalMails, currentStaff, roles]);

    // Calculate unread mail count for the header indicator
    const unreadMailsCount = useMemo(() => {
        if (!currentStaff) return 0;
        return internalMails.filter(m => 
            m.recipientIds.includes(currentStaff.id) && 
            !m.readBy.includes(currentStaff.id) && 
            !m.isDeleted && 
            !m.isDraft
        ).length;
    }, [internalMails, currentStaff]);


    // -- Toast Notification Logic (For Real-time popups) --
    const [toast, setToast] = useState<{ message: string; subtext: string } | null>(null);
    const prevMailsLengthRef = useRef(internalMails.length);
    const initialLoadRef = useRef(true);

    useEffect(() => {
        if (initialLoadRef.current) {
            initialLoadRef.current = false;
            prevMailsLengthRef.current = internalMails.length;
            return;
        }

        if (internalMails.length > prevMailsLengthRef.current) {
            // New mail detected
            const newMails = internalMails.slice(0, internalMails.length - prevMailsLengthRef.current);
            const latestMail = newMails[0]; // Just show latest if multiple

            // Only notify if we are the recipient and didn't send it ourselves
            if (latestMail && latestMail.recipientIds.includes(currentStaff.id) && latestMail.senderId !== currentStaff.id) {
                setToast({
                    message: latestMail.subject.includes('New Client') ? 'Onboarding Alert' : `New Message from ${latestMail.senderName}`,
                    subtext: latestMail.subject
                });
                // Play notification sound
                try {
                    const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
                    audio.volume = 0.5;
                    audio.play().catch(() => {}); // Ignore interaction errors
                } catch(e) {}
            }
        }
        prevMailsLengthRef.current = internalMails.length;
    }, [internalMails, currentStaff.id]);

    return (
        <div className="flex h-screen bg-gray-100 dark:bg-gray-950 transition-colors duration-200">
            <Sidebar 
                isMobileOpen={isMobileSidebarOpen}
                onMobileClose={() => setMobileSidebarOpen(false)}
                isDesktopCollapsed={isDesktopSidebarCollapsed}
                activePage={activePage}
                setActivePage={setActivePage}
                staffPermissions={staffPermissions}
                companySettings={companySettings}
                onLogout={onLogout}
            />
            <div className="flex-1 flex flex-col overflow-hidden relative">
                <Header 
                    onMobileMenuToggle={() => setMobileSidebarOpen(true)}
                    onDesktopToggle={() => setDesktopSidebarCollapsed(prev => !prev)}
                    isDesktopCollapsed={isDesktopSidebarCollapsed}
                    currentStaff={currentStaff}
                    onLogout={onLogout}
                    setActivePage={setActivePage}
                    notifications={headerNotifications}
                    unreadMailsCount={unreadMailsCount}
                />
                <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-950 transition-colors duration-200 flex flex-col">
                    <div className="container mx-auto px-6 py-8 flex-grow">
                        {children}
                    </div>
                </main>

                {/* Global Toast Notification */}
                {toast && (
                    <ToastNotification 
                        message={toast.message} 
                        subtext={toast.subtext} 
                        onClose={() => setToast(null)} 
                    />
                )}
            </div>
        </div>
    );
};

