                    {client.paidPercent !== undefined && (
                        <span className="text-[10px] font-bold text-gray-400">{Math.round(client.paidPercent)}% Paid</span>
                    )}
                </div>
            </div>
            {/* Status */}
            <div className="col-span-6 md:col-span-1 text-center">
                <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(client.status)}`}>
                    {client.status}
                </span>
            </div>
            {/* Payment Info */}
            <div className="col-span-12 md:col-span-2 text-xs">
                <p><span className="font-semibold text-gray-600 dark:text-gray-400">Total:</span> <span className="dark:text-gray-300">{formatCurrency(client.payment.total)}</span></p>
                <p><span className="font-semibold text-red-600 dark:text-red-400">Outstanding:</span> <span className="dark:text-gray-300">{formatCurrency(client.payment.balance)}</span></p>
            </div>
            {/* Actions */}
            <div className="col-span-12 md:col-span-1 flex items-center gap-2 justify-end md:justify-start">
                <button onClick={() => onViewDetails(client)} className="text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400 p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700" aria-label={`View details for ${client.name}`}>
                    <EyeIcon className="w-5 h-5"/>
                </button>
                <button onClick={() => onEdit(client)} className="text-gray-500 hover:text-green-600 dark:text-gray-400 dark:hover:text-green-400 p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700" aria-label={`Edit ${client.name}`}>
                    <PencilIcon className="w-5 h-5"/>
                </button>
                <button onClick={() => onDelete(client.id)} className="text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400 p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700" aria-label={`Delete ${client.name}`}>
                    <TrashIcon className="w-5 h-5"/>
                </button>
            </div>
        </div>
    </div>
  );
};

export default ClientListItem;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Client, Milestone, Property, Invoice, ActivityLog, Staff, AllocationStatus } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { VariableSizeList as List } from 'react-window';
import { useClients, useStaff } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';
import { useData } from '../context/DataContext';
import { useAuth } from '../context/AuthContext';

// Modular Imports
import { ClientListHeader } from '../components/clients/ClientListHeader';
import { ClientFilters } from '../components/clients/ClientFilters';
import { ClientTableHead } from '../components/clients/ClientTableHead';
import { ClientsList } from '../components/clients/ClientsList';

interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string, context?: any) => void;
    setClientForInvoice: (client: Client | null) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (formData: FormData): boolean => {
    const requiredFields: (keyof FormData)[] = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    for (const field of requiredFields) {
        if (!formData[field] || String(formData[field]).trim() === '') return false;
    }
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);
    const { sendMail } = useData();
    const { staff } = useStaff();
    const { currentStaff } = useAuth();

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [deletedClientInfo, setDeletedClientInfo] = useState<{ name: string; timeoutId: ReturnType<typeof setTimeout> } | null>(null);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    // Virtualization State
    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});

    // --- SCROLL ANIMATION LOGIC ---
    const [scrollOffset, setScrollOffset] = useState(0);
    const MAX_SCROLL = 80;

    const handleScroll = ({ scrollOffset: offset }: { scrollOffset: number }) => {
        setScrollOffset(Math.min(offset, MAX_SCROLL));
    };

    const headerOpacity = Math.max(0, 1 - scrollOffset / (MAX_SCROLL * 0.8));
    const headerHeight = Math.max(0, 48 - (scrollOffset / MAX_SCROLL) * 48);
    const controlsTranslate = (scrollOffset / MAX_SCROLL) * -52;

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const handleDeleteClick = useCallback((clientId: number) => {
        const client = clients.find(c => c.id === clientId);
        if (client) setClientToDelete(client);
    }, [clients]);

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);
            const timeoutId = setTimeout(() => setDeletedClientInfo(null), 3000);
            setDeletedClientInfo({ name: clientToDelete.name, timeoutId });
            setClientToDelete(null);
        }
    };

    const createClientObject = (formData: FormData, id: number, existingClient?: Client | null): Client => {
        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();
        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;
        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }
        const isComplete = isClientDataComplete(formData);

        const clientType = (formData as any).clientType || 'Individual';

        const baseClient = existingClient || {
            id: id, 
            clientType,
            status: 'Active Client' as const, 
            allocationStatus: 'RESERVED_NOT_ALLOCATED' as AllocationStatus, // Initialize as Reserved
            paidPercent: 0, // Initialize with 0% paid
            stage: milestones[0]?.acronym || 'N/A',
            payment: { total: baseTotal, paid: 0, balance: baseTotal, dueDate: 'N/A', planType: 'N/A', promoDetails: promoDetails, paymentHistory: [], installments: [] },
            interactions: [], documentation: { status: 'Pending' },
            officeUse: { commission: { type: 'Percentage', amount: 0, status: 'Pending' } }
        };
        return {
            ...baseClient, id, 
            clientType, 
            name: fullName, surname: formData.surname, otherNames: formData.otherNames, initials,
            regDate: formData.paymentDate, email: formData.email, phone: formData.telephone, dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'], location: formData.location, plot: formData.plotNumber, photo: formData.photo,
            propertyType: formData.propertyType, plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: { placeOfWork: formData.placeOfWork, profession: formData.profession, position: formData.position },
            witness: { name: formData.witnessName, address: formData.witnessAddress, phone: formData.witnessPhone },
            nextOfKin: { name: formData.kinName, phone: formData.kinPhone, relationship: formData.kinRelationship, email: formData.kinEmail, address: formData.kinAddress },
            indenture: { name: formData.indentureName, address: formData.indentureAddress },
            officeUse: { ...baseClient.officeUse, salesRep: formData.salesRep, salesManager: formData.salesManager, accountsHead: formData.accountsHead, clerk: formData.clerk },
            isComplete, filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClientAndRedirect = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            const isNewClient = !editingClient;
            const newId = editingClient ? editingClient.id : (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

            if (!newId) {
                alert("Error: Client ID could not be generated. Please retry.");
                return;
            }

            let photoUrl = formData.photo;
            if (files?.photo) photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId, editingClient);

            const savedClient = await onSaveClient(newClient);

            if (!savedClient) {
                alert("Error: Client data not saved correctly.");
                return;
            }

            // TRIGGER: Notification to Chief Accountant (Head of Accounts)
            // Rule: Only if actor is Front Desk Executive and this is a NEW client entry
            if (isNewClient && currentStaff?.roleId === 'Front Desk Executive') {
                const chiefAccountants = staff.filter(s => s.roleId === 'Chief Accountant');

                if (chiefAccountants.length > 0) {
                    await sendMail({
                        senderId: currentStaff.id,
                        senderName: currentStaff.fullName,
                        recipientIds: chiefAccountants.map(s => s.id),
                        groupIds: [], 
                        subject: 'ACTION REQUIRED: New Client Ledger Initialization',
                        body: `A new client record has been created and requires financial setup.\n\nClient: ${savedClient.name}\nReference: ${savedClient.initials}-${savedClient.id}\nProperty: ${savedClient.location}\n\nPlease proceed to Account Management to initialize the financial commitment and payment plan for this account.\n\nDate Registered: ${new Date().toLocaleString()}`,
                        attachments: [],
                        timestamp: new Date().toISOString(),
                        readBy: [currentStaff.id],
                        isDraft: false,
                        isDeleted: false,
                        targetPage: 'Account Management',
                        targetContext: savedClient
                    });
                } else {
                    // Log undelivered notification for CEO oversight
                    addActivityLog('Update', `System Warning: No Chief Accountant found to receive onboarding notification for client ${savedClient.name}.`);
                }
            }

            setClientFormOpen(false);
            addActivityLog(editingClient ? 'Update' : 'Create', `Processed client: ${savedClient.name}`);

            // Auto-Redirect to Client Details
            onClientSelect(savedClient);

        } catch (error) { 
            console.error("Save failed:", error);
            alert("Failed to save client."); 
        }
    };

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            <div className="bg-gray-100 dark:bg-gray-950 z-20 flex-shrink-0 transition-all duration-300 ease-out"
                 style={{ transform: `translateY(${controlsTranslate}px)` }}>

                <ClientListHeader 
                    clientCount={clients.length} 
                    hasNextPage={hasNextPage} 
                    onImportClick={() => setImportWizardOpen(true)}
                    onNewClientClick={() => { setEditingClient(null); setClientFormOpen(true); }}
                    headerOpacity={headerOpacity}
                    headerHeight={headerHeight}
                />

                <ClientFilters 
                    searchTerm={searchTerm} 
                    onSearchChange={setSearchTerm} 
                    isLoading={isLoading} 
                    properties={properties} 
                />

                <ClientTableHead />
            </div>

            <ClientsList 
                clients={clients}
                onViewDetails={onClientSelect}
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }}
                onDelete={handleDeleteClick}
                milestones={milestones}
                expandedIds={expandedIds}
                toggleExpand={toggleExpand}
                onScroll={handleScroll}
                listRef={listRef}
            />

            {hasNextPage && !debouncedSearchTerm && (
                <div className="py-3 text-center border-t border-gray-200 dark:border-gray-800 flex-shrink-0">
                    <button 
                        onClick={() => fetchNextPage()} 
                        disabled={isFetchingNextPage}
                        className="text-blue-600 dark:text-blue-400 text-xs font-black uppercase tracking-widest hover:underline disabled:opacity-50"
                    >
                        {isFetchingNextPage ? 'Loading...' : 'Load More Results'}
                    </button>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={() => { setClientFormOpen(false); setEditingClient(null); }}
                onSave={handleSaveClientAndRedirect}
                onSaveAndPay={handleSaveClientAndRedirect}
                properties={properties}
                editingClient={editingClient}
                clients={clients}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={() => {}}
                requiredHeaders={requiredCsvHeaders}
                sampleHeaders=""
                sampleData=""
                wizardTitle="Import Client Data"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />
        </div>
    );
};

export default ClientsPage;

import React, { useState, useMemo } from 'react';
import { Client, Property } from '../types';
import { 
    ArrowLeftIcon, 
    UserCheckIcon, 
    EyeIcon
} from '../components/icons/DummyIcons';
import { Card } from '../ui/Card';
import { Select } from '../ui/Input';
import { useClients } from '../hooks/useAppData';

// Modular Imports
import { QualificationCard } from '../components/allocation/QualificationCard';
import { PlotSelectionGrid } from '../components/allocation/PlotSelectionGrid';
import { SiteMapLedger } from '../components/allocation/SiteMapLedger';

interface AllocatePlotPageProps {
    onBack: () => void;
    clients: Client[];
    properties: Property[];
}

const AllocatePlotPage: React.FC<AllocatePlotPageProps> = ({ onBack, clients, properties }) => {
    const { saveClient } = useClients();

    const [selectedClientId, setSelectedClientId] = useState<number | ''>('');
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [selectedPlots, setSelectedPlots] = useState<string[]>([]);
    const [isSaving, setIsSaving] = useState(false);
    const [allocationSuccess, setAllocationSuccess] = useState(false);

    const [isViewAllOpen, setIsViewAllOpen] = useState(false);
    const [viewAllLocationId, setViewAllLocationId] = useState<number | ''>('');
    const [statusFilter, setStatusFilter] = useState<'All' | 'Allocated' | 'Available'>('All');

    const selectedClient = useMemo(() => clients.find(c => c.id === selectedClientId), [selectedClientId, clients]);
    const selectedProperty = useMemo(() => properties.find(p => p.id === selectedPropertyId), [selectedPropertyId, properties]);

    const globalPlotStatus = useMemo(() => {
        const pool: Record<string, { allocated: boolean, owner?: string, status?: string }> = {};
        clients.forEach(c => {
            if (c.plot && c.plot !== 'N/A') {
                c.plot.split(',').forEach(p => {
                    const plotNum = p.trim().toUpperCase();
                    if (plotNum) {
                        pool[plotNum] = { 
                            // Authority Rule: Only 'ALLOCATED' status blocks selection
                            allocated: c.allocationStatus === 'ALLOCATED', 
                            owner: c.name,
                            status: c.allocationStatus
                        };
                    }
                });
            }
        });
        return pool;
    }, [clients]);

    const availablePlotsList = useMemo(() => {
        if (!selectedProperty || !selectedProperty.inventory) return [];
        const plots: { plotNumber: string; isTaken: boolean; owner?: string; status?: string }[] = [];
        selectedProperty.inventory.forEach((inv: any) => {
            const prefix = inv.zone || 'P1';
            for (let i = 1; i <= inv.count; i++) {
                const pNum = `${prefix}-${i}`;
                plots.push({
                    plotNumber: pNum,
                    isTaken: globalPlotStatus[pNum]?.allocated || false,
                    owner: globalPlotStatus[pNum]?.owner,
                    status: globalPlotStatus[pNum]?.status
                });
            }
        });
        return plots;
    }, [selectedProperty, globalPlotStatus]);

    const masterPlotList = useMemo(() => {
        const prop = properties.find(p => p.id === viewAllLocationId);
        if (!prop || !prop.inventory) return [];

        const all: { plotNumber: string; size: string; allocatedTo: string | null; isProvisional: boolean, status?: string }[] = [];
        prop.inventory.forEach((inv: any) => {
            const prefix = inv.zone || 'P1';
            for (let i = 1; i <= inv.count; i++) {
                const pNum = `${prefix}-${i}`;
                const ownerInfo = globalPlotStatus[pNum];

                let isProvisional = false;
                if (ownerInfo?.allocated) {
                    const client = clients.find(c => c.name === ownerInfo.owner);
                    if (client) {
                        const pct = client.paidPercent || 0;
                        isProvisional = pct < 70;
                    }
                }

                all.push({
                    plotNumber: pNum,
                    size: inv.size,
                    allocatedTo: ownerInfo?.owner || null,
                    isProvisional,
                    status: ownerInfo?.status
                });
            }
        });

        return all.filter(p => {
            if (statusFilter === 'Allocated') return p.allocatedTo !== null;
            if (statusFilter === 'Available') return p.allocatedTo === null;
            return true;
        });
    }, [viewAllLocationId, properties, globalPlotStatus, clients, statusFilter]);

    const handlePlotToggle = (plot: string) => {
        // Selection blocked ONLY if status is 'ALLOCATED'
        if (globalPlotStatus[plot]?.allocated) return;
        setSelectedPlots(prev => prev.includes(plot) ? prev.filter(p => p !== plot) : [...prev, plot]);
    };

    const handleConfirmAllocation = async () => {
        if (!selectedClient || selectedPlots.length === 0) return;
        setIsSaving(true);
        try {
            const updatedClient: Client = {
                ...selectedClient,
                plot: selectedPlots.join(', '),
                interactions: [
                    { id: Date.now(), type: 'Note', date: new Date().toISOString(), agent: 'System', notes: `Plots ${selectedPlots.join(', ')} allocated at ${selectedProperty?.location}.` },
                    ...selectedClient.interactions
                ]
            };
            await saveClient(updatedClient);
            setAllocationSuccess(true);
            setTimeout(() => onBack(), 2000);
        } catch (error) {
            alert('Save failed.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors"><ArrowLeftIcon className="w-5 h-5" /> Back</button>
                    <div className="flex items-center gap-4">
                        <UserCheckIcon className="w-10 h-10 text-blue-600" />
                        <div>
                            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Allocate Plot</h1>
                            <p className="text-gray-500 dark:text-gray-400 mt-1">Single source inventory partitioning and assignment.</p>
                        </div>
                    </div>
                </div>
            </div>

            {allocationSuccess && <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded shadow-md animate-bounce">Allocation Successful!</div>}

            <Card className="bg-white dark:bg-gray-800">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <Select label="1. Client" value={selectedClientId} onChange={(e) => { setSelectedClientId(Number(e.target.value)); setSelectedPlots([]); }}>
                        <option value="">-- Select --</option>
                        {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </Select>
                    <Select label="2. Location" value={selectedPropertyId} onChange={(e) => { setSelectedPropertyId(Number(e.target.value)); setSelectedPlots([]); }}>
                        <option value="">-- Select --</option>
                        {properties.map(p => <option key={p.id} value={p.id}>{p.location}</option>)}
                    </Select>
                </div>
                <div className="mt-4 pt-4 border-t border-gray-100 dark:border-gray-700">
                    <button onClick={() => setIsViewAllOpen(!isViewAllOpen)} className="text-sm font-bold text-indigo-600 hover:underline flex items-center gap-1">
                        <EyeIcon className="w-4 h-4" /> View Site Map Ledger
                    </button>
                    {isViewAllOpen && (
                        <SiteMapLedger 
                            properties={properties}
                            viewAllLocationId={viewAllLocationId}
                            setViewAllLocationId={setViewAllLocationId}
                            statusFilter={statusFilter}
                            setStatusFilter={setStatusFilter}
                            masterPlotList={masterPlotList}
                        />
                    )}
                </div>
            </Card>

            {selectedClient && selectedProperty && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4">
                    <QualificationCard client={selectedClient} />

                    <PlotSelectionGrid 
                        property={selectedProperty}
                        availablePlots={availablePlotsList}
                        selectedPlots={selectedPlots}
                        onTogglePlot={handlePlotToggle}
                        onConfirm={handleConfirmAllocation}
                        isSaving={isSaving}
                    />
                </div>
            )}
            <style>{` .scrollbar-thin::-webkit-scrollbar { width: 4px; } .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; } `}</style>
        </div>
    );
};

export default AllocatePlotPage;

import React from 'react';
import { Property } from '../../types';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { ExclamationTriangleIcon, PhoneIcon } from '../icons/DummyIcons';

interface PlotSelectionGridProps {
    property: Property;
    availablePlots: { plotNumber: string; isTaken: boolean; owner?: string; status?: string }[];
    selectedPlots: string[];
    onTogglePlot: (plot: string) => void;
    onConfirm: () => void;
    isSaving: boolean;
}

export const PlotSelectionGrid: React.FC<PlotSelectionGridProps> = ({ 
    property, 
    availablePlots, 
    selectedPlots, 
    onTogglePlot, 
    onConfirm, 
    isSaving 
}) => {
    // Determine if any selected plot is currently reserved by another user
    const reservedConflicts = selectedPlots.map(pNum => 
        availablePlots.find(ap => ap.plotNumber === pNum && ap.status === 'RESERVED_NOT_ALLOCATED')
    ).filter(Boolean);

    return (
        <Card title={`3. Select Plot(s) for ${property.location}`} className="lg:col-span-2">
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-2 max-h-[350px] overflow-y-auto scrollbar-thin p-1">
                {availablePlots.map(plot => {
                    const isReserved = plot.status === 'RESERVED_NOT_ALLOCATED';
                    const isSelected = selectedPlots.includes(plot.plotNumber);

                    return (
                        <button
                            key={plot.plotNumber}
                            disabled={plot.isTaken}
                            onClick={() => onTogglePlot(plot.plotNumber)}
                            className={`p-3 rounded-lg border text-[10px] font-black flex flex-col items-center gap-1 transition-all h-20 justify-center shadow-sm ${
                                plot.isTaken 
                                ? 'bg-gray-100 text-gray-300 border-gray-200 cursor-not-allowed grayscale' 
                                : isSelected
                                    ? 'bg-blue-600 text-white border-blue-600 scale-105 z-10'
                                    : isReserved
                                        ? 'bg-white text-blue-600 border-blue-300 border-dashed hover:border-blue-500 hover:bg-blue-50/50'
                                        : 'bg-white text-gray-600 border-gray-200 hover:border-blue-500'
                            }`}
                        >
                            <span className="text-sm uppercase tracking-tight">{plot.plotNumber}</span>
                            <span className="opacity-70 font-bold">
                                {plot.isTaken ? 'Taken' : isReserved ? '(Reserved not allocated)' : 'Pick'}
                            </span>
                        </button>
                    );
                })}
            </div>

            {selectedPlots.length > 0 && (
                <div className="mt-6 space-y-4">
                    {/* Policy Disclosure Side Panel Block */}
                    {reservedConflicts.length > 0 && (
                        <div className="p-4 bg-amber-50 dark:bg-amber-900/10 border-l-4 border-amber-500 rounded-lg animate-in fade-in slide-in-from-left-4 duration-300">
                            <div className="flex gap-3">
                                <ExclamationTriangleIcon className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                                <div className="space-y-3">
                                    {reservedConflicts.map(conflict => (
                                        <div key={conflict!.plotNumber} className="text-xs text-amber-800 dark:text-amber-200 font-medium">
                                            <p className="font-bold uppercase tracking-tight">Reservation Conflict: Plot {conflict!.plotNumber}</p>
                                            <p className="mt-1">This plot was reserved by <span className="font-black underline">{conflict!.owner}</span>.</p>
                                            <p>Client has not paid up to 70%. Plot can be allocated to someone else.</p>
                                        </div>
                                    ))}

                                    <div className="pt-3 border-t border-amber-200 dark:border-amber-800 space-y-2">
                                        <p className="text-[10px] font-black uppercase text-amber-600 flex items-center gap-1">
                                            <PhoneIcon className="w-3 h-3" /> Mandatory Protocol:
                                        </p>
                                        <p className="text-[11px] text-amber-700 dark:text-amber-400 leading-tight">
                                            If allocated elsewhere: Call and inform client that their reserved plot has been allocated because they did not reach 70%. Client has first right if they can pay 70% immediately.
                                        </p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="flex justify-between items-center bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-200 dark:border-blue-800">
                        <div>
                            <p className="text-xs text-blue-800 dark:text-blue-400 font-bold uppercase tracking-widest">Ready for assignment:</p>
                            <p className="text-sm font-black text-blue-900 dark:text-white mt-1">{selectedPlots.join(', ')}</p>
                        </div>
                        <Button onClick={onConfirm} isLoading={isSaving} className="px-8 font-black uppercase tracking-widest">Confirm Selection</Button>
                    </div>
                </div>
            )}
        </Card>
    );
};

