const getStatusColor = (status: Client['status']) => {
  switch (status) {
    case 'Active Client':
      return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
    case 'Refunded':
      return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200';
    case 'Reallocated':
      return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200';
    default:
      return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300';
  }
};

const getAllocationBadgeColor = (status?: string) => {
    if (status === 'ALLOCATED') return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200';
    if (status === 'RESERVED_NOT_ALLOCATED') return 'bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200';
    return 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400';
};

