              <PhoneIcon className="w-5 h-5" />
              <span>{client.phone}</span>
            </a>
          </div>
        </div>
        <div className="flex items-center gap-2 self-start sm:self-center">
            {onAmend && (
                <button onClick={onAmend} className="bg-gray-800 dark:bg-gray-700 text-white font-semibold py-2 px-4 rounded-lg hover:bg-gray-700 dark:hover:bg-gray-600 transition-colors flex items-center gap-2">
                    <PencilSquareIcon className="w-5 h-5" /> Amendment
                </button>
            )}
        </div>
      </div>
    </div>
  );
};

export default ClientProfileHeader;

import React from 'react';
import { Property, AllocationStatus } from '../../types';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { ExclamationTriangleIcon, PhoneIcon, LockClosedIcon, CheckCircleIcon } from '../icons/DummyIcons';

interface PlotSelectionGridProps {
    property: Property;
    availablePlots: { plotNumber: string; isTaken: boolean; owner?: string; status?: AllocationStatus }[];
    selectedPlots: string[];
    onTogglePlot: (plot: string) => void;
    onConfirm: () => void;
    isSaving: boolean;
    isAlreadyAllocated?: boolean;
    isReserved?: boolean;
    clientPlotNumbers?: string;
}

export const PlotSelectionGrid: React.FC<PlotSelectionGridProps> = ({ 
    property, 
    availablePlots, 
    selectedPlots, 
    onTogglePlot, 
    onConfirm, 
    isSaving,
    isAlreadyAllocated = false,
    isReserved = false,
    clientPlotNumbers = ''
}) => {
    // RULE 2: If client plots already exist (Reserved state), make them read-only
    const isSelectionBlocked = isAlreadyAllocated || isReserved;

    // Find if any currently selected plot is actually reserved by another user
    const selectedReservedPlots = availablePlots.filter(p => 
        selectedPlots.includes(p.plotNumber) && p.status === 'RESERVED_NOT_ALLOCATED' && p.owner !== availablePlots.find(x => x.plotNumber === p.plotNumber)?.owner
    );

    return (
        <Card title={isReserved ? `3. Review RESERVED Plot(s) for ${property.location}` : `3. Select Plot(s) for ${property.location}`} className="lg:col-span-2 relative">
            {/* Locking Overlay UI Hint */}
            {isSelectionBlocked && (
                <div className="absolute inset-0 bg-white/5 dark:bg-gray-900/5 backdrop-blur-[0.5px] z-10 cursor-not-allowed rounded-lg" />
            )}

            <div className={`grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-2 max-h-[350px] overflow-y-auto scrollbar-thin p-1 ${isSelectionBlocked ? 'opacity-80' : ''}`}>
                {availablePlots.map(plot => {
                    const isReservedBySomeone = plot.status === 'RESERVED_NOT_ALLOCATED';
                    const isSelected = selectedPlots.includes(plot.plotNumber);

                    return (
                        <button
                            key={plot.plotNumber}
                            disabled={plot.isTaken || isSelectionBlocked}
                            onClick={() => onTogglePlot(plot.plotNumber)}
                            className={`p-2 rounded border text-[10px] font-bold flex flex-col items-center gap-1 transition-all h-20 justify-center shadow-sm ${
                                plot.isTaken 
                                ? 'bg-gray-100 text-gray-300 border-gray-200 cursor-not-allowed grayscale' 
                                : isSelected
                                    ? isReserved 
                                        ? 'bg-blue-50 text-blue-700 border-blue-200 border-dashed scale-100' // Visual hint for pre-selected
                                        : 'bg-blue-600 text-white border-blue-600 scale-105 z-10'
                                    : isReservedBySomeone
                                        ? 'bg-white text-blue-600 border-blue-300 border-dashed hover:border-blue-500 hover:bg-blue-50/50'
                                        : isSelectionBlocked
                                            ? 'bg-gray-50 text-gray-400 border-gray-200 cursor-not-allowed'
                                            : 'bg-white text-gray-600 border-gray-300 hover:border-blue-500'
                            }`}
                        >
                            <span className={isReservedBySomeone ? "text-blue-600 font-black" : ""}>{plot.plotNumber}</span>
                            <span className={`opacity-60 text-[9px] ${isReservedBySomeone ? "text-blue-500 font-black italic" : ""}`}>
                                {plot.isTaken ? 'ALLOCATED' : isReserved && isSelected ? 'RESERVED' : isReservedBySomeone ? 'RESERVED' : isSelectionBlocked ? 'Locked' : 'Pick'}
                            </span>
                        </button>
                    );
                })}
            </div>

            <div className="mt-6 space-y-4">
                {/* RULE 1 & 2: Multiple Allocation Prevention Message */}
                {isAlreadyAllocated && (
                    <div className="p-4 bg-red-50 dark:bg-red-900/10 border-l-4 border-red-600 rounded-r-lg animate-in fade-in slide-in-from-top-1 duration-300">
                        <div className="flex gap-3">
                            <LockClosedIcon className="w-5 h-5 text-red-600 shrink-0 mt-0.5" />
                            <div>
                                <p className="text-sm font-black text-red-900 dark:text-red-100 uppercase tracking-tight">Allocation Locked</p>
                                <p className="text-xs text-red-800 dark:text-red-200 mt-1 font-medium">
                                    Plot number(s) <span className="underline font-black">{clientPlotNumbers}</span> have already been ALLOCATED to this client.
                                </p>
                                <p className="text-xs text-red-700 dark:text-red-300 mt-2 font-bold italic">
                                    Request amendment to add or update the plot number.
                                </p>
                            </div>
                        </div>
                    </div>
                )}

                {/* RULE 3: Reserved Confirmation Banner */}
                {isReserved && (
                    <div className="p-4 bg-blue-50 dark:bg-blue-900/10 border-l-4 border-blue-600 rounded-r-lg animate-in fade-in slide-in-from-top-1 duration-300">
                        <div className="flex gap-3">
                            <CheckCircleIcon className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
                            <div>
                                <p className="text-sm font-black text-blue-900 dark:text-blue-100 uppercase tracking-tight">Pending Confirmation</p>
                                <p className="text-xs text-blue-800 dark:text-blue-200 mt-1 font-medium">
                                    The client has pre-RESERVED plot(s): <span className="font-black">{clientPlotNumbers}</span>. 
                                </p>
                                <p className="text-xs text-red-700 dark:text-red-300 mt-2 font-bold italic">
                                    Confirm selection to finalize ALLOCATION in the master ledger.
                                </p>
                            </div>
                        </div>
                    </div>
                )}

                {/* Conflict Warning Side Panel (Only if not already locked) */}
                {!isSelectionBlocked && selectedReservedPlots.length > 0 && (
                    <div className="bg-amber-50 dark:bg-amber-900/10 border-l-4 border-amber-500 p-4 rounded-r-lg animate-in fade-in slide-in-from-left-4">
                        <div className="flex gap-3">
                            <ExclamationTriangleIcon className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                            <div className="space-y-4 text-xs font-medium text-amber-800 dark:text-amber-200">
                                {selectedReservedPlots.map(p => (
                                    <div key={p.plotNumber} className="space-y-1">
                                        <p className="font-black uppercase tracking-tight text-amber-900 dark:text-amber-100">Conflict Warning: Plot {p.plotNumber}</p>
                                        <p>This plot was reserved by <span className="font-black underline">{p.owner}</span>.</p>
                                        <p>Client has not paid up to 70%. Plot can be allocated to someone else.</p>
                                    </div>
                                ))}

                                <div className="pt-3 border-t border-amber-200 dark:border-amber-800">
                                    <p className="flex items-center gap-1.5 font-black uppercase text-amber-600 mb-1">
                                        <PhoneIcon className="w-3.5 h-3.5" /> Advisory Communication
                                    </p>
                                    <p className="italic leading-relaxed">
                                        If allocated elsewhere: Call and inform client that their reserved plot has been allocated because they did not reach 70%. Client has first right if they can pay 70% immediately.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Confirm Button - Enabled if selection exists or reserved */}
                {selectedPlots.length > 0 && (
                    <div className={`flex justify-between items-center bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-200 dark:border-blue-800 ${isAlreadyAllocated ? 'opacity-40 grayscale' : ''}`}>
                        <div>
                            <p className="text-xs text-blue-800 dark:text-blue-400 font-bold uppercase tracking-widest">{isReserved ? 'Ready for confirmation:' : 'Ready for assignment:'}</p>
                            <p className="text-sm font-black text-blue-900 dark:text-white mt-1">{selectedPlots.join(', ')}</p>
                        </div>
                        <Button 
                            onClick={onConfirm} 
                            isLoading={isSaving} 
                            disabled={isAlreadyAllocated}
                            className="px-8 font-black uppercase tracking-widest"
                        >
                            {isReserved ? 'Confirm ALLOCATION' : 'Confirm Selection'}
                        </Button>
                    </div>
                )}
            </div>
        </Card>
    );
};

import React, { useMemo } from 'react';
import { Client } from '../../types';
import { Card } from '../ui/Card';
import { 
    UserCircleIcon, 
    MapPinIcon, 
    LockClosedIcon, 
    ExclamationTriangleIcon, 
    CheckCircleIcon,
    InformationCircleIcon 
} from '../icons/DummyIcons';

interface QualificationCardProps {
    client: Client;
}

export const QualificationCard: React.FC<QualificationCardProps> = ({ client }) => {
    const qualification = useMemo(() => {
        if (!client) return { isQualified: false, percentage: 0, status: 'N/A', hasAllocated: false };

        const total = client.payment.total || 1;
        const paid = client.payment.paid || 0;
        const percentage = (paid / total) * 100;
        const isQualified = percentage >= 70;
        const hasAllocated = client.allocationStatus === 'ALLOCATED';

        return {
            percentage: Math.round(percentage),
            isQualified,
            hasAllocated,
            status: hasAllocated 
                ? 'Record Finalized' 
                : isQualified 
                    ? 'Qualified (≥70%)' 
                    : 'Provisionally Flagged (<70%)'
        };
    }, [client]);

    const hasPlots = client.plot && client.plot !== 'N/A';

    return (
        <Card title="Qualification Detail" className="lg:col-span-1 space-y-6">
            {/* Part A: Payment Status */}
            <div className="text-center space-y-4">
                <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Payment Progress</p>
                <div className="relative">
                    <p className={`text-2xl font-black ${qualification.hasAllocated ? 'text-blue-600' : qualification.isQualified ? 'text-green-600' : 'text-amber-600'}`}>
                        {qualification.percentage}%
                    </p>
                    <p className="text-[10px] font-bold text-gray-500 uppercase mt-1">{qualification.status}</p>
                </div>
                <div className="w-full bg-gray-100 dark:bg-gray-700 h-2.5 rounded-full overflow-hidden shadow-inner">
                    <div 
                        className={`h-full transition-all duration-1000 ${qualification.hasAllocated ? 'bg-blue-600' : qualification.isQualified ? 'bg-green-500' : 'bg-amber-500'}`} 
                        style={{ width: `${qualification.percentage}%` }}
                    ></div>
                </div>
            </div>

            {/* Part B: Allocation Audit (Directly below Payment Status) */}
            <div className="pt-6 border-t border-gray-100 dark:border-gray-700 space-y-4">
                <div className="space-y-2">
                    <div className="flex items-center gap-2 text-xs">
                        <UserCircleIcon className="w-4 h-4 text-gray-400" />
                        <span className="text-gray-500 font-medium">Client:</span>
                        <span className="font-bold text-gray-900 dark:text-white">{client.name}</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs">
                        <MapPinIcon className="w-4 h-4 text-gray-400" />
                        <span className="text-gray-500 font-medium">Location:</span>
                        <span className="font-bold text-gray-900 dark:text-white">{client.location || 'NONE'}</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs">
                        <InformationCircleIcon className="w-4 h-4 text-gray-400" />
                        <span className="text-gray-500 font-medium">Plot(s):</span>
                        <span className="font-bold text-gray-900 dark:text-white">{client.plot || 'NONE'}</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs pt-2">
                        <div className={`w-2 h-2 rounded-full ${qualification.hasAllocated ? 'bg-blue-600' : hasPlots ? 'bg-amber-500' : 'bg-gray-300'}`}></div>
                        <span className="text-gray-500 font-medium">Plot Status:</span>
                        <span className={`font-black uppercase tracking-tighter ${qualification.hasAllocated ? 'text-blue-600' : hasPlots ? 'text-amber-600' : 'text-gray-400'}`}>
                            {qualification.hasAllocated ? 'ALLOCATED' : hasPlots ? 'RESERVED' : 'NONE'}
                        </span>
                    </div>
                </div>

                <div className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-100 dark:border-gray-800">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-tight">
                        Protocol: Allocation is done once per client.
                    </p>
                </div>

                {/* Allocation Specific Messages */}
                {qualification.hasAllocated ? (
                    <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border-l-4 border-blue-600 rounded-r-lg space-y-2 animate-in fade-in slide-in-from-top-1">
                        <div className="flex items-center gap-2 text-blue-800 dark:text-blue-400">
                            <LockClosedIcon className="w-4 h-4 shadow-sm" />
                            <p className="text-[10px] font-black uppercase tracking-tight">Allocation Finalized</p>
                        </div>
                        <p className="text-xs text-blue-700 dark:text-blue-300 leading-relaxed font-medium">
                            Allocation already completed. Plot number(s) <span className="font-black underline">{client.plot}</span> have been allocated to this client. 
                        </p>
                        <p className="text-[10px] text-blue-500 italic font-bold">
                            Request amendment to add or update plot numbers.
                        </p>
                    </div>
                ) : !qualification.isQualified ? (
                    <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border-l-4 border-amber-500 rounded-r-lg space-y-1 animate-in fade-in slide-in-from-top-1">
                        <div className="flex items-center gap-2 text-amber-800 dark:text-amber-400">
