import React, { useMemo } from 'react';
import { Property, AllocationStatus } from '../../types';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { ExclamationTriangleIcon, PhoneIcon } from '../icons/DummyIcons';

interface PlotSelectionGridProps {
    property: Property;
    availablePlots: { plotNumber: string; isTaken: boolean; owner?: string; status?: AllocationStatus }[];
    selectedPlots: string[];
    onTogglePlot: (plot: string) => void;
    onConfirm: () => void;
    isSaving: boolean;
    isAlreadyAllocated?: boolean;
    isReserved?: boolean;
    clientPlotNumbers?: string;
    clientPaidPercent?: number;
}

export const PlotSelectionGrid: React.FC<PlotSelectionGridProps> = ({ 
    property, 
    availablePlots, 
    selectedPlots, 
    onTogglePlot, 
    onConfirm, 
    isSaving,
    isAlreadyAllocated = false,
    isReserved = false,
    clientPaidPercent = 0
}) => {
    // Computed Business Rules for Interaction
    const paymentAtOrAbove70 = clientPaidPercent >= 70;
    const isSelectionBlocked = isAlreadyAllocated || isReserved;

    // Final Button Enabling Logic
    const canConfirm = !isAlreadyAllocated && paymentAtOrAbove70 && selectedPlots.length > 0;

    // Find if any currently selected plot is actually reserved by another user
    const selectedReservedPlots = availablePlots.filter(p => 
        selectedPlots.includes(p.plotNumber) && 
        p.status === 'RESERVED_NOT_ALLOCATED' && 
        p.owner !== availablePlots.find(x => x.plotNumber === p.plotNumber)?.owner
    );

    return (
        <Card title={isReserved ? `3. Review RESERVED Plot(s) for ${property.location}` : `3. Select Plot(s) for ${property.location}`} className="lg:col-span-2 relative">
            {/* Interaction Lock for Finalized Records */}
            {isAlreadyAllocated && (
                <div className="absolute inset-0 bg-white/5 dark:bg-gray-900/5 backdrop-blur-[0.5px] z-10 cursor-not-allowed rounded-lg" />
            )}

            <div className={`grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-2 max-h-[350px] overflow-y-auto scrollbar-thin p-1 ${isAlreadyAllocated ? 'opacity-80' : ''}`}>
                {availablePlots.map(plot => {
                    const isReservedBySomeone = plot.status === 'RESERVED_NOT_ALLOCATED';
                    const isSelected = selectedPlots.includes(plot.plotNumber);

                    return (
                        <button
                            key={plot.plotNumber}
                            disabled={plot.isTaken || isAlreadyAllocated || isReserved}
                            onClick={() => onTogglePlot(plot.plotNumber)}
                            className={`p-2 rounded border text-[10px] font-bold flex flex-col items-center gap-1 transition-all h-20 justify-center shadow-sm ${
                                plot.isTaken 
                                ? 'bg-gray-100 text-gray-300 border-gray-200 cursor-not-allowed grayscale' 
                                : isSelected
                                    ? isReserved 
                                        ? 'bg-blue-50 text-blue-700 border-blue-200 border-dashed scale-100' 
                                        : 'bg-blue-600 text-white border-blue-600 scale-105 z-10'
                                    : isReservedBySomeone
                                        ? 'bg-white text-blue-600 border-blue-300 border-dashed hover:border-blue-500 hover:bg-blue-50/50'
                                        : isSelectionBlocked
                                            ? 'bg-gray-50 text-gray-400 border-gray-200 cursor-not-allowed'
                                            : 'bg-white text-gray-600 border-gray-300 hover:border-blue-500'
                            }`}
                        >
                            <span className={isReservedBySomeone ? "text-blue-600 font-black" : ""}>{plot.plotNumber}</span>
                            <span className={`opacity-60 text-[9px] ${isReservedBySomeone ? "text-blue-500 font-black italic" : ""}`}>
                                {plot.isTaken ? 'ALLOCATED' : isReserved && isSelected ? 'RESERVED' : isReservedBySomeone ? 'RESERVED' : isSelectionBlocked ? 'Locked' : 'Pick'}
                            </span>
                        </button>
                    );
                })}
            </div>

            <div className="mt-6 space-y-4">
                {/* Conflict Warning Side Panel (Only visible during active selection phase) */}
                {!isSelectionBlocked && selectedReservedPlots.length > 0 && (
                    <div className="bg-amber-50 dark:bg-amber-900/10 border-l-4 border-amber-500 p-4 rounded-r-lg animate-in fade-in slide-in-from-left-4">
                        <div className="flex gap-3">
                            <ExclamationTriangleIcon className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                            <div className="space-y-4 text-xs font-medium text-amber-800 dark:text-amber-200">
                                {selectedReservedPlots.map(p => (
                                    <div key={p.plotNumber} className="space-y-1">
                                        <p className="font-black uppercase tracking-tight text-amber-900 dark:text-amber-100">Conflict Warning: Plot {p.plotNumber}</p>
                                        <p>This plot is RESERVED by <span className="font-black underline">{p.owner}</span>.</p>
                                        <p>Client has not paid up to 70%. Plot can be ALLOCATED to someone else.</p>
                                    </div>
                                ))}

                                <div className="pt-3 border-t border-amber-200 dark:border-amber-800">
                                    <p className="flex items-center gap-1.5 font-black uppercase text-amber-600 mb-1">
                                        <PhoneIcon className="w-3.5 h-3.5" /> Advisory Communication
                                    </p>
                                    <p className="italic leading-relaxed">
                                        If allocated elsewhere: Call and inform client that their reserved plot has been allocated because they did not reach 70%. Client has first right if they can pay 70% immediately.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Final Selection Summary and Authority Action Button */}
                {selectedPlots.length > 0 && (
                    <div className={`flex justify-between items-center bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-200 dark:border-blue-800 ${isAlreadyAllocated || !paymentAtOrAbove70 ? 'opacity-50' : ''}`}>
                        <div>
                            <p className="text-xs text-blue-800 dark:text-blue-400 font-bold uppercase tracking-widest">{isReserved ? 'Ready for confirmation:' : 'Ready for assignment:'}</p>
                            <p className="text-sm font-black text-blue-900 dark:text-white mt-1">{selectedPlots.join(', ')}</p>
                        </div>
                        <Button 
                            onClick={onConfirm} 
                            isLoading={isSaving} 
                            disabled={!canConfirm}
                            className="px-8 font-black uppercase tracking-widest"
                        >
                            {isAlreadyAllocated ? 'Already Allocated' : !paymentAtOrAbove70 ? 'Ineligible (Low Payment)' : isReserved ? 'Confirm ALLOCATION' : 'Confirm Selection'}
                        </Button>
                    </div>
                )}
            </div>
        </Card>
    );
};

import React, { useState, useMemo } from 'react';
import { Client, Property, AllocationStatus } from '../types';
import { 
    ArrowLeftIcon, 
    UserCheckIcon, 
    EyeIcon,
    ExclamationTriangleIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Select, Input } from '../components/ui/Input';
import { useClients } from '../hooks/useAppData';

// Modular Imports
import { QualificationCard } from '../components/allocation/QualificationCard';
import { PlotSelectionGrid } from '../components/allocation/PlotSelectionGrid';
import { SiteMapLedger } from '../components/allocation/SiteMapLedger';

interface AllocatePlotPageProps {
    onBack: () => void;
    clients: Client[];
    properties: Property[];
}

const AllocatePlotPage: React.FC<AllocatePlotPageProps> = ({ onBack, clients, properties }) => {
    const { saveClient } = useClients();

    const [selectedClientId, setSelectedClientId] = useState<number | ''>('');
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [selectedPlots, setSelectedPlots] = useState<string[]>([]);
    const [isSaving, setIsSaving] = useState(false);
    const [allocationSuccess, setAllocationSuccess] = useState(false);

    const [isViewAllOpen, setIsViewAllOpen] = useState(false);
    const [viewAllLocationId, setViewAllLocationId] = useState<number | ''>('');
    const [statusFilter, setStatusFilter] = useState<'All' | 'Allocated' | 'Available'>('All');

    const selectedClient = useMemo(() => clients.find(c => c.id === selectedClientId), [selectedClientId, clients]);
    const selectedProperty = useMemo(() => properties.find(p => p.id === selectedPropertyId), [selectedPropertyId, properties]);

    // Handle Client Selection and Auto-populate Location/Plots
    const handleClientChange = (clientId: number | '') => {
        setSelectedClientId(clientId);

        if (clientId) {
            const client = clients.find(c => c.id === clientId);
            if (client) {
                // RULE 1: Auto-bind existing plot data from registration
                const preExistingPlots = client.plot && client.plot !== 'N/A' 
                    ? client.plot.split(',').map(p => p.trim()).filter(Boolean) 
                    : [];
                setSelectedPlots(preExistingPlots);

                // Auto-load location
                if (client.location && client.location !== 'N/A') {
                    const matchingProp = properties.find(p => p.location === client.location);
                    setSelectedPropertyId(matchingProp ? matchingProp.id : '');
                } else {
                    setSelectedPropertyId('');
                }
            }
        } else {
            setSelectedClientId('');
            setSelectedPlots([]);
            setSelectedPropertyId('');
        }
    };

    // AUTHORITY RULE: Multiple Allocation Prevention
    const isAlreadyAllocated = useMemo(() => selectedClient?.allocationStatus === 'ALLOCATED', [selectedClient]);

    // RULE 3: Determine if plots are pre-reserved
    const isReserved = useMemo(() => selectedClient?.allocationStatus === 'RESERVED_NOT_ALLOCATED' && selectedPlots.length > 0, [selectedClient, selectedPlots]);

    const globalPlotStatus = useMemo(() => {
        const pool: Record<string, { allocated: boolean, owner?: string, status?: AllocationStatus }> = {};
        clients.forEach(c => {
            if (c.plot && c.plot !== 'N/A') {
                c.plot.split(',').forEach(p => {
                    const plotNum = p.trim().toUpperCase();
                    if (plotNum) {
                        pool[plotNum] = { 
                            // Rule: ONLY 'ALLOCATED' status strictly blocks selection for other clients.
                            allocated: c.allocationStatus === 'ALLOCATED', 
                            owner: c.name,
                            status: c.allocationStatus
                        };
                    }
                });
            }
        });
        return pool;
    }, [clients]);

    const availablePlotsList = useMemo(() => {
        if (!selectedProperty || !selectedProperty.inventory) return [];
        const plots: { plotNumber: string; isTaken: boolean; owner?: string; status?: AllocationStatus }[] = [];
        selectedProperty.inventory.forEach((inv: any) => {
            const prefix = inv.zone || 'P1';
            for (let i = 1; i <= inv.count; i++) {
                const pNum = `${prefix}-${i}`;
                plots.push({
                    plotNumber: pNum,
                    isTaken: globalPlotStatus[pNum]?.allocated || false,
                    owner: globalPlotStatus[pNum]?.owner,
                    status: globalPlotStatus[pNum]?.status
                });
            }
        });
        return plots;
    }, [selectedProperty, globalPlotStatus]);

    const masterPlotList = useMemo(() => {
        const prop = properties.find(p => p.id === viewAllLocationId);
        if (!prop || !prop.inventory) return [];

        const all: { plotNumber: string; size: string; allocatedTo: string | null; isProvisional: boolean, status?: AllocationStatus }[] = [];
        prop.inventory.forEach((inv: any) => {
            const prefix = inv.zone || 'P1';
            for (let i = 1; i <= inv.count; i++) {
                const pNum = `${prefix}-${i}`;
                const ownerInfo = globalPlotStatus[pNum];

                let isProvisional = false;
                if (ownerInfo?.allocated || ownerInfo?.status === 'RESERVED_NOT_ALLOCATED') {
                    const client = clients.find(c => c.name === ownerInfo.owner);
                    if (client) {
                        const pct = client.paidPercent || 0;
                        isProvisional = pct < 70;
                    }
                }

                all.push({
                    plotNumber: pNum,
                    size: inv.size,
                    allocatedTo: ownerInfo?.owner || null,
                    isProvisional,
                    status: ownerInfo?.status
                });
            }
        });

        return all.filter(p => {
            if (statusFilter === 'Allocated') return p.allocatedTo !== null;
            if (statusFilter === 'Available') return p.allocatedTo === null;
            return true;
        });
    }, [viewAllLocationId, properties, globalPlotStatus, clients, statusFilter]);

    const handlePlotToggle = (plot: string) => {
        // Rule 2: If client plots exist (Reserved state), make them read-only
        if (isReserved || globalPlotStatus[plot]?.allocated || isAlreadyAllocated) return;
        setSelectedPlots(prev => prev.includes(plot) ? prev.filter(p => p !== plot) : [...prev, plot]);
    };

    const handleConfirmAllocation = async () => {
        if (!selectedClient || selectedPlots.length === 0 || isAlreadyAllocated) return;
        setIsSaving(true);
        try {
            const updatedClient: Client = {
                ...selectedClient,
                plot: selectedPlots.join(', '),
                allocationStatus: 'ALLOCATED', // Authority: Elevate status on confirmation
                interactions: [
                    { id: Date.now(), type: 'Note', date: new Date().toISOString(), agent: 'System', notes: `Plots ${selectedPlots.join(', ')} confirmed for ALLOCATION at ${selectedProperty?.location}.` },
                    ...selectedClient.interactions
                ]
            };
            await saveClient(updatedClient);
            setAllocationSuccess(true);
            setTimeout(() => onBack(), 2000);
        } catch (error) {
            alert('Save failed.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors"><ArrowLeftIcon className="w-5 h-5" /> Back</button>
                    <div className="flex items-center gap-4">
                        <UserCheckIcon className="w-10 h-10 text-blue-600" />
                        <div>
                            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">ALLOCATE Plot</h1>
                            <p className="text-gray-500 dark:text-gray-400 mt-1">Single source inventory partitioning and ALLOCATION.</p>
                        </div>
                    </div>
                </div>
            </div>

            {allocationSuccess && <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded shadow-md animate-bounce">ALLOCATION Successful!</div>}

            <Card className="bg-white dark:bg-gray-800">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <Select 
                        label="1. Client" 
                        value={selectedClientId} 
                        onChange={(e) => handleClientChange(e.target.value ? Number(e.target.value) : '')}
                    >
                        <option value="">-- Select Client --</option>
                        {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </Select>

                    <div>
                        <Input 
                            label="2. Location (Auto-detected)" 
                            value={selectedClient ? (selectedClient.location || 'Not Specified') : 'Select client to load location'} 
                            readOnly 
                            className="bg-gray-50 dark:bg-gray-900 font-bold cursor-not-allowed"
                        />
                        {selectedClient && (!selectedClient.location || selectedClient.location === 'N/A') && (
                            <div className="mt-2 flex items-center gap-2 p-2 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 text-[10px] font-black uppercase rounded border border-red-100 dark:border-red-900/50">
                                <ExclamationTriangleIcon className="w-3.5 h-3.5" />
                                Client has no saved location. Update client details first.
                            </div>
                        )}
                    </div>
                </div>
                <div className="mt-4 pt-4 border-t border-gray-100 dark:border-gray-700">
                    <button onClick={() => setIsViewAllOpen(!isViewAllOpen)} className="text-sm font-bold text-indigo-600 hover:underline flex items-center gap-1">
                        <EyeIcon className="w-4 h-4" /> View Site Map Ledger
                    </button>
                    {isViewAllOpen && (
                        <SiteMapLedger 
                            properties={properties}
                            viewAllLocationId={viewAllLocationId}
                            setViewAllLocationId={setViewAllLocationId}
                            statusFilter={statusFilter}
                            setStatusFilter={setStatusFilter}
                            masterPlotList={masterPlotList}
                        />
                    )}
                </div>
            </Card>

            {selectedClient && selectedProperty ? (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4">
                    <QualificationCard client={selectedClient} />

                    <PlotSelectionGrid 
                        property={selectedProperty}
                        availablePlots={availablePlotsList}
                        selectedPlots={selectedPlots}
                        onTogglePlot={handlePlotToggle}
                        onConfirm={handleConfirmAllocation}
                        isSaving={isSaving}
                        isAlreadyAllocated={isAlreadyAllocated}
                        isReserved={isReserved}
                        clientPlotNumbers={selectedClient.plot}
                        clientPaidPercent={selectedClient.paidPercent}
                    />
                </div>
            ) : selectedClient && (
                <div className="p-12 text-center bg-white dark:bg-gray-800 rounded-xl border-2 border-dashed border-gray-200 dark:border-gray-700 opacity-60">
                    <p className="text-sm font-bold text-gray-400 uppercase tracking-widest">
                        Cannot load plots: Missing or Invalid Location Context
                    </p>
                </div>
            )}
            <style>{` .scrollbar-thin::-webkit-scrollbar { width: 4px; } .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; } `}</style>
        </div>
    );
};

export default AllocatePlotPage;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Sidebar from './Sidebar';
import Header, { HeaderNotification } from './Header';
import { Staff, PermissionSet, CompanySettings } from '../types';
import { useData } from '../context/DataContext';
import { useClients, useRoles } from '../hooks/useAppData';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { ToastNotification } from './ui/ToastNotification';

interface LayoutProps {
    children: React.ReactNode;
    activePage: string;
    setActivePage: (page: string, context?: any) => void;
    currentStaff: Staff;
    onLogout: () => void;
    staffPermissions: { [key: string]: PermissionSet };
    companySettings: CompanySettings;
}

const Layout: React.FC<LayoutProps> = ({ children, activePage, setActivePage, currentStaff, onLogout, staffPermissions, companySettings }) => {
    const [isMobileSidebarOpen, setMobileSidebarOpen] = useState(false);
    const [isDesktopSidebarCollapsed, setDesktopSidebarCollapsed] = useState(false);

    // Local state to track alerts handled in current session (since backend is read-only)
    const [handledAlertIds, setHandledAlertIds] = useState<string[]>([]);

    // Data Hooks
    const { internalMails } = useData();
    const { clients } = useClients(); 
    const { roles } = useRoles(); 

    const systemAlerts = useNotificationTriggers(clients);

    const handleMarkAlertHandled = (id: string) => {
        setHandledAlertIds(prev => [...new Set([...prev, id])]);
    };

    // -- Global Notification Aggregation --
    const headerNotifications = useMemo(() => {
        const aggregated: HeaderNotification[] = [];
        const userRoleName = roles.find(r => r.id === currentStaff.roleId)?.name;

        // 1. Filter System Alerts by Role and Session-Handled State
        const myAlerts = systemAlerts.filter(alert => 
            alert.recipientRole === userRoleName && 
            !alert.isRead && 
            !handledAlertIds.includes(alert.id)
        );

        myAlerts.forEach(alert => {
            aggregated.push({
                id: alert.id,
                title: alert.title,
                description: alert.message,
                timestamp: alert.timestamp,
                type: 'alert',
                targetPage: 'Account Management',
                targetContext: { view: 'alerts', alertId: alert.id } 
            });
        });

        // 2. Filter Unread Mails
        const myMails = internalMails.filter(m => 
            m.recipientIds.includes(currentStaff.id) && 
            !m.readBy.includes(currentStaff.id) && 
            !m.isDeleted
        );
        myMails.forEach(mail => {
            aggregated.push({
                id: mail.id,
                title: mail.subject,
                description: mail.body.length > 80 ? `${mail.body.substring(0, 80)}...` : mail.body,
                timestamp: mail.timestamp,
                type: 'mail',
                targetPage: mail.targetPage || 'Mailing',
                targetContext: mail.targetContext || null
            });
        });

        return aggregated.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [systemAlerts, internalMails, currentStaff, roles, handledAlertIds]);

    const unreadMailsCount = useMemo(() => {
        if (!currentStaff) return 0;
        return internalMails.filter(m => 
            m.recipientIds.includes(currentStaff.id) && 
            !m.readBy.includes(currentStaff.id) && 
            !m.isDeleted && 
            !m.isDraft
        ).length;
    }, [internalMails, currentStaff]);


    // -- Toast Notification Logic --
    const [toast, setToast] = useState<{ message: string; subtext: string } | null>(null);
    const prevMailsLengthRef = useRef(internalMails.length);
    const initialLoadRef = useRef(true);

    useEffect(() => {
        if (initialLoadRef.current) {
            initialLoadRef.current = false;
            prevMailsLengthRef.current = internalMails.length;
            return;
        }

        if (internalMails.length > prevMailsLengthRef.current) {
            const newMails = internalMails.slice(0, internalMails.length - prevMailsLengthRef.current);
            const latestMail = newMails[0]; 

            if (latestMail && latestMail.recipientIds.includes(currentStaff.id) && latestMail.senderId !== currentStaff.id) {
                setToast({
                    message: latestMail.subject.includes('New Client') ? 'Onboarding Alert' : `New Message from ${latestMail.senderName}`,
                    subtext: latestMail.subject
                });
                try {
                    const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
                    audio.volume = 0.5;
                    audio.play().catch(() => {});
                } catch(e) {}
            }
        }
        prevMailsLengthRef.current = internalMails.length;
    }, [internalMails, currentStaff.id]);

    const handleNotificationInteraction = (n: HeaderNotification) => {
        if (n.type === 'alert') {
            handleMarkAlertHandled(n.id);
        }
        setActivePage(n.targetPage, n.targetContext);
    };

    return (
        <div className="flex h-screen bg-gray-100 dark:bg-gray-950 transition-colors duration-200">
            <Sidebar 
                isMobileOpen={isMobileSidebarOpen}
                onMobileClose={() => setMobileSidebarOpen(false)}
                isDesktopCollapsed={isDesktopSidebarCollapsed}
                activePage={activePage}
                setActivePage={setActivePage}
                staffPermissions={staffPermissions}
                companySettings={companySettings}
                onLogout={onLogout}
            />
            <div className="flex-1 flex flex-col overflow-hidden relative">
                <Header 
                    onMobileMenuToggle={() => setMobileSidebarOpen(true)}
                    onDesktopToggle={() => setDesktopSidebarCollapsed(prev => !prev)}
                    isDesktopCollapsed={isDesktopSidebarCollapsed}
                    currentStaff={currentStaff}
                    onLogout={onLogout}
                    setActivePage={handleNotificationInteraction}
                    notifications={headerNotifications}
                    unreadMailsCount={unreadMailsCount}
                />
                <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-950 transition-colors duration-200 flex flex-col">
                    <div className="container mx-auto px-6 py-8 flex-grow">
                        {/* Inject handledAlertIds/handleMarkAlertHandled into context if necessary, 
                            but for now we'll pass to specific pages via context if needed or just handle via setActivePage context */}
                        {React.cloneElement(children as React.ReactElement, { 
                            handledAlertIds, 
                            onMarkAlertHandled: handleMarkAlertHandled 
                        })}
                    </div>
                </main>

                {toast && (
                    <ToastNotification 
                        message={toast.message} 
                        subtext={toast.subtext} 
                        onClose={() => setToast(null)} 
                    />
                )}
            </div>
        </div>
    );
};

export default Layout;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    DocumentTextIcon,
    ChartBarIcon,
    DocumentDuplicateIcon
} from '../components/icons/DummyIcons';
import { Button } from '../components/ui/Button';
import { Select } from '../components/ui/Input';
import { NotificationCenter } from '../components/NotificationCenter';
import { AccountOverview } from '../components/account/AccountOverview';
import { AccountHistory } from '../components/account/AccountHistory';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useProperties, useMilestones } from '../hooks/useAppData';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';
import { AccountStatementModal } from '../components/financials/AccountStatementModal';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect?: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
  overrideClientId?: number | null;
  isEmbedded?: boolean;
  handledAlertIds?: string[];
  onMarkAlertHandled?: (id: string) => void;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage, 
    overrideClientId = null, isEmbedded = false, handledAlertIds = [], onMarkAlertHandled
}) => {
  const { properties } = useProperties();
  const { saveMilestone } = useMilestones();
  const { openModal } = useModal();
  const [viewMode, setViewMode] = useState<'list' | 'alerts'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(overrideClientId);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isStatementModalOpen, setStatementModalOpen] = useState(false);

  // Sync viewMode with context if deep linked from notification
  useEffect(() => {
    // Note: pageContext/context handling is usually in App.tsx/Layout, but here we can check if we were passed a signal
  }, []);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (selectedClientId || clientForInvoice?.id))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);
  const isHeadOfAccounts = useMemo(() => currentStaff.roleId === 'Chief Accountant', [currentStaff]);

  const canGenerateStatement = useMemo(() => isCEO || isHeadOfAccounts, [isCEO, isHeadOfAccounts]);

  const canMakePayment = useMemo(() => {
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  const originalPricePerPlot = useMemo(() => {
    if (!selectedClient) return 0;
    const matchingProperty = properties.find(p => p.location === selectedClient.location);
    return matchingProperty ? matchingProperty.price : 0;
  }, [selectedClient, properties]);

  const discountAmount = selectedClient?.payment.promoDetails ? (originalPricePerPlot * 0.1) : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land';
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async () => {
    if (!selectedClient) return;
    setIsSaving(true);
    try {
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: installmentOption,
                total: priceAfterDiscount,
                balance: priceAfterDiscount - selectedClient.payment.paid
            }
        };
        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const newPaid = client.payment.paid + newTransaction.amount;
    const newBalance = client.payment.balance - newTransaction.amount;

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: newPaid,
            balance: newBalance,
        }
    };
    await onSaveClient(updatedClient);

    if (newBalance <= 0) {
        await saveMilestone({
            clientId: client.id,
            milestoneCode: 'PLR',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Full payment for land received.'
        });
    }

    if (paymentData.type === 'Indenture') {
        await saveMilestone({
            clientId: client.id,
            milestoneCode: 'PFI',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Payment for indenture documents received.'
        });
    }
  };

  const openPaymentModal = () => {
      if(selectedClient) {
          openModal(MODAL_TYPES.RECORD_PAYMENT, {
              client: selectedClient,
              onSave: (data: any) => handleRecordPayment(selectedClient, data)
          });
      }
  };

  const systemAlerts = useNotificationTriggers(clients);
  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';

  // Filter alerts for visibility: Role match AND not handled in this session
  const activeRoleAlerts = useMemo(() => {
    return systemAlerts.filter(n => n.recipientRole === currentRoleName && !handledAlertIds.includes(n.id));
  }, [systemAlerts, currentRoleName, handledAlertIds]);

  const handleReschedule = (id: string) => {
    if (onMarkAlertHandled) onMarkAlertHandled(id);
  };

  const handleMarkRead = (id: string) => {
    if (onMarkAlertHandled) onMarkAlertHandled(id);
  };

  return (
    <div className={`flex flex-col ${isEmbedded ? 'h-auto' : 'h-[calc(100vh-120px)]'} space-y-6`}>
      {!isEmbedded && (
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
              <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
              <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm font-medium">Standard bookkeeping ledger and transactional audit.</p>
          </div>
          <div className="flex gap-3">
            {canGenerateStatement && (
              <Button 
                variant="secondary"
                disabled={!selectedClient}
                className="bg-indigo-50 border-indigo-200 text-indigo-700 dark:bg-indigo-900/20 dark:border-indigo-800 dark:text-indigo-400 font-bold"
                onClick={() => setStatementModalOpen(true)}
                icon={<DocumentDuplicateIcon className="w-5 h-5" />}
              >
                Official Statement
              </Button>
            )}
            <Button 
              variant={activeRoleAlerts.length > 0 ? 'primary' : 'secondary'} 
              onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
              icon={<BellIcon className="w-5 h-5" />}
              className="relative"
            >
                Role Alerts
                {activeRoleAlerts.length > 0 && (
                    <span className="absolute -top-1 -right-1 flex h-4 w-4">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{activeRoleAlerts.length}</span>
                    </span>
                )}
            </Button>
            <Button variant="secondary" onClick={() => setActivePage('Analytics & Reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
                Business Analysis
            </Button>
          </div>
        </div>
      )}

      <div className="flex-grow flex gap-6 overflow-hidden">
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          {!isEmbedded && (
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
               <Select 
                label="Select Account" 
                value={selectedClientId || ''} 
                onChange={(e) => {
                    setSelectedClientId(Number(e.target.value));
                    setClientForInvoice(null);
                }}
              >
                <option value="">-- Choose Client --</option>
                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </Select>
            </div>
          )}
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={systemAlerts}
                    currentRole={currentRoleName}
                    handledAlertIds={handledAlertIds}
                    onReschedule={handleReschedule}
                    onMarkRead={handleMarkRead}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40 py-20">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">
                    {isEmbedded ? 'Client data unavailable.' : 'Select a Client to view financial records'}
                  </p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <AccountOverview
                    selectedClient={selectedClient}
                    originalPricePerPlot={originalPricePerPlot}
                    discountAmount={discountAmount}
                    priceAfterDiscount={priceAfterDiscount}
                    installmentOption={installmentOption}
                    setInstallmentOption={setInstallmentOption}
                    onInitialSave={handleInitialSave}
                    isSaving={isSaving}
                />
            ) : (
                <AccountHistory 
                    selectedClient={selectedClient}
                    canMakePayment={canMakePayment}
                    isCEO={isCEO}
                    onMakePayment={openPaymentModal}
                    onAuthorizeAmendment={() => setActivePage('Amendment Form', selectedClient)}
                    paymentAggregation={paymentAggregation}
                />
            )}
        </div>
      </div>

      {isStatementModalOpen && selectedClient && (
          <AccountStatementModal 
            isOpen={isStatementModalOpen}
            onClose={() => setStatementModalOpen(false)}
            client={selectedClient}
            properties={properties}
          />
      )}
    </div>
  );
};

