import React from 'react';
import { VariableSizeList as List } from 'react-window';
import AutoSizer from 'react-virtualized-auto-sizer';
import ClientListItem from '../ClientListItem';
import { Client, Milestone } from '../../types';

interface ClientsListProps {
    clients: Client[];
    onViewDetails: (client: Client) => void;
    onEdit: (client: Client) => void;
    onDelete: (id: number) => void;
    milestones: Milestone[];
    expandedIds: Record<number, boolean>;
    toggleExpand: (id: number, index: number) => void;
    onScroll: (props: { scrollOffset: number }) => void;
    listRef: React.RefObject<List>;
}

export const ClientsList: React.FC<ClientsListProps> = ({
    clients, onViewDetails, onEdit, onDelete, milestones, expandedIds, toggleExpand, onScroll, listRef
}) => {
    const getItemSize = (index: number) => {
        // Reduced standard height from 100 to 64 for a compact view.
        // Stage progress bars are removed, so expanded height is no longer needed but kept for safety.
        return expandedIds[clients[index]?.id] ? 120 : 64;
    };

    const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => {
        const client = clients[index];
        if (!client) return null;
        return (
            <ClientListItem 
                key={client.id} 
                client={client} 
                onViewDetails={onViewDetails} 
                onEdit={onEdit} 
                onDelete={onDelete} 
                milestones={milestones}
                style={style}
                isExpanded={!!expandedIds[client.id]}
                onToggleExpand={() => toggleExpand(client.id, index)}
            />
        );
    };

    return (
        <div className="flex-grow relative mt-1">
            <AutoSizer>
                {({ height, width }) => (
                    <List
                        ref={listRef}
                        height={height}
                        itemCount={clients.length}
                        itemSize={getItemSize}
                        width={width}
                        onScroll={onScroll}
                        className="scrollbar-thin"
                    >
                        {Row}
                    </List>
                )}
            </AutoSizer>
        </div>
    );
};

