                    {properties.map(p => <option key={p.id} value={p.id}>{p.location}</option>)}
                </Select>
                <Select label="Filter" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as any)}>
                    <option value="All">All</option>
                    <option value="Allocated">ALLOCATED</option>
                    <option value="Available">Available</option>
                </Select>
            </div>
            <TableContainer className="max-h-[300px]">
                <table className="w-full text-xs">
                    <Thead><tr><Th>Plot</Th><Th>Owner</Th><Th className="text-center">Status</Th></tr></Thead>
                    <Tbody>
                        {masterPlotList.map((p, i) => {
                            const isReservedOnly = p.status === 'RESERVED_NOT_ALLOCATED';

                            return (
                                <Tr key={i}>
                                    <Td className={`font-mono font-bold ${isReservedOnly ? 'text-amber-600 dark:text-amber-400' : ''}`}>
                                        {p.plotNumber} {isReservedOnly && <span className="text-[9px] font-normal italic ml-1">(RESERVED not ALLOCATED)</span>}
                                    </Td>
                                    <Td>{p.allocatedTo || '—'}</Td>
                                    <Td className="text-center">
                                        <Badge variant={p.allocatedTo ? (isReservedOnly || p.isProvisional ? 'warning' : 'success') : 'success'}>
                                            {p.allocatedTo ? (isReservedOnly || p.isProvisional ? 'RESERVED' : 'ALLOCATED') : 'Available'}
                                        </Badge>
                                    </Td>
                                </Tr>
                            );
                        })}
                    </Tbody>
                </table>
            </TableContainer>
        </div>
    );
};

import React from 'react';
import { Client, Milestone } from '../types';
import { EyeIcon, PencilIcon, CheckCircleIcon, ExclamationTriangleIcon, TrashIcon } from './icons/DummyIcons';
import { Badge } from './ui/Badge';

interface ClientListItemProps {
  client: Client;
  onViewDetails: (client: Client) => void;
  onEdit: (client: Client) => void;
  onDelete: (clientId: number) => void;
  milestones: Milestone[];
  style?: React.CSSProperties; // For virtualization positioning
  isExpanded?: boolean;
  onToggleExpand?: () => void;
}

const getStatusColor = (status: Client['status']) => {
  switch (status) {
    case 'Active Client':
      return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
    case 'Refunded':
      return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200';
    case 'Reallocated':
      return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200';
    default:
      return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300';
  }
};

const formatCurrency = (amount: number) => {
    return `GHC ${new Intl.NumberFormat('en-GH').format(amount)}`;
};

const ClientListItem: React.FC<ClientListItemProps> = ({ 
    client, 
    onViewDetails, 
    onEdit, 
    onDelete, 
    style
}) => {
  const isAllocated = client.allocationStatus === 'ALLOCATED';
  const hasPlot = client.plot && client.plot !== 'N/A';

  return (
    <div style={style} className="px-2 group">
        <div className="bg-white dark:bg-gray-900/50 py-2 px-4 border-b border-gray-100 dark:border-gray-800 grid grid-cols-12 gap-4 items-center hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors h-full">
            {/* Client & Phone */}
            <div className="col-span-12 md:col-span-4 flex items-center gap-3">
                <div 
                    title={client.isComplete ? 'Complete' : 'Incomplete'}
                    className={`w-9 h-9 rounded-full flex items-center justify-center font-bold flex-shrink-0 text-xs text-white ${client.isComplete ? 'bg-green-500' : 'bg-red-500'}`}
                >
                    {client.initials}
                </div>
                <div className="flex-grow min-w-0">
                    <p className="text-base font-bold text-gray-900 dark:text-white flex items-center gap-1.5 truncate">
                        {client.name}
                        <span title={client.isComplete ? "Complete" : "Incomplete"}>
                            {client.isComplete 
                                ? <CheckCircleIcon className="w-4 h-4 text-green-500" /> 
                                : <ExclamationTriangleIcon className="w-4 h-4 text-red-500" />}
                        </span>
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400 font-medium">{client.phone}</p>
                </div>
            </div>

            {/* Location */}
            <div className="col-span-12 md:col-span-4 text-sm flex items-center gap-3">
                <div className="flex-grow min-w-0">
                    <p className="font-semibold text-gray-700 dark:text-gray-200 truncate" title={client.location}>
                        {client.location}
                    </p>
                    <div className="flex items-center gap-2">
                        <p className="text-xs text-gray-400 truncate">{client.plot}</p>
                        {hasPlot && (
                            <Badge variant={isAllocated ? 'success' : 'warning'} className="text-[8px] uppercase px-1 py-0 font-black tracking-tighter">
                                {isAllocated ? 'ALLOC' : 'RES'}
                            </Badge>
                        )}
                    </div>
                </div>
            </div>

            {/* Status */}
            <div className="col-span-6 md:col-span-1 text-center">
                <span className={`px-2 py-0.5 text-xs font-bold rounded-full ${getStatusColor(client.status)}`}>
                    {client.status.split(' ')[0]}
                </span>
            </div>

            {/* Financials (Outstanding Only) */}
            <div className="col-span-12 md:col-span-2 text-sm">
                <p className="font-black text-gray-800 dark:text-gray-200">{formatCurrency(client.payment.balance)}</p>
            </div>

            {/* Actions - Hidden by default on desktop, shown on group-hover */}
            <div className="col-span-12 md:col-span-1 flex items-center gap-1 justify-end opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                <button onClick={() => onViewDetails(client)} className="text-gray-400 hover:text-blue-600 p-1.5 rounded-full transition-colors" title="View">
                    <EyeIcon className="w-5 h-5"/>
