import React, { useMemo } from 'react';
import { Client } from '../../types';
import { Card } from '../ui/Card';
import { Badge } from '../ui/Badge';
import { 
    UserCircleIcon, 
    MapPinIcon, 
    LockClosedIcon, 
    ExclamationTriangleIcon, 
    CheckCircleIcon,
    InformationCircleIcon 
} from '../icons/DummyIcons';

interface QualificationCardProps {
    client: Client;
}

export const QualificationCard: React.FC<QualificationCardProps> = ({ client }) => {
    const qualification = useMemo(() => {
        if (!client) return { isQualified: false, percentage: 0, status: 'N/A', hasAllocated: false };

        const total = client.payment.total || 1;
        const paid = client.payment.paid || 0;
        const percentage = (paid / total) * 100;
        const isQualified = percentage >= 70;
        const hasAllocated = client.allocationStatus === 'ALLOCATED';

        return {
            percentage: Math.round(percentage),
            isQualified,
            hasAllocated,
            status: hasAllocated 
                ? 'Record Finalized' 
                : isQualified 
                    ? 'Qualified (≥70%)' 
                    : 'Provisionally Flagged (<70%)'
        };
    }, [client]);

    const hasPlots = client.plot && client.plot !== 'N/A' && client.plot.trim() !== '';

    return (
        <Card title="Qualification Detail" className="lg:col-span-1 space-y-6">
            {/* Part A: Payment Status */}
            <div className="text-center space-y-4">
                <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Payment Progress</p>
                <div className="relative">
                    <p className={`text-2xl font-black ${qualification.hasAllocated ? 'text-blue-600' : qualification.isQualified ? 'text-green-600' : 'text-amber-600'}`}>
                        {qualification.percentage}%
                    </p>
                    <p className="text-[10px] font-bold text-gray-500 uppercase mt-1">{qualification.status}</p>
                </div>
                <div className="w-full bg-gray-100 dark:bg-gray-700 h-2.5 rounded-full overflow-hidden shadow-inner">
                    <div 
                        className={`h-full transition-all duration-1000 ${qualification.hasAllocated ? 'bg-blue-600' : qualification.isQualified ? 'bg-green-500' : 'bg-amber-500'}`} 
                        style={{ width: `${qualification.percentage}%` }}
                    ></div>
                </div>
            </div>

            {/* Part B: Allocation Audit */}
            <div className="pt-6 border-t border-gray-100 dark:border-gray-700 space-y-4">
                <div className="space-y-2">
                    <div className="flex items-center gap-2 text-xs">
                        <UserCircleIcon className="w-4 h-4 text-gray-400" />
                        <span className="text-gray-500 font-medium">Client:</span>
                        <span className="font-bold text-gray-900 dark:text-white">{client.name}</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs">
                        <MapPinIcon className="w-4 h-4 text-gray-400" />
                        <span className="text-gray-500 font-medium">Location:</span>
                        <span className="font-bold text-gray-900 dark:text-white">{client.location || 'NONE'}</span>
                    </div>
                    <div className="flex items-center gap-2 text-xs">
                        <InformationCircleIcon className="w-4 h-4 text-gray-400" />
                        <span className="text-gray-500 font-medium">Plot(s):</span>
                        <span className="font-bold text-gray-900 dark:text-white">{hasPlots ? client.plot : 'NONE'}</span>
                    </div>
                    <div className="flex flex-col gap-1 pt-2">
                        <div className="flex items-center gap-2 text-xs">
                            <span className="text-gray-500 font-medium">Plot Status:</span>
                            <Badge 
                                variant={qualification.hasAllocated ? 'success' : hasPlots ? 'warning' : 'neutral'} 
                                className="font-black uppercase tracking-tighter text-[10px]"
                            >
                                {qualification.hasAllocated ? 'ALLOCATED' : hasPlots ? 'RESERVED' : 'NONE'}
                            </Badge>
                        </div>
                        {!hasPlots && (
                            <p className="text-[10px] font-bold text-amber-600 dark:text-amber-400 italic">
                                No plots reserved for this client yet.
                            </p>
                        )}
                    </div>
                </div>

                <div className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-100 dark:border-gray-800">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-tight">
                        {qualification.hasAllocated ? 'Allocation record verified.' : 'No allocation has been done for this client.'}
                    </p>
                </div>

                {/* Allocation Specific Messages */}
                {qualification.hasAllocated ? (
                    <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border-l-4 border-blue-600 rounded-r-lg space-y-2 animate-in fade-in slide-in-from-top-1">
                        <div className="flex items-center gap-2 text-blue-800 dark:text-blue-400">
                            <LockClosedIcon className="w-4 h-4 shadow-sm" />
                            <p className="text-[10px] font-black uppercase tracking-tight">Allocation Finalized</p>
                        </div>
                        <p className="text-xs text-blue-700 dark:text-blue-300 leading-relaxed font-medium">
                            Allocation already completed. Plot number(s) <span className="font-black underline">{client.plot}</span> have been allocated to this client. 
                        </p>
                        <p className="text-[10px] text-blue-500 italic font-bold">
                            Request amendment to add or update plot numbers.
                        </p>
                    </div>
                ) : !qualification.isQualified ? (
                    <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border-l-4 border-amber-500 rounded-r-lg space-y-1 animate-in fade-in slide-in-from-top-1">
                        <div className="flex items-center gap-2 text-amber-800 dark:text-amber-400">
                            <ExclamationTriangleIcon className="w-4 h-4" />
                            <p className="text-[10px] font-black uppercase tracking-tight">Ineligible for Allocation</p>
                        </div>
                        <p className="text-xs text-amber-700 dark:text-amber-300 font-medium">
                            Client has not paid up to 70%. Allocation cannot be confirmed.
                        </p>
                    </div>
                ) : (
                    <div className="p-4 bg-green-50 dark:bg-green-900/20 border-l-4 border-green-600 rounded-r-lg space-y-1 animate-in fade-in slide-in-from-top-1">
                        <div className="flex items-center gap-2 text-green-800 dark:text-green-400">
                            <CheckCircleIcon className="w-4 h-4" />
                            <p className="text-[10px] font-black uppercase tracking-tight">Eligibility Verified</p>
                        </div>
                        <p className="text-xs text-green-700 dark:text-green-300 font-medium">
                            Client qualifies for allocation. Confirm allocation in the panel to finalize.
                        </p>
                    </div>
                )}
            </div>
        </Card>
    );
};

import React, { useState } from 'react';
import { Client } from '../../types';
import { XMarkIcon, ExclamationTriangleIcon } from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';

interface RecordPaymentModalProps {
    isOpen: boolean;
    onClose: () => void;
    client: Client;
    onSave: (paymentData: any) => Promise<void> | void;
}

export const RecordPaymentModal: React.FC<RecordPaymentModalProps> = ({ isOpen, onClose, client, onSave }) => {
    const [amount, setAmount] = useState('');
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>('Land');

    // UI State for Submission Flow
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (!amount || parseFloat(amount) <= 0) {
            setError("Please enter a valid amount.");
            return;
        }

        setIsSubmitting(true);
        try {
            // Await the save operation provided by parent
            await onSave({
                amount: parseFloat(amount),
                method,
                receiptNumber,
                type,
                date: new Date().toISOString().split('T')[0]
            });

            // On Success: Automatically close the window
            onClose();
        } catch (err: any) {
            // On Failure: Keep window open and show error
            console.error("Payment Submission Error:", err);
            setError(err.message || "Failed to post transaction. Please verify your connection.");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/60 z-[100] flex justify-center items-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <Card className="w-full max-w-md p-0 overflow-hidden shadow-2xl animate-in zoom-in duration-300">
                <form onSubmit={handleSubmit}>
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900">
                        <div className="flex flex-col">
                            <h3 className="font-bold text-gray-900 dark:text-white uppercase tracking-tight">Record New Payment</h3>
                            <p className="text-[10px] text-gray-500 font-medium uppercase">{client.name}</p>
                        </div>
                        <button 
                            type="button" 
                            onClick={onClose} 
                            disabled={isSubmitting}
                            className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
                        >
                            <XMarkIcon className="w-6 h-6"/>
                        </button>
                    </div>

                    <div className="p-6 space-y-4 bg-white dark:bg-gray-800">
                        {error && (
                            <div className="p-3 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded flex gap-2 animate-in slide-in-from-top-1">
                                <ExclamationTriangleIcon className="w-5 h-5 text-red-600 shrink-0" />
                                <p className="text-xs text-red-800 dark:text-red-200 font-medium">{error}</p>
                            </div>
                        )}

                        <Input 
                            label="Amount (GHC)*" 
                            type="number" 
                            value={amount} 
                            onChange={e => setAmount(e.target.value)} 
                            required 
                            disabled={isSubmitting}
                            className="font-bold text-lg"
                        />

                        <div className="grid grid-cols-1 gap-4">
                            <Select 
                                label="Payment Method*" 
                                value={method} 
                                onChange={e => setMethod(e.target.value as any)} 
                                required 
                                disabled={isSubmitting}
                            >
                                <option>Bank Transfer</option>
                                <option>MoMo</option>
                                <option>Cash</option>
                                <option>Cheque</option>
                                <option>Other</option>
                            </Select>

                            <Select 
                                label="Transaction Type*" 
                                value={type} 
                                onChange={e => setType(e.target.value as any)} 
                                required 
                                disabled={isSubmitting}
                            >
                                <option value="Land">Land Payment</option>
                                <option value="Indenture">Indenture / Documentation</option>
                                <option value="Commission">Commission Payout</option>
                            </Select>
                        </div>

                        <Input 
                            label="Receipt Number*" 
                            value={receiptNumber} 
                            onChange={e => setReceiptNumber(e.target.value)} 
                            required 
                            disabled={isSubmitting}
                            placeholder="e.g. REC-100234"
                            className="font-mono uppercase"
                        />
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <button 
                            type="button" 
                            onClick={onClose}
                            disabled={isSubmitting}
                            className="px-4 py-2 text-sm font-bold text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-200 transition-colors disabled:opacity-50"
                        >
                            Cancel
                        </button>
                        <Button 
                            type="submit" 
                            variant="success"
                            isLoading={isSubmitting}
                            className="font-black uppercase tracking-widest px-6"
                        >
                            Post Transaction
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    DocumentTextIcon,
    ChartBarIcon,
    DocumentDuplicateIcon
} from '../components/icons/DummyIcons';
import { Button } from '../components/ui/Button';
import { Select } from '../components/ui/Input';
import { NotificationCenter } from '../components/NotificationCenter';
import { AccountOverview } from '../components/account/AccountOverview';
import { AccountHistory } from '../components/account/AccountHistory';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useProperties, useMilestones } from '../hooks/useAppData';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';
import { AccountStatementModal } from '../components/financials/AccountStatementModal';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect?: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
  overrideClientId?: number | null;
  isEmbedded?: boolean;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage, overrideClientId = null, isEmbedded = false
}) => {
  const { properties } = useProperties();
  const { saveMilestone } = useMilestones();
  const { openModal } = useModal();
  const [viewMode, setViewMode] = useState<'list' | 'alerts'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(overrideClientId);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isStatementModalOpen, setStatementModalOpen] = useState(false);

  useEffect(() => {
    if (overrideClientId !== null) {
      setSelectedClientId(overrideClientId);
    }
  }, [overrideClientId]);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (selectedClientId || clientForInvoice?.id))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);
  const isHeadOfAccounts = useMemo(() => currentStaff.roleId === 'Chief Accountant', [currentStaff]);

  // Rule: Statement access is restricted
  const canGenerateStatement = useMemo(() => isCEO || isHeadOfAccounts, [isCEO, isHeadOfAccounts]);

  const canMakePayment = useMemo(() => {
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  const originalPricePerPlot = useMemo(() => {
    if (!selectedClient) return 0;
    const matchingProperty = properties.find(p => p.location === selectedClient.location);
    return matchingProperty ? matchingProperty.price : 0;
  }, [selectedClient, properties]);

  const discountAmount = selectedClient?.payment.promoDetails ? (originalPricePerPlot * 0.1) : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land';
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async () => {
    if (!selectedClient) return;
    setIsSaving(true);
    try {
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: installmentOption,
                total: priceAfterDiscount,
                balance: priceAfterDiscount - selectedClient.payment.paid
            }
        };
        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const newPaid = client.payment.paid + newTransaction.amount;
    const newBalance = client.payment.balance - newTransaction.amount;

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: newPaid,
            balance: newBalance,
        }
    };

    // AUTHORITY RULE: Wait for save to complete before allowing modal to close
    await onSaveClient(updatedClient);

    // Concurrent non-blocking updates (Milestones)
    if (newBalance <= 0) {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PLR',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Full payment for land received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }

    if (paymentData.type === 'Indenture') {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PFI',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Payment for indenture documents received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }
  };

  const openPaymentModal = () => {
      if(selectedClient) {
          openModal(MODAL_TYPES.RECORD_PAYMENT, {
              client: selectedClient,
              onSave: (data: any) => handleRecordPayment(selectedClient, data)
          });
      }
  };

  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  return (
    <div className={`flex flex-col ${isEmbedded ? 'h-auto' : 'h-[calc(100vh-120px)]'} space-y-6`}>
      {!isEmbedded && (
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
              <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
              <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm font-medium">Standard bookkeeping ledger and transactional audit.</p>
          </div>
          <div className="flex gap-3">
            {canGenerateStatement && (
              <Button 
                variant="secondary"
                disabled={!selectedClient}
                className="bg-indigo-50 border-indigo-200 text-indigo-700 dark:bg-indigo-900/20 dark:border-indigo-800 dark:text-indigo-400 font-bold"
                onClick={() => setStatementModalOpen(true)}
                icon={<DocumentDuplicateIcon className="w-5 h-5" />}
              >
                Official Statement
              </Button>
            )}
            <Button 
              variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
              onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
              icon={<BellIcon className="w-5 h-5" />}
              className="relative"
            >
                Role Alerts
                {roleAlerts.length > 0 && (
                    <span className="absolute -top-1 -right-1 flex h-4 w-4">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                    </span>
                )}
            </Button>
            <Button variant="secondary" onClick={() => setActivePage('Analytics & Reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
                Business Analysis
            </Button>
          </div>
        </div>
      )}

      <div className="flex-grow flex gap-6 overflow-hidden">
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          {!isEmbedded && (
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
               <Select 
                label="Select Account" 
                value={selectedClientId || ''} 
                onChange={(e) => {
                    setSelectedClientId(Number(e.target.value));
                    setClientForInvoice(null);
                }}
              >
                <option value="">-- Choose Client --</option>
                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </Select>
            </div>
          )}
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName}
                    onReschedule={() => {}}
                    onMarkRead={(id) => setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40 py-20">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">
                    {isEmbedded ? 'Client data unavailable.' : 'Select a Client to view financial records'}
                  </p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <AccountOverview
                    selectedClient={selectedClient}
                    originalPricePerPlot={originalPricePerPlot}
                    discountAmount={discountAmount}
                    priceAfterDiscount={priceAfterDiscount}
                    installmentOption={installmentOption}
                    setInstallmentOption={setInstallmentOption}
                    onInitialSave={handleInitialSave}
                    isSaving={isSaving}
                />
            ) : (
                <AccountHistory 
                    selectedClient={selectedClient}
                    canMakePayment={canMakePayment}
                    isCEO={isCEO}
                    onMakePayment={openPaymentModal}
                    onAuthorizeAmendment={() => setActivePage('Amendment Form', selectedClient)}
                    paymentAggregation={paymentAggregation}
                />
            )}
        </div>
      </div>

      {isStatementModalOpen && selectedClient && (
          <AccountStatementModal 
            isOpen={isStatementModalOpen}
            onClose={() => setStatementModalOpen(false)}
            client={selectedClient}
            properties={properties}
          />
      )}
    </div>
  );
};

export default AccountManagementPage;

import React, { useMemo, useState } from 'react';
import { Client } from '../../types';
import { CheckCircleIcon, BanknotesIcon } from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';

interface AccountOverviewProps {
    selectedClient: Client;
    originalPricePerPlot: number;
    discountAmount: number;
    priceAfterDiscount: number;
    installmentOption: string;
    setInstallmentOption: (val: string) => void;
    onInitialSave: (customMonths?: number) => void;
    isSaving: boolean;
}

export const AccountOverview: React.FC<AccountOverviewProps> = ({
    selectedClient,
    originalPricePerPlot,
    discountAmount,
    priceAfterDiscount,
    installmentOption,
    setInstallmentOption,
    onInitialSave,
    isSaving
}) => {
    const [customMonths, setCustomMonths] = useState<string>('24');
    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const emiBreakdown = useMemo(() => {
        if (installmentOption === 'Outright') return null;
        let months = installmentOption === 'Other' ? parseInt(customMonths) : parseInt(installmentOption);
        if (isNaN(months) || months <= 0) return null;

        return {
            monthlyAmount: priceAfterDiscount / months,
            installments: months,
            totalPayable: priceAfterDiscount
        };
    }, [installmentOption, priceAfterDiscount, customMonths]);

    const isInitialized = !!(selectedClient.payment as any).isInitialized;

    return (
        <div className="space-y-6 animate-in fade-in duration-300">
            <Card title="Active Account Ledger">
                <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Property Location</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.location || '—'}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Number of Plots</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.plot.split(',').length}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Price Per Plot</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(originalPricePerPlot)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Discount Applied</p>
                        <Badge variant={discountAmount > 0 ? 'success' : 'neutral'}>{discountAmount > 0 ? 'YES' : 'NO'}</Badge>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">EMI Selection</p>
                        <Badge variant="info">{selectedClient.payment.planType || 'N/A'}</Badge>
                    </div>
                </div>
                <div className="mt-8 border-t border-gray-100 dark:border-gray-700 pt-6">
                    <Button 
                        onClick={() => onInitialSave(installmentOption === 'Other' ? parseInt(customMonths) : undefined)}
                        disabled={isInitialized}
                        isLoading={isSaving}
                        icon={<CheckCircleIcon className="w-5 h-5" />}
                        className="w-full md:w-auto px-12 py-3"
                    >
                        {isInitialized ? 'Details Locked' : 'Save Payment Details'}
                    </Button>
                </div>
            </Card>

            <Card title="Payment Details">
                <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-6 items-end">
                    <Input label="Original Price Per Plot" value={formatCurrency(originalPricePerPlot)} readOnly className="bg-gray-50 font-bold" />
                    <Input label="Price After Discount" value={formatCurrency(priceAfterDiscount)} readOnly className="bg-gray-50 font-bold text-green-600" />
                    <Select 
                        label="Installment Options*" 
                        value={installmentOption} 
                        onChange={(e) => setInstallmentOption(e.target.value)}
                        disabled={isInitialized}
                    >
                        <option value="Outright">Outright</option>
                        <option value="3">3 Months</option>
                        <option value="6">6 Months</option>
                        <option value="12">12 Months</option>
                        <option value="Other">Other (Custom)</option>
                    </Select>
                    {installmentOption === 'Other' && (
                        <div className="animate-in slide-in-from-left-2 duration-200">
                             <Input 
                                label="Custom Months (1-60)*" 
                                type="number" 
                                min="1" 
                                max="60"
                                value={customMonths} 
                                onChange={(e) => setCustomMonths(e.target.value)}
                                disabled={isInitialized}
                                placeholder="e.g. 24"
                                className="font-bold"
                            />
                        </div>
                    )}
                </div>
                {emiBreakdown && (
                    <div className="mt-8 p-6 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-100 dark:border-blue-800 animate-in slide-in-from-top-2">
                        <h4 className="text-xs font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                            <BanknotesIcon className="w-4 h-4" /> EMI Calculation Breakdown
                        </h4>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div>
                                <p className="text-[10px] font-black text-blue-400 uppercase">Monthly Installment</p>
                                <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(emiBreakdown.monthlyAmount)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-blue-400 uppercase">Term Length</p>
                                <p className="text-xl font-black text-blue-700 dark:text-blue-300">{emiBreakdown.installments} Months</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-blue-400 uppercase">Total Commitment</p>
                                <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(emiBreakdown.totalPayable)}</p>
                            </div>
                        </div>
                    </div>
                )}
            </Card>

            <Card title="Current Ledger Standing" className="bg-gray-50/50 dark:bg-gray-900/20 border-dashed">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Contract Total</p>
                        <p className="text-2xl font-black text-gray-900 dark:text-white">{formatCurrency(selectedClient.payment.total)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Amount Paid</p>
                        <p className="text-2xl font-black text-green-600">{formatCurrency(selectedClient.payment.paid)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Outstanding Balance</p>
                        <p className={`text-2xl font-black ${selectedClient.payment.balance < 0 ? 'text-purple-600' : 'text-red-600'}`}>
                            {formatCurrency(selectedClient.payment.balance)}
                            {selectedClient.payment.balance < 0 && <span className="text-[10px] block uppercase text-purple-400 font-black">Account Overpaid</span>}
                        </p>
                    </div>
                </div>
            </Card>
        </div>
    );
};

