export const AccountStatementModal: React.FC<AccountStatementModalProps> = ({ isOpen, onClose, client, properties }) => {
    const { sendMail } = useData();
    const [startDate, setStartDate] = useState(() => {
        const d = new Date();
        d.setMonth(0); d.setDate(1);
        return d.toISOString().split('T')[0];
    });
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);

    const discountInfo = useMemo(() => ({
        type: (client.payment as any).discountType || 'Percentage',
        value: (client.payment as any).discountValue || 0,
        amount: (client.payment as any).discountAmountApplied || 0,
        preTotal: (client.payment as any).contractTotalBeforeDiscount || client.payment.total
    }), [client]);

    const statementData = useMemo(() => {
        const start = new Date(startDate);
        const end = new Date(endDate);

        // Load expected schedule
        const storageKey = `expected_schedule_${client.id}`;
        const rawSchedule = localStorage.getItem(storageKey);
        const expectedSchedule = rawSchedule ? JSON.parse(rawSchedule) : [];

        // Actual history
        const actualHistory = [...client.payment.paymentHistory].sort((a, b) => 
            new Date(a.date).getTime() - new Date(b.date).getTime()
        );

        let runningBalance = discountInfo.preTotal - discountInfo.amount;
        let totalPaidInPeriod = 0;

        // Map Actual to Expected or List Both
        const ledgerEntries = actualHistory.map((txn, idx) => {
            const txnDate = new Date(txn.date);
            runningBalance -= txn.amount;
            if (txnDate >= start && txnDate <= end) totalPaidInPeriod += txn.amount;

            // Try to find matching expected date
            const expected = expectedSchedule[idx];

            return {
                type: idx === 0 ? 'Initial Deposit' : 'Instalment Payment',
                expectedDate: expected?.date || '—',
                actualDate: txn.date,
                amount: txn.amount,
                receipt: txn.receiptNumber,
                balance: runningBalance,
                status: 'Paid'
            };
        });

        // Add remaining expected items that haven't been paid yet
        const remainingExpected = expectedSchedule.slice(ledgerEntries.length).map(exp => ({
            type: 'Future Instalment',
            expectedDate: exp.date,
            actualDate: '—',
            amount: exp.amount,
            receipt: '—',
            balance: 0, // Balance doesn't compute for future in ledger view
            status: new Date(exp.date) < new Date() ? 'Arrears' : 'Pending'
        }));

        return {
            ledgerEntries: [...ledgerEntries, ...remainingExpected],
            totalPaidInPeriod,
            closingBalance: client.payment.balance
        };
    }, [client, startDate, endDate, discountInfo]);

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const handlePrint = () => window.print();

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/90 z-[100] flex justify-center items-center p-4 backdrop-blur-sm overflow-hidden">
            <Card className="w-full max-w-5xl h-[95vh] p-0 flex flex-col shadow-2xl border-0 overflow-hidden bg-white">
                <div className="p-4 border-b border-gray-100 bg-gray-50 flex flex-wrap items-center justify-between gap-4 print:hidden shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-gray-400 uppercase">Start</span>
                            <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="text-xs p-1 rounded border border-gray-200" />
                        </div>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-gray-400 uppercase">End</span>
                            <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="text-xs p-1 rounded border border-gray-200" />
                        </div>
                    </div>
                    <div className="flex gap-2">
                        <Button variant="secondary" size="sm" icon={<PrinterIcon className="w-4 h-4" />} onClick={handlePrint}>Print Statement</Button>
                        <button onClick={onClose} className="p-1 hover:bg-gray-200 rounded-full"><XMarkIcon className="w-6 h-6 text-gray-400" /></button>
                    </div>
                </div>

                <div id="printable-statement" className="flex-grow p-10 overflow-y-auto scrollbar-thin text-slate-900">
                    <div className="max-w-4xl mx-auto space-y-8">

                        <div className="flex justify-between items-start border-b-4 border-slate-900 pb-6">
                            <div className="space-y-1">
                                <h1 className="text-2xl font-black tracking-tighter uppercase">Official Account Statement</h1>
                                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">FAIM Legacy Real Estate</p>
                            </div>
                            <div className="text-right">
                                <p className="text-xs font-bold uppercase">Statement Period</p>
                                <p className="text-sm font-black">{startDate} to {endDate}</p>
                            </div>
                        </div>

                        {/* Discount Summary Section */}
                        <div className="p-4 bg-slate-50 rounded-xl border border-slate-200 grid grid-cols-2 md:grid-cols-4 gap-6">
                            <div className="col-span-2 md:col-span-1">
                                <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Contract Sub-Total</p>
