import { useMemo } from 'react';
import { Client, AppNotification } from '../types';

export const useNotificationTriggers = (clients: Client[]) => {
    const notifications = useMemo(() => {
        const alerts: AppNotification[] = [];
        const now = new Date();
        const accraTimeNow = new Intl.DateTimeFormat('en-GB', { 
            timeZone: 'Africa/Accra', 
            dateStyle: 'short', timeStyle: 'medium' 
        });

        clients.forEach(client => {
            const contractTotal = client.payment.total || 0;
            if (contractTotal <= 0) return;

            const paidTotal = client.payment.paid || 0;
            const paymentPercentage = (paidTotal / contractTotal) * 100;
            const isAllocated = client.allocationStatus === 'ALLOCATED';

            // RULE: 70% Qualification Notification
            if (paymentPercentage >= 70 && !isAllocated) {
                const qualifiedAtStr = (client as any).qualifiedAt;

                // 1. Initial Qualification Trigger (Within first hour of detecting)
                alerts.push({
                    id: `qual-init-${client.id}`,
                    title: 'Client Qualified for Allocation (70%)',
                    message: `${client.name} has paid 70% (${formatCurrency(paidTotal)}). Allocate plot and confirm on-site within 48h.`,
                    type: 'Qualification',
                    recipientRole: 'Administrator',
                    timestamp: now.toISOString(),
                    isRead: false,
                    metadata: { clientId: client.id, clientName: client.name, paidTotal, contractTotal }
                });

                // 2. CEO Escalation (48 Hours Rule)
                if (qualifiedAtStr) {
                    const qualifiedAtDate = new Date(qualifiedAtStr);
                    const hoursSinceQual = (now.getTime() - qualifiedAtDate.getTime()) / (1000 * 60 * 60);

                    if (hoursSinceQual >= 48) {
                        alerts.push({
                            id: `qual-esc-ceo-${client.id}`,
                            title: 'Allocation Delayed Beyond 48 Hours',
                            message: `Allocation not completed for ${client.name} who reached 70% payment on ${qualifiedAtStr}. CEO action required.`,
                            type: 'Escalation',
                            recipientRole: 'CEO',
                            timestamp: now.toISOString(),
                            isRead: false,
                            metadata: { clientId: client.id, clientName: client.name, qualifiedAt: qualifiedAtStr }
                        });
                    }
                }
            }

            // Standard Default Alerts (3 Month Rule)
            const lastPaymentDate = client.payment.paymentHistory.length > 0 
                ? new Date(client.payment.paymentHistory[client.payment.paymentHistory.length - 1].date)
                : new Date(client.regDate);
            const monthsSinceLastPayment = (now.getTime() - lastPaymentDate.getTime()) / (1000 * 60 * 60 * 24 * 30);

            if (monthsSinceLastPayment >= 3 && client.payment.balance > 0) {
                alerts.push({
                    id: `def-esc-acc-${client.id}`,
                    title: 'Payment Default Escalation',
                    message: `${client.name} has defaulted for 3 months. Review required.`,
                    type: 'Default',
                    recipientRole: 'Chief Accountant',
                    timestamp: now.toISOString(),
                    isRead: false,
                    metadata: { clientId: client.id, clientName: client.name }
                });
            }
        });

        return alerts;
    }, [clients]);

    return notifications;
};

const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH').format(amount)}`;

import { useQuery, useMutation, useQueryClient, useInfiniteQuery } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { auth } from '../../services/firebase';
import { Client, MilestoneRecord } from '../../types';

export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const {
        data,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
        isLoading
    } = useInfiniteQuery({
        queryKey: ['clients', searchTerm],
        queryFn: ({ pageParam }) => 
            searchTerm 
                ? dbService.searchClients(searchTerm).then(data => ({ data, lastDoc: null }))
                : dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc,
        enabled: isAuthenticated,
    });

    const clients = data?.pages.flatMap(page => page.data) || [];

    const saveClientMutation = useMutation({
        mutationFn: async (client: Client) => {
            const isNew = !clients.some(c => c.id === client.id);

            // AUTHORITY RULE: Deterministic Allocation Qualification
            const totalCost = client.payment.total || 0;
            const totalPaid = client.payment.paid || 0;
            const currentAccraTime = new Intl.DateTimeFormat('en-GB', { 
                timeZone: 'Africa/Accra', 
                dateStyle: 'short', timeStyle: 'medium' 
            }).format(new Date());

            if (totalCost > 0) {
                const percent = (totalPaid / totalCost) * 100;
                client.paidPercent = percent;

                // If moving to Qualified for the first time, record timestamp for 48h escalation
                if (percent >= 70 && client.allocationStatus !== 'ALLOCATED') {
                    if (client.allocationStatus !== 'QUALIFIED') {
                        client.allocationStatus = 'QUALIFIED';
                        (client as any).qualifiedAt = currentAccraTime;
                    }
                } else if (percent < 70) {
                    client.allocationStatus = 'RESERVED_NOT_ALLOCATED';
                    (client as any).qualifiedAt = null; // Reset if they drop below (e.g. refund/amendment)
                }
            }

            // If status changed to ALLOCATED, record timestamp and stop escalation
            if (client.allocationStatus === 'ALLOCATED' && !(client as any).allocatedAt) {
                (client as any).allocatedAt = currentAccraTime;
            }

            const result = await dbService.persistClient(client);

            if (isNew) {
                await dbService.persistMilestone({
                    clientId: client.id,
                    milestoneCode: 'SFR',
                    dateCompleted: new Date().toISOString().split('T')[0],
                    notes: 'Initial registration received.'
                });
            }

            if (client.location && client.location !== 'N/A') {
                await dbService.persistMilestone({
                    clientId: client.id,
                    milestoneCode: 'ACA',
                    dateCompleted: new Date().toISOString().split('T')[0],
                    notes: `Address assigned: ${client.location}`
                });
            }

            return result;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return {
        clients,
        isLoading,
        hasNextPage,
        fetchNextPage,
        isFetchingNextPage,
        saveClient: (client: Client) => saveClientMutation.mutateAsync(client),
        deleteClient: (id: number) => deleteClientMutation.mutateAsync(id)
    };
};

export const useMilestones = (clientId?: number) => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: milestones = [], isLoading } = useQuery({
        queryKey: ['milestones', clientId],
        queryFn: () => clientId ? dbService.fetchMilestonesForClient(clientId) : dbService.fetchMilestones(),
        enabled: isAuthenticated,
    });

    const saveMilestoneMutation = useMutation({
        mutationFn: dbService.persistMilestone,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['milestones'] });
        }
    });

    return { 
        milestones, 
        isLoading, 
        saveMilestone: saveMilestoneMutation.mutateAsync 
    };
};

