import { useMemo } from 'react';
import { Client, AppNotification } from '../types';

export const useNotificationTriggers = (clients: Client[]) => {
    const notifications = useMemo(() => {
        const alerts: AppNotification[] = [];
        const now = new Date();

        // Deterministic Accra Date Calculation
        const accraDateStr = new Intl.DateTimeFormat('en-GB', { 
            timeZone: 'Africa/Accra', 
            year: 'numeric', month: '2-digit', day: '2-digit' 
        }).format(now);

        const [day, month, year] = accraDateStr.split('/');
        const todayMonthDay = `${month}-${day}`;
        const todayFull = `${year}-${month}-${day}`;

        clients.forEach(client => {
            // --- SECTION 1: BIRTHDAY CHECK ---
            // Requirement: Compare DOB day/month with Accra today
            if (client.dateOfBirth) {
                try {
                    // Expecting YYYY-MM-DD format from form
                    const dobParts = client.dateOfBirth.split('-');
                    if (dobParts.length === 3) {
                        const dobMonthDay = `${dobParts[1]}-${dobParts[2]}`;

                        if (dobMonthDay === todayMonthDay) {
                            alerts.push({
                                id: `bday-${client.id}-${todayFull}`,
                                title: 'Client Birthday Today 🎉',
                                message: `${client.name} is celebrating a birthday today. Please call or text to wish them a happy birthday.`,
                                type: 'Birthday',
                                recipientRole: 'ALL_USERS',
                                timestamp: now.toISOString(),
                                isRead: false,
                                metadata: { 
                                    clientId: client.id, 
                                    clientName: client.name,
                                    eventType: 'CLIENT_BIRTHDAY'
                                }
                            });
                        }
                    }
                } catch (e) {
                    console.warn(`Malformed DOB for client ${client.id}: ${client.dateOfBirth}`);
                }
            }

            // --- SECTION 2: 70% QUALIFICATION & ESCALATION ---
            const totalCost = client.payment.total || 0;
            if (totalCost <= 0) return;

            const paidTotal = client.payment.paid || 0;
            const paymentPercentage = (paidTotal / totalCost) * 100;
            const isAllocated = client.allocationStatus === 'ALLOCATED';

            if (paymentPercentage >= 70 && !isAllocated) {
                const qualifiedAtStr = (client as any).qualifiedAt;

                // Initial Qualification Alert
                alerts.push({
                    id: `qual-init-${client.id}`,
                    title: 'Client Qualified for Allocation (70%)',
                    message: `${client.name} has paid 70% (${formatCurrency(paidTotal)}). Allocate plot and confirm on-site within 48h.`,
                    type: 'Qualification',
                    recipientRole: 'Administrator',
                    timestamp: now.toISOString(),
                    isRead: false,
                    metadata: { clientId: client.id, clientName: client.name, paidTotal, contractTotal: totalCost, eventType: 'ALLOCATION_70_PERCENT_QUALIFIED' }
                });

                // 48-Hour Escalation to CEO
                if (qualifiedAtStr) {
                    const qualifiedAtDate = new Date(qualifiedAtStr);
                    const hoursSinceQual = (now.getTime() - qualifiedAtDate.getTime()) / (1000 * 60 * 60);

                    if (hoursSinceQual >= 48) {
                        alerts.push({
                            id: `qual-esc-ceo-${client.id}`,
                            title: 'Allocation Delayed Beyond 48 Hours',
                            message: `Allocation not completed for ${client.name} who reached 70% payment on ${qualifiedAtStr}. CEO action required.`,
                            type: 'Escalation',
                            recipientRole: 'CEO',
                            timestamp: now.toISOString(),
                            isRead: false,
                            metadata: { clientId: client.id, clientName: client.name, qualifiedAt: qualifiedAtStr, eventType: 'ALLOCATION_NOT_DONE_48H' }
                        });
                    }
                }
            }

            // --- SECTION 3: DEFAULT ESCALATION ---
            const lastPaymentDate = client.payment.paymentHistory.length > 0 
                ? new Date(client.payment.paymentHistory[client.payment.paymentHistory.length - 1].date)
                : new Date(client.regDate);
            const monthsSinceLastPayment = (now.getTime() - lastPaymentDate.getTime()) / (1000 * 60 * 60 * 24 * 30);

            if (monthsSinceLastPayment >= 3 && client.payment.balance > 0) {
                alerts.push({
                    id: `def-esc-acc-${client.id}`,
                    title: 'Payment Default Escalation',
                    message: `${client.name} has defaulted for 3 months. Review required.`,
                    type: 'Default',
                    recipientRole: 'Chief Accountant',
                    timestamp: now.toISOString(),
                    isRead: false,
                    metadata: { clientId: client.id, clientName: client.name }
                });
            }
        });

        return alerts;
    }, [clients]);

    return notifications;
};

const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH').format(amount)}`;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Sidebar from './Sidebar';
import Header, { HeaderNotification } from './Header';
import { Staff, PermissionSet, CompanySettings } from '../types';
import { useData } from '../context/DataContext';
import { useClients, useRoles } from '../hooks/useAppData';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { ToastNotification } from './ui/ToastNotification';

interface LayoutProps {
    children: React.ReactNode;
    activePage: string;
    setActivePage: (page: string, context?: any) => void;
    currentStaff: Staff;
    onLogout: () => void;
    staffPermissions: { [key: string]: PermissionSet };
    companySettings: CompanySettings;
}

const Layout: React.FC<LayoutProps> = ({ children, activePage, setActivePage, currentStaff, onLogout, staffPermissions, companySettings }) => {
    const [isMobileSidebarOpen, setMobileSidebarOpen] = useState(false);
    const [isDesktopSidebarCollapsed, setDesktopSidebarCollapsed] = useState(false);

    const { internalMails } = useData();
    const { clients } = useClients(); 
    const { roles } = useRoles(); 

    const systemAlerts = useNotificationTriggers(clients);

    const headerNotifications = useMemo(() => {
        const aggregated: HeaderNotification[] = [];
        const userRoleName = roles.find(r => r.id === currentStaff.roleId)?.name;

        // Filter System Alerts by Role OR Broadcase (ALL_USERS)
        const myAlerts = systemAlerts.filter(alert => 
            (alert.recipientRole === userRoleName || alert.recipientRole === 'ALL_USERS') && !alert.isRead
        );

        myAlerts.forEach(alert => {
            aggregated.push({
                id: alert.id,
                title: alert.title,
                description: alert.message,
                timestamp: alert.timestamp,
                type: 'alert',
                targetPage: 'Account Management',
                targetContext: null 
            });
        });

        // Filter Unread Mails
        const myMails = internalMails.filter(m => 
            m.recipientIds.includes(currentStaff.id) && 
            !m.readBy.includes(currentStaff.id) && 
            !m.isDeleted
        );
        myMails.forEach(mail => {
            aggregated.push({
                id: mail.id,
                title: mail.subject,
                description: mail.body.length > 80 ? `${mail.body.substring(0, 80)}...` : mail.body,
                timestamp: mail.timestamp,
                type: 'mail',
                targetPage: mail.targetPage || 'Mailing',
                targetContext: mail.targetContext || null
            });
        });

        return aggregated.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [systemAlerts, internalMails, currentStaff, roles]);

    const unreadMailsCount = useMemo(() => {
        if (!currentStaff) return 0;
        return internalMails.filter(m => 
            m.recipientIds.includes(currentStaff.id) && 
            !m.readBy.includes(currentStaff.id) && 
            !m.isDeleted && 
            !m.isDraft
        ).length;
    }, [internalMails, currentStaff]);

    const [toast, setToast] = useState<{ message: string; subtext: string } | null>(null);
    const prevMailsLengthRef = useRef(internalMails.length);
    const initialLoadRef = useRef(true);

    useEffect(() => {
        if (initialLoadRef.current) {
            initialLoadRef.current = false;
            prevMailsLengthRef.current = internalMails.length;
            return;
        }

        if (internalMails.length > prevMailsLengthRef.current) {
            const newMails = internalMails.slice(0, internalMails.length - prevMailsLengthRef.current);
            const latestMail = newMails[0]; 

            if (latestMail && latestMail.recipientIds.includes(currentStaff.id) && latestMail.senderId !== currentStaff.id) {
                setToast({
                    message: latestMail.subject.includes('New Client') ? 'Onboarding Alert' : `New Message from ${latestMail.senderName}`,
                    subtext: latestMail.subject
                });
                try {
                    const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
                    audio.volume = 0.5;
                    audio.play().catch(() => {});
                } catch(e) {}
            }
        }
        prevMailsLengthRef.current = internalMails.length;
    }, [internalMails, currentStaff.id]);

    return (
        <div className="flex h-screen bg-gray-100 dark:bg-gray-950 transition-colors duration-200">
            <Sidebar 
                isMobileOpen={isMobileSidebarOpen}
                onMobileClose={() => setMobileSidebarOpen(false)}
                isDesktopCollapsed={isDesktopSidebarCollapsed}
                activePage={activePage}
                setActivePage={setActivePage}
                staffPermissions={staffPermissions}
                companySettings={companySettings}
                onLogout={onLogout}
            />
            <div className="flex-1 flex flex-col overflow-hidden relative">
                <Header 
                    onMobileMenuToggle={() => setMobileSidebarOpen(true)}
                    onDesktopToggle={() => setDesktopSidebarCollapsed(prev => !prev)}
                    isDesktopCollapsed={isDesktopSidebarCollapsed}
                    currentStaff={currentStaff}
                    onLogout={onLogout}
                    setActivePage={setActivePage}
                    notifications={headerNotifications}
                    unreadMailsCount={unreadMailsCount}
                />
                <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-950 transition-colors duration-200 flex flex-col">
                    <div className="container mx-auto px-6 py-8 flex-grow">
                        {children}
                    </div>
                </main>
                {toast && (
                    <ToastNotification 
                        message={toast.message} 
                        subtext={toast.subtext} 
                        onClose={() => setToast(null)} 
                    />
                )}
            </div>
        </div>
    );
};

export default Layout;

