    status: 'Paid' | 'Pending' | 'Overdue';
    issueDate: string;
    dueDate: string;
}

export interface ReceiptPattern {
    prefix: string;
    lastNumber: number;
    minLength: number;
}

export interface ReceiptAlert {
    id: number;
    clientId: number;
    enteredBy: string;
