import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification, Installment } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    DocumentTextIcon,
    ChartBarIcon,
    DocumentDuplicateIcon
} from '../components/icons/DummyIcons';
import { Button } from '../components/ui/Button';
import { Select } from '../components/ui/Input';
import { NotificationCenter } from '../components/NotificationCenter';
import { AccountOverview } from '../components/account/AccountOverview';
import { AccountHistory } from '../components/account/AccountHistory';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useProperties, useMilestones } from '../hooks/useAppData';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';
import { AccountStatementModal } from '../components/financials/AccountStatementModal';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect?: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
  overrideClientId?: number | null;
  isEmbedded?: boolean;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage, overrideClientId = null, isEmbedded = false
}) => {
  const { properties } = useProperties();
  const { saveMilestone } = useMilestones();
  const { openModal } = useModal();
  const [viewMode, setViewMode] = useState<'list' | 'alerts'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(overrideClientId);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isStatementModalOpen, setStatementModalOpen] = useState(false);

  useEffect(() => {
    if (overrideClientId !== null) {
      setSelectedClientId(overrideClientId);
    }
  }, [overrideClientId]);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (selectedClientId || clientForInvoice?.id))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);
  const isHeadOfAccounts = useMemo(() => currentStaff.roleId === 'Chief Accountant', [currentStaff]);
  const canGenerateStatement = useMemo(() => isCEO || isHeadOfAccounts, [isCEO, isHeadOfAccounts]);

  const canMakePayment = useMemo(() => {
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  const originalPricePerPlot = useMemo(() => {
    if (!selectedClient) return 0;
    const matchingProperty = properties.find(p => p.location === selectedClient.location);
    return matchingProperty ? matchingProperty.price : 0;
  }, [selectedClient, properties]);

  const discountAmount = selectedClient?.payment.promoDetails ? (originalPricePerPlot * 0.1) : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land';
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async (customMonths?: number, financialSnapshot?: any) => {
    if (!selectedClient) return;

    const monthsCount = installmentOption === 'Outright' ? 1 : (installmentOption === 'Other' ? (customMonths || 1) : parseInt(installmentOption));

    if (installmentOption !== 'Outright' && (!monthsCount || monthsCount <= 0)) {
        alert("Please provide a valid number of months.");
        return;
    }

    setIsSaving(true);
    try {
        const finalPlanType = installmentOption === 'Outright' ? 'Outright' : `${monthsCount} Months`;
        const contractTotal = financialSnapshot?.contractTotalAfterDiscount || priceAfterDiscount;
        const emi = contractTotal / monthsCount;
        const now = new Date();

        // DETERMINISTIC SCHEDULE GENERATION
        const generatedInstallments: Installment[] = [];
        let planStartDate = new Date(selectedClient.regDate || now.toISOString().split('T')[0]);

        // Offset starting date by 1 month for the first installment
        for (let i = 1; i <= monthsCount; i++) {
            const dueDate = new Date(planStartDate);
            dueDate.setMonth(planStartDate.getMonth() + i);

            generatedInstallments.push({
                id: `SCH-${selectedClient.id}-${Date.now()}-${i}`,
                expectedDueDate: dueDate.toISOString().split('T')[0],
                expectedAmount: emi,
                amountPaid: 0,
                balance: emi,
                status: 'Pending'
            });
        }

        const updatedClient: Client = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planVersionId: `PLN-${Date.now()}`,
                planType: finalPlanType,
                total: contractTotal,
                balance: contractTotal - selectedClient.payment.paid,
                emiMonthlyPayment: emi,
                installments: generatedInstallments, // Permanent storage in Firestore
                ...financialSnapshot
            }
        };

        await onSaveClient(updatedClient);
        alert("Financial commitment and payment schedule initialized successfully.");
    } catch (err) {
        console.error("Schedule Gen Failure:", err);
        alert("Installment plan saved, but expected dates were not generated. Please try again.");
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const newPaid = client.payment.paid + newTransaction.amount;
    const newBalance = client.payment.balance - newTransaction.amount;

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: newPaid,
            balance: newBalance,
        }
    };

    await onSaveClient(updatedClient);

    if (newBalance <= 0) {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PLR',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Full payment for land received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }
  };

  const openPaymentModal = () => {
      if(selectedClient) {
          openModal(MODAL_TYPES.RECORD_PAYMENT, {
              client: selectedClient,
              onSave: (data: any) => handleRecordPayment(selectedClient, data)
          });
      }
  };

  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  return (
    <div className={`flex flex-col ${isEmbedded ? 'h-auto' : 'h-[calc(100vh-120px)]'} space-y-6`}>
      {!isEmbedded && (
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
              <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
              <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm font-medium">Standard bookkeeping ledger and transactional audit.</p>
          </div>
          <div className="flex gap-3">
            {canGenerateStatement && (
              <Button 
                variant="secondary"
                disabled={!selectedClient}
                className="bg-indigo-50 border-indigo-200 text-indigo-700 dark:bg-indigo-900/20 dark:border-indigo-800 dark:text-indigo-400 font-bold"
                onClick={() => setStatementModalOpen(true)}
                icon={<DocumentDuplicateIcon className="w-5 h-5" />}
              >
                Official Statement
              </Button>
            )}
            <Button 
              variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
              onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
              icon={<BellIcon className="w-5 h-5" />}
              className="relative"
            >
                Role Alerts
                {roleAlerts.length > 0 && (
                    <span className="absolute -top-1 -right-1 flex h-4 w-4">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                    </span>
                )}
            </Button>
            <Button variant="secondary" onClick={() => setActivePage('Analytics & Reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
                Business Analysis
            </Button>
          </div>
        </div>
      )}

      <div className="flex-grow flex gap-6 overflow-hidden">
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          {!isEmbedded && (
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
               <Select 
                label="Select Account" 
                value={selectedClientId || ''} 
                onChange={(e) => {
                    setSelectedClientId(Number(e.target.value));
                    setClientForInvoice(null);
                }}
              >
                <option value="">-- Choose Client --</option>
                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </Select>
            </div>
          )}
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName}
                    onReschedule={() => {}}
                    onMarkRead={(id) => setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40 py-20">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">
                    {isEmbedded ? 'Client data unavailable.' : 'Select a Client to view financial records'}
                  </p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <AccountOverview
                    selectedClient={selectedClient}
                    originalPricePerPlot={originalPricePerPlot}
                    discountAmount={discountAmount}
                    priceAfterDiscount={priceAfterDiscount}
                    installmentOption={installmentOption}
                    setInstallmentOption={setInstallmentOption}
                    onInitialSave={handleInitialSave}
                    isSaving={isSaving}
                />
            ) : (
                <AccountHistory 
                    selectedClient={selectedClient}
                    canMakePayment={canMakePayment}
                    isCEO={isCEO}
                    onMakePayment={openPaymentModal}
                    onAuthorizeAmendment={() => setActivePage('Amendment Form', selectedClient)}
                    paymentAggregation={paymentAggregation}
                />
            )}
        </div>
      </div>

      {isStatementModalOpen && selectedClient && (
          <AccountStatementModal 
            isOpen={isStatementModalOpen}
            onClose={() => setStatementModalOpen(false)}
            client={selectedClient}
            properties={properties}
          />
      )}
    </div>
  );
};

export default AccountManagementPage;

import React, { useMemo } from 'react';
import { Client } from '../../types';
import { PlusCircleIcon, ShieldCheckIcon, ExclamationTriangleIcon } from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../../components/ui/Table';

interface AccountHistoryProps {
    selectedClient: Client;
    canMakePayment: boolean;
    isCEO: boolean;
    onMakePayment: () => void;
    onAuthorizeAmendment: () => void;
    paymentAggregation: { land: number; indenture: number };
}

export const AccountHistory: React.FC<AccountHistoryProps> = ({
    selectedClient,
    canMakePayment,
    isCEO,
    onMakePayment,
    onAuthorizeAmendment,
    paymentAggregation
}) => {
    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const mergedLedger = useMemo(() => {
        // 1. Map Actual Transactions
        const actualHistory = (selectedClient.payment.paymentHistory || []).map(txn => ({
            id: txn.id,
            date: txn.date,
            amount: txn.amount,
            isExpected: false,
            displayType: (txn as any).type || 'Land',
            receipt: txn.receiptNumber || 'Ref Entry',
            status: 'PAID'
        }));

        // 2. Map Expected Installments from Client Object (Firestore Authority)
        const expectedHistory = (selectedClient.payment.installments || []).map(inst => ({
            id: inst.id,
            date: inst.expectedDueDate,
            amount: inst.expectedAmount,
            isExpected: true,
            displayType: 'EXPECTED PAYMENT',
            receipt: 'Schedule Item',
            status: 'EXPECTED'
        }));

        // 3. Aggregate and sort chronologically
        return [...actualHistory, ...expectedHistory].sort((a, b) => 
            new Date(a.date).getTime() - new Date(b.date).getTime()
        );
    }, [selectedClient]);

    const hasSchedule = selectedClient.payment.installments && selectedClient.payment.installments.length > 0;

    return (
        <div className="space-y-6 animate-in fade-in duration-300">
            {/* FAILURE RECOVERY BANNER */}
            {!hasSchedule && selectedClient.payment.isInitialized && (
                <div className="bg-amber-50 border-l-4 border-amber-500 p-4 rounded flex items-start gap-4">
                    <ExclamationTriangleIcon className="w-6 h-6 text-amber-600 shrink-0" />
                    <div>
                        <p className="text-sm font-bold text-amber-800">No expected payment schedule found.</p>
                        <p className="text-xs text-amber-700 mt-1">
                            An installment plan was saved, but the schedule was not generated or lost. 
                            Please contact system support to regenerate expected dates.
                        </p>
                    </div>
                </div>
            )}

            <Card title="Transactional Ledger History" action={
                <div className="flex gap-2">
                    <Button 
                        variant="primary" 
                        size="sm" 
                        disabled={!canMakePayment}
                        onClick={onMakePayment}
                        icon={<PlusCircleIcon className="w-4 h-4" />}
                        title={!canMakePayment ? "Insufficient permissions" : "Post new payment"}
                    >
                        Make Payment
                    </Button>
                    <Button 
                        variant="secondary" 
                        size="sm" 
                        disabled={!isCEO}
                        onClick={onAuthorizeAmendment}
                        icon={<ShieldCheckIcon className="w-4 h-4" />}
                    >
                        Authorize Amendment
                    </Button>
                </div>
            }>
                <TableContainer className="border-0 shadow-none">
                    <table className="w-full text-sm text-left">
                        <Thead>
                            <tr>
                                <Th>Type</Th>
                                <Th>Actual Date</Th>
                                <Th>Scheduled Date</Th>
                                <Th className="text-right">Amount</Th>
                                <Th className="text-center">Status</Th>
                                <Th className="text-right">Description</Th>
                            </tr>
                        </Thead>
                        <Tbody>
                            {mergedLedger.length === 0 ? (
                                <Tr>
                                    <Td colSpan={6} className="text-center py-12 text-gray-400 italic">No transactional records found.</Td>
                                </Tr>
                            ) : (
                                mergedLedger.map((item) => {
                                    const isFuture = new Date(item.date) > new Date();

                                    return (
                                        <Tr key={item.id} className={item.isExpected ? 'opacity-70 border-dashed bg-blue-50/10 dark:bg-blue-900/5' : ''}>
                                            <Td className={`font-bold ${item.isExpected ? 'text-blue-500 italic' : 'text-gray-600 dark:text-gray-400'}`}>
                                                {item.displayType}
                                            </Td>
                                            <Td className="font-mono text-gray-600 dark:text-gray-400">
                                                {item.isExpected ? '—' : (item.date || '—')}
                                            </Td>
                                            <Td className={`font-bold ${item.isExpected ? 'text-blue-600' : 'text-gray-900 dark:text-white'}`}>
                                                {item.date || '—'}
                                            </Td>
                                            <Td className={`text-right font-black ${item.isExpected ? 'text-blue-400' : 'text-green-600'}`}>
                                                {formatCurrency(item.amount)}
                                            </Td>
                                            <Td className="text-center">
                                                <Badge variant={item.isExpected ? 'neutral' : (isFuture ? 'info' : 'success')}>
                                                    {item.status}
                                                </Badge>
                                            </Td>
                                            <Td className="text-right font-medium text-gray-500 truncate max-w-[150px]">
                                                {item.receipt}
                                            </Td>
                                        </Tr>
                                    );
                                })
                            )}
                        </Tbody>
                    </table>
                </TableContainer>

                <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4 border-t border-gray-100 dark:border-gray-700 pt-6">
                    <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-100 dark:border-blue-900/50">
                        <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Total Land Payments Made</p>
                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(paymentAggregation.land)}</p>
                    </div>
                    <div className="p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-xl border border-emerald-100 dark:border-emerald-900/50">
                        <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Total Indenture Payments Made</p>
                        <p className="text-xl font-black text-emerald-700 dark:text-blue-300">{formatCurrency(paymentAggregation.indenture)}</p>
                    </div>
                </div>
            </Card>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { 
    MegaphoneIcon, 
    PlusCircleIcon, 
    ClockIcon, 
    UserCircleIcon,
    XMarkIcon,
    PaperClipIcon,
    ArrowDownTrayIcon
} from '../../components/icons/DummyIcons';
import { useAuth } from '../../context/AuthContext';
import { useActivityLogs, useRoles } from '../../hooks/useAppData';
import { uploadFile } from '../../services/storageService';

export interface Announcement {
    id: string;
    title: string;
    body: string;
    author: string;
    date: string;
    attachmentUrl?: string;
    readBy: string[];
    priorityDisplay: boolean; // Flag for Dashboard Banner
    createdAt: string; // ISO for sorting
}

const AnnouncementsPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    // Note: In production, these should come from a Firestore collection 'announcements'
    const [announcements, setAnnouncements] = useState<Announcement[]>([
        {
            id: 'ann-1',
            title: 'New Client Referral Bonus Program',
            body: 'Effective immediately, staff members are entitled to a 5% bonus on all successful land sale referrals. Documentation is attached.',
            author: 'Araba CEO',
            date: new Date(Date.now() - 86400000).toISOString(),
            attachmentUrl: '#',
            readBy: [],
            priorityDisplay: true,
            createdAt: new Date(Date.now() - 86400000).toISOString()
        }
    ]);

    const [isModalOpen, setModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [pendingFile, setPendingFile] = useState<File | null>(null);

    const userRole = roles.find(r => r.id === currentStaff?.roleId)?.name;
    const canPost = userRole === 'CEO' || userRole === 'Administrator';

    const sortedAnnouncements = useMemo(() => 
        [...announcements].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    , [announcements]);

    const handleMarkAsRead = (id: string) => {
        if (!currentStaff) return;
        setAnnouncements(prev => prev.map(a => {
            if (a.id === id && !a.readBy.includes(currentStaff.id)) {
                return { ...a, readBy: [...a.readBy, currentStaff.id] };
            }
            return a;
        }));
    };

    const handleCreateAnnouncement = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSaving(true);
        const formData = new FormData(e.currentTarget);

        try {
            let fileUrl = '';
            if (pendingFile) {
                fileUrl = await uploadFile(pendingFile, `announcements/${Date.now()}_${pendingFile.name}`);
            }

            const now = new Date().toISOString();
            const newAnn: Announcement = {
                id: `ANN-${Date.now()}`,
                title: formData.get('title') as string,
                body: formData.get('body') as string,
                author: currentStaff?.fullName || 'Management',
                date: now,
                attachmentUrl: fileUrl,
                readBy: [currentStaff?.id || ''],
                priorityDisplay: true, // Orchestration Requirement
                createdAt: now
            };

            // PERSISTENCE ORCHESTRATION: Sync with global shared state/DB
            setAnnouncements(prev => [newAnn, ...prev]);

            // For the demo/frontend orchestration, we use localStorage to share with Dashboard
            const storageKey = 'faim_priority_items';
            const existing = JSON.parse(localStorage.getItem(storageKey) || '[]');
            const priorityItem = { ...newAnn, type: 'Announcement' };
            localStorage.setItem(storageKey, JSON.stringify([priorityItem, ...existing]));

            if (currentStaff) {
                addActivityLog('Create', `Posted announcement: ${newAnn.title}`, currentStaff.id);
            }
            setModalOpen(false);
            setPendingFile(null);
        } catch (error) {
            alert('Failed to post announcement.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Internal Announcements</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Official company notices and team updates.</p>
                </div>
                {canPost && (
                    <button 
                      onClick={() => setModalOpen(true)} 
                      className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors"
                    >
                        <PlusCircleIcon className="w-5 h-5" />
                        Post Announcement
                    </button>
                )}
            </div>

            <div className="space-y-6">
                {sortedAnnouncements.length === 0 ? (
                    <div className="py-32 text-center bg-white dark:bg-gray-800 rounded-3xl border border-gray-200 dark:border-gray-700 opacity-40">
                        <MegaphoneIcon className="w-20 h-20 mx-auto mb-6 text-gray-300" />
                        <p className="text-xl font-bold text-gray-400">No active announcements</p>
                    </div>
                ) : (
                    sortedAnnouncements.map(ann => {
                        const isUnread = !ann.readBy.includes(currentStaff?.id || '');
                        return (
                            <Card 
                                key={ann.id} 
                                onMouseEnter={() => isUnread && handleMarkAsRead(ann.id)}
                                className={`transition-all ${isUnread ? 'ring-2 ring-blue-600/50 shadow-lg' : ''}`}
                            >
                                <div className="flex justify-between items-start mb-4">
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-2">
                                            {isUnread && <div className="w-2.5 h-2.5 rounded-full bg-blue-600 animate-pulse" />}
                                            <h3 className="text-xl font-black text-gray-900 dark:text-white leading-tight uppercase tracking-tighter">{ann.title}</h3>
                                        </div>
                                        <div className="flex items-center gap-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                            <span className="flex items-center gap-1"><UserCircleIcon className="w-3 h-3 text-blue-500" /> {ann.author}</span>
                                            <span className="flex items-center gap-1"><ClockIcon className="w-3 h-3 text-blue-500" /> {new Date(ann.date).toLocaleString()}</span>
                                        </div>
                                    </div>
                                    <Badge variant={isUnread ? 'info' : 'neutral'}>{isUnread ? 'NEW' : 'READ'}</Badge>
                                </div>
                                <div className="prose prose-sm max-w-none dark:prose-invert text-gray-700 dark:text-gray-300 whitespace-pre-wrap mb-6 leading-relaxed">
                                    {ann.body}
                                </div>
                                {ann.attachmentUrl && (
                                    <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <a 
                                            href={ann.attachmentUrl} 
                                            className="inline-flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-lg text-xs font-bold hover:bg-blue-100 transition-colors"
                                            target="_blank"
                                            rel="noopener noreferrer"
                                        >
                                            <PaperClipIcon className="w-4 h-4" /> View Attachment <ArrowDownTrayIcon className="w-3 h-3" />
                                        </a>
                                    </div>
                                )}
                            </Card>
                        );
                    })
                )}
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
                    <Card className="w-full max-w-2xl p-0 overflow-hidden shadow-2xl border border-indigo-500/30 flex flex-col max-h-[90vh]">
                        <form onSubmit={handleCreateAnnouncement} className="flex flex-col h-full overflow-hidden">
                            <div className="p-5 border-b border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center shrink-0">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">New Company Notice</h3>
                                <button type="button" onClick={() => setModalOpen(false)} className="text-gray-400 hover:text-gray-600 transition-colors"><XMarkIcon className="w-6 h-6" /></button>
                            </div>

                            <div className="p-6 space-y-4 overflow-y-auto scrollbar-thin flex-grow bg-white dark:bg-gray-800">
                                <Input label="Announcement Title*" name="title" required placeholder="e.g. Policy Update regarding Plot Allocations" />
                                <Textarea label="Message Body*" name="body" required rows={10} placeholder="Type your announcement content here..." />
                                <div>
                                    <label className="block text-xs font-black text-gray-400 uppercase mb-2">Optional Attachment</label>
                                    <label className="flex items-center gap-3 p-3 bg-white dark:bg-gray-800 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-xl cursor-pointer hover:border-indigo-400 transition-colors">
                                        <PaperClipIcon className="w-6 h-6 text-gray-400" />
