                                <Button type="button" variant="secondary" onClick={() => setModalOpen(false)}>Cancel</Button>
                                <Button type="submit" isLoading={isSaving}>Broadcast Notice</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

