import React, { useState, useMemo } from 'react';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { 
    CalendarDaysIcon, 
    PlusCircleIcon, 
    XMarkIcon
} from '../../components/icons/DummyIcons';
import { useAuth } from '../../context/AuthContext';
import { useActivityLogs, useRoles } from '../../hooks/useAppData';

export interface InternalEvent {
    id: string;
    title: string;
    dateTime: string;
    location: string;
    description: string;
    createdBy: string;
    rsvps: Record<string, 'Yes' | 'No'>;
    priorityDisplay: boolean;
    createdAt: string;
}

// Modular Imports
import { EventCard } from '../../components/team/EventCard';

const EventsPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    const [events, setEvents] = useState<InternalEvent[]>([
        {
            id: 'evt-1',
            title: 'Q4 Strategy Meeting',
            dateTime: '2024-12-01T10:00',
            location: 'Conference Room A',
            description: 'Discussing goals and budgets for the upcoming year.',
            createdBy: 'Araba CEO',
            rsvps: { '1': 'Yes' },
            priorityDisplay: true,
            createdAt: new Date().toISOString()
        }
    ]);

    const [isModalOpen, setModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const userRole = roles.find(r => r.id === currentStaff?.roleId)?.name;
    const canCreate = userRole === 'CEO' || userRole === 'Administrator';

    const { upcoming, past } = useMemo(() => {
        const now = new Date();
        const sorted = [...events].sort((a, b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime());
        return {
            upcoming: sorted.filter(e => new Date(e.dateTime) >= now),
            past: sorted.filter(e => new Date(e.dateTime) < now).reverse()
        };
    }, [events]);

    const handleCreateEvent = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSaving(true);
        const formData = new FormData(e.currentTarget);

        const now = new Date().toISOString();
        const newEvent: InternalEvent = {
            id: `EVT-${Date.now()}`,
            title: formData.get('title') as string,
            dateTime: formData.get('dateTime') as string,
            location: formData.get('location') as string,
            description: formData.get('description') as string,
            createdBy: currentStaff?.fullName || 'System',
            rsvps: {},
            priorityDisplay: true,
            createdAt: now
        };

        setEvents(prev => [...prev, newEvent]);

        // ORCHESTRATION: Sync with Dashboard
        const storageKey = 'faim_priority_items';
        const existing = JSON.parse(localStorage.getItem(storageKey) || '[]');
        const priorityItem = { ...newEvent, type: 'Event' };
        localStorage.setItem(storageKey, JSON.stringify([priorityItem, ...existing]));

        if (currentStaff) {
            addActivityLog('Create', `Created internal event: ${newEvent.title}`, currentStaff.id);
        }
        setModalOpen(false);
        setIsSaving(false);
    };

    const handleRSVP = (eventId: string, status: 'Yes' | 'No') => {
        setEvents(prev => prev.map(e => {
            if (e.id === eventId) {
                return { ...e, rsvps: { ...e.rsvps, [currentStaff?.id || '']: status } };
            }
            return e;
        }));
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Company Events</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Calendar coordination and team gatherings.</p>
                </div>
                {canCreate && (
                    <button 
                      onClick={() => setModalOpen(true)} 
                      className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors"
                    >
                        <PlusCircleIcon className="w-5 h-5" />
                        Create Event
                    </button>
                )}
            </div>

            <div className="space-y-8">
                <section>
                    <h2 className="text-xs font-black text-blue-600 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <CalendarDaysIcon className="w-4 h-4" /> Upcoming Events
                    </h2>
                    {upcoming.length === 0 ? (
                        <div className="py-20 text-center border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-3xl opacity-40">
                            <CalendarDaysIcon className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                            <p className="text-lg font-bold text-gray-400">No upcoming events scheduled</p>
                        </div>
                    ) : (
                        <div className="grid gap-6">
                            {upcoming.map(e => (
                                <EventCard 
                                    key={e.id} 
                                    event={e} 
                                    currentStaffId={currentStaff?.id}
                                    onRSVP={handleRSVP}
                                />
                            ))}
                        </div>
                    )}
                </section>

                {past.length > 0 && (
                    <section>
                        <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Past Events</h2>
                        <div className="grid gap-4 opacity-70">
                            {past.map(e => (
                                <EventCard 
                                    key={e.id} 
                                    event={e} 
                                    isPast 
                                    currentStaffId={currentStaff?.id}
                                    onRSVP={handleRSVP}
                                />
                            ))}
                        </div>
                    </section>
                )}
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
                    <Card className="w-full max-w-xl p-0 overflow-hidden shadow-2xl border border-blue-500/30 flex flex-col max-h-[90vh]">
                        <form id="new-event-form" onSubmit={handleCreateEvent} className="flex flex-col h-full overflow-hidden">
                            <div className="p-5 border-b border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center flex-shrink-0">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">New Company Event</h3>
                                <button type="button" onClick={() => setModalOpen(false)} className="text-gray-400 hover:text-gray-600 transition-colors"><XMarkIcon className="w-6 h-6" /></button>
                            </div>

                            <div className="p-6 space-y-4 overflow-y-auto scrollbar-thin flex-grow bg-white dark:bg-gray-800">
                                <Input label="Event Title*" name="title" required placeholder="e.g. End of Year Awards" />
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                    <Input label="Date & Time*" name="dateTime" type="datetime-local" required />
                                    <Input label="Location" name="location" placeholder="e.g. Accra Office Lounge" />
                                </div>
                                <Textarea label="Event Description" name="description" rows={6} placeholder="What should attendees know?" />

                                <div className="pt-2">
                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Visibility</p>
                                    <Badge variant="info">Internal Staff Only</Badge>
                                </div>
                            </div>

                            <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800 flex justify-end gap-3 flex-shrink-0">
                                <Button type="button" variant="secondary" onClick={() => setModalOpen(false)}>Cancel</Button>
                                <Button type="submit" form="new-event-form" isLoading={isSaving}>Save and Broadcast</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

export default EventsPage;

import React, { useState, useEffect, useMemo } from 'react';
import { Badge } from './ui/Badge';
import { MegaphoneIcon, CalendarDaysIcon, XMarkIcon, EyeIcon } from './icons/DummyIcons';
import { useAuth } from '../context/AuthContext';

interface PriorityItem {
    id: string;
    type: 'Announcement' | 'Event';
    title: string;
    description?: string;
    body?: string;
    createdAt: string;
    author?: string;
    createdBy?: string;
}

export const PriorityBanner: React.FC = () => {
    const { currentStaff } = useAuth();
    const [latestItem, setLatestItem] = useState<PriorityItem | null>(null);
    const [isDismissed, setIsDismissed] = useState(false);

    // Orchestration Logic: Fetch the most recent priority item
    useEffect(() => {
        const syncPriority = () => {
            if (!currentStaff) return;

            const storageKey = 'faim_priority_items';
            const items: PriorityItem[] = JSON.parse(localStorage.getItem(storageKey) || '[]');

            if (items.length > 0) {
                // Sort by createdAt descending
                const sorted = items.sort((a, b) => 
                    new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
                );

                const topItem = sorted[0];
                setLatestItem(topItem);

                // Check dismissal persistence
                const dismissalKey = `faim_dismissed_${currentStaff.id}_${topItem.id}`;
                setIsDismissed(localStorage.getItem(dismissalKey) === 'true');
            } else {
                setLatestItem(null);
            }
        };

        syncPriority();
        // Set up an interval or listener for cross-tab or cross-component sync
        const interval = setInterval(syncPriority, 3000);
        return () => clearInterval(interval);
    }, [currentStaff]);

    const handleDismiss = () => {
        if (!latestItem || !currentStaff) return;
        const dismissalKey = `faim_dismissed_${currentStaff.id}_${latestItem.id}`;
        localStorage.setItem(dismissalKey, 'true');
        setIsDismissed(true);
    };

    if (!latestItem || isDismissed) return null;

    const Icon = latestItem.type === 'Announcement' ? MegaphoneIcon : CalendarDaysIcon;
    const colorClass = latestItem.type === 'Announcement' ? 'bg-indigo-600' : 'bg-amber-600';
    const textPreview = latestItem.body || latestItem.description || '';

    return (
        <div className="sticky top-0 z-[100] w-full animate-in slide-in-from-top-full duration-500">
            <div className={`${colorClass} text-white shadow-xl px-6 py-4 flex flex-wrap items-center justify-between gap-4 border-b border-white/10`}>
                <div className="flex items-center gap-4 flex-1 min-w-0">
                    <div className="p-2.5 bg-white/20 rounded-xl backdrop-blur-md">
                        <Icon className="w-6 h-6" />
                    </div>
                    <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-0.5">
                            <Badge variant="neutral" className="bg-white/10 text-white border-white/20 text-[10px] font-black uppercase tracking-widest">
                                Priority {latestItem.type}
                            </Badge>
                            <span className="text-[10px] font-bold text-white/60 uppercase tracking-tighter">
                                {new Date(latestItem.createdAt).toLocaleString()}
                            </span>
                        </div>
                        <h2 className="text-lg font-black uppercase tracking-tight truncate leading-tight">
                            {latestItem.title}
                        </h2>
                        <p className="text-xs text-white/80 font-medium truncate max-w-2xl">
                            {textPreview}
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-3 shrink-0">
                    <button 
                        className="px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 border border-white/10"
                    >
                        <EyeIcon className="w-4 h-4" /> View Details
                    </button>
                    <button 
                        onClick={handleDismiss}
                        className="p-2 hover:bg-white/10 rounded-lg transition-colors group"
                        title="Dismiss for now"
                    >
                        <XMarkIcon className="w-5 h-5 group-hover:rotate-90 transition-transform duration-300" />
                    </button>
                </div>
            </div>

            {/* Visual highlight bar */}
            <div className="h-1 w-full bg-gradient-to-r from-transparent via-white/40 to-transparent opacity-30"></div>
        </div>
    );
};

