import React, { useState, useEffect } from 'react';
import { Badge } from './ui/Badge';
import { MegaphoneIcon, CalendarDaysIcon, XMarkIcon, EyeIcon, ClockIcon } from './icons/DummyIcons';
import { useAuth } from '../context/AuthContext';

interface PriorityItem {
    id: string;
    type: 'Announcement' | 'Event';
    title: string;
    description?: string;
    body?: string;
    createdAt: string;
    expiresAt?: string; // Time-based expiry
    author?: string;
    createdBy?: string;
}

export const PriorityBanner: React.FC = () => {
    const { currentStaff } = useAuth();
    const [latestItem, setLatestItem] = useState<PriorityItem | null>(null);
    const [isDismissed, setIsDismissed] = useState(false);

    // Orchestration Logic: Fetch the most recent VALID (non-expired) priority item
    useEffect(() => {
        const syncPriority = () => {
            if (!currentStaff) return;

            const storageKey = 'faim_priority_items';
            const items: PriorityItem[] = JSON.parse(localStorage.getItem(storageKey) || '[]');

            if (items.length > 0) {
                const now = new Date();

                // Deterministic Filtering:
                // 1. Must be priorityDisplay === true (implicitly handled by storage choice here)
                // 2. Must not be expired (if expiresAt exists)
                const validItems = items.filter(item => {
                    if (!item.expiresAt) return true; // Events currently don't expire via 24h rule in prompt
                    return new Date(item.expiresAt) > now;
                });

                if (validItems.length > 0) {
                    // Sort by createdAt descending
                    const sorted = validItems.sort((a, b) => 
                        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
                    );

                    const topItem = sorted[0];
                    setLatestItem(topItem);

                    // Check dismissal persistence
                    const dismissalKey = `faim_dismissed_${currentStaff.id}_${topItem.id}`;
                    setIsDismissed(localStorage.getItem(dismissalKey) === 'true');
                } else {
                    setLatestItem(null);
                }
            } else {
                setLatestItem(null);
            }
        };

        syncPriority();
        const interval = setInterval(syncPriority, 10000); // Check every 10s for time expiry
        return () => clearInterval(interval);
    }, [currentStaff]);

    const handleDismiss = () => {
        if (!latestItem || !currentStaff) return;
        const dismissalKey = `faim_dismissed_${currentStaff.id}_${latestItem.id}`;
        localStorage.setItem(dismissalKey, 'true');
        setIsDismissed(true);
    };

    if (!latestItem || isDismissed) return null;

    const Icon = latestItem.type === 'Announcement' ? MegaphoneIcon : CalendarDaysIcon;
    const colorClass = latestItem.type === 'Announcement' ? 'bg-indigo-600' : 'bg-amber-600';
    const textPreview = latestItem.body || latestItem.description || '';

    return (
        <div className="sticky top-0 z-[100] w-full animate-in slide-in-from-top-full duration-500">
            <div className={`${colorClass} text-white shadow-xl px-6 py-4 flex flex-wrap items-center justify-between gap-4 border-b border-white/10`}>
                <div className="flex items-center gap-4 flex-1 min-w-0">
                    <div className="p-2.5 bg-white/20 rounded-xl backdrop-blur-md">
                        <Icon className="w-6 h-6" />
                    </div>
                    <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-0.5">
                            <Badge variant="neutral" className="bg-white/10 text-white border-white/20 text-[10px] font-black uppercase tracking-widest">
                                Priority {latestItem.type}
                            </Badge>
                            <span className="text-[10px] font-bold text-white/60 uppercase tracking-tighter flex items-center gap-1">
                                <ClockIcon className="w-3 h-3" />
                                {latestItem.expiresAt ? `Visible until: ${new Date(latestItem.expiresAt).toLocaleTimeString()}` : new Date(latestItem.createdAt).toLocaleString()}
                            </span>
                        </div>
                        <h2 className="text-lg font-black uppercase tracking-tight truncate leading-tight">
                            {latestItem.title}
                        </h2>
                        <p className="text-xs text-white/80 font-medium truncate max-w-2xl">
                            {textPreview}
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-3 shrink-0">
                    <button 
                        className="px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 border border-white/10"
                    >
                        <EyeIcon className="w-4 h-4" /> View Details
                    </button>
                    <button 
                        onClick={handleDismiss}
                        className="p-2 hover:bg-white/10 rounded-lg transition-colors group"
                        title="Dismiss for now"
                    >
                        <XMarkIcon className="w-5 h-5 group-hover:rotate-90 transition-transform duration-300" />
                    </button>
                </div>
            </div>

            <div className="h-1 w-full bg-gradient-to-r from-transparent via-white/40 to-transparent opacity-30"></div>
        </div>
    );
};

