import { useMemo } from 'react';
import { Client, AppNotification } from '../types';
import { useAuth } from '../context/AuthContext';

export const useNotificationTriggers = (clients: Client[]) => {
    const { currentStaff } = useAuth();

    const notifications = useMemo(() => {
        if (!currentStaff) return [];

        const rawAlerts: AppNotification[] = [];
        const now = new Date();
        const accraDateStr = new Intl.DateTimeFormat('en-GB', { 
            timeZone: 'Africa/Accra', 
            year: 'numeric', month: '2-digit', day: '2-digit' 
        }).format(now);

        const [day, month, year] = accraDateStr.split('/');
        const todayMonthDay = `${month}-${day}`;

        // MOCK ACCOUNT ID for current env
        const ACC_ID = "FAIM_PROD_1";

        clients.forEach(client => {
            // 1. Birthday Check (Target: GLOBAL/ALL)
            if (client.dateOfBirth) {
                const dobParts = client.dateOfBirth.split('-');
                if (dobParts.length === 3 && `${dobParts[1]}-${dobParts[2]}` === todayMonthDay) {
                    rawAlerts.push({
                        id: `bday-${client.id}-${year}-${month}-${day}`,
                        title: 'Client Birthday Today 🎉',
                        message: `${client.name} is celebrating a birthday today.`,
                        type: 'Birthday',
                        targetType: 'GLOBAL',
                        accountId: ACC_ID,
                        timestamp: now.toISOString(),
                        readByUserIds: [],
                        moduleKey: 'Clients',
                        entityId: client.id,
                        metadata: { clientId: client.id, clientName: client.name }
                    });
                }
            }

            // 2. 70% Qualification (Target: ROLE -> Administrator, CEO)
            const totalCost = client.payment.total || 0;
            const paidTotal = client.payment.paid || 0;
            const paymentPercentage = totalCost > 0 ? (paidTotal / totalCost) * 100 : 0;

            if (paymentPercentage >= 70 && client.allocationStatus !== 'ALLOCATED') {
                rawAlerts.push({
                    id: `qual-70-${client.id}`,
                    title: '70% Payment Qualification',
                    message: `${client.name} has qualified for plot allocation.`,
                    type: 'Qualification',
                    targetType: 'ROLE',
                    targetRoles: ['Administrator', 'CEO', 'Head of Sales'],
                    accountId: ACC_ID,
                    timestamp: now.toISOString(),
                    readByUserIds: [],
                    moduleKey: 'Allocate Plot',
                    entityId: client.id,
                    metadata: { clientId: client.id, clientName: client.name }
                });
            }

            // 3. 3-Month Default (Target: ROLE -> Chief Accountant, CEO)
            const lastPaymentDate = client.payment.paymentHistory.length > 0 
                ? new Date(client.payment.paymentHistory[client.payment.paymentHistory.length - 1].date)
                : new Date(client.regDate);
            const monthsSinceLastPayment = (now.getTime() - lastPaymentDate.getTime()) / (1000 * 60 * 60 * 24 * 30);

            if (monthsSinceLastPayment >= 3 && client.payment.balance > 0) {
                rawAlerts.push({
                    id: `default-${client.id}`,
                    title: 'Payment Default Escalation',
                    message: `${client.name} has exceeded 3 months without payment.`,
                    type: 'Default',
                    targetType: 'ROLE',
                    targetRoles: ['Chief Accountant', 'CEO'],
                    accountId: ACC_ID,
                    timestamp: now.toISOString(),
                    readByUserIds: [],
                    moduleKey: 'Account Management',
                    entityId: client.id,
                    metadata: { clientId: client.id, clientName: client.name }
                });
            }
        });

        // --- DETERMINISTIC ELIGIBILITY FILTERING ---
        // A user only sees notifications if they are the targeted recipients
        return rawAlerts.filter(alert => {
            const isGlobal = alert.targetType === 'GLOBAL';
            const isRoleTargeted = alert.targetType === 'ROLE' && alert.targetRoles?.includes(currentStaff.roleId);
            const isUserTargeted = alert.targetType === 'USER' && alert.targetUserIds?.includes(currentStaff.id);

            return isGlobal || isRoleTargeted || isUserTargeted;
        }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

    }, [clients, currentStaff]);

    return notifications;
};

import React, { useState, useEffect, useMemo } from 'react';
import { Card } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';
import { 
    BellIcon, 
    ClockIcon, 
    CheckCircleIcon, 
    InformationCircleIcon, 
    ArrowRightIcon,
    MagnifyingGlassIcon
} from '../components/icons/DummyIcons';
import { useClients } from '../hooks/useAppData';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useAuth } from '../context/AuthContext';
import { AppNotification } from '../types';

interface NotificationsPageProps {
    setActivePage: (page: string, context?: any) => void;
}

const NotificationsPage: React.FC<NotificationsPageProps> = ({ setActivePage }) => {
    const { clients } = useClients();
    const { currentStaff } = useAuth();
    const eligibleAlerts = useNotificationTriggers(clients);

    const [viewMode, setViewMode] = useState<'all' | 'unread'>('all');
    const [searchTerm, setSearchTerm] = useState('');

    // Local state to simulate per-user read tracking for the session
    // In production, this would be a mutation to the `notification_reads` table
    const [readSet, setReadSet] = useState<Set<string>>(new Set());

    // Effect: Auto-mark as read when visiting via the Bell Icon
    useEffect(() => {
        const unreadIds = eligibleAlerts.map(a => a.id);
        setReadSet(prev => {
            const next = new Set(prev);
            unreadIds.forEach(id => next.add(id));
            return next;
        });

        // Broadcast to system that badge should reset
        const event = new CustomEvent('faim_notifications_opened');
        window.dispatchEvent(event);
    }, [eligibleAlerts.length]);

    const filteredAlerts = useMemo(() => {
        return eligibleAlerts.filter(alert => {
            const matchesSearch = alert.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                                alert.message.toLowerCase().includes(searchTerm.toLowerCase());
            const matchesView = viewMode === 'all' || !readSet.has(alert.id);
            return matchesSearch && matchesView;
        });
    }, [eligibleAlerts, searchTerm, viewMode, readSet]);

    const handleAction = (alert: AppNotification) => {
        if (alert.moduleKey) {
            // Find target client object if entityId exists
            const context = alert.entityId ? clients.find(c => c.id === alert.entityId) : null;
            setActivePage(alert.moduleKey, context);
        }
    };

    const getTargetTag = (type: AppNotification['targetType']) => {
        switch(type) {
            case 'ROLE': return <Badge variant="info" className="text-[9px] uppercase">Role Alert</Badge>;
            case 'USER': return <Badge variant="warning" className="text-[9px] uppercase">Direct</Badge>;
            default: return <Badge variant="neutral" className="text-[9px] uppercase">Global</Badge>;
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Notification Center</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1 font-medium">My personalized alerts and system escalations.</p>
                </div>
                <div className="flex bg-gray-100 dark:bg-gray-800 p-1 rounded-xl border border-gray-200 dark:border-gray-700">
                    <button 
                        onClick={() => setViewMode('all')}
                        className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${viewMode === 'all' ? 'bg-white dark:bg-gray-700 shadow-sm text-blue-600' : 'text-gray-500'}`}
                    >
                        Inbox
                    </button>
                    <button 
                        onClick={() => setViewMode('unread')}
                        className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${viewMode === 'unread' ? 'bg-white dark:bg-gray-700 shadow-sm text-blue-600' : 'text-gray-500'}`}
                    >
                        Unread
                    </button>
                </div>
            </div>

            <Card className="p-0 overflow-hidden border-0 shadow-none bg-transparent">
                <div className="relative mb-6">
                    <MagnifyingGlassIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                    <input 
                        type="text"
                        placeholder="Search alerts by keyword or client name..."
                        className="w-full pl-12 pr-4 py-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-2xl shadow-sm focus:ring-2 focus:ring-blue-500 outline-none text-sm dark:text-white"
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                    />
                </div>

                <div className="space-y-4">
                    {filteredAlerts.length === 0 ? (
                        <div className="py-24 text-center bg-white dark:bg-gray-800 rounded-3xl border-2 border-dashed border-gray-200 dark:border-gray-700 opacity-60">
                            <CheckCircleIcon className="w-16 h-16 mx-auto mb-4 text-gray-200 dark:text-gray-600" />
                            <p className="text-lg font-black text-gray-400 uppercase tracking-widest">No new notifications</p>
                            <p className="text-sm text-gray-400">You're all caught up with your role-based alerts.</p>
                        </div>
                    ) : (
                        filteredAlerts.map(alert => {
                            const isUnread = !readSet.has(alert.id);
                            return (
                                <div 
                                    key={alert.id}
                                    className={`group relative flex flex-col md:flex-row items-start md:items-center gap-4 p-5 rounded-2xl border transition-all duration-300 bg-white dark:bg-gray-800 hover:shadow-xl hover:border-blue-200 dark:hover:border-blue-900 ${isUnread ? 'border-l-4 border-l-blue-600' : 'border-gray-100 dark:border-gray-700 opacity-80'}`}
                                >
                                    <div className={`p-3 rounded-xl shrink-0 ${isUnread ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600' : 'bg-gray-50 dark:bg-gray-900/50 text-gray-400'}`}>
                                        <BellIcon className="w-6 h-6" />
                                    </div>

                                    <div className="flex-grow min-w-0">
                                        <div className="flex items-center gap-3 mb-1">
                                            {getTargetTag(alert.targetType)}
                                            <span className="text-[10px] font-bold text-gray-400 uppercase flex items-center gap-1">
                                                <ClockIcon className="w-3 h-3" />
                                                {new Date(alert.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                            </span>
                                        </div>
                                        <h3 className={`text-base truncate ${isUnread ? 'font-black text-gray-900 dark:text-white' : 'font-bold text-gray-600 dark:text-gray-400'}`}>
                                            {alert.title}
                                        </h3>
                                        <p className="text-sm text-gray-500 dark:text-gray-400 line-clamp-1 mt-0.5">
                                            {alert.message}
                                        </p>
                                    </div>

                                    <div className="shrink-0 w-full md:w-auto mt-4 md:mt-0 flex gap-2">
                                        {alert.moduleKey && (
                                            <button 
                                                onClick={() => handleAction(alert)}
                                                className="w-full md:w-auto px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-black uppercase tracking-widest rounded-xl shadow-lg shadow-blue-600/20 flex items-center justify-center gap-2 transition-all"
                                            >
                                                Resolve <ArrowRightIcon className="w-4 h-4" />
                                            </button>
                                        )}
                                        {!alert.moduleKey && (
                                            <button className="w-full md:w-auto px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 text-xs font-black uppercase tracking-widest rounded-xl transition-all">
                                                View Details
                                            </button>
                                        )}
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>
            </Card>
        </div>
    );
};

export default NotificationsPage;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { MenuIcon } from './icons/MenuIcon';
import { BellIcon, MagnifyingGlassIcon, ArrowRightOnRectangleIcon, EnvelopeIcon, CheckCircleIcon } from './icons/DummyIcons';
import { Staff } from '../types';
import { ROLES } from '../data/mockData';
import ThemeSelector from './ThemeSelector';
import { useClients } from '../hooks/useAppData';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';

interface HeaderProps {
  onMobileMenuToggle: () => void;
  onDesktopToggle: () => void;
  isDesktopCollapsed: boolean;
  currentStaff: Staff;
  onLogout: () => void;
  setActivePage: (page: string, context?: any) => void;
  unreadMailsCount?: number;
}

const Header: React.FC<HeaderProps> = ({ 
    onMobileMenuToggle, 
    onDesktopToggle, 
    isDesktopCollapsed, 
    currentStaff, 
    onLogout, 
    setActivePage,
    unreadMailsCount = 0
}) => {
  const [isProfileOpen, setProfileOpen] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);

  // Real-time Notification Engine
  const { clients } = useClients();
  const eligibleAlerts = useNotificationTriggers(clients);

  // Deterministic Badge Logic: 
  // Only counts alerts where current session hasn't "read" them yet
  const [sessionReadIds, setSessionReadIds] = useState<Set<string>>(new Set());

  const unreadAlertsCount = useMemo(() => {
      return eligibleAlerts.filter(a => !sessionReadIds.has(a.id)).length;
  }, [eligibleAlerts, sessionReadIds]);

  // Listen for global signal that notifications were viewed
  useEffect(() => {
      const handleReset = () => {
          setSessionReadIds(new Set(eligibleAlerts.map(a => a.id)));
      };
      window.addEventListener('faim_notifications_opened', handleReset);
      return () => window.removeEventListener('faim_notifications_opened', handleReset);
  }, [eligibleAlerts]);

  const staffRole = ROLES.find(r => r.id === currentStaff.roleId)?.name || 'Staff';

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
            setProfileOpen(false);
        }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="flex items-center justify-between h-20 px-4 sm:px-6 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-30 transition-colors duration-200">
      <div className="flex items-center gap-4">
        <button onClick={onMobileMenuToggle} className="md:hidden text-gray-500"><MenuIcon className="w-6 h-6" /></button>
        <button onClick={onDesktopToggle} className="hidden md:block text-gray-500"><MenuIcon className="w-6 h-6" /></button>
        <div className="hidden md:block relative">
           <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input type="text" placeholder="Global Search..." className="bg-gray-100 dark:bg-gray-900 border border-transparent dark:border-gray-700 rounded-lg pl-10 pr-4 py-2 w-64 focus:ring-2 focus:ring-blue-500 text-sm" />
        </div>
      </div>

      <div className="flex items-center gap-4">
        <div className="flex items-center gap-1">
            <ThemeSelector />

            <button onClick={() => setActivePage('Mailing')} className={`relative p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors ${unreadMailsCount > 0 ? 'text-blue-600' : 'text-gray-500'}`}>
                <EnvelopeIcon className="w-6 h-6" />
                {unreadMailsCount > 0 && <span className="absolute top-1 right-1 h-4 w-4 rounded-full bg-blue-600 text-[9px] text-white flex items-center justify-center font-bold">{unreadMailsCount}</span>}
            </button>

            <button 
                onClick={() => setActivePage('Notifications')}
                className={`relative p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors ${unreadAlertsCount > 0 ? 'text-red-500' : 'text-gray-500'}`}
            >
                <BellIcon className="w-6 h-6" />
                {unreadAlertsCount > 0 && (
                    <span className="absolute top-1 right-1 flex h-4 w-4">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[9px] text-white items-center justify-center font-bold">
                            {unreadAlertsCount}
                        </span>
                    </span>
                )}
            </button>
        </div>

        <div className="relative" ref={profileRef}>
             <button onClick={() => setProfileOpen(!isProfileOpen)} className="flex items-center gap-3">
                 {currentStaff.photo ? (
                    <img src={currentStaff.photo} className="w-10 h-10 rounded-full object-cover border-2 border-gray-200" />
                 ) : (
                    <div className="w-10 h-10 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold">{currentStaff.initials}</div>
                 )}
                <div className="hidden sm:block text-left">
                    <p className="text-sm font-semibold text-gray-800 dark:text-white leading-none">{currentStaff.fullName}</p>
                    <p className="text-[10px] text-gray-500 dark:text-gray-400 uppercase font-black tracking-widest mt-1">{staffRole}</p>
                </div>
            </button>
             {isProfileOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-md shadow-lg py-1 z-50 ring-1 ring-black ring-opacity-5 animate-in fade-in slide-in-from-top-2 duration-200">
                    <button onClick={() => { setActivePage('Settings'); setProfileOpen(false); }} className="w-full text-left block px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100">Profile</button>
                    <button onClick={onLogout} className="w-full text-left flex items-center gap-2 px-4 py-2 text-sm text-red-700 hover:bg-red-50">Sign Out</button>
                </div>
            )}
        </div>
      </div>
    </header>
  );
};

export default Header;

import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PurchaseSaleManagementPage from './pages/PurchaseSaleManagementPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import MappingsPage from './pages/MappingsPage';
import SupportPage from './pages/SupportPage';
import NotificationsPage from './pages/NotificationsPage';

// Team Module Pages
import LeadsManagementPage from './pages/LeadsManagementPage';
import MailingPage from './pages/team/MailingPage';
import LeavePage from './pages/team/LeavePage';
import EventsPage from './pages/team/EventsPage';
import AnnouncementsPage from './pages/team/AnnouncementsPage';

import { DataProvider, usePermissions } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { ModalProvider } from './context/ModalContext';
import { ModalManager } from './components/ModalManager';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet, AppModuleName } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { 
    useClients, useProperties, useInvoices, useStaff, useLeads, 
    usePromotions, useActivityLogs, useRoles, useAmendments, useCompanySettings 
} from './hooks/useAppData';
import { LoaderIcon } from './components/icons/LoaderIcon';
import { ShieldCheckIcon, LockClosedIcon } from './components/icons/DummyIcons';

const queryClient = new QueryClient();

const AuthenticatedApp: React.FC = () => {
    const { clients, saveClient, deleteClient } = useClients();
    const { properties, saveProperty } = useProperties();
    const { invoices, saveInvoice } = useInvoices();
    const { staff, updateStaff } = useStaff(); 
    const { leads, saveLead, deleteLead } = useLeads();
    const { promotions, savePromotion, deletePromotion } = usePromotions();
    const { activityLogs, addActivityLog } = useActivityLogs();
    const { roles, setRoles } = useRoles();
    const { amendments, setAmendmentList } = useAmendments();
    const { companySettings, setCompanySettings } = useCompanySettings();
    const { rolePermissions } = usePermissions();

    const { currentStaff, logout } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);
        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });
        return userPermissions;
    }, [currentStaff, rolePermissions]);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        if (page === 'Account Management' && context && (context.id || context.clientId)) {
            setClientForInvoice(context);
        }
        setActivePage(page);
        setPageContext(context);
    };

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard': return <Dashboard />;
            case 'Clients': return <ClientsPage clients={clients} onSaveClient={saveClient} onDeleteClient={deleteClient} properties={properties} milestones={[]} onClientSelect={(client) => handleSetPage('Client Details', client)} setActivePage={handleSetPage} setClientForInvoice={setClientForInvoice} invoices={invoices} addActivityLog={handleAddActivityLog} />;
            case 'Client Details': return <ClientDetailPage client={pageContext} properties={properties} onBack={() => handleSetPage('Clients')} currentStaff={currentStaff!} roles={roles} setActivePage={handleSetPage} />;
            case 'Account Management': return <AccountManagementPage clients={clients} onSaveClient={saveClient} invoices={invoices} onSaveInvoice={saveInvoice} clientForInvoice={clientForInvoice} setClientForInvoice={setClientForInvoice} receiptPattern={null} setReceiptPattern={() => {}} setReceiptAlerts={() => {}} currentStaff={currentStaff!} roles={roles} setActivePage={handleSetPage} />;
            case 'Leads & Follow-Ups': return <LeadsManagementPage onSaveLead={saveLead} onDeleteLead={deleteLead} clients={clients} onSaveClient={saveClient} staffList={staff} roles={roles} properties={properties} milestones={[]} currentStaff={currentStaff!} addActivityLog={handleAddActivityLog} />;
            case 'Mailing': return <MailingPage />;
            case 'Leave': return <LeavePage />;
            case 'Events': return <EventsPage />;
            case 'Announcements': return <AnnouncementsPage />;
            case 'Notifications': return <NotificationsPage setActivePage={handleSetPage} />;
            case 'Settings': return <SettingsPage currentStaff={currentStaff!} staff={staff} roles={roles} setRoles={setRoles} onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)} companySettings={companySettings} setCompanySettings={setCompanySettings} onUpdateStaff={updateStaff} />;
            case 'CEO Hub': return <CEOHub setActivePage={handleSetPage} properties={properties} clients={clients} invoices={invoices} staff={staff} roles={roles} onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)} addActivityLog={handleAddActivityLog} />;
            case 'Properties': return <PropertiesPage properties={properties} currentStaff={currentStaff!} initialProperty={pageContext} onBack={() => handleSetPage('Purchase & Sale Management')} />;
            case 'New Land Acquisition': return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
            case 'Purchase & Sale Management': return <PurchaseSaleManagementPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} currentStaff={currentStaff!} setActivePage={handleSetPage} />;
            case 'Promotions': return <PromotionsPage promotions={promotions} onSavePromotion={savePromotion} onDeletePromotion={deletePromotion} properties={properties} showForm={true} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
            case 'Administration': return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Human Resources': return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts': return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot': return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation': return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings': return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form': return <AmendmentFormPage client={pageContext} onBack={() => handleSetPage('Client Details', pageContext)} onSave={async (data, updatedClient) => { setAmendmentList(prev => [data, ...prev]); await saveClient(updatedClient); handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`); alert('Amendment processed successfully!'); handleSetPage('Client Details', updatedClient); }} currentStaff={currentStaff!} />;
            case 'Analytics & Reports': return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports': return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity': return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Support': return <SupportPage />;
            default: return <Dashboard />;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff!} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
            <ModalManager />
        </Layout>
    );
};

const AppContent: React.FC = () => {
    const { loading, sessionStatus, currentStaff, login, authError } = useAuth();
    const { companySettings } = useCompanySettings();

    if (loading || sessionStatus === 'authenticating' || sessionStatus === 'resolving_profile' || sessionStatus === 'bootstrapping') {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-950">
                <LoaderIcon className="w-12 h-12 text-blue-600 animate-spin mb-4" />
                <p className="text-sm font-bold text-gray-400 uppercase tracking-widest animate-pulse">
                    Authorizing access...
                </p>
            </div>
        );
    }

    if (!currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} externalError={authError} />;
    }

    return <AuthenticatedApp />;
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <ModalProvider>
                    <AuthProvider>
                        <DataProvider>
                            <AppContent />
                        </DataProvider>
                    </AuthProvider>
                </ModalProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { MenuIcon } from './icons/MenuIcon';
import { BellIcon, MagnifyingGlassIcon, ArrowRightOnRectangleIcon, EnvelopeIcon, CheckCircleIcon } from './icons/DummyIcons';
import { Staff } from '../types';
import { ROLES } from '../data/mockData';
import ThemeSelector from './ThemeSelector';
import { useClients } from '../hooks/useAppData';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';

// FIX: Export HeaderNotification interface to resolve import error in Layout.tsx
export interface HeaderNotification {
  id: string;
  title: string;
  description: string;
  timestamp: string;
  type: 'alert' | 'mail';
  targetPage: string;
  targetContext: any;
}

interface HeaderProps {
  onMobileMenuToggle: () => void;
  onDesktopToggle: () => void;
  isDesktopCollapsed: boolean;
  currentStaff: Staff;
  onLogout: () => void;
  setActivePage: (page: string, context?: any) => void;
  unreadMailsCount?: number;
  // FIX: Added notifications to HeaderProps
  notifications?: HeaderNotification[];
}

const Header: React.FC<HeaderProps> = ({ 
    onMobileMenuToggle, 
    onDesktopToggle, 
    isDesktopCollapsed, 
    currentStaff, 
    onLogout, 
    setActivePage,
    unreadMailsCount = 0,
    // FIX: Include notifications in destructuring
    notifications = []
}) => {
  const [isProfileOpen, setProfileOpen] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);

  // Real-time Notification Engine
  const { clients } = useClients();
  const eligibleAlerts = useNotificationTriggers(clients);

  // Deterministic Badge Logic: 
  // Only counts alerts where current session hasn't "read" them yet
  const [sessionReadIds, setSessionReadIds] = useState<Set<string>>(new Set());

  const unreadAlertsCount = useMemo(() => {
      return eligibleAlerts.filter(a => !sessionReadIds.has(a.id)).length;
  }, [eligibleAlerts, sessionReadIds]);

  // Listen for global signal that notifications were viewed
  useEffect(() => {
      const handleReset = () => {
          setSessionReadIds(new Set(eligibleAlerts.map(a => a.id)));
      };
      window.addEventListener('faim_notifications_opened', handleReset);
      return () => window.removeEventListener('faim_notifications_opened', handleReset);
  }, [eligibleAlerts]);

  const staffRole = ROLES.find(r => r.id === currentStaff.roleId)?.name || 'Staff';

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
            setProfileOpen(false);
        }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="flex items-center justify-between h-20 px-4 sm:px-6 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-30 transition-colors duration-200">
      <div className="flex items-center gap-4">
        <button onClick={onMobileMenuToggle} className="md:hidden text-gray-500"><MenuIcon className="w-6 h-6" /></button>
        <button onClick={onDesktopToggle} className="hidden md:block text-gray-500"><MenuIcon className="w-6 h-6" /></button>
        <div className="hidden md:block relative">
           <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input type="text" placeholder="Global Search..." className="bg-gray-100 dark:bg-gray-900 border border-transparent dark:border-gray-700 rounded-lg pl-10 pr-4 py-2 w-64 focus:ring-2 focus:ring-blue-500 text-sm" />
        </div>
      </div>

      <div className="flex items-center gap-4">
        <div className="flex items-center gap-1">
            <ThemeSelector />

            <button onClick={() => setActivePage('Mailing')} className={`relative p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors ${unreadMailsCount > 0 ? 'text-blue-600' : 'text-gray-500'}`}>
                <EnvelopeIcon className="w-6 h-6" />
                {unreadMailsCount > 0 && <span className="absolute top-1 right-1 h-4 w-4 rounded-full bg-blue-600 text-[9px] text-white flex items-center justify-center font-bold">{unreadMailsCount}</span>}
            </button>

            <button 
                onClick={() => setActivePage('Notifications')}
                className={`relative p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors ${unreadAlertsCount > 0 ? 'text-red-500' : 'text-gray-500'}`}
            >
                <BellIcon className="w-6 h-6" />
                {unreadAlertsCount > 0 && (
                    <span className="absolute top-1 right-1 flex h-4 w-4">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[9px] text-white items-center justify-center font-bold">
                            {unreadAlertsCount}
                        </span>
                    </span>
                )}
            </button>
        </div>

        <div className="relative" ref={profileRef}>
             <button onClick={() => setProfileOpen(!isProfileOpen)} className="flex items-center gap-3">
                 {currentStaff.photo ? (
                    <img src={currentStaff.photo} className="w-10 h-10 rounded-full object-cover border-2 border-gray-200" />
                 ) : (
                    <div className="w-10 h-10 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold">{currentStaff.initials}</div>
                 )}
                <div className="hidden sm:block text-left">
                    <p className="text-sm font-semibold text-gray-800 dark:text-white leading-none">{currentStaff.fullName}</p>
                    <p className="text-[10px] text-gray-500 dark:text-gray-400 uppercase font-black tracking-widest mt-1">{staffRole}</p>
                </div>
            </button>
             {isProfileOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-md shadow-lg py-1 z-50 ring-1 ring-black ring-opacity-5 animate-in fade-in slide-in-from-top-2 duration-200">
                    <button onClick={() => { setActivePage('Settings'); setProfileOpen(false); }} className="w-full text-left block px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100">Profile</button>
                    <button onClick={onLogout} className="w-full text-left flex items-center gap-2 px-4 py-2 text-sm text-red-700 hover:bg-red-50">Sign Out</button>
                </div>
            )}
        </div>
      </div>
    </header>
  );
};

export default Header;

