                            Client has not paid up to 70%. Current: {qualification.percentage}%.
                        </p>
                    </div>
                ) : (
                    <div className="p-4 bg-green-50 dark:bg-green-900/20 border-l-4 border-green-600 rounded-r-lg space-y-1 animate-in fade-in slide-in-from-top-1">
                        <div className="flex items-center gap-2 text-green-800 dark:text-green-400">
                            <CheckCircleIcon className="w-4 h-4" />
                            <p className="text-[10px] font-black uppercase tracking-tight">Eligibility Verified</p>
                        </div>
                        <p className="text-xs text-green-700 dark:text-green-300 font-medium">
                            Client qualifies for allocation (≥70%).
                        </p>
                    </div>
                )}
            </div>
        </Card>
    );
};

import React, { useMemo } from 'react';
import { Property, AllocationStatus } from '../../types';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { ExclamationTriangleIcon, PhoneIcon } from '../icons/DummyIcons';

interface PlotSelectionGridProps {
    property: Property;
    availablePlots: { plotNumber: string; isTaken: boolean; owner?: string; status?: AllocationStatus }[];
    selectedPlots: string[];
    onTogglePlot: (plot: string) => void;
    onConfirm: () => void;
    isSaving: boolean;
    isAlreadyAllocated?: boolean;
    isReserved?: boolean;
    clientPlotNumbers?: string;
    clientPaidPercent: number | null;
}

export const PlotSelectionGrid: React.FC<PlotSelectionGridProps> = ({ 
    property, 
    availablePlots, 
    selectedPlots, 
    onTogglePlot, 
    onConfirm, 
    isSaving,
    isAlreadyAllocated = false,
    isReserved = false,
    clientPaidPercent
}) => {
    // Computed Business Rules for Interaction
    const isUninitialized = clientPaidPercent === null;
    const paymentAtOrAbove70 = !isUninitialized && (clientPaidPercent as number) >= 70;
    const isSelectionBlocked = isAlreadyAllocated || isReserved;

    // Final Button Enabling Logic
    const canConfirm = !isAlreadyAllocated && paymentAtOrAbove70 && selectedPlots.length > 0;

    // Find if any currently selected plot is actually reserved by another user
    const selectedReservedPlots = availablePlots.filter(p => 
        selectedPlots.includes(p.plotNumber) && 
        p.status === 'RESERVED_NOT_ALLOCATED' && 
        p.owner !== availablePlots.find(x => x.plotNumber === p.plotNumber)?.owner
    );

    return (
        <Card title={isReserved ? `3. Review RESERVED Plot(s) for ${property.location}` : `3. Select Plot(s) for ${property.location}`} className="lg:col-span-2 relative">
            {/* Interaction Lock for Finalized Records */}
            {isAlreadyAllocated && (
                <div className="absolute inset-0 bg-white/5 dark:bg-gray-900/5 backdrop-blur-[0.5px] z-10 cursor-not-allowed rounded-lg" />
            )}

            <div className={`grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-2 max-h-[350px] overflow-y-auto scrollbar-thin p-1 ${isAlreadyAllocated ? 'opacity-80' : ''}`}>
                {availablePlots.map(plot => {
                    const isReservedBySomeone = plot.status === 'RESERVED_NOT_ALLOCATED';
                    const isSelected = selectedPlots.includes(plot.plotNumber);

                    return (
                        <button
                            key={plot.plotNumber}
                            disabled={plot.isTaken || isAlreadyAllocated || isReserved}
                            onClick={() => onTogglePlot(plot.plotNumber)}
                            className={`p-2 rounded border text-[10px] font-bold flex flex-col items-center gap-1 transition-all h-20 justify-center shadow-sm ${
                                plot.isTaken 
                                ? 'bg-gray-100 text-gray-300 border-gray-200 cursor-not-allowed grayscale' 
                                : isSelected
                                    ? isReserved 
                                        ? 'bg-blue-50 text-blue-700 border-blue-200 border-dashed scale-100' 
                                        : 'bg-blue-600 text-white border-blue-600 scale-105 z-10'
                                    : isReservedBySomeone
                                        ? 'bg-white text-blue-600 border-blue-300 border-dashed hover:border-blue-500 hover:bg-blue-50/50'
                                        : isSelectionBlocked
                                            ? 'bg-gray-50 text-gray-400 border-gray-200 cursor-not-allowed'
                                            : 'bg-white text-gray-600 border-gray-300 hover:border-blue-500'
                            }`}
                        >
                            <span className={isReservedBySomeone ? "text-blue-600 font-black" : ""}>{plot.plotNumber}</span>
                            <span className={`opacity-60 text-[9px] ${isReservedBySomeone ? "text-blue-500 font-black italic" : ""}`}>
                                {plot.isTaken ? 'ALLOCATED' : isReserved && isSelected ? 'RESERVED' : isReservedBySomeone ? 'RESERVED' : isSelectionBlocked ? 'Locked' : 'Pick'}
                            </span>
                        </button>
                    );
                })}
            </div>

            <div className="mt-6 space-y-4">
                {!isSelectionBlocked && selectedReservedPlots.length > 0 && (
                    <div className="bg-amber-50 dark:bg-amber-900/10 border-l-4 border-amber-500 p-4 rounded-r-lg animate-in fade-in slide-in-from-left-4">
                        <div className="flex gap-3">
                            <ExclamationTriangleIcon className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                            <div className="space-y-4 text-xs font-medium text-amber-800 dark:text-amber-200">
                                {selectedReservedPlots.map(p => (
                                    <div key={p.plotNumber} className="space-y-1">
                                        <p className="font-black uppercase tracking-tight text-amber-900 dark:text-amber-100">Conflict Warning: Plot {p.plotNumber}</p>
                                        <p>This plot is RESERVED by <span className="font-black underline">{p.owner}</span>.</p>
                                        <p>Qualification check failed or not reached 70%.</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}

                {selectedPlots.length > 0 && (
                    <div className={`flex justify-between items-center bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-200 dark:border-blue-800 ${isAlreadyAllocated || (!paymentAtOrAbove70 && !isUninitialized) ? 'opacity-50' : ''}`}>
                        <div>
                            <p className="text-xs text-blue-800 dark:text-blue-400 font-bold uppercase tracking-widest">{isReserved ? 'Ready for confirmation:' : 'Ready for assignment:'}</p>
                            <p className="text-sm font-black text-blue-900 dark:text-white mt-1">{selectedPlots.join(', ')}</p>
                        </div>
                        <Button 
                            onClick={onConfirm} 
                            isLoading={isSaving} 
                            disabled={!canConfirm}
                            className="px-8 font-black uppercase tracking-widest"
                        >
                            {isAlreadyAllocated ? 'Already Allocated' : isUninitialized ? 'Requires Ledger Initialization' : !paymentAtOrAbove70 ? 'Ineligible (Low Payment)' : isReserved ? 'Confirm ALLOCATION' : 'Confirm Selection'}
                        </Button>
                    </div>
                )}
            </div>
        </Card>
    );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Client } from '../../types';
import { CheckCircleIcon, BanknotesIcon, LockClosedIcon, ArrowTrendingUpIcon, InformationCircleIcon } from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';

interface AccountOverviewProps {
    selectedClient: Client;
    originalPricePerPlot: number;
    discountAmount: number;
    priceAfterDiscount: number;
    installmentOption: string;
    setInstallmentOption: (val: string) => void;
    onInitialSave: (customMonths?: number, financialSnapshot?: any) => void;
    isSaving: boolean;
}

export const AccountOverview: React.FC<AccountOverviewProps> = ({
    selectedClient,
    originalPricePerPlot,
    discountAmount: propDiscountAmount,
    priceAfterDiscount: propPriceAfterDiscount,
    installmentOption,
    setInstallmentOption,
    onInitialSave,
    isSaving
}) => {
    const isInitialized = !!(selectedClient.payment as any).isInitialized;
    const hasPaymentsWithoutInit = !isInitialized && (selectedClient.payment.paymentHistory || []).length > 0;

    const plotCount = useMemo(() => selectedClient.plot.split(',').filter(p => p.trim()).length || 1, [selectedClient.plot]);
    const preDiscountTotal = originalPricePerPlot * plotCount;

    // Internal state for Discount Logic (Only used before Save)
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>(
        (selectedClient.payment as any).discountType || 'percentage'
    );
    const [discountValue, setDiscountValue] = useState<string>(
        String((selectedClient.payment as any).discountValue || '0')
    );
    const [customMonths, setCustomMonths] = useState<string>(
        String((selectedClient.payment as any).customMonths || '24')
    );

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const financials = useMemo(() => {
        const dVal = parseFloat(discountValue) || 0;
        let dAmt = 0;

        if (discountType === 'percentage') {
            dAmt = preDiscountTotal * (Math.min(100, Math.max(0, dVal)) / 100);
        } else {
            dAmt = Math.min(preDiscountTotal, Math.max(0, dVal));
        }

        const finalTotal = preDiscountTotal - dAmt;
        const months = installmentOption === 'Outright' ? 1 : 
                       (installmentOption === 'Other' ? (parseInt(customMonths) || 1) : parseInt(installmentOption));

        const emi = finalTotal / months;

        return {
            preDiscountTotal,
            discountAmount: dAmt,
            finalTotal: isInitialized ? selectedClient.payment.total : finalTotal,
            emi: isInitialized ? ((selectedClient.payment as any).emiMonthlyPayment || (selectedClient.payment.total / months)) : emi,
            months
        };
    }, [discountType, discountValue, preDiscountTotal, installmentOption, customMonths, isInitialized, selectedClient.payment]);

    const handleSave = () => {
        const snapshot = {
            isInitialized: true,
            discountType,
            discountValue: parseFloat(discountValue),
            discountAmountApplied: financials.discountAmount,
            contractTotalBeforeDiscount: financials.preDiscountTotal,
            contractTotalAfterDiscount: financials.finalTotal,
            emiMonthlyPayment: financials.emi,
            monthlyInstallmentAmount: financials.emi, // Explicitly mirrored
            customMonths: installmentOption === 'Other' ? parseInt(customMonths) : null
        };
        onInitialSave(installmentOption === 'Other' ? parseInt(customMonths) : undefined, snapshot);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-300">
            {/* AUTHORITATIVE BLOCKER BANNER */}
            {hasPaymentsWithoutInit && (
                <div className="bg-amber-50 border-l-4 border-amber-500 p-4 rounded flex items-start gap-4 shadow-sm">
                    <InformationCircleIcon className="w-6 h-6 text-amber-600 shrink-0" />
                    <div>
                        <p className="text-sm font-black text-amber-800 uppercase tracking-tight">Ledger Initialization Required</p>
                        <p className="text-xs text-amber-700 mt-1">
                            Payments exist for this account but the **Contract Total** is not initialized. 
                            The system cannot compute qualification percentages until you save the payment details below.
                        </p>
                    </div>
                </div>
            )}

            <Card title="Active Account Ledger">
                <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Property Location</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.location || '—'}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Number of Plots</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{plotCount}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Base Price Total</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(preDiscountTotal)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Contract Status</p>
                        <Badge variant={isInitialized ? 'success' : 'warning'}>
                            {isInitialized ? 'LOCKED' : 'PENDING INITIALIZATION'}
                        </Badge>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">EMI Selection</p>
                        <Badge variant="info">{selectedClient.payment.planType || 'N/A'}</Badge>
                    </div>
                </div>
                {!isInitialized && (
                    <div className="mt-8 border-t border-gray-100 dark:border-gray-700 pt-6">
                        <Button 
                            onClick={handleSave}
                            disabled={isSaving}
                            isLoading={isSaving}
                            icon={<CheckCircleIcon className="w-5 h-5" />}
                            className="w-full md:w-auto px-12 py-3"
                        >
                            Save & Initialize Ledger
                        </Button>
                    </div>
                )}
            </Card>

            <Card title="Financial Configuration">
                <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-6 items-end">
                    <div className="space-y-1">
                        <label className="text-xs font-black text-gray-400 uppercase">Discount Type</label>
                        <Select 
                            value={discountType} 
                            onChange={(e) => setDiscountType(e.target.value as any)}
                            disabled={isInitialized}
                        >
                            <option value="percentage">Percentage (%)</option>
                            <option value="fixed">Fixed Amount (GHC)</option>
                        </Select>
                    </div>

                    <Input 
                        label={`Discount Value ${discountType === 'percentage' ? '(%)' : '(GHC)'}`} 
                        type="number"
                        value={discountValue} 
                        onChange={(e) => setDiscountValue(e.target.value)}
                        disabled={isInitialized}
                        className="font-bold"
                    />

                    <div className="space-y-1">
                        <label className="text-xs font-black text-gray-400 uppercase">Installment Option</label>
                        {isInitialized ? (
                            <div className="h-10 flex items-center px-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-md font-bold text-gray-800 dark:text-white">
                                {selectedClient.payment.planType}
                            </div>
                        ) : (
                            <Select 
                                value={installmentOption} 
                                onChange={(e) => setInstallmentOption(e.target.value)}
                            >
                                <option value="Outright">Outright</option>
                                <option value="3">3 Months</option>
                                <option value="6">6 Months</option>
                                <option value="12">12 Months</option>
                                <option value="Other">Other (Custom)</option>
                            </Select>
                        )}
                    </div>

                    {installmentOption === 'Other' && (
                        <Input 
                            label="Custom Months (1-60)" 
                            type="number" 
                            value={customMonths} 
                            onChange={(e) => setCustomMonths(e.target.value)}
                            disabled={isInitialized}
                            className="font-bold"
                        />
                    )}
                </div>

                <div className="mt-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 border-t border-gray-100 dark:border-gray-700 pt-6">
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Contract Total (After Discount)</p>
                        <p className="text-xl font-black text-green-600">{formatCurrency(financials.finalTotal)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Discount Applied</p>
                        <p className="text-xl font-black text-red-500">-{formatCurrency(financials.discountAmount)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">EMI Monthly Payment</p>
                        <p className="text-xl font-black text-blue-600 dark:text-blue-400">{formatCurrency(financials.emi)}</p>
                    </div>
                    {isInitialized && (
                        <div>
                             <Button 
                                variant="secondary" 
                                size="sm" 
                                className="mt-2 text-[10px] font-black uppercase tracking-tighter"
                                icon={<ArrowTrendingUpIcon className="w-3 h-3" />}
                                onClick={() => handleSave()} // Authority correction: Re-runs the computation
                             >
                                Force Sync Ledger
                             </Button>
                        </div>
                    )}
                </div>

                {isInitialized && (
                    <div className="mt-6 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-dashed border-gray-200 dark:border-gray-700 flex items-center gap-3">
                        <LockClosedIcon className="w-5 h-5 text-gray-400" />
                        <p className="text-xs text-gray-500 italic">This ledger is initialized. Use "Force Sync" only if discrepancies are detected in payment standing.</p>
                    </div>
                )}
            </Card>

            <Card title="Authoritative Ledger Standing" className="bg-gray-50/50 dark:bg-gray-900/20 border-dashed">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Contract Total</p>
                        <p className="text-2xl font-black text-gray-900 dark:text-white">{formatCurrency(selectedClient.payment.total)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Amount Paid</p>
                        <p className="text-2xl font-black text-green-600">{formatCurrency(selectedClient.payment.paid)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Authoritative Balance</p>
                        <p className={`text-2xl font-black ${selectedClient.payment.balance < 0 ? 'text-purple-600' : 'text-red-600'}`}>
                            {formatCurrency(selectedClient.payment.balance)}
                            {selectedClient.payment.balance < 0 && <span className="text-[10px] ml-2 uppercase font-black tracking-tighter text-purple-500">(Overpaid)</span>}
                        </p>
                    </div>
                </div>
            </Card>
        </div>
    );
};

