import { useMemo } from 'react';
import { Client, AppNotification } from '../types';

export const useNotificationTriggers = (clients: Client[]) => {
    const notifications = useMemo(() => {
        const alerts: AppNotification[] = [];
        const now = new Date();

        // Deterministic Accra Date Calculation
        const accraDateStr = new Intl.DateTimeFormat('en-GB', { 
            timeZone: 'Africa/Accra', 
            year: 'numeric', month: '2-digit', day: '2-digit' 
        }).format(now);

        const [day, month, year] = accraDateStr.split('/');
        const todayMonthDay = `${month}-${day}`;
        const todayFull = `${year}-${month}-${day}`;

        clients.forEach(client => {
            // --- SECTION 1: BIRTHDAY CHECK ---
            if (client.dateOfBirth) {
                try {
                    const dobParts = client.dateOfBirth.split('-');
                    if (dobParts.length === 3) {
                        const dobMonthDay = `${dobParts[1]}-${dobParts[2]}`;

                        if (dobMonthDay === todayMonthDay) {
                            alerts.push({
                                id: `bday-${client.id}-${todayFull}`,
                                title: 'Client Birthday Today 🎉',
                                message: `${client.name} is celebrating a birthday today. Please call or text to wish them a happy birthday.`,
                                type: 'Birthday',
                                recipientRole: 'ALL_USERS',
                                timestamp: now.toISOString(),
                                isRead: false,
                                module_key: 'Client Details',
                                entity_id: client.id,
                                metadata: { 
                                    clientId: client.id, 
                                    clientName: client.name,
                                    eventType: 'CLIENT_BIRTHDAY'
                                }
                            });
                        }
                    }
                } catch (e) {}
            }

            // --- SECTION 2: 70% QUALIFICATION ---
            const totalCost = client.payment.total || 0;
            if (totalCost <= 0) return;

            const paidTotal = client.payment.paid || 0;
            const paymentPercentage = (paidTotal / totalCost) * 100;
            const isAllocated = client.allocationStatus === 'ALLOCATED';

            if (paymentPercentage >= 70 && !isAllocated) {
                alerts.push({
                    id: `qual-init-${client.id}`,
                    title: 'Client Qualified for Allocation (70%)',
                    message: `${client.name} has paid 70% (${formatCurrency(paidTotal)}). Allocate plot and confirm on-site within 48h.`,
                    type: 'Qualification',
                    recipientRole: 'Administrator',
                    timestamp: now.toISOString(),
                    isRead: false,
                    module_key: 'Allocate Plot',
                    entity_id: client.id,
                    metadata: { clientId: client.id, clientName: client.name, paidTotal, contractTotal: totalCost, eventType: 'ALLOCATION_70_PERCENT_QUALIFIED' }
                });
            }

            // --- SECTION 3: DEFAULT ESCALATION ---
            const lastPaymentDate = client.payment.paymentHistory.length > 0 
                ? new Date(client.payment.paymentHistory[client.payment.paymentHistory.length - 1].date)
                : new Date(client.regDate);
            const monthsSinceLastPayment = (now.getTime() - lastPaymentDate.getTime()) / (1000 * 60 * 60 * 24 * 30);

            if (monthsSinceLastPayment >= 3 && client.payment.balance > 0) {
                alerts.push({
                    id: `def-esc-acc-${client.id}`,
                    title: 'Payment Default Escalation',
                    message: `${client.name} has defaulted for 3 months. Review required.`,
                    type: 'Default',
                    recipientRole: 'Chief Accountant',
                    timestamp: now.toISOString(),
                    isRead: false,
                    module_key: 'Account Management',
                    entity_id: client.id,
                    metadata: { clientId: client.id, clientName: client.name }
                });
            }
        });

        return alerts.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [clients]);

    return notifications;
};

const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH').format(amount)}`;

import React, { useState, useRef, useEffect, useMemo } from 'react';
