        <div className="hidden md:block relative">
           <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500" />
            <input type="text" placeholder="Global Search..." className="bg-gray-100 dark:bg-gray-900 border border-transparent dark:border-gray-700 rounded-lg pl-10 pr-4 py-2 w-64 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400 text-sm" />
        </div>
      </div>

      <div className="flex items-center gap-4">
        <div className="flex items-center gap-1">
            <ThemeSelector />

            <button onClick={() => setActivePage('Mailing')} title="Mail" className={`relative p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors group ${unreadMailsCount > 0 ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>
                <EnvelopeIcon className="w-6 h-6" />
                {unreadMailsCount > 0 && <span className="absolute top-1 right-1 h-4 w-4 rounded-full bg-blue-600 text-[9px] text-white flex items-center justify-center font-bold ring-2 ring-white dark:ring-gray-800">{unreadMailsCount > 99 ? '99+' : unreadMailsCount}</span>}
            </button>

            <button 
                onClick={() => setActivePage('Notifications')}
                title="Notifications"
                className={`relative p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors ${unreadAlertsCount > 0 ? 'text-red-500' : 'text-gray-500'}`}
            >
                <BellIcon className="w-6 h-6" />
                {unreadAlertsCount > 0 && (
                    <span className="absolute top-1 right-1 flex h-4 w-4">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[9px] text-white items-center justify-center font-bold">
                            {unreadAlertsCount > 9 ? '9+' : unreadAlertsCount}
                        </span>
                    </span>
                )}
            </button>
        </div>

        <div className="relative" ref={profileRef}>
             <button onClick={() => setProfileOpen(!isProfileOpen)} className="flex items-center gap-3 cursor-pointer">
                 {currentStaff.photo ? (
                    <img src={currentStaff.photo} alt="Profile" className="w-10 h-10 rounded-full object-cover border-2 border-gray-200 dark:border-gray-600" />
                 ) : (
                    <div className="w-10 h-10 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold border-2 border-transparent">{currentStaff.initials}</div>
                 )}
                <div className="hidden sm:block text-left">
                    <p className="text-sm font-semibold text-gray-800 dark:text-white leading-none">{currentStaff.fullName}</p>
                    <p className="text-[10px] text-gray-500 dark:text-gray-400 uppercase font-black tracking-widest mt-1">{staffRole}</p>
                </div>
            </button>
             {isProfileOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-md shadow-lg py-1 z-50 ring-1 ring-black ring-opacity-5 dark:ring-gray-700 animate-in fade-in slide-in-from-top-2 duration-200">
                    <button onClick={() => { setActivePage('Settings'); setProfileOpen(false); }} className="w-full text-left block px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">Profile</button>
                    <button onClick={onLogout} className="w-full text-left flex items-center gap-2 px-4 py-2 text-sm text-red-700 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20">Sign Out</button>
                </div>
            )}
        </div>
      </div>
    </header>
  );
};

