import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Client, Milestone, Property, Invoice, ActivityLog, Staff, AllocationStatus } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { VariableSizeList as List } from 'react-window';
import { useClients, useStaff } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';
import { useData } from '../context/DataContext';
import { useAuth } from '../context/AuthContext';

// Modular Imports
import { ClientListHeader } from '../components/clients/ClientListHeader';
import { ClientFilters } from '../components/clients/ClientFilters';
import { ClientTableHead } from '../components/clients/ClientTableHead';
import { ClientsList } from '../components/clients/ClientsList';

interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string, context?: any) => void;
    setClientForInvoice: (client: Client | null) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (formData: FormData): boolean => {
    const requiredFields: (keyof FormData)[] = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    for (const field of requiredFields) {
        if (!formData[field] || String(formData[field]).trim() === '') return false;
    }
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);
    const { sendMail } = useData();
    const { staff } = useStaff();
    const { currentStaff } = useAuth();

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [deletedClientInfo, setDeletedClientInfo] = useState<{ name: string; timeoutId: ReturnType<typeof setTimeout> } | null>(null);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    // Virtualization State
    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});

    // --- SCROLL ANIMATION LOGIC ---
    const [scrollOffset, setScrollOffset] = useState(0);
    const MAX_SCROLL = 80;

    const handleScroll = ({ scrollOffset: offset }: { scrollOffset: number }) => {
        setScrollOffset(Math.min(offset, MAX_SCROLL));
    };

    const headerOpacity = Math.max(0, 1 - scrollOffset / (MAX_SCROLL * 0.8));
    const headerHeight = Math.max(0, 48 - (scrollOffset / MAX_SCROLL) * 48);
    const controlsTranslate = (scrollOffset / MAX_SCROLL) * -52;

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const handleDeleteClick = useCallback((clientId: number) => {
        const client = clients.find(c => c.id === clientId);
        if (client) setClientToDelete(client);
    }, [clients]);

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);
            const timeoutId = setTimeout(() => setDeletedClientInfo(null), 3000);
            setDeletedClientInfo({ name: clientToDelete.name, timeoutId });
            setClientToDelete(null);
        }
    };

    const createClientObject = (formData: FormData, id: number, existingClient?: Client | null): Client => {
        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();
        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;
        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }
        const isComplete = isClientDataComplete(formData);

        const clientType = (formData as any).clientType || 'Individual';

        const baseClient = existingClient || {
            id: id, 
            clientType,
            status: 'Active Client' as const, 
            allocationStatus: 'RESERVED_NOT_ALLOCATED' as AllocationStatus, // Authority Rule: Mark as Reserved on New Save
            paidPercent: 0, // Authority Rule: Initialize with 0% paid on New Save
            allocationQualified: false, // FIX: Added missing required property
            stage: milestones[0]?.acronym || 'N/A',
            payment: { total: baseTotal, paid: 0, balance: baseTotal, dueDate: 'N/A', planType: 'N/A', promoDetails: promoDetails, paymentHistory: [], installments: [] },
            interactions: [], documentation: { status: 'Pending' },
            officeUse: { commission: { type: 'Percentage', amount: 0, status: 'Pending' } }
        };
        return {
            ...baseClient, id, 
            clientType, 
            name: fullName, surname: formData.surname, otherNames: formData.otherNames, initials,
            regDate: formData.paymentDate, email: formData.email, phone: formData.telephone, dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'], location: formData.location, plot: formData.plotNumber, photo: formData.photo,
            propertyType: formData.propertyType, plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: { placeOfWork: formData.placeOfWork, profession: formData.profession, position: formData.position },
            witness: { name: formData.witnessName, address: formData.witnessAddress, phone: formData.witnessPhone },
            nextOfKin: { name: formData.kinName, phone: formData.kinPhone, relationship: formData.kinRelationship, email: formData.kinEmail, address: formData.kinAddress },
            indenture: { name: formData.indentureName, address: formData.indentureAddress },
            officeUse: { ...baseClient.officeUse, salesRep: formData.salesRep, salesManager: formData.salesManager, accountsHead: formData.accountsHead, clerk: formData.clerk },
            isComplete, filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClientAndRedirect = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            const isNewClient = !editingClient;
            const newId = editingClient ? editingClient.id : (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

            if (!newId) {
                alert("Error: Client ID could not be generated. Please retry.");
                return;
            }

            let photoUrl = formData.photo;
            if (files?.photo) photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId, editingClient);

            const savedClient = await onSaveClient(newClient);

            if (!savedClient) {
                alert("Error: Client data not saved correctly.");
                return;
            }

            // TRIGGER: Notification to Chief Accountant (Head of Accounts)
            // Rule: Only if actor is Front Desk Executive and this is a NEW client entry
            if (isNewClient && currentStaff?.roleId === 'Front Desk Executive') {
                const chiefAccountants = staff.filter(s => s.roleId === 'Chief Accountant');

                if (chiefAccountants.length > 0) {
                    await sendMail({
                        senderId: currentStaff.id,
                        senderName: currentStaff.fullName,
                        recipientIds: chiefAccountants.map(s => s.id),
                        groupIds: [], 
                        subject: 'ACTION REQUIRED: New Client Ledger Initialization',
                        body: `A new client record has been created and requires financial setup.\n\nClient: ${savedClient.name}\nReference: ${savedClient.initials}-${savedClient.id}\nProperty: ${savedClient.location}\n\nPlease proceed to Account Management to initialize the financial commitment and payment plan for this account.\n\nDate Registered: ${new Date().toLocaleString()}`,
                        attachments: [],
                        timestamp: new Date().toISOString(),
                        readBy: [currentStaff.id],
                        isDraft: false,
                        isDeleted: false,
                        targetPage: 'Account Management',
                        targetContext: savedClient
                    });
                } else {
                    // Log undelivered notification for CEO oversight
                    addActivityLog('Update', `System Warning: No Chief Accountant found to receive onboarding notification for client ${savedClient.name}.`);
                }
            }

            setClientFormOpen(false);
            addActivityLog(editingClient ? 'Update' : 'Create', `Processed client: ${savedClient.name}`);

            // Auto-Redirect to Client Details
            onClientSelect(savedClient);

        } catch (error) { 
            console.error("Save failed:", error);
            alert("Failed to save client."); 
        }
    };

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            {/* STICKY HEADER WRAPPER */}
            <div className="sticky top-0 z-30 bg-gray-100 dark:bg-gray-950 flex-shrink-0 border-b border-gray-200 dark:border-gray-800 pb-1">
                <div className="transition-all duration-300 ease-out"
                     style={{ transform: `translateY(${controlsTranslate}px)` }}>

                    <ClientListHeader 
                        clientCount={clients.length} 
                        hasNextPage={hasNextPage} 
                        onImportClick={() => setImportWizardOpen(true)}
                        onNewClientClick={() => { setEditingClient(null); setClientFormOpen(true); }}
                        headerOpacity={headerOpacity}
                        headerHeight={headerHeight}
                    />

                    <ClientFilters 
                        searchTerm={searchTerm} 
                        onSearchChange={setSearchTerm} 
                        isLoading={isLoading} 
                        properties={properties} 
                    />

                    <ClientTableHead />
                </div>
            </div>

            <ClientsList 
                clients={clients}
                onViewDetails={onClientSelect}
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }}
                onDelete={handleDeleteClick}
                milestones={milestones}
                expandedIds={expandedIds}
                toggleExpand={toggleExpand}
                onScroll={handleScroll}
                listRef={listRef}
            />

            {hasNextPage && !debouncedSearchTerm && (
                <div className="py-3 text-center border-t border-gray-200 dark:border-gray-800 flex-shrink-0">
                    <button 
                        onClick={() => fetchNextPage()} 
                        disabled={isFetchingNextPage}
                        className="text-blue-600 dark:text-blue-400 text-xs font-black uppercase tracking-widest hover:underline disabled:opacity-50"
                    >
                        {isFetchingNextPage ? 'Loading...' : 'Load More Results'}
                    </button>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={() => { setClientFormOpen(false); setEditingClient(null); }}
                onSave={handleSaveClientAndRedirect}
                onSaveAndPay={handleSaveClientAndRedirect}
                properties={properties}
                editingClient={editingClient}
                clients={clients}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={() => {}}
                requiredHeaders={requiredCsvHeaders}
                sampleHeaders=""
                sampleData=""
                wizardTitle="Import Client Data"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />
        </div>
    );
};

export default ClientsPage;

import React, { useState, useMemo, useEffect } from 'react';
import { Lead, Client, Staff, Property, Milestone, LeadComment, ActivityLog, Role } from '../types';
import { 
    MagnifyingGlassIcon, 
    PlusCircleIcon, 
    UploadIcon
} from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import LeadForm from '../components/LeadForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { useLeads } from '../hooks/useAppData';

// Modular Imports
import { LeadsBoard } from '../components/leads/LeadsBoard';
import { LeadsList } from '../components/leads/LeadsList';
import { CommentModal } from '../components/leads/CommentModal';

interface LeadsManagementPageProps {
    onSaveLead: (lead: Lead) => Promise<void>;
    onDeleteLead: (leadId: number) => Promise<void>;
    clients: Client[];
    onSaveClient: (client: Client) => Promise<Client>;
    staffList: Staff[];
    roles: Role[];
    properties: Property[];
    milestones: Milestone[];
    currentStaff: Staff;
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const LeadsManagementPage: React.FC<LeadsManagementPageProps> = ({ onSaveLead, onDeleteLead, clients, onSaveClient, staffList, roles, milestones, currentStaff, addActivityLog }) => {
    const [activeTab, setActiveTab] = useState<'board' | 'list'>('board');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [editingLead, setEditingLead] = useState<Lead | null>(null);

    // Search State
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');

    // Fetch data via hook
    const { leads, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useLeads(debouncedSearchTerm);

    const [draggedLeadId, setDraggedLeadId] = useState<number | null>(null);
    const [commentingLead, setCommentingLead] = useState<Lead | null>(null);
    const [leadToDelete, setLeadToDelete] = useState<Lead | null>(null);

    const salesReps = useMemo(() => staffList.filter(u => ['Head of Sales', 'Sales Representative'].includes(roles.find(r => r.id === u.roleId)?.name || '')), [staffList, roles]);

    // Debounce Effect
    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const handleOpenModal = (lead: Lead | null = null) => {
        setEditingLead(lead);
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setEditingLead(null);
        setIsModalOpen(false);
    };

    const handleSaveLead = (leadData: Omit<Lead, 'id' | 'createdAt' | 'lastContactDate' | 'comments'>) => {
        const currentDate = new Date().toISOString();
        if (editingLead) {
            const leadToSave = { ...editingLead, ...leadData, lastContactDate: currentDate };
            onSaveLead(leadToSave);
            addActivityLog('Update', `Updated lead details for ${leadData.fullName}.`);
        } else {
            const newLead: Lead = {
                id: Date.now(),
                ...leadData,
                status: 'Contacted',
                createdAt: currentDate,
                lastContactDate: currentDate,
                comments: []
            };
            onSaveLead(newLead);
            addActivityLog('Create', `Created new lead: ${newLead.fullName}.`);
        }
        handleCloseModal();
    };

    const handleDeleteClick = (id: number) => {
        const lead = leads.find(l => l.id === id);
        if (lead) {
            setLeadToDelete(lead);
        }
    };

    const confirmDeleteLead = async () => {
        if (leadToDelete) {
            await onDeleteLead(leadToDelete.id);
            addActivityLog('Delete', `Deleted lead: ${leadToDelete.fullName}.`);
            setLeadToDelete(null);
        }
    };

    const handleConvertLead = (lead: Lead) => {
        if (window.confirm(`This lead will now be converted to a client. Continue?`)) {
            const nameParts = lead.fullName.split(' ');
            const surname = nameParts.pop() || '';
            const otherNames = nameParts.join(' ');
            const initials = ((otherNames[0] || '') + (surname[0] || '')).toUpperCase();

            const newClient: Client = {
                id: clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1,
                clientType: 'Individual',
                name: lead.fullName, surname, otherNames, initials,
                regDate: new Date().toISOString().split('T')[0],
                email: lead.email, phone: lead.phone,
                location: 'N/A', plot: 'N/A', status: 'Active Client', stage: milestones[0]?.acronym || 'REG',
                paidPercent: 0, // FIX: Added missing required property
                allocationQualified: false, // FIX: Added missing required property
                payment: { total: 0, paid: 0, balance: 0, dueDate: 'N/A', planType: 'N/A', paymentHistory: [], installments: [] },
                interactions: lead.comments.map((c, i) => ({ id: i + 1, type: 'Note', date: c.date, agent: staffList.find(u => u.id === c.authorId)?.fullName || 'System', notes: `From Lead Follow-up: ${c.text}` })),
                witness: { name: '', address: '', phone: '' },
                nextOfKin: { name: '', phone: '', relationship: '' },
                indenture: { name: '', address: '' },
                officeUse: { salesRep: staffList.find(u=>u.id === lead.assignedRepId)?.fullName || '', salesManager: '', accountsHead: '', clerk: '', commission: { type: 'Percentage', amount: 0, status: 'Pending' } },
                documentation: { status: 'Pending' },
                isComplete: false,
                filledFormPdf: null,
            };

            onSaveClient(newClient);
            onDeleteLead(lead.id);
            addActivityLog('Update', `Converted lead ${lead.fullName} to a client.`);
        }
    };

    // Drag and Drop Handlers
    const handleDragStart = (e: React.DragEvent<HTMLDivElement>, leadId: number) => {
        setDraggedLeadId(leadId);
        e.dataTransfer.effectAllowed = 'move';
    };

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => e.preventDefault();

    const handleDrop = (e: React.DragEvent<HTMLDivElement>, newStatus: Lead['status']) => {
        e.preventDefault();
        if (draggedLeadId === null) return;

        const droppedLead = leads.find(l => l.id === draggedLeadId);
        if (!droppedLead || droppedLead.status === newStatus) return;

        if (newStatus === 'Converted to Client') {
            handleConvertLead(droppedLead);
        } else {
            const oldStatus = droppedLead.status;
            onSaveLead({ ...droppedLead, status: newStatus, lastContactDate: new Date().toISOString() });
            addActivityLog('Update', `Updated lead status for ${droppedLead.fullName} from "${oldStatus}" to "${newStatus}".`);
            setCommentingLead(leads.find(l => l.id === draggedLeadId)!);
        }
        setDraggedLeadId(null);
    };

    const handleAddComment = (leadId: number, text: string) => {
        const lead = leads.find(l => l.id === leadId);
        if (!lead) return;

        const newComment: LeadComment = {
            id: Date.now(),
            text,
            authorId: currentStaff.id,
            date: new Date().toISOString()
        };
        onSaveLead({ ...lead, comments: [...lead.comments, newComment], lastContactDate: new Date().toISOString() });
        addActivityLog('Update', `Added a comment to lead: ${lead.fullName}.`);
    };

    const handleImportLeads = (importedData: any[]) => {
      const highestId = leads.length > 0 ? Math.max(...leads.map(c => c.id)) : 0;

      const newLeads: Lead[] = importedData.map((data, index) => {
          const currentDate = new Date().toISOString();
          return {
              id: highestId + 1 + index,
              fullName: data.fullName || 'Unnamed Lead',
              email: data.email || '',
              phone: data.phone || '',
              source: data.source || 'Other',
              status: 'Contacted',
              assignedRepId: salesReps[0]?.id || '',
              nextFollowUpDate: '',
              lastContactDate: currentDate,
              notes: 'Imported via CSV.',
              createdAt: currentDate,
              comments: [],
          };
      });

      Promise.all(newLeads.map(lead => onSaveLead(lead)));
      addActivityLog('Import', `Imported ${newLeads.length} new leads from a CSV file.`);
    };

    return (
        <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">
            <div className="flex flex-wrap items-center justify-between gap-4 flex-shrink-0">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Lead Management & Follow-Up</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Visually track lead progress and manage conversions.</p>
                </div>
                <div className="flex items-center gap-4">
                    <button onClick={() => setImportWizardOpen(true)} className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 flex items-center gap-2 transition-colors">
                        <UploadIcon className="w-5 h-5" /> Import Leads
                    </button>
                    <button onClick={() => handleOpenModal()} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors">
                        <PlusCircleIcon className="w-5 h-5" /> Add New Lead
                    </button>
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 flex flex-wrap gap-4 justify-between items-center transition-colors flex-shrink-0">
                <div className="flex border-b border-gray-200 dark:border-gray-700">
                    <button onClick={() => setActiveTab('board')} className={`px-4 py-2 font-semibold transition-colors ${activeTab === 'board' ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>Follow-Up Board</button>
                    <button onClick={() => setActiveTab('list')} className={`px-4 py-2 font-semibold transition-colors ${activeTab === 'list' ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>Lead List</button>
                </div>
                 <div className="relative flex-grow sm:flex-grow-0 sm:w-80">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500">
                        {isLoading ? <LoaderIcon className="animate-spin" /> : <MagnifyingGlassIcon />}
                    </div>
                    <input 
                        type="text" 
                        placeholder="Search leads..." 
                        value={searchTerm} 
                        onChange={e => setSearchTerm(e.target.value)} 
                        className="bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-600 rounded-lg pl-10 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400" 
                    />
                </div>
            </div>

            {activeTab === 'board' && (
                <LeadsBoard 
                    leads={leads}
                    staffList={staffList}
                    searchTerm={searchTerm}
                    hasNextPage={hasNextPage}
                    isFetchingNextPage={isFetchingNextPage}
                    fetchNextPage={fetchNextPage}
                    onDragStart={handleDragStart}
                    onDragOver={handleDragOver}
                    onDrop={handleDrop}
                    onCardClick={setCommentingLead}
                />
            )}

            {activeTab === 'list' && (
                <LeadsList 
                    leads={leads}
                    staffList={staffList}
                    isLoading={isLoading}
                    hasNextPage={hasNextPage}
                    isFetchingNextPage={isFetchingNextPage}
                    fetchNextPage={fetchNextPage}
                    onConvert={handleConvertLead}
                    onComment={setCommentingLead}
                    onEdit={handleOpenModal}
                    onDelete={handleDeleteClick}
                />
            )}

            <LeadForm isOpen={isModalOpen} onClose={handleCloseModal} onSave={handleSaveLead} salesReps={salesReps} editingLead={editingLead} />
            <CommentModal isOpen={!!commentingLead} onClose={() => setCommentingLead(null)} lead={commentingLead} onAddComment={handleAddComment} staffList={staffList} />
            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={handleImportLeads}
                requiredHeaders={['fullName', 'phone']}
                sampleHeaders="fullName,email,phone,source"
                sampleData="John Doe,john.doe@example.com,0241234567,Referral\nJane Smith,jane.smith@example.com,0559876543,Facebook"
                wizardTitle="Import Leads from CSV"
            />

            <DeleteConfirmationModal 
                isOpen={!!leadToDelete}
                onClose={() => setLeadToDelete(null)}
                onConfirm={confirmDeleteLead}
                itemName={leadToDelete?.fullName || ''}
                itemType="Lead"
            />
        </div>
    );
};

export default LeadsManagementPage;

