        // Deep linking logic for Account Management
        if (page === 'Account Management' && context && (context.id || context.clientId)) {
            setClientForInvoice(context);
        }

        setActivePage(page);
        setPageContext(context);
    };

    if (!hasAccessToDashboard && activePage === 'Dashboard') {
        return (
            <Layout activePage={activePage} setActivePage={handleSetPage} currentStaff={currentStaff!} onLogout={logout} staffPermissions={staffPermissions} companySettings={companySettings}>
