        const pageToModuleMap: Record<string, AppModuleName> = {
            'Dashboard': 'Dashboard',
            'Clients': 'Clients',
            'Client Details': 'Clients',
            'Account Management': 'Account Management',
            'Leads & Follow-Ups': 'Leads Management',
            'Mailing': 'Internal Mailing',
