import { useQuery, useMutation, useQueryClient, useInfiniteQuery } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { auth } from '../../services/firebase';
import { Client, MilestoneRecord, Property } from '../../types';

// --- Clients ---
export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const {
        data,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
        isLoading
    } = useInfiniteQuery({
        queryKey: ['clients', searchTerm],
        queryFn: ({ pageParam }) => 
            searchTerm 
                ? dbService.searchClients(searchTerm).then(data => ({ data, lastDoc: null }))
                : dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc,
        enabled: isAuthenticated,
    });

    const clients = data?.pages.flatMap(page => page.data) || [];

    const saveClientMutation = useMutation({
        mutationFn: async (client: Client) => {
            const oldClient = clients.find(c => c.id === client.id);
            const isNew = !oldClient;

            // Fetch properties for market price fallback if total is missing
            const properties: Property[] = queryClient.getQueryData(['properties']) || [];

            // --- DETERMINISTIC FINANCE ENGINE ---
            // 1. Recalculate totalPaid from ledger (source of truth)
            const totalPaid = (client.payment.paymentHistory || [])
                .filter(t => t.status === 'Success' && (t.type === 'Land' || !t.type))
                .reduce((sum, t) => sum + t.amount, 0);

            client.payment.paid = totalPaid;

            // 2. Identify effective contract total
            // Tier 1: User-committed total
            // Tier 2: Current catalog price for location
            let effectiveTotal = client.payment.total > 0 ? client.payment.total : 0;

            if (effectiveTotal === 0 && client.location) {
                const catalogMatch = properties.find(p => p.location === client.location);
                if (catalogMatch) {
                    effectiveTotal = catalogMatch.price;
                }
            }

            // 3. Deterministic Percent & Qualification
            if (effectiveTotal > 0) {
                const percent = (totalPaid / effectiveTotal) * 100;
                client.paidPercent = percent;

                const isNowQualified = percent >= 70;
                const wasQualified = oldClient?.allocationQualified || false;

                client.allocationQualified = isNowQualified;

                // Threshold Cross Notification Gate (Fires only on flip false -> true)
                if (isNowQualified && !wasQualified) {
                    console.log(`System Logic: Client ${client.name} now qualified for allocation.`);
                }
            } else {
                // UNINITIALIZED TOTAL: Cannot compute percent
                client.paidPercent = null;
                client.allocationQualified = false;
            }

            const result = await dbService.persistClient(client);

            // Trigger: SFR (Initial)
            if (isNew) {
                await dbService.persistMilestone({
                    clientId: client.id,
                    milestoneCode: 'SFR',
                    dateCompleted: new Date().toISOString().split('T')[0],
                    notes: 'Initial registration received.'
                });
            }

            return result;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return {
        clients,
        isLoading,
        hasNextPage,
        fetchNextPage,
        isFetchingNextPage,
        saveClient: (client: Client) => saveClientMutation.mutateAsync(client),
        deleteClient: (id: number) => deleteClientMutation.mutateAsync(id)
    };
};

// --- Milestones ---
export const useMilestones = (clientId?: number) => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: milestones = [], isLoading } = useQuery({
        queryKey: ['milestones', clientId],
        queryFn: () => clientId ? dbService.fetchMilestonesForClient(clientId) : dbService.fetchMilestones(),
        enabled: isAuthenticated,
    });

    const saveMilestoneMutation = useMutation({
        mutationFn: dbService.persistMilestone,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['milestones'] });
        }
    });

    return { 
        milestones, 
        isLoading, 
        saveMilestone: saveMilestoneMutation.mutateAsync 
    };
};

import React, { useMemo, useState } from 'react';
import { Client } from '../../types';
import { CheckCircleIcon, ArrowPathIcon, ExclamationTriangleIcon, LockClosedIcon } from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';

interface AccountOverviewProps {
    selectedClient: Client;
    originalPricePerPlot: number;
    discountAmount: number;
    priceAfterDiscount: number;
    installmentOption: string;
    setInstallmentOption: (val: string) => void;
    onInitialSave: (customMonths?: number, financialSnapshot?: any) => void;
    isSaving: boolean;
    currentStaff?: any;
}

export const AccountOverview: React.FC<AccountOverviewProps> = ({
    selectedClient,
    originalPricePerPlot,
    discountAmount: propDiscountAmount,
    priceAfterDiscount: propPriceAfterDiscount,
    installmentOption,
    setInstallmentOption,
    onInitialSave,
    isSaving,
    currentStaff
}) => {
    const isInitialized = !!selectedClient.payment.isInitialized;
    const isUninitializedWithPayments = !isInitialized && selectedClient.payment.paid > 0;

    // Permission Rule: Only CEO and Accountants can force a re-sync
    const canRecalculate = ['CEO', 'Chief Accountant'].includes(currentStaff?.roleId || '');

    const plotCount = useMemo(() => selectedClient.plot.split(',').filter(p => p.trim()).length || 1, [selectedClient.plot]);
    const preDiscountTotal = originalPricePerPlot * plotCount;

    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>(
        (selectedClient.payment as any).discountType || 'percentage'
    );
    const [discountValue, setDiscountValue] = useState<string>(
        String((selectedClient.payment as any).discountValue || '0')
    );
    const [customMonths, setCustomMonths] = useState<string>(
        String((selectedClient.payment as any).customMonths || '24')
    );

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const financials = useMemo(() => {
        const dVal = parseFloat(discountValue) || 0;
        let dAmt = 0;

        if (discountType === 'percentage') {
            dAmt = preDiscountTotal * (Math.min(100, Math.max(0, dVal)) / 100);
        } else {
            dAmt = Math.min(preDiscountTotal, Math.max(0, dVal));
        }

        const finalTotal = preDiscountTotal - dAmt;
        const months = installmentOption === 'Outright' ? 1 : 
                       (installmentOption === 'Other' ? (parseInt(customMonths) || 1) : parseInt(installmentOption));

        const emi = finalTotal / months;

        return {
            preDiscountTotal,
            discountAmount: dAmt,
            finalTotal: isInitialized ? selectedClient.payment.total : finalTotal,
            emi: isInitialized ? ((selectedClient.payment as any).emiMonthlyPayment || (selectedClient.payment.total / months)) : emi,
            months
        };
    }, [discountValue, discountType, preDiscountTotal, installmentOption, customMonths, isInitialized, selectedClient.payment]);

    const handleSave = () => {
        const snapshot = {
            isInitialized: true,
            discountType,
            discountValue: parseFloat(discountValue),
            discountAmountApplied: financials.discountAmount,
            contractTotalBeforeDiscount: financials.preDiscountTotal,
            contractTotalAfterDiscount: financials.finalTotal,
            emiMonthlyPayment: financials.emi,
            monthlyInstallmentAmount: financials.emi,
            customMonths: installmentOption === 'Other' ? parseInt(customMonths) : null
        };
        onInitialSave(installmentOption === 'Other' ? parseInt(customMonths) : undefined, snapshot);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-300">
            {isUninitializedWithPayments && (
                <div className="bg-amber-50 border-l-4 border-amber-500 p-4 rounded flex items-start gap-4">
                    <ExclamationTriangleIcon className="w-6 h-6 text-amber-600 shrink-0" />
                    <div>
                        <p className="text-sm font-black text-amber-800 uppercase tracking-tighter">Initialization Required (Ledger Mismatch)</p>
                        <p className="text-xs text-amber-700 mt-1">
                            Payments exist for this account but the **Contract Total** is uninitialized. 
                            The system cannot compute qualification status until you commit a payment plan below.
                        </p>
                    </div>
                </div>
            )}

            <Card title="Active Account Ledger">
                <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Property Location</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.location || '—'}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Number of Plots</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{plotCount}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Base Price Total</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(preDiscountTotal)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Contract Status</p>
                        <Badge variant={isInitialized ? 'success' : 'warning'}>
                            {isInitialized ? 'INITIALIZED' : 'PENDING'}
                        </Badge>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Actions</p>
                        {canRecalculate && (
                             <button 
                                onClick={handleSave}
                                className="text-blue-600 hover:text-blue-800 text-[10px] font-black uppercase flex items-center gap-1"
                             >
                                <ArrowPathIcon className="w-3 h-3" /> Re-Sync
                             </button>
                        )}
                    </div>
                </div>
                {!isInitialized && (
                    <div className="mt-8 border-t border-gray-100 dark:border-gray-700 pt-6">
                        <Button 
                            onClick={handleSave}
                            disabled={isSaving}
                            isLoading={isSaving}
                            icon={<CheckCircleIcon className="w-5 h-5" />}
                            className="w-full md:w-auto px-12 py-3"
                        >
                            Initialize Ledger & Recalculate
                        </Button>
                    </div>
                )}
            </Card>

            <Card title="Financial Configuration">
                <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-6 items-end">
                    <div className="space-y-1">
                        <label className="text-xs font-black text-gray-400 uppercase">Discount Type</label>
                        <Select 
                            value={discountType} 
                            onChange={(e) => setDiscountType(e.target.value as any)}
                            disabled={isInitialized}
                        >
                            <option value="percentage">Percentage (%)</option>
                            <option value="fixed">Fixed Amount (GHC)</option>
                        </Select>
                    </div>

                    <Input 
                        label={`Discount Value ${discountType === 'percentage' ? '(%)' : '(GHC)'}`} 
                        type="number"
                        value={discountValue} 
                        onChange={(e) => setDiscountValue(e.target.value)}
                        disabled={isInitialized}
                        className="font-bold"
                    />

                    <div className="space-y-1">
                        <label className="text-xs font-black text-gray-400 uppercase">Installment Option</label>
                        {isInitialized ? (
                            <div className="h-10 flex items-center px-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-md font-bold text-gray-800 dark:text-white text-sm">
                                {selectedClient.payment.planType}
                            </div>
                        ) : (
                            <Select 
                                value={installmentOption} 
                                onChange={(e) => setInstallmentOption(e.target.value)}
                            >
                                <option value="Outright">Outright</option>
                                <option value="3">3 Months</option>
                                <option value="6">6 Months</option>
                                <option value="12">12 Months</option>
                                <option value="Other">Other (Custom)</option>
                            </Select>
                        )}
                    </div>

                    {installmentOption === 'Other' && (
                        <Input 
                            label="Custom Months (1-60)" 
                            type="number" 
                            value={customMonths} 
                            onChange={(e) => setCustomMonths(e.target.value)}
                            disabled={isInitialized}
                            className="font-bold"
                        />
                    )}
                </div>

                <div className="mt-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 border-t border-gray-100 dark:border-gray-700 pt-6">
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Contract Total (Expected)</p>
                        <p className="text-xl font-black text-green-600">{formatCurrency(financials.finalTotal)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Discount Applied</p>
                        <p className="text-xl font-black text-red-500">-{formatCurrency(financials.discountAmount)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Paid Status</p>
                        <p className={`text-xl font-black ${selectedClient.paidPercent && selectedClient.paidPercent >= 70 ? 'text-green-600' : 'text-amber-500'}`}>
                            {selectedClient.paidPercent ? `${Math.round(selectedClient.paidPercent)}%` : '0%'}
                        </p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Monthly EMI</p>
                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(financials.emi)}</p>
                    </div>
                </div>

                {isInitialized && (
                    <div className="mt-6 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-dashed border-gray-200 dark:border-gray-700 flex items-center gap-3">
                        <LockClosedIcon className="w-5 h-5 text-gray-400" />
                        <p className="text-xs text-gray-500 italic">This ledger is deterministic and locked. Manual recalculated required for plan changes.</p>
                    </div>
                )}
            </Card>

            <Card title="Source-of-Truth Standings" className="bg-gray-50/50 dark:bg-gray-900/20 border-dashed">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Committed Total</p>
                        <p className="text-2xl font-black text-gray-900 dark:text-white">{formatCurrency(selectedClient.payment.total)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Ledger Credits</p>
                        <p className="text-2xl font-black text-green-600">{formatCurrency(selectedClient.payment.paid)}</p>
                    </div>
                    <div>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Effective Balance</p>
                        <p className={`text-2xl font-black ${selectedClient.payment.balance < 0 ? 'text-purple-600' : 'text-red-600'}`}>
                            {formatCurrency(selectedClient.payment.balance)}
                            {selectedClient.payment.balance < 0 && <span className="text-xs ml-2 text-purple-500">(OVERPAID)</span>}
                        </p>
                    </div>
                </div>
            </Card>
        </div>
    );
};

import React, { useMemo } from 'react';
import { Client } from '../../types';
import { Card } from '../ui/Card';
import { Badge } from '../ui/Badge';
import { 
    UserCircleIcon, 
    MapPinIcon, 
    LockClosedIcon, 
    ExclamationTriangleIcon, 
    CheckCircleIcon,
    InformationCircleIcon 
} from '../icons/DummyIcons';

interface QualificationCardProps {
    client: Client;
}

export const QualificationCard: React.FC<QualificationCardProps> = ({ client }) => {
    const qualification = useMemo(() => {
        if (!client) return { isQualified: false, percentage: 0, status: 'N/A', hasAllocated: false, isUninitialized: true };

        // Tiered logic: If paidPercent is null, it means contract total is missing (UNINITIALIZED)
        const isUninitialized = client.paidPercent === null;
        const percentage = client.paidPercent || 0;
        const isQualified = client.allocationQualified || false;
        const hasAllocated = client.allocationStatus === 'ALLOCATED';

        return {
            percentage: Math.round(percentage),
            isQualified,
            hasAllocated,
            isUninitialized,
            status: isUninitialized 
                ? 'PENDING INITIALIZATION' 
                : hasAllocated 
                    ? 'Allocation Verified' 
                    : isQualified 
                        ? 'Qualified (≥70%)' 
                        : 'Ineligible (<70%)'
        };
    }, [client]);

    return (
        <Card title="Qualification Detail" className="lg:col-span-1 space-y-6">
            <div className="text-center space-y-4">
                <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Calculated Progress</p>
                <div className="relative">
                    {qualification.isUninitialized ? (
                        <p className="text-xl font-black text-amber-600 animate-pulse uppercase tracking-tighter">Requires Setup</p>
                    ) : (
                        <p className={`text-2xl font-black ${qualification.hasAllocated ? 'text-blue-600' : qualification.isQualified ? 'text-green-600' : 'text-amber-600'}`}>
                            {qualification.percentage}%
                        </p>
                    )}
                    <p className="text-[10px] font-bold text-gray-500 uppercase mt-1">{qualification.status}</p>
                </div>
                <div className="w-full bg-gray-100 dark:bg-gray-700 h-2.5 rounded-full overflow-hidden shadow-inner">
                    <div 
                        className={`h-full transition-all duration-1000 ${qualification.isUninitialized ? 'bg-gray-300' : qualification.hasAllocated ? 'bg-blue-600' : qualification.isQualified ? 'bg-green-500' : 'bg-amber-500'}`} 
                        style={{ width: `${qualification.isUninitialized ? 0 : Math.min(100, qualification.percentage)}%` }}
                    ></div>
                </div>
            </div>

            <div className="pt-6 border-t border-gray-100 dark:border-gray-700 space-y-4">
                <div className="space-y-2">
                    <div className="flex items-center gap-2 text-xs">
                        <UserCircleIcon className="w-4 h-4 text-gray-400" />
                        <span className="text-gray-500 font-medium">Account:</span>
                        <span className="font-bold text-gray-900 dark:text-white">{client.name}</span>
                    </div>
                </div>

                {qualification.isUninitialized ? (
                    <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border-l-4 border-amber-500 rounded-r-lg space-y-2">
                        <div className="flex items-center gap-2 text-amber-800 dark:text-amber-400">
                            <ExclamationTriangleIcon className="w-4 h-4" />
                            <p className="text-[10px] font-black uppercase">Allocation Blocked</p>
                        </div>
                        <p className="text-xs text-amber-700 dark:text-amber-300 leading-relaxed font-medium">
                            Cannot qualify client. No **Contract Total** found. Initialize financial commitment in Account Management.
                        </p>
                    </div>
                ) : qualification.hasAllocated ? (
                    <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border-l-4 border-blue-600 rounded-r-lg space-y-2">
                        <div className="flex items-center gap-2 text-blue-800 dark:text-blue-400">
                            <LockClosedIcon className="w-4 h-4" />
                            <p className="text-[10px] font-black uppercase">Process Finalized</p>
                        </div>
                        <p className="text-xs text-blue-700 dark:text-blue-300 leading-relaxed font-medium">
                            Physical allocation confirmed for <span className="font-black underline">{client.plot}</span>.
                        </p>
                    </div>
                ) : !qualification.isQualified ? (
                    <div className="p-4 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded-r-lg space-y-1">
                        <div className="flex items-center gap-2 text-red-800 dark:text-red-400">
                            <ExclamationTriangleIcon className="w-4 h-4" />
                            <p className="text-[10px] font-black uppercase">Ineligible</p>
                        </div>
                        <p className="text-xs text-red-700 dark:text-red-300 font-medium">
                            Minimum 70% payment required for plot selection. Current standing: {qualification.percentage}%.
                        </p>
                    </div>
                ) : (
                    <div className="p-4 bg-green-50 dark:bg-green-900/20 border-l-4 border-green-600 rounded-r-lg space-y-1">
                        <div className="flex items-center gap-2 text-green-800 dark:text-green-400">
                            <CheckCircleIcon className="w-4 h-4" />
                            <p className="text-[10px] font-black uppercase">Standing Verified</p>
                        </div>
                        <p className="text-xs text-green-700 dark:text-green-300 font-medium">
                            Client is qualified for plot allocation. Proceed to grid selection.
                        </p>
                    </div>
                )}
            </div>
        </Card>
    );
};

