import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { auth } from '../../services/firebase';
import { Property, Client, Staff } from '../../types';

// --- Properties ---
export const useProperties = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: properties = [] } = useQuery({
        queryKey: ['properties'],
        queryFn: dbService.fetchProperties,
        staleTime: 1000 * 60 * 10,
        enabled: isAuthenticated,
    });

    const activeProperties = properties.filter(p => p.status === 'ACTIVE' || !p.status);

    const savePropertyMutation = useMutation({
        mutationFn: dbService.persistProperty,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['properties'] })
    });

    const archivePropertyMutation = useMutation({
        mutationFn: async ({ property, archivedBy }: { property: Property, archivedBy: Staff }) => {
            // 1. Mark Property as Archived
            const archivedProperty: Property = {
                ...property,
                status: 'ARCHIVED',
                archivedAt: new Date().toISOString(),
                archivedBy: archivedBy.fullName
            };

            // 2. Fetch all clients to identify dependencies
            const allClients = await dbService.fetchClients();
            const impactedClients = allClients.filter(c => 
                c.locationSelectedId === property.id || c.location === property.location
            );

            // 3. Update Impacted Clients (Atomic)
            const clientUpdates = impactedClients.map(client => {
                const updatedClient: Client = {
                    ...client,
                    accountStatus: 'INCOMPLETE',
                    incompleteReason: 'PROPERTY_ARCHIVED',
                    location: 'N/A (Archived)',
                    locationSelectedId: null,
                    plot: 'N/A',
                    allocationStatus: 'RESERVED_NOT_ALLOCATED',
                    paidPercent: null,
                    allocationQualified: false,
                    payment: {
                        ...client.payment,
                        total: 0,
                        balance: 0,
                        planType: 'RE-ASSIGNMENT REQUIRED',
                        emiMonthlyPayment: 0,
                        installments: [] // Clear schedule, preserve history
                    },
                    interactions: [
                        {
                            id: Date.now(),
                            type: 'Note',
                            date: new Date().toISOString(),
                            agent: 'System (Archive Engine)',
                            notes: `PROPERTY_ARCHIVED_IMPACT: Selected property "${property.location}" was archived by ${archivedBy.fullName}. Account reset for re-assignment.`
                        },
                        ...client.interactions
                    ]
                };
                return dbService.persistClient(updatedClient);
            });

            // 4. Batch Execution
            await Promise.all([
                dbService.persistProperty(archivedProperty),
                ...clientUpdates
            ]);

            // 5. Trigger Administrative Notification
            await dbService.sendInternalMail({
                senderId: 'SYSTEM',
                senderName: 'Archive Governance',
                recipientIds: [], // To be handled by groups
                groupIds: ['ROLE_CEO', 'ROLE_ADMINISTRATOR', 'ROLE_ACCOUNTS_HEAD'],
                subject: `SYSTEM ALERT: Property Archived - ${property.location}`,
                body: `Property "${property.location}" has been archived by ${archivedBy.fullName}.\n\nTotal Affected Clients: ${impactedClients.length}\n\nThese accounts have been marked as INCOMPLETE and require immediate re-assignment of an active property and pricing re-initialization.`,
                attachments: [],
                timestamp: new Date().toISOString(),
                readBy: [],
                isDraft: false,
                isDeleted: false,
                participants: []
            });

            return { impactedCount: impactedClients.length };
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['properties'] });
            queryClient.invalidateQueries({ queryKey: ['clients'] });
        }
    });

    const deletePropertyMutation = useMutation({
        mutationFn: dbService.removeProperty,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['properties'] })
    });

    return {
        properties,
        activeProperties,
        saveProperty: (property: Property) => savePropertyMutation.mutateAsync(property),
        archiveProperty: (property: Property, archivedBy: Staff) => archivePropertyMutation.mutateAsync({ property, archivedBy }),
        deleteProperty: (id: number) => deletePropertyMutation.mutateAsync(id)
    };
};

import React, { useState, useMemo } from 'react';
import { Property, Staff } from '../types';
import { ArrowLeftIcon, CheckCircleIcon, EyeIcon, TrashIcon, FolderIcon, LockClosedIcon } from '../components/icons/DummyIcons';
import { Input, Select } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { useProperties, useClients } from '../hooks/useAppData';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';

interface PurchaseSaleManagementPageProps {
    onBack: () => void;
    properties: Property[];
    onSaveProperty: (property: Property) => Promise<void>;
    currentStaff: Staff;
    setActivePage: (page: string, context?: any) => void;
}

const PurchaseSaleManagementPage: React.FC<PurchaseSaleManagementPageProps> = ({ onBack, properties, onSaveProperty, currentStaff, setActivePage }) => {
    const { archiveProperty, activeProperties } = useProperties();
    const { clients } = useClients();
    const { openModal } = useModal();
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [editSellingPrice, setEditSellingPrice] = useState('');
    const [isSaving, setIsSaving] = useState(false);

    const canArchive = useMemo(() => {
        return currentStaff.roleId === 'CEO' || currentStaff.roleId === 'Administrator';
    }, [currentStaff]);

    const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const handlePropertyChange = (id: number) => {
        setSelectedPropertyId(id);
        const prop = properties.find(p => p.id === id);
        if (prop) {
            setEditSellingPrice(String(prop.price));
        }
    };

    const handleUpdatePrice = async () => {
        const prop = properties.find(p => p.id === selectedPropertyId);
        if (!prop || !editSellingPrice) return;

        setIsSaving(true);
        try {
            await onSaveProperty({
                ...prop,
                price: parseFloat(editSellingPrice)
            });
            alert('Selling price updated successfully. This price is now authoritative across the system.');
        } catch (error) {
            alert('Failed to update price.');
        } finally {
            setIsSaving(false);
        }
    };

    const handleArchiveClick = (property: Property) => {
        if (property.status === 'ARCHIVED') {
            alert("Property already archived.");
            return;
        }

        const affectedClients = clients.filter(c => c.locationSelectedId === property.id || c.location === property.location);

        openModal(MODAL_TYPES.ARCHIVE_PROPERTY, {
            property,
            affectedCount: affectedClients.length,
            onConfirm: async () => {
                const result = await archiveProperty(property, currentStaff);
                alert(`Property archived successfully. ${result.impactedCount} client accounts marked incomplete.`);
            }
        });
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white mt-2 tracking-tight uppercase">Purchase & Sale Management</h1>
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 space-y-4">
                <Select 
                    label="Quick Management (Select Property)" 
                    value={selectedPropertyId} 
                    onChange={(e) => handlePropertyChange(Number(e.target.value))}
                >
                    <option value="">-- Choose Property --</option>
                    {activeProperties.map(p => <option key={p.id} value={p.id}>{p.location}</option>)}
                </Select>

                {selectedPropertyId && (
                    <div className="flex flex-col sm:flex-row gap-4 items-end animate-in fade-in duration-300">
                        <Input 
                            label="New Selling Price per Plot (Market Authority)"
                            type="number"
                            value={editSellingPrice}
                            onChange={(e) => setEditSellingPrice(e.target.value)}
                            placeholder="0.00"
                            className="font-black text-xl text-blue-600"
                            containerClassName="flex-grow"
                        />
                        <Button 
                            onClick={handleUpdatePrice} 
                            isLoading={isSaving}
                            icon={<CheckCircleIcon className="w-5 h-5" />}
                        >
                            Publish Authority Price
                        </Button>
                    </div>
                )}
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Active Property Listings</h2>
                    <Badge variant="info">{activeProperties.length} Active</Badge>
                </div>

                <TableContainer>
                    <table className="w-full text-sm text-left">
                        <Thead>
                            <tr>
                                <Th>Location</Th>
                                <Th>Reg. Status</Th>
                                <Th>Plots Available</Th>
                                <Th className="text-right">Market Price</Th>
                                <Th className="text-center">Actions</Th>
                            </tr>
                        </Thead>
                        <Tbody>
                            {activeProperties.length === 0 ? (
                                <Tr>
                                    <Td colSpan={5} className="text-center py-20 text-gray-400 italic">
                                        No active properties. Add properties in CEO Hub.
                                    </Td>
                                </Tr>
                            ) : (
                                activeProperties.map(prop => {
                                    const totalPlots = prop.inventory.reduce((sum, inv) => sum + inv.count, 0);
                                    const plotsSold = prop.inventory.reduce((sum, inv) => sum + inv.sold, 0);
                                    const plotsAvailable = totalPlots - plotsSold;

                                    return (
                                        <Tr key={prop.id}>
                                            <Td className="font-bold text-gray-900 dark:text-white">{prop.location}</Td>
                                            <Td><Badge variant="info">{prop.registrationStatus}</Badge></Td>
                                            <Td className="font-semibold text-gray-600 dark:text-gray-400">{plotsAvailable} Plots</Td>
                                            <Td className="font-black text-right">{formatCurrency(prop.price)}</Td>
                                            <Td>
                                                <div className="flex justify-center items-center gap-1">
                                                    <button 
                                                        onClick={() => setActivePage('Properties', prop)}
                                                        className="p-2 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-all"
                                                        title="Open Dossier"
                                                    >
                                                        <EyeIcon className="w-5 h-5" />
                                                    </button>
                                                    <button 
                                                        onClick={() => handlePropertyChange(prop.id)}
                                                        className="p-2 text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-lg transition-all"
                                                        title="Quick Edit"
                                                    >
                                                        <CheckCircleIcon className="w-5 h-5" />
                                                    </button>
                                                    <div className="group relative">
                                                        <button 
                                                            onClick={() => handleArchiveClick(prop)}
                                                            disabled={!canArchive}
                                                            className={`p-2 rounded-lg transition-all ${canArchive ? 'text-amber-600 hover:bg-amber-50 dark:hover:bg-amber-900/20' : 'text-gray-300 cursor-not-allowed opacity-50'}`}
                                                            title={canArchive ? "Archive Property" : "Insufficient permissions"}
                                                        >
                                                            <FolderIcon className="w-5 h-5" />
                                                        </button>
                                                        {!canArchive && (
                                                            <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-48 p-2 bg-gray-900 text-white text-[10px] rounded opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none text-center font-bold uppercase tracking-widest">
                                                                You don't have permission to archive properties.
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                            </Td>
                                        </Tr>
                                    );
                                })
                            )}
                        </Tbody>
                    </table>
