    const handleNext = () => {
        if (step === 2 && file) {
            processFile();
        } else {
            setStep(s => s + 1);
        }
    };

    const handleBack = () => setStep(s => s - 1);

    const handleConfirmImport = () => {
        setIsLoading(true);
        setTimeout(() => {
            onImport(parsedData);
            setStep(4);
            setIsLoading(false);
        }, 100);
    };

    const downloadSampleCSV = () => {
        const csvContent = `${sampleHeaders}\n${sampleData}`;
        // Prefix with BOM for Excel compatibility
        const universalCsvContent = "\uFEFF" + csvContent;
        const blob = new Blob([universalCsvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        if (link.download !== undefined) {
            const url = URL.createObjectURL(blob);
            link.setAttribute("href", url);
            link.setAttribute("download", "client_import_template.csv");
            link.style.visibility = 'hidden';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm" aria-modal="true" role="dialog">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">{wizardTitle}</h2>
                    <button onClick={handleClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div className="space-y-6">
                            <div>
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Step 1: Download Sample Template</h3>
                                <p className="mt-2 text-sm text-gray-600 dark:text-gray-300 leading-relaxed">
                                    To ensure your data is imported correctly, please use our standardized CSV template. It contains the exact headers required by the ERP system.
                                </p>
                            </div>

                            <div className="p-5 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm space-y-4">
                                <div className="flex items-center gap-4">
                                    <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-lg">
                                        <DocumentTextIcon className="w-8 h-8 text-green-600 dark:text-green-400" />
                                    </div>
                                    <div className="flex-grow">
                                        <p className="text-sm font-black text-gray-900 dark:text-white uppercase">client_import_template.csv</p>
                                        <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Includes 30 mandatory and optional headers with sample data.</p>
                                    </div>
                                    <button 
                                        onClick={downloadSampleCSV} 
                                        className="bg-green-600 hover:bg-green-700 text-white font-black uppercase tracking-widest text-[10px] py-2.5 px-5 rounded-lg transition-all shadow-md hover:shadow-lg active:scale-95"
                                    >
                                        Download Template
                                    </button>
                                </div>
                            </div>

                            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                                <h4 className="font-black text-[10px] uppercase tracking-widest text-blue-800 dark:text-blue-300 flex items-center gap-2">
                                    <InformationCircleIcon className="w-4 h-4" /> Header Mapping Guide:
                                </h4>
                                <div className="text-xs text-blue-700 dark:text-blue-200 mt-3 space-y-2 leading-relaxed">
                                    <p><strong className="uppercase">Identity:</strong> surname, otherNames, dateOfBirth (YYYY-MM-DD), gender</p>
                                    <p><strong className="uppercase">Contact:</strong> telephone, email, currentAddress</p>
                                    <p><strong className="uppercase">Acquisition:</strong> location, plotNumber, propertyType, paymentDate</p>
                                </div>
                            </div>
                        </div>
                   )}
                   {step === 2 && (
                       <div>
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Step 2: Upload Your Prepared File</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                Once you've populated the template, drag and drop it below or click to select.
                            </p>
                            <div className="mt-6 flex justify-center px-6 pt-10 pb-10 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-xl bg-white dark:bg-gray-800/50 hover:border-blue-400 transition-colors cursor-pointer">
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                        <label htmlFor="file-upload" className="relative cursor-pointer rounded-md font-bold text-blue-600 dark:text-blue-400 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                                            <span>Select file from computer</span>
                                            <input id="file-upload" name="file-upload" type="file" className="sr-only" onChange={handleFileChange} accept=".csv,text/csv,application/vnd.ms-excel" />
                                        </label>
                                    </div>
                                    <p className="text-[10px] text-gray-400 uppercase tracking-widest font-black">CSV file up to 5MB</p>
                                </div>
                            </div>
                            {file && (
                                <div className="mt-4 p-4 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg border border-indigo-200 dark:border-indigo-800 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <DocumentTextIcon className="w-5 h-5 text-indigo-600" />
                                        <span className="text-sm font-bold text-indigo-900 dark:text-indigo-200">{file.name}</span>
                                    </div>
                                    <Badge variant="info">Ready to process</Badge>
                                </div>
                            )}
                            {errors.length > 0 && <div className="mt-4 text-sm text-red-600 dark:text-red-400 font-bold flex items-center gap-2"><ExclamationTriangleIcon className="w-5 h-5" /> {errors[0]}</div>}
                        </div>
                   )}
                   {step === 3 && (
                        <div>
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Step 3: Verification & Integrity Check</h3>
                             <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                Review the parsed data below. We identified <span className="font-bold text-green-600 dark:text-green-400">{parsedData.length}</span> valid records for import.
                            </p>
                            {errors.length > 0 && (
                                <div className="mt-4 p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg">
                                    <h4 className="font-black text-[10px] text-yellow-800 dark:text-yellow-300 flex items-center gap-2 uppercase tracking-widest"><ExclamationTriangleIcon className="w-5 h-5" /> Validation Warnings</h4>
                                    <ul className="list-disc list-inside text-xs text-yellow-700 dark:text-yellow-200 mt-2 max-h-24 overflow-y-auto">
                                        {errors.map((err, i) => <li key={i}>{err}</li>)}
                                    </ul>
                                </div>
                            )}
                            <div className="mt-4 border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden shadow-sm max-h-80">
                                <table className="w-full text-xs text-left">
                                    <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0 z-10 border-b dark:border-gray-600">
                                        <tr>
                                            <th className="px-4 py-3 font-black uppercase text-gray-500 tracking-widest">Status</th>
                                            {Object.keys(validationResults[0]?.data || {}).slice(0, 5).map(key => <th key={key} className="px-4 py-3 font-black uppercase text-gray-500 tracking-widest whitespace-nowrap">{key}</th>)}
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-100 dark:divide-gray-700">
                                        {validationResults.slice(0, 20).map((result, index) => (
                                            <tr key={index} className={result.errors.length > 0 ? 'bg-red-50/50 dark:bg-red-900/10' : 'bg-green-50/30 dark:bg-green-900/10'}>
                                                <td className="px-4 py-3">
                                                    {result.errors.length > 0 ? (
                                                        <div className="flex items-center gap-1 text-red-600 dark:text-red-400" title={result.errors.join('\n')}>
                                                            <ExclamationTriangleIcon className="w-4 h-4 shrink-0" />
                                                            <span className="text-[10px] font-black uppercase">Fail</span>
                                                        </div>
                                                    ) : (
                                                        <div className="flex items-center gap-1 text-green-600 dark:text-green-400">
                                                            <CheckCircleIcon className="w-4 h-4 shrink-0" />
                                                            <span className="text-[10px] font-black uppercase">Valid</span>
                                                        </div>
                                                    )}
                                                </td>
                                                {Object.values(result.data).slice(0, 5).map((val: any, i) => <td key={i} className="px-4 py-3 whitespace-nowrap text-gray-700 dark:text-gray-300 font-medium">{val}</td>)}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                            {validationResults.length > 20 && <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tighter mt-3 text-center">... showing first 20 of {validationResults.length} records</p>}
                        </div>
                   )}
                   {step === 4 && (
                       <div className="text-center py-20 animate-in zoom-in duration-300">
                            <div className="w-20 h-20 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-6">
                                <CheckCircleIcon className="h-12 w-12 text-green-500" />
                            </div>
                            <h3 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Import Triggered!</h3>
                            <p className="mt-2 text-sm text-gray-500 dark:text-gray-400 max-w-sm mx-auto leading-relaxed">
                                <span className="font-black text-green-600">{parsedData.length}</span> records have been processed. You can now find them in the client directory.
                            </p>
                        </div>
                   )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>
                        {step > 1 && step < 4 && (
                            <button onClick={handleBack} className="bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-bold py-2 px-6 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-600 flex items-center gap-2 text-xs uppercase tracking-widest transition-all">
                                <ChevronLeftIcon className="w-4 h-4" /> Back
                            </button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        {step < 3 && (
                            <button onClick={handleNext} disabled={(step === 2 && !file) || isLoading} className="bg-blue-600 text-white font-black uppercase tracking-widest text-xs py-3 px-8 rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2 transition-all shadow-md hover:shadow-lg active:scale-95">
                                {isLoading ? 'Working...' : `Proceed to ${step === 1 ? 'Upload' : 'Verification'}`} <ChevronRightIcon className="w-4 h-4" />
                            </button>
                        )}
                        {step === 3 && (
                            <button onClick={handleConfirmImport} disabled={parsedData.length === 0 || isLoading} className="bg-green-600 text-white font-black uppercase tracking-widest text-xs py-3 px-8 rounded-lg hover:bg-green-700 disabled:opacity-50 transition-all shadow-md hover:shadow-lg active:scale-95">
                                {isLoading ? 'Processing...' : `Commit ${parsedData.length} Records`}
                            </button>
                        )}
                        {step === 4 && (
                             <button onClick={handleClose} className="bg-blue-600 text-white font-black uppercase tracking-widest text-xs py-3 px-10 rounded-lg hover:bg-blue-700 transition-all shadow-md active:scale-95">
                                Return to List
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CSVImportWizard;
const InformationCircleIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
        <path strokeLinecap="round" strokeLinejoin="round" d="m11.25 11.25.041-.02a.75.75 0 0 1 1.063.852l-.708 2.836a.75.75 0 0 0 1.063.853l.041-.021M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9-3.75h.008v.008H12V8.25Z" />
    </svg>
);

import React, { useState, useCallback, ChangeEvent, useMemo, useEffect } from 'react';
import { XIcon } from './icons/XIcon';
import { 
    UploadIcon, 
    DocumentTextIcon, 
    ExclamationTriangleIcon, 
    CheckCircleIcon, 
    ChevronLeftIcon, 
    ChevronRightIcon,
    MagnifyingGlassIcon,
    PencilSquareIcon,
    TrashIcon,
    ArrowPathIcon,
    ShieldCheckIcon,
    ArrowDownTrayIcon
} from './icons/DummyIcons';
import { Badge } from './ui/Badge';
import { Button } from './ui/Button';
import { Input } from './ui/Input';
import { Client, ClientAccountStatus, IncompleteReason } from '../types';

// --- TYPES FOR IMPORT ENGINE ---

type ImportStatus = 'READY' | 'INCOMPLETE' | 'ERROR' | 'AMBIGUOUS' | 'SKIPPED';
type ImportMode = 'STRICT' | 'DRAFT';

interface StagedRow {
    rowNumber: number;
    status: ImportStatus;
    data: Partial<Record<string, any>>;
    errors: string[];
    matchedClientId?: number;
    originalName?: string; // For split tracking
}

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[];
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
  clients: Client[]; // For duplicate matching
}

// --- CONSTANTS & MAPPINGS ---

const HEADER_ALIASES: Record<string, string> = {
    'phone': 'telephone',
    'land location': 'location',
    'number of plots': 'plotNumber',
    'primary contact': 'name',
    'full name': 'name',
    'full_name': 'name',
    'contact': 'telephone',
    'email address': 'email',
};

const IGNORED_HEADERS = ['ID', 'Due', 'Client Status', 'Client groups', 'Labels', 'Projects', 'Total invoiced', 'Payment Received'];

// --- UTILS ---

const normalizePhone = (val: string) => {
    if (!val) return '';
    const cleaned = val.trim().replace(/[^\d+]/g, '');
    return cleaned;
};

const normalizeEmail = (val: string) => val ? val.trim().toLowerCase() : '';

const splitFullName = (fullName: string) => {
    if (!fullName) return { surname: '', otherNames: '' };
    const tokens = fullName.trim().split(/\s+/);
    if (tokens.length === 1) return { surname: tokens[0], otherNames: '' };
    const surname = tokens.pop() || '';
    const otherNames = tokens.join(' ');
    return { surname, otherNames };
};

// --- COMPONENT ---

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ 
    isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle, clients 
}) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [importMode, setImportMode] = useState<ImportMode>('DRAFT');
    const [updateExisting, setUpdateExisting] = useState(false);
    const [allowBlankOverwrite, setAllowBlankOverwrite] = useState(false);

    const [stagedRows, setStagedRows] = useState<StagedRow[]>([]);
    const [ignoredHeaders, setIgnoredHeaders] = useState<string[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<ImportStatus | 'ALL'>('ALL');
    const [isLoading, setIsLoading] = useState(false);
    const [importResults, setImportResults] = useState<{ processed: number, created: number, updated: number, incomplete: number, skipped: number } | null>(null);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setStagedRows([]);
        setIgnoredHeaders([]);
        setImportResults(null);
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    // --- PHASE 1: PARSING & MAPPING ---

    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (char === '"') {
                if (inQuotes && text[i + 1] === '"') { cell += '"'; i++; }
                else { inQuotes = !inQuotes; }
            } else if (char === ',' && !inQuotes) {
                result.push(cell.trim());
                cell = '';
            } else { cell += char; }
        }
        result.push(cell.trim());
        return result;
    };

    const validateRow = (rowData: Record<string, any>, mode: ImportMode, updateMode: boolean): { status: ImportStatus; errors: string[]; matchedId?: number } => {
        const localErrors: string[] = [];

        // Safeguard 1: Min identifying info
        const hasIdentity = rowData.surname || rowData.otherNames || rowData.telephone || rowData.email;
        if (!hasIdentity) return { status: 'ERROR', errors: ['No identifying information found in this row.'] };

        // Safeguard 2: Duplicate Check
        let matchedId: number | undefined;
        if (rowData.telephone) {
            const match = clients.find(c => normalizePhone(c.phone) === normalizePhone(rowData.telephone));
            if (match) matchedId = match.id;
        }
        if (!matchedId && rowData.email) {
            const match = clients.find(c => normalizeEmail(c.email) === normalizeEmail(rowData.email));
            if (match) matchedId = match.id;
        }

        if (matchedId && !updateMode) {
            return { status: 'AMBIGUOUS', errors: [`Identified potential duplicate (ID: ${matchedId}). Enable "Update Existing" to merge.`], matchedId };
        }

        // Safeguard 3: Required Fields for STRICT mode
        const missingKeys = requiredHeaders.filter(h => !rowData[h] || rowData[h].trim() === '');
        if (missingKeys.length > 0) {
            if (mode === 'STRICT') {
                return { status: 'ERROR', errors: [`Missing required fields: ${missingKeys.join(', ')}`], matchedId };
            } else {
                return { status: 'INCOMPLETE', errors: [`Row will be marked INCOMPLETE. Missing: ${missingKeys.join(', ')}`], matchedId };
            }
        }

        return { status: 'READY', errors: [], matchedId };
    };

    const processFile = useCallback(() => {
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 2) throw new Error('File is empty.');

                const headerLine = lines[0].replace(/^\uFEFF/, '');
                const rawHeaders = parseCSVLine(headerLine).map(h => h.replace(/^"|"$/g, '').trim());

                const mappedHeaders: Record<number, string> = {};
                const localIgnored: string[] = [];

                rawHeaders.forEach((raw, idx) => {
                    const clean = raw.toLowerCase();
                    if (requiredHeaders.includes(raw)) mappedHeaders[idx] = raw;
                    else if (HEADER_ALIASES[clean]) mappedHeaders[idx] = HEADER_ALIASES[clean];
                    else localIgnored.push(raw);
                });

                const newStaged: StagedRow[] = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);
                    const rowData: Record<string, any> = {};
                    let rawName = '';

                    Object.entries(mappedHeaders).forEach(([idx, key]) => {
                        const val = values[parseInt(idx)]?.replace(/^"|"$/g, '') || '';
                        if (key === 'name') rawName = val;
                        else rowData[key] = val;
                    });

                    // Special Name Splitting
                    if (rawName && (!rowData.surname || !rowData.otherNames)) {
                        const { surname, otherNames } = splitFullName(rawName);
                        if (!rowData.surname) rowData.surname = surname;
                        if (!rowData.otherNames) rowData.otherNames = otherNames;
                    }

                    // Normalization
                    if (rowData.telephone) rowData.telephone = normalizePhone(rowData.telephone);
                    if (rowData.email) rowData.email = normalizeEmail(rowData.email);

                    const validation = validateRow(rowData, importMode, updateExisting);
                    newStaged.push({
                        rowNumber: i,
                        status: validation.status,
                        data: rowData,
                        errors: validation.errors,
                        matchedClientId: validation.matchedId
                    });
                }

                setIgnoredHeaders(localIgnored);
                setStagedRows(newStaged);
                setStep(2);
            } catch (err: any) {
                alert(err.message);
            } finally { setIsLoading(false); }
        };
        reader.readAsText(file);
    }, [file, importMode, updateExisting, requiredHeaders, clients]);

    // --- PHASE 2: EDITING ---

    const updateStagedRow = (rowIdx: number, field: string, value: any) => {
        setStagedRows(prev => {
            const next = [...prev];
            const row = { ...next[rowIdx] };
            row.data = { ...row.data, [field]: value };
            const validation = validateRow(row.data, importMode, updateExisting);
            row.status = validation.status;
            row.errors = validation.errors;
            row.matchedClientId = validation.matchedId;
            next[rowIdx] = row;
            return next;
        });
    };

    const handleConfirmImport = async () => {
        setIsLoading(true);
        const rowsToProcess = stagedRows.filter(r => r.status !== 'SKIPPED' && r.status !== 'ERROR');

        let created = 0;
        let updated = 0;
        let incomplete = 0;

        const resultsData = rowsToProcess.map(row => {
            const isUpdate = !!row.matchedClientId;
            if (isUpdate) updated++; else created++;
            if (row.status === 'INCOMPLETE') incomplete++;

            // Data Transformation for database
            const finalData: any = { ...row.data };
            if (row.status === 'INCOMPLETE') {
                finalData.accountStatus = 'INCOMPLETE';
                finalData.incompleteReason = 'IMPORT_MISSING_FIELDS';
            } else {
                finalData.accountStatus = 'ACTIVE';
            }

            return finalData;
        });

        // Trigger commit via parent hook
        await onImport(resultsData);

        setImportResults({
            processed: stagedRows.length,
            created,
            updated,
            incomplete,
            skipped: stagedRows.length - rowsToProcess.length
        });
        setStep(3);
        setIsLoading(false);
    };

    const filteredStagedRows = useMemo(() => {
        return stagedRows.filter(r => {
            const matchesStatus = statusFilter === 'ALL' || r.status === statusFilter;
            const matchesSearch = !searchTerm || JSON.stringify(r.data).toLowerCase().includes(searchTerm.toLowerCase());
            return matchesStatus && matchesSearch;
        });
    }, [stagedRows, statusFilter, searchTerm]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-50 flex justify-center items-center p-4 backdrop-blur-md" aria-modal="true">
            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-6xl max-h-[90vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">

                {/* Header */}
                <div className="flex justify-between items-center p-5 border-b border-gray-100 dark:border-gray-700">
                    <div>
                        <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">{wizardTitle}</h2>
                        <div className="flex items-center gap-4 mt-1 text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                            <span className={step >= 1 ? 'text-blue-600' : ''}>1. Source & Configuration</span>
                            <ChevronRightIcon className="w-3 h-3" />
                            <span className={step >= 2 ? 'text-blue-600' : ''}>2. Preview & Validation</span>
                            <ChevronRightIcon className="w-3 h-3" />
                            <span className={step === 3 ? 'text-blue-600' : ''}>3. Summary Report</span>
                        </div>
                    </div>
                    <button onClick={handleClose} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full"><XMarkIcon className="w-6 h-6 text-gray-400" /></button>
                </div>

                <div className="flex-grow overflow-hidden flex flex-col bg-gray-50/50 dark:bg-gray-950/20">

                    {/* STEP 1: UPLOAD & CONFIG */}
