        setScrollOffset(Math.min(offset, MAX_SCROLL));
    };

    const headerOpacity = Math.max(0, 1 - scrollOffset / (MAX_SCROLL * 0.8));
    const headerHeight = Math.max(0, 48 - (scrollOffset / MAX_SCROLL) * 48);
    const controlsTranslate = (scrollOffset / MAX_SCROLL) * -52;

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const handleDeleteClick = useCallback((clientId: number) => {
        const client = clients.find(c => c.id === clientId);
        if (client) setClientToDelete(client);
    }, [clients]);

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);
            const timeoutId = setTimeout(() => setDeletedClientInfo(null), 3000);
            setDeletedClientInfo({ name: clientToDelete.name, timeoutId });
            setClientToDelete(null);
        }
    };

    const createClientObject = (formData: FormData, id: number, existingClient?: Client | null): Client => {
        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();
        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;
        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }
        const isComplete = isClientDataComplete(formData);

        const clientType = (formData as any).clientType || 'Individual';

        const baseClient = existingClient || {
            id: id, 
            clientType,
            status: 'Active Client' as const, 
            accountStatus: 'ACTIVE' as const,
            allocationStatus: 'RESERVED_NOT_ALLOCATED' as AllocationStatus, 
            paidPercent: 0, 
            allocationQualified: false, 
            stage: milestones[0]?.acronym || 'N/A',
            payment: { total: baseTotal, paid: 0, balance: baseTotal, dueDate: 'N/A', planType: 'N/A', promoDetails: promoDetails, paymentHistory: [], installments: [] },
            interactions: [], documentation: { status: 'Pending' },
            officeUse: { commission: { type: 'Percentage', amount: 0, status: 'Pending' } }
        };
        return {
            ...baseClient, id, 
            clientType, 
            name: fullName, surname: formData.surname, otherNames: formData.otherNames, initials,
            regDate: formData.paymentDate, email: formData.email, phone: formData.telephone, dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'], location: formData.location, plot: formData.plotNumber, photo: formData.photo,
            propertyType: formData.propertyType, plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: { placeOfWork: formData.placeOfWork, profession: formData.profession, position: formData.position },
            witness: { name: formData.witnessName, address: formData.witnessAddress, phone: formData.witnessPhone },
            nextOfKin: { name: formData.kinName, phone: formData.kinPhone, relationship: formData.kinRelationship, email: formData.kinEmail, address: formData.kinAddress },
            indenture: { name: formData.indentureName, address: formData.indentureAddress },
            officeUse: { ...baseClient.officeUse, salesRep: formData.salesRep, salesManager: formData.salesManager, accountsHead: formData.accountsHead, clerk: formData.clerk },
            isComplete, filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClientAndRedirect = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            const isNewClient = !editingClient;
            const newId = editingClient ? editingClient.id : (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

            if (!newId) {
                alert("Error: Client ID could not be generated. Please retry.");
                return;
            }

            let photoUrl = formData.photo;
            if (files?.photo) photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId, editingClient);

            const savedClient = await onSaveClient(newClient);

            if (!savedClient) {
                alert("Error: Client data not saved correctly.");
                return;
            }

            if (isNewClient && currentStaff?.roleId === 'Front Desk Executive') {
                const chiefAccountants = staff.filter(s => s.roleId === 'Chief Accountant');

                if (chiefAccountants.length > 0) {
                    await sendMail({
                        senderId: currentStaff.id,
                        senderName: currentStaff.fullName,
                        recipientIds: chiefAccountants.map(s => s.id),
                        groupIds: [], 
                        subject: 'ACTION REQUIRED: New Client Ledger Initialization',
                        body: `A new client record has been created and requires financial setup.\n\nClient: ${savedClient.name}\nReference: ${savedClient.initials}-${savedClient.id}\nProperty: ${savedClient.location}\n\nPlease proceed to Account Management to initialize the financial commitment and payment plan for this account.\n\nDate Registered: ${new Date().toLocaleString()}`,
                        attachments: [],
                        timestamp: new Date().toISOString(),
                        readBy: [currentStaff.id],
                        isDraft: false,
                        isDeleted: false,
                        targetPage: 'Account Management',
                        targetContext: savedClient
                    });
                } else {
                    addActivityLog('Update', `System Warning: No Chief Accountant found to receive onboarding notification for client ${savedClient.name}.`);
                }
            }

            setClientFormOpen(false);
            addActivityLog(editingClient ? 'Update' : 'Create', `Processed client: ${savedClient.name}`);
            onClientSelect(savedClient);

        } catch (error) { 
            console.error("Save failed:", error);
            alert("Failed to save client."); 
        }
    };

    const handleBulkImport = async (data: any[]) => {
        try {
            await importClients(data);
            addActivityLog('Import', `Completed bulk import of ${data.length} records.`);
        } catch (error) {
            console.error("Bulk Import Commit Failed:", error);
            alert("Database commit failed for the batch.");
        }
    };

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];

    const sampleCsvData = `"Mensah","Kwame Kofi","1985-06-15","No. 12 Cantonments, Accra",+233244123456,kwame.mensah@example.com,Male,"GCB Bank PLC",Banker,Manager,"Ama Mensah","No. 12 Cantonments, Accra",+233244123457,Spouse,ama@example.com,"John Smith","Osu, Accra",+233201112222,2024-01-10,"Bank Transfer","East Legon Hills","PHASE1-10, PHASE1-11",Residential,2025,"Kwame Kofi Mensah","No. 12 Cantonments, Accra","Samuel Sales","Head of Sales","Chief Accountant","Front Desk Clerk"
"Asante","Abena Serwaa","1992-02-28","Plot 4, Airport Residential Area",+233555987654,abena.asante@example.com,Female,"Tullow Oil",Engineer,Lead,"Kofi Asante","Plot 4, Airport Residential Area",+233555987655,Brother,kofi@example.com,"Mary Appiah","Legon, Accra",+233501234567,2024-02-15,MoMo,"Appolonia City","P1-05",Residential,2026,"Abena Serwaa Asante","Plot 4, Airport Residential Area","Samuel Sales","Head of Sales","Chief Accountant","Front Desk Clerk"`;

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            <div className="sticky top-0 z-30 bg-gray-100 dark:bg-gray-950 flex-shrink-0 border-b border-gray-200 dark:border-gray-800 pb-1">
                <div className="transition-all duration-300 ease-out"
                     style={{ transform: `translateY(${controlsTranslate}px)` }}>

                    <ClientListHeader 
                        clientCount={clients.length} 
                        hasNextPage={hasNextPage} 
                        onImportClick={() => setImportWizardOpen(true)}
                        onNewClientClick={() => { setEditingClient(null); setClientFormOpen(true); }}
                        headerOpacity={headerOpacity}
                        headerHeight={headerHeight}
                    />

                    <ClientFilters 
                        searchTerm={searchTerm} 
                        onSearchChange={setSearchTerm} 
                        isLoading={isLoading} 
                        properties={properties} 
                    />

                    <ClientTableHead />
                </div>
            </div>

            <ClientsList 
                clients={clients}
                onViewDetails={onClientSelect}
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }}
                onDelete={handleDeleteClick}
                milestones={milestones}
                expandedIds={expandedIds}
                toggleExpand={toggleExpand}
                onScroll={handleScroll}
                listRef={listRef}
            />

            {hasNextPage && !debouncedSearchTerm && (
                <div className="py-3 text-center border-t border-gray-200 dark:border-gray-800 flex-shrink-0">
                    <button 
                        onClick={() => fetchNextPage()} 
                        disabled={isFetchingNextPage}
                        className="text-blue-600 dark:text-blue-400 text-xs font-black uppercase tracking-widest hover:underline disabled:opacity-50"
                    >
                        {isFetchingNextPage ? 'Loading...' : 'Load More Results'}
                    </button>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={() => { setClientFormOpen(false); setEditingClient(null); }}
                onSave={handleSaveClientAndRedirect}
                onSaveAndPay={handleSaveClientAndRedirect}
                properties={properties}
                editingClient={editingClient}
                clients={clients}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={handleBulkImport}
                requiredHeaders={requiredCsvHeaders}
                sampleHeaders={requiredCsvHeaders.join(',')}
                sampleData={sampleCsvData}
                wizardTitle="Import Client Data"
                clients={clients}
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />
        </div>
    );
};

export default ClientsPage;

import React, { useState, useCallback, ChangeEvent, useMemo, useEffect } from 'react';
import { XIcon } from './icons/XIcon';
import { 
    UploadIcon, 
    DocumentTextIcon, 
    ExclamationTriangleIcon, 
    CheckCircleIcon, 
    ChevronLeftIcon, 
    ChevronRightIcon,
    MagnifyingGlassIcon,
    PencilSquareIcon,
    TrashIcon,
    ArrowPathIcon,
    ShieldCheckIcon,
    ArrowDownTrayIcon,
    // FIX: Imported missing XMarkIcon from DummyIcons
    XMarkIcon
} from './icons/DummyIcons';
import { Badge } from './ui/Badge';
import { Button } from './ui/Button';
import { Input } from './ui/Input';
import { Client, ClientAccountStatus, IncompleteReason } from '../types';

// --- TYPES FOR IMPORT ENGINE ---

type ImportStatus = 'READY' | 'INCOMPLETE' | 'ERROR' | 'AMBIGUOUS' | 'SKIPPED';
type ImportMode = 'STRICT' | 'DRAFT';

interface StagedRow {
    rowNumber: number;
    status: ImportStatus;
    data: Partial<Record<string, any>>;
    errors: string[];
    matchedClientId?: number;
    originalName?: string; // For split tracking
}

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[];
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
  clients: Client[]; // For duplicate matching
}

// --- CONSTANTS & MAPPINGS ---

const HEADER_ALIASES: Record<string, string> = {
    'phone': 'telephone',
    'land location': 'location',
    'number of plots': 'plotNumber',
    'primary contact': 'name',
    'full name': 'name',
    'full_name': 'name',
    'contact': 'telephone',
    'email address': 'email',
};

const IGNORED_HEADERS = ['ID', 'Due', 'Client Status', 'Client groups', 'Labels', 'Projects', 'Total invoiced', 'Payment Received'];

// --- UTILS ---

const normalizePhone = (val: string) => {
    if (!val) return '';
    const cleaned = val.trim().replace(/[^\d+]/g, '');
    return cleaned;
};

const normalizeEmail = (val: string) => val ? val.trim().toLowerCase() : '';

const splitFullName = (fullName: string) => {
    if (!fullName) return { surname: '', otherNames: '' };
    const tokens = fullName.trim().split(/\s+/);
    if (tokens.length === 1) return { surname: tokens[0], otherNames: '' };
    const surname = tokens.pop() || '';
    const otherNames = tokens.join(' ');
    return { surname, otherNames };
};

// --- COMPONENT ---

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ 
    isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle, clients 
}) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [importMode, setImportMode] = useState<ImportMode>('DRAFT');
    const [updateExisting, setUpdateExisting] = useState(false);
    const [allowBlankOverwrite, setAllowBlankOverwrite] = useState(false);

    const [stagedRows, setStagedRows] = useState<StagedRow[]>([]);
    const [ignoredHeaders, setIgnoredHeaders] = useState<string[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<ImportStatus | 'ALL'>('ALL');
    const [isLoading, setIsLoading] = useState(false);
    const [importResults, setImportResults] = useState<{ processed: number, created: number, updated: number, incomplete: number, skipped: number } | null>(null);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setStagedRows([]);
        setIgnoredHeaders([]);
        setImportResults(null);
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    // --- PHASE 1: PARSING & MAPPING ---

    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (char === '"') {
                if (inQuotes && text[i + 1] === '"') { cell += '"'; i++; }
                else { inQuotes = !inQuotes; }
            } else if (char === ',' && !inQuotes) {
                result.push(cell.trim());
                cell = '';
            } else { cell += char; }
        }
        result.push(cell.trim());
        return result;
    };

    const validateRow = (rowData: Record<string, any>, mode: ImportMode, updateMode: boolean): { status: ImportStatus; errors: string[]; matchedId?: number } => {
        const localErrors: string[] = [];

        // Safeguard 1: Min identifying info
        const hasIdentity = rowData.surname || rowData.otherNames || rowData.telephone || rowData.email;
        if (!hasIdentity) return { status: 'ERROR', errors: ['No identifying information found in this row.'] };

        // Safeguard 2: Duplicate Check
        let matchedId: number | undefined;
        if (rowData.telephone) {
            const match = clients.find(c => normalizePhone(c.phone) === normalizePhone(rowData.telephone));
            if (match) matchedId = match.id;
        }
        if (!matchedId && rowData.email) {
            const match = clients.find(c => normalizeEmail(c.email) === normalizeEmail(rowData.email));
            if (match) matchedId = match.id;
        }

        if (matchedId && !updateMode) {
            return { status: 'AMBIGUOUS', errors: [`Identified potential duplicate (ID: ${matchedId}). Enable "Update Existing" to merge.`], matchedId };
        }

        // Safeguard 3: Required Fields for STRICT mode
        const missingKeys = requiredHeaders.filter(h => !rowData[h] || rowData[h].trim() === '');
        if (missingKeys.length > 0) {
            if (mode === 'STRICT') {
                return { status: 'ERROR', errors: [`Missing required fields: ${missingKeys.join(', ')}`], matchedId };
            } else {
                return { status: 'INCOMPLETE', errors: [`Row will be marked INCOMPLETE. Missing: ${missingKeys.join(', ')}`], matchedId };
            }
        }

        return { status: 'READY', errors: [], matchedId };
    };

    const processFile = useCallback(() => {
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 2) throw new Error('File is empty.');

                const headerLine = lines[0].replace(/^\uFEFF/, '');
                const rawHeaders = parseCSVLine(headerLine).map(h => h.replace(/^"|"$/g, '').trim());

                const mappedHeaders: Record<number, string> = {};
                const localIgnored: string[] = [];

                rawHeaders.forEach((raw, idx) => {
                    const clean = raw.toLowerCase();
                    if (requiredHeaders.includes(raw)) mappedHeaders[idx] = raw;
                    else if (HEADER_ALIASES[clean]) mappedHeaders[idx] = HEADER_ALIASES[clean];
                    else localIgnored.push(raw);
                });

                const newStaged: StagedRow[] = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);
                    const rowData: Record<string, any> = {};
                    let rawName = '';

                    Object.entries(mappedHeaders).forEach(([idx, key]) => {
                        const val = values[parseInt(idx)]?.replace(/^"|"$/g, '') || '';
                        if (key === 'name') rawName = val;
                        else rowData[key] = val;
                    });

                    // Special Name Splitting
                    if (rawName && (!rowData.surname || !rowData.otherNames)) {
                        const { surname, otherNames } = splitFullName(rawName);
                        if (!rowData.surname) rowData.surname = surname;
                        if (!rowData.otherNames) rowData.otherNames = otherNames;
                    }

                    // Normalization
                    if (rowData.telephone) rowData.telephone = normalizePhone(rowData.telephone);
                    if (rowData.email) rowData.email = normalizeEmail(rowData.email);

                    const validation = validateRow(rowData, importMode, updateExisting);
                    newStaged.push({
                        rowNumber: i,
                        status: validation.status,
                        data: rowData,
                        errors: validation.errors,
                        matchedClientId: validation.matchedId
                    });
                }

                setIgnoredHeaders(localIgnored);
                setStagedRows(newStaged);
                setStep(2);
            } catch (err: any) {
                alert(err.message);
            } finally { setIsLoading(false); }
        };
        reader.readAsText(file);
    }, [file, importMode, updateExisting, requiredHeaders, clients]);

    // --- PHASE 2: EDITING ---

    const updateStagedRow = (rowIdx: number, field: string, value: any) => {
        setStagedRows(prev => {
            const next = [...prev];
            const row = { ...next[rowIdx] };
            row.data = { ...row.data, [field]: value };
            const validation = validateRow(row.data, importMode, updateExisting);
            row.status = validation.status;
            row.errors = validation.errors;
            row.matchedClientId = validation.matchedId;
            next[rowIdx] = row;
            return next;
        });
    };

    const handleConfirmImport = async () => {
        setIsLoading(true);
        const rowsToProcess = stagedRows.filter(r => r.status !== 'SKIPPED' && r.status !== 'ERROR');

        let created = 0;
        let updated = 0;
        let incomplete = 0;

        const resultsData = rowsToProcess.map(row => {
            const isUpdate = !!row.matchedClientId;
            if (isUpdate) updated++; else created++;
            if (row.status === 'INCOMPLETE') incomplete++;

            // Data Transformation for database
            const finalData: any = { ...row.data };
            if (row.status === 'INCOMPLETE') {
                finalData.accountStatus = 'INCOMPLETE';
                finalData.incompleteReason = 'IMPORT_MISSING_FIELDS';
            } else {
                finalData.accountStatus = 'ACTIVE';
            }

            return finalData;
        });

        // Trigger commit via parent hook
        await onImport(resultsData);

        setImportResults({
            processed: stagedRows.length,
            created,
            updated,
            incomplete,
            skipped: stagedRows.length - rowsToProcess.length
        });
        setStep(3);
        setIsLoading(false);
    };

    const filteredStagedRows = useMemo(() => {
        return stagedRows.filter(r => {
            const matchesStatus = statusFilter === 'ALL' || r.status === statusFilter;
            const matchesSearch = !searchTerm || JSON.stringify(r.data).toLowerCase().includes(searchTerm.toLowerCase());
            return matchesStatus && matchesSearch;
        });
    }, [stagedRows, statusFilter, searchTerm]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-50 flex justify-center items-center p-4 backdrop-blur-md" aria-modal="true">
            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-6xl max-h-[90vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">

                {/* Header */}
                <div className="flex justify-between items-center p-5 border-b border-gray-100 dark:border-gray-700">
                    <div>
                        <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">{wizardTitle}</h2>
                        <div className="flex items-center gap-4 mt-1 text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                            <span className={step >= 1 ? 'text-blue-600' : ''}>1. Source & Configuration</span>
                            <ChevronRightIcon className="w-3 h-3" />
                            <span className={step >= 2 ? 'text-blue-600' : ''}>2. Preview & Validation</span>
                            <ChevronRightIcon className="w-3 h-3" />
                            <span className={step === 3 ? 'text-blue-600' : ''}>3. Summary Report</span>
                        </div>
                    </div>
                    <button onClick={handleClose} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full"><XMarkIcon className="w-6 h-6 text-gray-400" /></button>
                </div>

                <div className="flex-grow overflow-hidden flex flex-col bg-gray-50/50 dark:bg-gray-950/20">

                    {/* STEP 1: UPLOAD & CONFIG */}
                    {step === 1 && (
                        <div className="p-8 max-w-2xl mx-auto w-full space-y-8 animate-in fade-in duration-300">
                            <div className="space-y-4">
                                <h3 className="text-lg font-black text-gray-800 dark:text-white uppercase tracking-tighter flex items-center gap-2">
                                    <ShieldCheckIcon className="w-6 h-6 text-blue-600" /> Ingestion Policy
                                </h3>
                                <div className="grid grid-cols-2 gap-4">
                                    <button 
                                        onClick={() => setImportMode('STRICT')}
                                        className={`p-4 rounded-xl border-2 text-left transition-all ${importMode === 'STRICT' ? 'border-blue-600 bg-blue-50/50 dark:bg-blue-900/20' : 'border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900'}`}
                                    >
                                        <p className="font-bold text-sm text-gray-900 dark:text-white">STRICT MODE</p>
                                        <p className="text-[10px] text-gray-500 mt-1 uppercase">Rejects rows with missing mandatory fields.</p>
                                    </button>
                                    <button 
                                        onClick={() => setImportMode('DRAFT')}
                                        className={`p-4 rounded-xl border-2 text-left transition-all ${importMode === 'DRAFT' ? 'border-blue-600 bg-blue-50/50 dark:bg-blue-900/20' : 'border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900'}`}
                                    >
                                        <p className="font-bold text-sm text-gray-900 dark:text-white">DRAFT IMPORT</p>
                                        <p className="text-[10px] text-gray-500 mt-1 uppercase">Imports incomplete records for later manual update.</p>
                                    </button>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <h3 className="text-lg font-black text-gray-800 dark:text-white uppercase tracking-tighter">Collision Handling</h3>
                                <div className="space-y-3">
                                    <label className="flex items-center gap-3 p-4 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl cursor-pointer">
                                        <input type="checkbox" checked={updateExisting} onChange={e => setUpdateExisting(e.target.checked)} className="w-5 h-5 rounded border-gray-300 text-blue-600" />
                                        <div>
                                            <p className="text-sm font-bold text-gray-900 dark:text-white">Update existing clients if match found</p>
                                            <p className="text-[10px] text-gray-400 uppercase font-bold mt-0.5">Matching priority: Phone > Email</p>
                                        </div>
                                    </label>
                                    {updateExisting && (
