import { useQuery, useMutation, useQueryClient, useInfiniteQuery } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { auth } from '../../services/firebase';
import { Client, MilestoneRecord, Property } from '../../types';

// --- Clients ---
export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const {
        data,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
        isLoading
    } = useInfiniteQuery({
        queryKey: ['clients', searchTerm],
        queryFn: ({ pageParam }) => 
            searchTerm 
                ? dbService.searchClients(searchTerm).then(data => ({ data, lastDoc: null }))
                : dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc,
        enabled: isAuthenticated,
    });

    const clients = data?.pages.flatMap(page => page.data) || [];

    const saveClientMutation = useMutation({
        mutationFn: async (client: Client) => {
            const oldClient = clients.find(c => c.id === client.id);
            const isNew = !oldClient;

            const properties: Property[] = queryClient.getQueryData(['properties']) || [];

            // --- DETERMINISTIC FINANCE ENGINE ---
            const totalPaid = (client.payment.paymentHistory || [])
                .filter(t => t.status === 'Success' && (t.type === 'Land' || !t.type))
                .reduce((sum, t) => sum + t.amount, 0);

            client.payment.paid = totalPaid;

            let effectiveTotal = client.payment.total > 0 ? client.payment.total : 0;

            if (effectiveTotal === 0 && client.location) {
                const catalogMatch = properties.find(p => p.location === client.location);
                if (catalogMatch) {
                    effectiveTotal = catalogMatch.price;
                }
            }

            if (effectiveTotal > 0) {
                const percent = (totalPaid / effectiveTotal) * 100;
                client.paidPercent = percent;

                const isNowQualified = percent >= 70;
                const wasQualified = oldClient?.allocationQualified || false;

                client.allocationQualified = isNowQualified;
            } else {
                client.paidPercent = null;
                client.allocationQualified = false;
            }

            const result = await dbService.persistClient(client);

            if (isNew) {
                await dbService.persistMilestone({
                    clientId: client.id,
                    milestoneCode: 'SFR',
                    dateCompleted: new Date().toISOString().split('T')[0],
                    notes: 'Initial registration received.'
                });
            }

            return result;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    // Support for bulk import commit
    const importClientsMutation = useMutation({
        mutationFn: async (importArray: any[]) => {
            const results = [];
            for (const data of importArray) {
                // Generate basic deterministic client object
                const id = data.id || Date.now() + Math.floor(Math.random() * 1000);
                const name = `${data.surname} ${data.otherNames}`;
                const initials = (data.surname[0] || '') + (data.otherNames[0] || '');

                // FIX: Added required 'clientType' property
                const client: Client = {
                    id,
                    clientType: data.clientType || 'Individual',
                    name,
                    surname: data.surname,
                    otherNames: data.otherNames,
                    initials: initials.toUpperCase(),
                    regDate: data.paymentDate || new Date().toISOString().split('T')[0],
                    email: data.email || '',
                    phone: data.telephone || '',
                    location: data.location || 'N/A',
                    plot: data.plotNumber || 'N/A',
                    status: 'Active Client',
                    accountStatus: data.accountStatus || 'ACTIVE',
                    incompleteReason: data.incompleteReason || null,
                    paidPercent: 0,
                    allocationQualified: false,
                    stage: 'SFR',
                    payment: {
                        total: 0, paid: 0, balance: 0, dueDate: 'N/A', planType: 'Outright',
                        paymentHistory: [], installments: []
                    },
                    interactions: [{ id: Date.now(), type: 'Note', date: new Date().toISOString(), agent: 'System (Importer)', notes: 'Imported via spreadsheet batch.' }],
                    witness: { name: data.witnessName || '', address: data.witnessAddress || '', phone: data.witnessPhone || '' },
                    nextOfKin: { name: data.kinName || '', phone: data.kinPhone || '', relationship: data.kinRelationship || '' },
                    indenture: { name: data.indentureName || data.name, address: data.indentureAddress || '' },
                    officeUse: { salesRep: data.salesRep || '', salesManager: data.salesManager || '', accountsHead: data.accountsHead || '', clerk: data.clerk || '', commission: { type: 'Fixed', amount: 0, status: 'Pending' } },
                    documentation: { status: 'Pending' },
                    isComplete: data.accountStatus !== 'INCOMPLETE',
                    filledFormPdf: null
                };

                await dbService.persistClient(client);
                results.push(client);
            }
            return results;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return {
        clients,
        isLoading,
        hasNextPage,
        fetchNextPage,
        isFetchingNextPage,
        saveClient: (client: Client) => saveClientMutation.mutateAsync(client),
        deleteClient: (id: number) => deleteClientMutation.mutateAsync(id),
        importClients: (data: any[]) => importClientsMutation.mutateAsync(data)
    };
};

// --- Milestones ---
export const useMilestones = (clientId?: number) => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: milestones = [], isLoading } = useQuery({
        queryKey: ['milestones', clientId],
        queryFn: () => clientId ? dbService.fetchMilestonesForClient(clientId) : dbService.fetchMilestones(),
        enabled: isAuthenticated,
    });

    const saveMilestoneMutation = useMutation({
        mutationFn: dbService.persistMilestone,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['milestones'] });
        }
    });

    return { 
        milestones, 
        isLoading, 
        saveMilestone: saveMilestoneMutation.mutateAsync 
    };
};

import React, { useState, useCallback, ChangeEvent } from 'react';
import { XIcon } from './icons/XIcon';
import { UploadIcon, DocumentTextIcon, ExclamationTriangleIcon, CheckCircleIcon, ChevronLeftIcon, ChevronRightIcon, InformationCircleIcon } from './icons/DummyIcons';
import { Badge } from './ui/Badge';

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[];
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
}

const ALIAS_MAP: Record<string, string> = {
    'phone': 'telephone',
    'land location': 'location',
    'number of plots': 'plotNumber',
    'primary contact': 'name_composite',
    'name': 'name_composite',
    'full name': 'name_composite',
    'contact': 'telephone',
    'email address': 'email'
};

const IGNORED_HEADERS = ['id', 'client groups', 'labels', 'projects', 'total invoiced', 'payment received', 'due', 'client status'];

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [validationResults, setValidationResults] = useState<{ data: any; errors: string[]; status: 'valid' | 'incomplete' | 'skip' }[]>([]);
    const [summary, setSummary] = useState({ processed: 0, imported: 0, skipped: 0, incompleteCount: 0 });
    const [isLoading, setIsLoading] = useState(false);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setParsedData([]);
        setValidationResults([]);
        setSummary({ processed: 0, imported: 0, skipped: 0, incompleteCount: 0 });
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    const normalizePhone = (val: string) => val ? val.trim().replace(/[^\d+]/g, '') : '';
    const normalizeEmail = (val: string) => val ? val.trim().toLowerCase() : '';

    const splitCompositeName = (name: string) => {
        const parts = (name || '').trim().split(/\s+/);
        if (parts.length === 0) return { surname: '', otherNames: '' };
        if (parts.length === 1) return { surname: parts[0], otherNames: '' };
        const surname = parts.pop() || '';
        const otherNames = parts.join(' ');
        return { surname, otherNames };
    };

    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (char === '"') {
                if (inQuotes && text[i + 1] === '"') { cell += '"'; i++; }
                else { inQuotes = !inQuotes; }
            } else if (char === ',' && !inQuotes) {
                result.push(cell.trim());
                cell = '';
            } else { cell += char; }
        }
        result.push(cell.trim());
        return result;
    };

    const processFile = useCallback(() => {
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 2) {
                    alert('CSV file must have a header row and data.');
                    setIsLoading(false);
                    return;
                }

                const rawHeaders = parseCSVLine(lines[0].replace(/^\uFEFF/, '')).map(h => h.replace(/^"|"$/g, '').trim());
                const headerMapping: Record<number, string> = {};

                rawHeaders.forEach((h, idx) => {
                    const lowerH = h.toLowerCase();
                    if (requiredHeaders.includes(h)) {
                        headerMapping[idx] = h;
                    } else if (ALIAS_MAP[lowerH]) {
                        headerMapping[idx] = ALIAS_MAP[lowerH];
                    }
                });

                const results: any[] = [];
                let imported = 0;
                let skipped = 0;
                let incompleteCount = 0;

                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);
                    if (values.length <= 1 && values[0] === '') continue;

                    let rowData: any = {};
                    let compositeName = '';

                    Object.entries(headerMapping).forEach(([idx, appField]) => {
                        const val = (values[parseInt(idx)] || '').replace(/^"|"$/g, '').trim();
                        if (appField === 'name_composite') compositeName = val;
                        else if (appField === 'telephone') rowData.telephone = normalizePhone(val);
                        else if (appField === 'email') rowData.email = normalizeEmail(val);
                        else rowData[appField] = val;
                    });

                    // Name splitting logic
                    if (compositeName) {
                        const { surname, otherNames } = splitCompositeName(compositeName);
                        if (!rowData.surname) rowData.surname = surname;
                        if (!rowData.otherNames) rowData.otherNames = otherNames;
                    }

                    // Safety Skip Condition
                    const hasIdentity = rowData.surname || rowData.otherNames || rowData.telephone || rowData.email;
                    if (!hasIdentity) {
                        skipped++;
                        results.push({ data: rowData, errors: ['Row skipped: no identifying information.'], status: 'skip' });
                        continue;
                    }

                    // Incomplete Check
                    const isMissingKeyData = !rowData.surname || !rowData.telephone || !rowData.location;
                    if (isMissingKeyData) {
                        incompleteCount++;
                        rowData.accountStatus = 'INCOMPLETE';
                        rowData.incompleteReason = 'IMPORTED_WITH_MISSING_DATA';
                        rowData.isComplete = false;
                        results.push({ data: rowData, errors: ['Marked INCOMPLETE: missing surname, phone, or location.'], status: 'incomplete' });
                    } else {
                        rowData.accountStatus = 'ACTIVE';
                        rowData.isComplete = true;
                        results.push({ data: rowData, errors: [], status: 'valid' });
                    }
                    imported++;
                }

                setValidationResults(results);
                setParsedData(results.filter(r => r.status !== 'skip').map(r => r.data));
                setSummary({ processed: lines.length - 1, imported, skipped, incompleteCount });
                setStep(3);
            } catch (error) {
                console.error(error);
                alert('Parsing failed. Check CSV formatting.');
            } finally {
                setIsLoading(false);
            }
        };
        reader.readAsText(file);
    }, [file, requiredHeaders]);

    const handleConfirmImport = () => {
        setIsLoading(true);
        setTimeout(() => {
            onImport(parsedData);
            setStep(4);
            setIsLoading(false);
        }, 100);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm" aria-modal="true" role="dialog">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">
