                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div className="space-y-6">
                            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border-l-4 border-blue-500 rounded flex gap-4">
                                <InformationCircleIcon className="w-6 h-6 text-blue-600 shrink-0" />
                                <div className="text-sm text-blue-800 dark:text-blue-200">
                                    <p className="font-bold">Flexible Importer Active</p>
