                            <div className="mt-6 flex justify-center px-6 pt-10 pb-10 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-xl bg-white dark:bg-gray-800/50 hover:border-blue-400 transition-colors cursor-pointer">
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                        <label htmlFor="file-upload" className="relative cursor-pointer rounded-md font-bold text-blue-600 dark:text-blue-400 hover:text-blue-500">
                                            <span>Select CSV/Excel File</span>
                                            <input id="file-upload" name="file-upload" type="file" className="sr-only" onChange={(e) => setFile(e.target.files?.[0] || null)} accept=".csv" />
                                        </label>
                                    </div>
                                    <p className="text-[10px] text-gray-400 uppercase tracking-widest font-black">Standard CSV up to 5MB</p>
                                </div>
                            </div>
                            {file && (
                                <div className="mt-4 p-4 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg border border-indigo-200 dark:border-indigo-800 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <DocumentTextIcon className="w-5 h-5 text-indigo-600" />
                                        <span className="text-sm font-bold text-indigo-900 dark:text-indigo-200">{file.name}</span>
                                    </div>
                                    <Badge variant="info">Ready</Badge>
                                </div>
                            )}
                        </div>
                   )}

                   {step === 3 && (
                        <div className="space-y-6">
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                                <Card className="p-4 text-center">
                                    <p className="text-[10px] font-black text-gray-400 uppercase">Processed</p>
                                    <p className="text-2xl font-black">{summary.processed}</p>
                                </Card>
                                <Card className="p-4 text-center border-l-4 border-green-500">
                                    <p className="text-[10px] font-black text-green-500 uppercase">Imported</p>
                                    <p className="text-2xl font-black">{summary.imported}</p>
                                </Card>
                                <Card className="p-4 text-center border-l-4 border-amber-500">
                                    <p className="text-[10px] font-black text-amber-500 uppercase">Incomplete</p>
                                    <p className="text-2xl font-black">{summary.incompleteCount}</p>
                                </Card>
                                <Card className="p-4 text-center border-l-4 border-red-500">
                                    <p className="text-[10px] font-black text-red-500 uppercase">Skipped</p>
                                    <p className="text-2xl font-black">{summary.skipped}</p>
                                </Card>
                            </div>

                            <div className="border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden shadow-sm max-h-80">
                                <table className="w-full text-xs text-left">
                                    <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0 z-10 border-b dark:border-gray-600">
                                        <tr>
                                            <th className="px-4 py-3 font-black uppercase text-gray-500 tracking-widest">Status</th>
                                            <th className="px-4 py-3 font-black uppercase text-gray-500 tracking-widest">Name</th>
                                            <th className="px-4 py-3 font-black uppercase text-gray-500 tracking-widest">Note</th>
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-100 dark:divide-gray-700">
                                        {validationResults.slice(0, 50).map((result, index) => (
                                            <tr key={index} className={result.status === 'skip' ? 'bg-red-50/50 opacity-60' : ''}>
                                                <td className="px-4 py-3">
                                                    <Badge variant={result.status === 'valid' ? 'success' : result.status === 'incomplete' ? 'warning' : 'danger'}>
                                                        {result.status.toUpperCase()}
                                                    </Badge>
                                                </td>
                                                <td className="px-4 py-3 font-bold truncate max-w-[200px]">
                                                    {result.data.surname ? `${result.data.surname}, ${result.data.otherNames}` : 'Unnamed Row'}
                                                </td>
                                                <td className="px-4 py-3 text-gray-500 italic">
                                                    {result.errors[0] || 'Clean data'}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                   )}

                   {step === 4 && (
                       <div className="text-center py-20 animate-in zoom-in duration-300">
                            <div className="w-20 h-20 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-6">
                                <CheckCircleIcon className="h-12 w-12 text-green-500" />
                            </div>
                            <h3 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Import Complete</h3>
                            <p className="mt-2 text-sm text-gray-500 dark:text-gray-400 max-w-sm mx-auto">
                                Successfully synced <span className="font-black text-blue-600">{summary.imported}</span> records to the database.
                            </p>
                        </div>
                   )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>
                        {step === 3 && (
                            <button onClick={() => setStep(1)} className="bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-bold py-2 px-6 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 flex items-center gap-2 text-xs uppercase tracking-widest transition-all">
                                <ChevronLeftIcon className="w-4 h-4" /> Back
                            </button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        {step === 1 && (
                            <button onClick={processFile} disabled={!file || isLoading} className="bg-blue-600 text-white font-black uppercase tracking-widest text-xs py-3 px-8 rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-all shadow-md">
                                {isLoading ? 'Working...' : 'Analyze File'}
                            </button>
                        )}
                        {step === 3 && (
                            <button onClick={handleConfirmImport} disabled={parsedData.length === 0 || isLoading} className="bg-green-600 text-white font-black uppercase tracking-widest text-xs py-3 px-8 rounded-lg hover:bg-green-700 disabled:opacity-50 transition-all shadow-md">
                                {isLoading ? 'Processing...' : `Commit ${parsedData.length} Records`}
                            </button>
                        )}
                        {step === 4 && (
                             <button onClick={handleClose} className="bg-blue-600 text-white font-black uppercase tracking-widest text-xs py-3 px-10 rounded-lg hover:bg-blue-700 shadow-md">
                                Finish
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

