import React, { useState, useCallback } from 'react';
import { XIcon } from './icons/XIcon';
import { UploadIcon, DocumentTextIcon, CheckCircleIcon, ChevronLeftIcon, InformationCircleIcon } from './icons/DummyIcons';
import { Badge } from './ui/Badge';
import { Card } from './ui/Card';

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[];
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
}

const ALIAS_MAP: Record<string, string> = {
    'phone': 'telephone',
    'land location': 'location',
    'number of plots': 'plotNumber',
    'primary contact': 'name_composite',
    'name': 'name_composite',
    'full name': 'name_composite',
    'contact': 'telephone',
    'email address': 'email'
};

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ isOpen, onClose, onImport, requiredHeaders, wizardTitle }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [summary, setSummary] = useState({ processed: 0, imported: 0 });
    const [isLoading, setIsLoading] = useState(false);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setSummary({ processed: 0, imported: 0 });
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    const normalizePhone = (val: string) => {
        const clean = val ? val.trim().replace(/[^\d+]/g, '') : '';
        return clean || 'unavailable';
    };

    const normalizeEmail = (val: string) => {
        const clean = val ? val.trim().toLowerCase() : '';
        return clean || 'unavailable';
    };

    const splitCompositeName = (name: string) => {
        const cleanName = (name || '').trim();
        if (!cleanName) return { surname: 'unavailable', otherNames: 'unavailable' };
        const parts = cleanName.split(/\s+/);
        if (parts.length === 1) return { surname: parts[0], otherNames: 'unavailable' };
        const surname = parts.pop() || 'unavailable';
        const otherNames = parts.join(' ');
        return { surname, otherNames };
    };

    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (char === '"') {
                if (inQuotes && text[i + 1] === '"') { cell += '"'; i++; }
                else { inQuotes = !inQuotes; }
            } else if (char === ',' && !inQuotes) {
                result.push(cell.trim());
                cell = '';
            } else { cell += char; }
        }
        result.push(cell.trim());
        return result;
    };

    const processFile = useCallback(() => {
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 2) {
                    alert('CSV file must have a header row and data.');
                    setIsLoading(false);
                    return;
                }

                const rawFileHeaders = parseCSVLine(lines[0].replace(/^\uFEFF/, '')).map(h => h.replace(/^"|"$/g, '').trim().toLowerCase());

                // Build Matrix
                const colMap: Record<string, number> = {};
                requiredHeaders.forEach(req => {
                    const idx = rawFileHeaders.indexOf(req.toLowerCase());
                    if (idx !== -1) colMap[req] = idx;
                });

                // Map Aliases
                requiredHeaders.forEach(req => {
                    if (colMap[req] === undefined) {
                        const aliasKey = Object.keys(ALIAS_MAP).find(k => ALIAS_MAP[k] === req);
                        if (aliasKey) {
                            const idx = rawFileHeaders.indexOf(aliasKey.toLowerCase());
                            if (idx !== -1) colMap[req] = idx;
                        }
                    }
                });

                // Find Composite Name Column
                const nameIdx = rawFileHeaders.indexOf('name') !== -1 ? rawFileHeaders.indexOf('name') : 
                              rawFileHeaders.indexOf('full name') !== -1 ? rawFileHeaders.indexOf('full name') :
                              rawFileHeaders.indexOf('primary contact') !== -1 ? rawFileHeaders.indexOf('primary contact') : -1;

                const results: any[] = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);
                    // If row is physically empty, values will be single empty string or empty array
                    const isEmptyRow = values.every(v => !v || v.trim() === '');

                    let rowData: any = {};
                    let hasUnavailable = false;

                    requiredHeaders.forEach(header => {
                        let val = 'unavailable';

                        if (!isEmptyRow) {
                            const fileIdx = colMap[header];
                            let rawVal = fileIdx !== undefined ? values[fileIdx]?.replace(/^"|"$/g, '').trim() : '';

                            // Identity Logic (Splitting Composite Name)
                            if (nameIdx !== -1 && (header === 'surname' || header === 'otherNames') && (!rawVal || rawVal === '')) {
                                const compositeName = values[nameIdx]?.replace(/^"|"$/g, '').trim();
                                const split = splitCompositeName(compositeName);
                                rawVal = header === 'surname' ? split.surname : split.otherNames;
                            }

                            if (header === 'telephone') rawVal = normalizePhone(rawVal);
                            else if (header === 'email') rawVal = normalizeEmail(rawVal);

                            val = (rawVal && rawVal !== '') ? rawVal : 'unavailable';
                        }

                        if (val === 'unavailable') hasUnavailable = true;
                        rowData[header] = val;
                    });

                    // Flagging
                    if (hasUnavailable) {
                        rowData.accountStatus = 'INCOMPLETE';
                        rowData.incompleteReason = 'IMPORTED_WITH_PLACEHOLDERS';
                        rowData.isComplete = false;
                    } else {
                        rowData.accountStatus = 'ACTIVE';
                        rowData.isComplete = true;
                    }

                    results.push(rowData);
                }

                setSummary({ processed: lines.length - 1, imported: results.length });
                setStep(3);
                onImport(results);
            } catch (error) {
                console.error(error);
                alert('Parsing failed. Check CSV formatting.');
            } finally {
                setIsLoading(false);
            }
        };
        reader.readAsText(file);
    }, [file, requiredHeaders, onImport]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm" aria-modal="true" role="dialog">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-2xl max-h-[90vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">{wizardTitle}</h2>
                    <button onClick={handleClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div className="space-y-6">
                            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border-l-4 border-blue-500 rounded flex gap-4">
                                <InformationCircleIcon className="w-6 h-6 text-blue-600 shrink-0" />
                                <div className="text-sm text-blue-800 dark:text-blue-200">
                                    <p className="font-bold">Zero-Skip Ingestion Engine</p>
                                    <p className="mt-1">Every row in your file will be converted into a client record. Missing data will be populated as 'unavailable' and flagged for manual update.</p>
                                </div>
                            </div>

                            <div className="mt-6 flex justify-center px-6 pt-10 pb-10 border-2 border-gray-300 dark:border-gray-700 border-dashed rounded-xl bg-white dark:bg-gray-800/50 hover:border-blue-400 transition-colors cursor-pointer relative">
                                <input id="file-upload" type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => setFile(e.target.files?.[0] || null)} accept=".csv" />
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600 dark:text-gray-400 justify-center">
                                        <span className="font-bold text-blue-600 dark:text-blue-400">Click to upload or drag CSV</span>
                                    </div>
                                    <p className="text-[10px] text-gray-400 uppercase tracking-widest font-black">Excel / Standard CSV</p>
                                </div>
                            </div>
                            {file && (
                                <div className="mt-4 p-4 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg border border-indigo-200 dark:border-indigo-800 flex items-center justify-between animate-in slide-in-from-top-1">
                                    <div className="flex items-center gap-3">
                                        <DocumentTextIcon className="w-5 h-5 text-indigo-600" />
                                        <span className="text-sm font-bold text-indigo-900 dark:text-indigo-200">{file.name}</span>
                                    </div>
                                    <Badge variant="info">Ready</Badge>
                                </div>
                            )}
                        </div>
                   )}

                   {step === 3 && (
                        <div className="text-center py-10 animate-in zoom-in duration-300">
                             <div className="w-20 h-20 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-6">
                                <CheckCircleIcon className="h-12 w-12 text-green-500" />
                            </div>
                            <h3 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Import Cycle Complete</h3>

                            <div className="mt-8 grid grid-cols-2 gap-4">
                                <Card className="p-4 bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700">
                                    <p className="text-[10px] font-black text-gray-400 uppercase">Rows Processed</p>
                                    <p className="text-xl font-bold">{summary.processed}</p>
                                </Card>
                                <Card className="p-4 bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700">
                                    <p className="text-[10px] font-black text-green-500 uppercase">Records Imported</p>
                                    <p className="text-xl font-bold text-green-600">{summary.imported}</p>
                                </Card>
                            </div>
                            <p className="mt-6 text-sm text-gray-500 dark:text-gray-400 max-w-sm mx-auto">
                                All rows have been synchronized. Records with placeholders are marked 'INCOMPLETE'.
                            </p>
                        </div>
                   )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>
                        {step === 3 && (
                             <button onClick={() => setStep(1)} className="text-xs font-black uppercase text-gray-400 hover:text-gray-800 flex items-center gap-1">
                                <ChevronLeftIcon className="w-4 h-4" /> Start New Batch
                            </button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        {step === 1 && (
                            <button 
                                onClick={processFile} 
                                disabled={!file || isLoading} 
                                className="bg-blue-600 text-white font-black uppercase tracking-widest text-xs py-3 px-8 rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-all shadow-md"
                            >
                                {isLoading ? 'Ingesting...' : 'Perform Resilient Import'}
                            </button>
                        )}
                        {step === 3 && (
                             <button onClick={handleClose} className="bg-blue-600 text-white font-black uppercase tracking-widest text-xs py-3 px-10 rounded-lg hover:bg-blue-700 shadow-md">
                                Return to Dashboard
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

