import { auth } from '../../services/firebase';
import { Client, MilestoneRecord, Property } from '../../types';

// --- Clients ---
export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const {
        data,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
        isLoading
    } = useInfiniteQuery({
        queryKey: ['clients', searchTerm],
        queryFn: ({ pageParam }) => 
            searchTerm 
                ? dbService.searchClients(searchTerm).then(data => ({ data, lastDoc: null }))
                : dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc,
        enabled: isAuthenticated,
    });

    const clients = data?.pages.flatMap(page => page.data) || [];

    const saveClientMutation = useMutation({
        mutationFn: async (client: Client) => {
            const oldClient = clients.find(c => c.id === client.id);
            const isNew = !oldClient;

            const properties: Property[] = queryClient.getQueryData(['properties']) || [];

            // --- DETERMINISTIC FINANCE ENGINE ---
            const totalPaid = (client.payment.paymentHistory || [])
                .filter(t => t.status === 'Success' && (t.type === 'Land' || !t.type))
                .reduce((sum, t) => sum + t.amount, 0);

            client.payment.paid = totalPaid;

            let effectiveTotal = client.payment.total > 0 ? client.payment.total : 0;

            if (effectiveTotal === 0 && client.location && client.location !== 'unavailable') {
                const catalogMatch = properties.find(p => p.location === client.location);
                if (catalogMatch) {
                    effectiveTotal = catalogMatch.price;
                }
            }

            if (effectiveTotal > 0) {
                const percent = (totalPaid / effectiveTotal) * 100;
                client.paidPercent = percent;

                const isNowQualified = percent >= 70;
                const wasQualified = oldClient?.allocationQualified || false;

                client.allocationQualified = isNowQualified;
            } else {
                client.paidPercent = null;
                client.allocationQualified = false;
            }

            const result = await dbService.persistClient(client);

            if (isNew) {
                await dbService.persistMilestone({
                    clientId: client.id,
                    milestoneCode: 'SFR',
                    dateCompleted: new Date().toISOString().split('T')[0],
                    notes: 'Initial registration received.'
                });
            }

            return result;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    // Support for bulk import commit with resilient placeholder mapping
    const importClientsMutation = useMutation({
        mutationFn: async (importArray: any[]) => {
            const results = [];
            for (const data of importArray) {
                const id = Date.now() + Math.floor(Math.random() * 10000);
                const surname = data.surname || 'unavailable';
                const otherNames = data.otherNames || 'unavailable';
                const initials = (surname[0] || 'U') + (otherNames[0] || 'U');

                const client: Client = {
                    id,
                    clientType: data.clientType || 'Individual',
                    name: surname === 'unavailable' ? 'Placeholder Account' : `${otherNames} ${surname}`.trim(),
                    surname,
                    otherNames,
                    initials: initials.toUpperCase(),
                    regDate: data.paymentDate || new Date().toISOString().split('T')[0],
                    email: data.email || 'unavailable',
                    phone: data.telephone || 'unavailable',
                    location: data.location || 'unavailable',
                    plot: data.plotNumber || 'unavailable',
                    status: 'Active Client',
                    accountStatus: data.accountStatus || 'ACTIVE',
                    incompleteReason: data.incompleteReason || null,
                    paidPercent: 0,
                    allocationQualified: false,
                    stage: 'SFR',
                    payment: {
                        total: 0, 
                        paid: 0, 
                        balance: 0, 
                        dueDate: 'N/A', 
                        planType: 'Imported',
                        paymentHistory: [], 
                        installments: []
                    },
                    interactions: [{ 
                        id: Date.now(), 
                        type: 'Note', 
                        date: new Date().toISOString(), 
                        agent: 'System (Importer)', 
                        notes: `Resilient import. Original Row State: ${data.accountStatus}` 
                    }],
                    witness: { name: data.witnessName || 'unavailable', address: data.witnessAddress || 'unavailable', phone: data.witnessPhone || 'unavailable' },
                    nextOfKin: { name: data.kinName || 'unavailable', phone: data.kinPhone || 'unavailable', relationship: data.kinRelationship || 'unavailable' },
                    indenture: { name: data.indentureName || 'unavailable', address: data.indentureAddress || 'unavailable' },
                    officeUse: { 
                        salesRep: data.salesRep || 'unavailable', 
                        salesManager: data.salesManager || 'unavailable', 
                        accountsHead: data.accountsHead || 'unavailable', 
                        clerk: data.clerk || 'unavailable', 
                        commission: { type: 'Fixed', amount: 0, status: 'Pending' } 
                    },
                    documentation: { status: 'Pending' },
                    isComplete: data.isComplete !== undefined ? data.isComplete : true,
                    filledFormPdf: null
                };

                await dbService.persistClient(client);
                results.push(client);
            }
            return results;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return {
        clients,
        isLoading,
        hasNextPage,
        fetchNextPage,
        isFetchingNextPage,
        saveClient: (client: Client) => saveClientMutation.mutateAsync(client),
        deleteClient: (id: number) => deleteClientMutation.mutateAsync(id),
        importClients: (data: any[]) => importClientsMutation.mutateAsync(data)
    };
};

export const useMilestones = (clientId?: number) => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: milestones = [], isLoading } = useQuery({
        queryKey: ['milestones', clientId],
        queryFn: () => clientId ? dbService.fetchMilestonesForClient(clientId) : dbService.fetchMilestones(),
        enabled: isAuthenticated,
    });

    const saveMilestoneMutation = useMutation({
        mutationFn: dbService.persistMilestone,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['milestones'] });
        }
    });

    return { 
        milestones, 
        isLoading, 
        saveMilestone: saveMilestoneMutation.mutateAsync 
    };
};

