const NOTIFICATIONS_COL = 'notifications';

/**
 * Creates a deterministic notification for Site Managers when an allocation is confirmed.
 * Uses idempotency keys to prevent duplicate alerts.
 */
export const triggerAllocationNotification = async (
    client: Client, 
    type: 'ALLOCATION_COMPLETED' | 'ALLOCATION_UPDATED'
) => {
    try {
        // Idempotency: Key based on client and event type
        // For updates, we add a timestamp grain (hourly) to allow re-notifying if changed again later, but not spamming
        const timeGrain = new Date().toISOString().substring(0, 13); // YYYY-MM-DDTHH
        const idempotencyKey = type === 'ALLOCATION_COMPLETED' 
            ? `ALLOC_DONE_${client.id}` 
            : `ALLOC_UPD_${client.id}_${timeGrain}`;

        const title = type === 'ALLOCATION_COMPLETED' 
            ? 'Allocation Completed — Site Visit Required' 
            : 'Allocation Updated — New Plot Verification';

        const message = type === 'ALLOCATION_COMPLETED'
            ? `Allocation has been completed for ${client.name}. Plot: ${client.plot} at ${client.location}. Please take the client to site and show them their plot.`
            : `Allocation was updated for ${client.name}. New Plot: ${client.plot} at ${client.location}. Please take the client to site to confirm the new plot.`;

        const notification: AppNotification = {
            id: idempotencyKey,
            title,
            message,
            type: 'Allocation',
            recipientRole: 'Site Manager',
            timestamp: new Date().toISOString(),
            isRead: false,
            module_key: 'Client Details',
            entity_id: client.id,
            metadata: {
                clientId: client.id,
                clientName: client.name,
                plotNumber: client.plot,
                location: client.location,
                eventType: type
            }
        };

        // Use setDoc to enforce idempotency via the specific ID
        await setDoc(doc(db, NOTIFICATIONS_COL, idempotencyKey), notification, { merge: true });

        console.debug(`[NotificationEngine] Triggered ${type} for ${client.name}`);
    } catch (error) {
        console.error("Failed to trigger allocation notification:", error);
    }
};

