    status: 'CLOSED' | 'COMPLETED', 
    user: Staff
) => {
    const ref = doc(db, NOTIFICATIONS_COL, notificationId);
    const now = new Date().toISOString();

    const updates: Partial<AppNotification> = {
        status: status,
        isRead: true
    };

    if (status === 'CLOSED') {
        updates.closedAt = now;
        updates.closedBy = user.fullName;
    } else if (status === 'COMPLETED') {
        updates.actionCompleted = true;
        updates.actionCompletedAt = now;
        updates.actionCompletedBy = user.fullName;
    }

    await updateDoc(ref, updates);

    // Log the lifecycle event
    await persistActivityLog({
        id: `LOG-NTF-${Date.now()}`,
        userId: user.id,
        username: user.fullName,
        role: user.roleId,
        type: 'Notification',
        actionType: status === 'CLOSED' ? 'NOTIFICATION_CLOSED' : 'NOTIFICATION_COMPLETED',
        entityType: 'Notification',
        entityId: notificationId,
        description: `${user.fullName} marked notification "${notificationId}" as ${status.toLowerCase()}.`,
        timestamp: now
    });
};

/**
 * Deterministic Resurface Logic
 * Checks for CLOSED but uncompleted action tasks that are 3+ days old.
 */
export const runResurfaceAudit = async (user: Staff) => {
    const q = query(
        collection(db, NOTIFICATIONS_COL), 
        where('status', '==', 'CLOSED'),
        where('requiresAction', '==', true),
        where('actionCompleted', '==', false)
    );

    const snapshot = await getDocs(q);
    const now = new Date();
    const threeDaysInMs = 3 * 24 * 60 * 60 * 1000;

    for (const d of snapshot.docs) {
        const data = d.data() as AppNotification;
        if (!data.closedAt) continue;

        const closedDate = new Date(data.closedAt);
        if (now.getTime() - closedDate.getTime() >= threeDaysInMs) {
            const newResurfaceCount = (data.resurfaceCount || 0) + 1;

            const updates: Partial<AppNotification> = {
                status: 'ACTIVE',
                isRead: false,
                resurfaceCount: newResurfaceCount,
                lastResurfacedAt: now.toISOString()
            };

            await updateDoc(d.ref, updates);

            // Escalation logic: resurfaced 3 times? Notify CEO
            if (newResurfaceCount >= 3) {
                const escalationId = `ESC_${data.id}`;
                await setDoc(doc(db, NOTIFICATIONS_COL, escalationId), {
                    ...data,
                    id: escalationId,
                    title: `ESCALATION: ${data.title}`,
                    message: `CRITICAL: Task ignored for 9+ days. Subject: ${data.message}`,
                    recipientRole: 'CEO',
                    status: 'ACTIVE',
                    type: 'Escalation',
                    resurfaceCount: 0,
                    requiresAction: true,
                    timestamp: now.toISOString()
                });
            }

            await persistActivityLog({
                id: `LOG-RSF-${Date.now()}`,
                userId: 'SYSTEM',
                username: 'Audit Engine',
                role: 'System',
                type: 'Notification',
                actionType: 'NOTIFICATION_RESURFACED',
                entityType: 'Notification',
                entityId: data.id,
                description: `System resurfaced ignored task: ${data.title}. Count: ${newResurfaceCount}`,
                timestamp: now.toISOString()
            });
        }
    }
};

export const triggerAllocationNotification = async (
    client: Client, 
    type: 'ALLOCATION_COMPLETED' | 'ALLOCATION_UPDATED'
) => {
    try {
        const timeGrain = new Date().toISOString().substring(0, 13);
        const idempotencyKey = type === 'ALLOCATION_COMPLETED' 
            ? `ALLOC_DONE_${client.id}` 
            : `ALLOC_UPD_${client.id}_${timeGrain}`;

        const notification: AppNotification = {
            id: idempotencyKey,
            title: type === 'ALLOCATION_COMPLETED' ? 'Allocation Completed' : 'Allocation Updated',
            message: `Action Required: Take ${client.name} to site for plot ${client.plot}.`,
            type: 'Allocation',
            recipientRole: 'Site Manager',
            timestamp: new Date().toISOString(),
            isRead: false,
            status: 'ACTIVE',
            requiresAction: true,
            actionCompleted: false,
            resurfaceCount: 0,
            module_key: 'Client Details',
            entity_id: client.id,
            metadata: {
                clientId: client.id,
                clientName: client.name,
                plotNumber: client.plot,
                location: client.location,
                eventType: type
            }
        };

        await setDoc(doc(db, NOTIFICATIONS_COL, idempotencyKey), notification, { merge: true });
    } catch (error) {
        console.error("Failed to trigger allocation notification:", error);
    }
};

