const ROLES_COL = 'roles';
const PERMISSIONS_COL = 'role_permissions';
const SETTINGS_COL = 'settings';

const sanitizeData = (data: any, seen = new WeakSet()): any => {
    if (data === null || typeof data !== 'object') {
        return data === undefined ? null : data;
    }
    if (seen.has(data)) return "[Circular]";
    if (data instanceof Date) return data.toISOString();
    if (Array.isArray(data)) {
        seen.add(data);
        return data.map(item => sanitizeData(item, seen));
    }

    const sanitizedObj: any = {};
    seen.add(data);
    Object.keys(data).forEach(key => {
        const value = data[key];
        if (typeof value !== 'function' && value !== undefined) {
            sanitizedObj[key] = sanitizeData(value, seen);
        }
    });
    return sanitizedObj;
};

// --- Staff ---
export const fetchStaff = async (): Promise<Staff[]> => {
    const snapshot = await getDocs(collection(db, USERS_COL));
    return snapshot.docs.map(doc => doc.data() as Staff);
};
export const persistStaff = async (staff: Staff) => {
    const { password, ...staffDataWithoutPassword } = staff;
    await setDoc(doc(db, USERS_COL, String(staff.id)), sanitizeData(staffDataWithoutPassword));
};
export const removeStaff = async (id: string) => {
    await deleteDoc(doc(db, USERS_COL, id));
};

// --- Activity Logs ---
export const fetchActivityLogs = async (limitCount: number = 100): Promise<ActivityLog[]> => {
    const q = query(collection(db, LOGS_COL), orderBy('timestamp', 'desc'), limit(limitCount));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => doc.data() as ActivityLog);
};

export const persistActivityLog = async (log: ActivityLog) => {
    await setDoc(doc(db, LOGS_COL, String(log.id)), sanitizeData(log));
};

// ... other existing methods remain unchanged
export const fetchRoles = async () => {
    const snapshot = await getDocs(collection(db, ROLES_COL));
    return snapshot.docs.map(doc => doc.data() as Role);
};
export const persistRole = async (role: Role) => {
    await setDoc(doc(db, ROLES_COL, String(role.id)), sanitizeData(role));
};
export const fetchCompanySettings = async (): Promise<CompanySettings> => {
    const docSnap = await getDoc(doc(db, SETTINGS_COL, 'main'));
    return docSnap.exists() ? docSnap.data() as CompanySettings : COMPANY_SETTINGS;
};
export const persistCompanySettings = async (settings: CompanySettings) => {
    await setDoc(doc(db, SETTINGS_COL, 'main'), sanitizeData(settings));
};
export const listenToRolePermissions = (onUpdate: (perms: RolePermission[]) => void) => {
    return onSnapshot(collection(db, PERMISSIONS_COL), (snapshot) => {
        const allPerms: RolePermission[] = [];
        snapshot.docs.forEach(doc => {
            const data = doc.data();
            if (data.modules) {
                Object.entries(data.modules).forEach(([moduleId, permissions]) => {
                    allPerms.push({ roleId: doc.id, moduleId: moduleId as AppModuleName, permissions: permissions as PermissionSet });
                });
            }
        });
        onUpdate(allPerms);
    });
};
export const updateRolePermissionInDb = async (roleId: string, moduleId: string, permission: string, value: boolean) => {
    await updateDoc(doc(db, PERMISSIONS_COL, roleId), { [`modules.${moduleId}.${permission}`]: value });
};
export const initRolePermissions = async (roleId: string) => {
    const defaultPermissions: Record<string, PermissionSet> = {};
    APP_MODULES.forEach(m => { defaultPermissions[m.id] = { view: false, create: false, edit: false, delete: false, approve: false }; });
    await setDoc(doc(db, PERMISSIONS_COL, roleId), { modules: defaultPermissions }, { merge: true });
};

import React, { useEffect, useMemo, useState } from 'react';
import { useClients } from '../hooks/useAppData';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { AppNotification, Client } from '../types';
import { Card } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';
import { 
    BellIcon, 
    CheckCircleIcon, 
    InformationCircleIcon, 
    ExclamationTriangleIcon, 
    ArrowRightIcon, 
    ClockIcon,
    TrashIcon,
    XMarkIcon
} from '../components/icons/DummyIcons';
import { useAuth } from '../context/AuthContext';
import { updateNotificationStatus, runResurfaceAudit } from '../services/notificationDbService';

interface NotificationsPageProps {
    setActivePage: (page: string, context?: any) => void;
    clients: Client[];
}

const NotificationsPage: React.FC<NotificationsPageProps> = ({ setActivePage, clients }) => {
    const { currentStaff } = useAuth();
    const alerts = useNotificationTriggers(clients);
    const [localAlerts, setLocalAlerts] = useState<AppNotification[]>([]);

    useEffect(() => {
        const event = new CustomEvent('faim_notifications_opened');
        window.dispatchEvent(event);
        // Run maintenance resurface audit on enter
        if (currentStaff) runResurfaceAudit(currentStaff);
    }, [currentStaff]);

    useEffect(() => {
        // Filter out items that are strictly CLOSED or COMPLETED in the UI
        setLocalAlerts(alerts.filter(a => a.status === 'ACTIVE' || !a.status));
    }, [alerts]);

    const grouped = useMemo(() => {
        const now = new Date();
        const today: AppNotification[] = [];
        const yesterday: AppNotification[] = [];
        const earlier: AppNotification[] = [];

        localAlerts.forEach(n => {
            const date = new Date(n.timestamp);
            const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60 * 24));

            if (diffDays === 0) today.push(n);
            else if (diffDays === 1) yesterday.push(n);
            else earlier.push(n);
        });

        return { today, yesterday, earlier };
    }, [localAlerts]);

    const handleAction = (n: AppNotification) => {
        if (n.module_key) {
            const context = clients.find(c => c.id === n.entity_id);
            if (context) {
                setActivePage(n.module_key, context);
            }
        }
    };

    const handleUpdateStatus = async (id: string, status: 'CLOSED' | 'COMPLETED') => {
        if (!currentStaff) return;
        try {
            await updateNotificationStatus(id, status, currentStaff);
            setLocalAlerts(prev => prev.filter(a => a.id !== id));
        } catch (e) {
            alert("Status update failed.");
        }
    };

    const NotificationItem: React.FC<{ item: AppNotification }> = ({ item }) => {
        const typeStyles = {
            Birthday: { icon: '🎂', color: 'text-pink-500', bg: 'bg-pink-50 dark:bg-pink-900/10' },
            Qualification: { icon: <CheckCircleIcon className="w-5 h-5" />, color: 'text-green-600', bg: 'bg-green-50 dark:bg-green-900/10' },
            Escalation: { icon: <ExclamationTriangleIcon className="w-5 h-5" />, color: 'text-red-600', bg: 'bg-red-50 dark:bg-red-900/10' },
            Reminder: { icon: <ClockIcon className="w-5 h-5" />, color: 'text-amber-600', bg: 'bg-amber-50 dark:bg-amber-900/10' },
            Default: { icon: <InformationCircleIcon className="w-5 h-5" />, color: 'text-blue-600', bg: 'bg-blue-50 dark:bg-blue-900/10' },
            Allocation: { icon: <ArrowRightIcon className="w-5 h-5" />, color: 'text-indigo-600', bg: 'bg-indigo-50 dark:bg-indigo-900/10' }
        };

        const style = typeStyles[item.type as keyof typeof typeStyles] || typeStyles.Default;

        return (
            <div className="group relative flex flex-col p-5 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-all border-b border-gray-100 dark:border-gray-700 last:border-0">
                <div className="flex gap-4">
                    <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${style.bg} ${style.color}`}>
                        {typeof style.icon === 'string' ? <span className="text-xl">{style.icon}</span> : style.icon}
                    </div>

                    <div className="flex-grow min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                            <h4 className="font-bold text-gray-900 dark:text-white truncate">{item.title}</h4>
                            <span className="text-[10px] text-gray-400 font-mono">
                                {new Date(item.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </span>
                        </div>
                        <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed">
                            {item.message}
                        </p>

                        {item.resurfaceCount > 0 && (
                            <Badge variant="warning" className="mt-2 text-[9px] uppercase tracking-tighter">
                                Resurfaced {item.resurfaceCount} times
                            </Badge>
                        )}
                    </div>

                    <button 
                        onClick={() => handleUpdateStatus(item.id, 'CLOSED')}
                        className="p-2 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity shrink-0" 
                        title="Close Task"
                    >
                        <XMarkIcon className="w-5 h-5" />
                    </button>
                </div>

                {item.requiresAction && (
                    <div className="flex items-center gap-4 mt-4 pt-4 border-t border-gray-50 dark:border-gray-700/50">
                        <button 
                            onClick={() => handleAction(item)}
                            className="flex items-center gap-1.5 text-xs font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest hover:underline"
                        >
                            Open Task <ArrowRightIcon className="w-3 h-3" />
                        </button>
                        <div className="h-3 w-px bg-gray-200 dark:bg-gray-700"></div>
                        <button 
                            onClick={() => handleUpdateStatus(item.id, 'COMPLETED')}
                            className="flex items-center gap-1.5 text-xs font-black text-green-600 dark:text-green-400 uppercase tracking-widest hover:underline"
                        >
                            Mark as Done <CheckCircleIcon className="w-3 h-3" />
                        </button>
                    </div>
                )}
            </div>
        );
    };

    return (
        <div className="max-w-4xl mx-auto space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Accountability Center</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Managed tasks and automated system alerts.</p>
                </div>
                <Badge variant="info">{localAlerts.length} Action Items</Badge>
            </div>

            {localAlerts.length === 0 ? (
                <div className="py-32 text-center bg-white dark:bg-gray-800 rounded-3xl border-2 border-dashed border-gray-100 dark:border-gray-700 opacity-50">
                    <CheckCircleIcon className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                    <p className="text-lg font-black text-gray-400 uppercase tracking-widest">Inbox Zero</p>
                    <p className="text-sm text-gray-500 mt-1">You are all caught up on your tasks.</p>
                </div>
            ) : (
                <div className="space-y-8">
                    {grouped.today.length > 0 && (
                        <section>
                            <h3 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                                <div className="h-px flex-grow bg-blue-100 dark:bg-blue-900/30" />
                                Recent Tasks
                                <div className="h-px flex-grow bg-blue-100 dark:bg-blue-900/30" />
                            </h3>
                            <Card className="p-0 overflow-hidden shadow-xl border-0 ring-1 ring-black/5">
                                {grouped.today.map(n => <NotificationItem key={n.id} item={n} />)}
                            </Card>
                        </section>
                    )}

                    {(grouped.yesterday.length > 0 || grouped.earlier.length > 0) && (
                        <section>
                            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                                <div className="h-px flex-grow bg-gray-100 dark:bg-gray-800" />
                                Pending Items
                                <div className="h-px flex-grow bg-gray-100 dark:bg-gray-800" />
                            </h3>
                            <Card className="p-0 overflow-hidden border-0 ring-1 ring-black/5">
                                {[...grouped.yesterday, ...grouped.earlier].map(n => <NotificationItem key={n.id} item={n} />)}
                            </Card>
                        </section>
                    )}
                </div>
            )}
        </div>
    );
};

