    status: 'Contacted' | 'Visited Site' | 'Filled a Form' | 'Submitted the Form' | 'Made Payment' | 'Converted to Client';
    assignedRepId: string;
    nextFollowUpDate: string;
    lastContactDate: string;
    notes: string;
    createdAt: string;
    comments: LeadComment[];
}

export type KPISourceModule = 'Leads' | 'SiteVisits' | 'Sales' | 'Finance';

export interface KPIDefinition {
    id: string;
    name: string;
    description: string;
    sourceModule: KPISourceModule;
    outcomeTag?: string; // e.g., 'LAND', 'BATTER'
    targetPerWeek: number;
    isActive: boolean;
    order: number;
}

export interface WeeklyPerformance {
    week1: number;
    week2: number;
    week3: number;
    week4: number;
    week5: number;
    total: number;
}

export interface KPIReportRow extends WeeklyPerformance {
    kpiId: string;
    kpiName: string;
    targetPerWeek: number;
    targetMonthly: number;
    achievementPercent: number;
}

export interface DailyReportSnapshot {
    id: string;
    date: string;
    staffId: string;
    acknowledged: boolean;
    timestamp?: string;
    metrics: Record<string, number>;
}

import { db } from './firebase';
import { collection, getDocs, doc, setDoc, updateDoc, query, where, orderBy, addDoc } from 'firebase/firestore';
import { KPIDefinition, DailyReportSnapshot } from '../types/reports';

const KPI_DEFS_COL = 'kpi_definitions';
const KPI_LOGS_COL = 'kpi_acknowledgments';

export const fetchKPIDefinitions = async (): Promise<KPIDefinition[]> => {
    const snapshot = await getDocs(query(collection(db, KPI_DEFS_COL), orderBy('order', 'asc')));
    return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as KPIDefinition));
};

export const saveKPIDefinition = async (kpi: KPIDefinition) => {
    await setDoc(doc(db, KPI_DEFS_COL, kpi.id), kpi);
};

export const acknowledgeDailyReport = async (staffId: string, metrics: Record<string, number>) => {
    const date = new Date().toISOString().split('T')[0];
    const docId = `${staffId}_${date}`;
    const data: DailyReportSnapshot = {
        id: docId,
        date,
        staffId,
        acknowledged: true,
        timestamp: new Date().toISOString(),
        metrics
    };
    await setDoc(doc(db, KPI_LOGS_COL, docId), data);
};

export const seedDefaultKPIs = async () => {
    const defaults: KPIDefinition[] = [
        { id: 'kpi_land', name: 'People spoken to - LAND', description: 'Leads categorized as LAND', sourceModule: 'Leads', outcomeTag: 'LAND', targetPerWeek: 15, isActive: true, order: 1 },
        { id: 'kpi_batter', name: 'People spoken to - BATTER', description: 'Leads categorized as BATTER', sourceModule: 'Leads', outcomeTag: 'BATTER', targetPerWeek: 15, isActive: true, order: 2 },
        { id: 'kpi_interested', name: 'People spoken to - INTERESTED', description: 'Leads categorized as INTERESTED', sourceModule: 'Leads', outcomeTag: 'INTERESTED', targetPerWeek: 30, isActive: true, order: 3 },
        { id: 'kpi_site', name: 'People scheduled for site', description: 'Scheduled site visits', sourceModule: 'SiteVisits', targetPerWeek: 15, isActive: true, order: 4 },
        { id: 'kpi_purchase', name: 'People who must purchase', description: 'Leads converted to clients', sourceModule: 'Sales', targetPerWeek: 10, isActive: true, order: 5 },
        { id: 'kpi_payments', name: 'Payments made', description: 'Successful payment transactions', sourceModule: 'Finance', targetPerWeek: 10, isActive: true, order: 6 },
