import React, { useMemo, useState } from 'react';
import { Lead, Client } from '../../types';
import { KPIDefinition, KPIReportRow } from '../../types/reports';
import { Card } from '../ui/Card';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../ui/Table';
import { Badge } from '../ui/Badge';

interface MonthlyKPISummaryProps {
    staffId: string;
    leads: Lead[];
    clients: Client[];
    definitions: KPIDefinition[];
}

export const MonthlyKPISummary: React.FC<MonthlyKPISummaryProps> = ({ staffId, leads, clients, definitions }) => {
    const [selectedMonth, setSelectedMonth] = useState(() => {
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    });

    const getWeek = (dateStr: string) => {
        const day = new Date(dateStr).getDate();
        if (day <= 7) return 'week1';
        if (day <= 14) return 'week2';
        if (day <= 21) return 'week3';
        if (day <= 28) return 'week4';
        return 'week5';
    };

    const reportRows = useMemo(() => {
        const [year, month] = selectedMonth.split('-').map(Number);
        const activeDefs = definitions.filter(d => d.isActive);

        return activeDefs.map(def => {
            const performance: Record<string, number> = { week1: 0, week2: 0, week3: 0, week4: 0, week5: 0 };

            if (def.sourceModule === 'Leads') {
                leads.forEach(l => {
                    if (l.assignedRepId === staffId) {
                        l.comments.forEach(c => {
                            const d = new Date(c.date);
                            if (d.getFullYear() === year && d.getMonth() === (month - 1) && c.outcomeCategory === def.outcomeTag) {
                                performance[getWeek(c.date)]++;
                            }
                        });
                    }
                });
            } else if (def.sourceModule === 'SiteVisits') {
                 leads.forEach(l => {
                    if (l.assignedRepId === staffId) {
                        l.comments.forEach(c => {
                            const d = new Date(c.date);
                            if (d.getFullYear() === year && d.getMonth() === (month - 1) && c.isSiteVisitScheduled) {
                                performance[getWeek(c.date)]++;
                            }
                        });
                    }
                });
            } else if (def.sourceModule === 'Sales') {
                clients.forEach(c => {
                    const d = new Date(c.regDate);
                    if (d.getFullYear() === year && d.getMonth() === (month - 1)) {
                        performance[getWeek(c.regDate)]++;
                    }
                });
            } else if (def.sourceModule === 'Finance') {
                clients.forEach(c => {
                    c.payment.paymentHistory.forEach(t => {
                        const d = new Date(t.date);
                        if (d.getFullYear() === year && d.getMonth() === (month - 1) && t.status === 'Success') {
                            performance[getWeek(t.date)]++;
                        }
                    });
                });
            }

            const total = Object.values(performance).reduce((a, b) => a + b, 0);
            const targetMonthly = def.targetPerWeek * 4; // Normalized target
            const achievementPercent = targetMonthly > 0 ? (total / targetMonthly) * 100 : 0;

            return {
                kpiId: def.id,
                kpiName: def.name,
                targetPerWeek: def.targetPerWeek,
                targetMonthly,
                ...performance,
                total,
                achievementPercent
            } as KPIReportRow;
        });
    }, [definitions, leads, clients, staffId, selectedMonth]);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center bg-gray-50 dark:bg-gray-900 p-4 rounded-xl border border-gray-100 dark:border-gray-700">
                <h3 className="text-sm font-black uppercase tracking-widest text-gray-500">Monthly Performance Audit</h3>
                <input 
                    type="month" 
                    value={selectedMonth} 
                    onChange={e => setSelectedMonth(e.target.value)}
                    className="p-2 text-sm font-bold bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
            </div>

            <TableContainer>
                <table className="w-full text-xs text-left">
                    <Thead>
                        <tr>
                            <Th>KPI Metric</Th>
                            <Th className="text-center">Target/Wk</Th>
                            <Th className="text-center">Wk1</Th>
                            <Th className="text-center">Wk2</Th>
                            <Th className="text-center">Wk3</Th>
                            <Th className="text-center">Wk4</Th>
                            <Th className="text-center">Wk5</Th>
                            <Th className="text-center">Monthly Total</Th>
                            <Th className="text-right">% Achieved</Th>
                        </tr>
                    </Thead>
                    <Tbody>
                        {reportRows.map(row => (
                            <Tr key={row.kpiId}>
                                <Td className="font-bold text-gray-900 dark:text-white">{row.kpiName}</Td>
                                <Td className="text-center font-mono text-gray-500">{row.targetPerWeek}</Td>
                                <Td className="text-center font-bold">{row.week1}</Td>
                                <Td className="text-center font-bold">{row.week2}</Td>
                                <Td className="text-center font-bold">{row.week3}</Td>
                                <Td className="text-center font-bold">{row.week4}</Td>
                                <Td className="text-center font-bold">{row.week5}</Td>
                                <Td className="text-center">
                                    <span className="font-black text-blue-600 dark:text-blue-400">{row.total}</span>
                                    <span className="text-[9px] text-gray-400 ml-1">/ {row.targetMonthly}</span>
                                </Td>
                                <Td className="text-right">
                                    <Badge variant={row.achievementPercent >= 100 ? 'success' : row.achievementPercent >= 70 ? 'warning' : 'danger'}>
                                        {Math.round(row.achievementPercent)}%
                                    </Badge>
                                </Td>
                            </Tr>
                        ))}
                    </Tbody>
                </table>
            </TableContainer>
        </div>
    );
};

import React, { useMemo, useState } from 'react';
