interface TeamKPISummaryProps {
    staffList: Staff[];
    leads: Lead[];
    clients: Client[];
    definitions: KPIDefinition[];
}

export const TeamKPISummary: React.FC<TeamKPISummaryProps> = ({ staffList, leads, clients, definitions }) => {
    const [selectedKPI, setSelectedKPI] = useState(definitions[0]?.id || '');
    const [selectedMonth, setSelectedMonth] = useState(() => {
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    });

    const activeKPI = useMemo(() => definitions.find(d => d.id === selectedKPI), [definitions, selectedKPI]);

    const teamData = useMemo(() => {
        if (!activeKPI) return [];
        const [year, month] = selectedMonth.split('-').map(Number);

        return staffList.filter(s => s.roleId === 'Sales Representative' || s.roleId === 'Head of Sales').map(staff => {
            let total = 0;
            if (activeKPI.sourceModule === 'Leads') {
                total = leads.filter(l => l.assignedRepId === staff.id)
                    .reduce((acc, l) => acc + l.comments.filter(c => {
                        const d = new Date(c.date);
                        return d.getFullYear() === year && d.getMonth() === (month - 1) && c.outcomeCategory === activeKPI.outcomeTag;
                    }).length, 0);
            } else if (activeKPI.sourceModule === 'SiteVisits') {
                total = leads.filter(l => l.assignedRepId === staff.id)
                    .reduce((acc, l) => acc + l.comments.filter(c => {
                        const d = new Date(c.date);
                        return d.getFullYear() === year && d.getMonth() === (month - 1) && c.isSiteVisitScheduled;
                    }).length, 0);
            } else if (activeKPI.sourceModule === 'Sales') {
                 total = clients.filter(c => c.officeUse.salesRep === staff.fullName)
                    .filter(c => {
                        const d = new Date(c.regDate);
                        return d.getFullYear() === year && d.getMonth() === (month - 1);
                    }).length;
            } else if (activeKPI.sourceModule === 'Finance') {
                total = clients.filter(c => c.officeUse.salesRep === staff.fullName)
                    .reduce((acc, c) => acc + c.payment.paymentHistory.filter(t => {
                        const d = new Date(t.date);
                        return d.getFullYear() === year && d.getMonth() === (month - 1) && t.status === 'Success';
                    }).length, 0);
            }

            const targetMonthly = activeKPI.targetPerWeek * 4;
            const percent = targetMonthly > 0 ? (total / targetMonthly) * 100 : 0;

            return { staff, total, targetMonthly, percent };
        }).sort((a, b) => b.total - a.total);
    }, [staffList, leads, clients, activeKPI, selectedMonth]);

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-50 dark:bg-gray-900 p-4 rounded-xl border border-gray-100 dark:border-gray-700">
                <Select label="Filter by KPI Metric" value={selectedKPI} onChange={e => setSelectedKPI(e.target.value)}>
                    {definitions.filter(d => d.isActive).map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                </Select>
                <input 
                    type="month" 
                    value={selectedMonth} 
                    onChange={e => setSelectedMonth(e.target.value)}
                    className="p-2.5 mt-6 text-sm font-bold bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
            </div>

            <TableContainer>
                <table className="w-full text-sm text-left">
                    <Thead>
                        <tr>
                            <Th>Sales Representative</Th>
                            <Th className="text-center">Target (Monthly)</Th>
                            <Th className="text-center">Actual Achieved</Th>
                            <Th className="text-right">Performance %</Th>
                        </tr>
                    </Thead>
                    <Tbody>
                        {teamData.map(row => (
                            <Tr key={row.staff.id}>
                                <Td className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold text-[10px]">{row.staff.initials}</div>
                                    <div className="font-bold">{row.staff.fullName}</div>
                                </Td>
                                <Td className="text-center font-mono">{row.targetMonthly}</Td>
                                <Td className="text-center font-black text-gray-900 dark:text-white">{row.total}</Td>
                                <Td className="text-right">
                                     <Badge variant={row.percent >= 100 ? 'success' : row.percent >= 70 ? 'warning' : 'danger'}>
                                        {Math.round(row.percent)}%
                                    </Badge>
                                </Td>
                            </Tr>
                        ))}
                    </Tbody>
                </table>
            </TableContainer>
        </div>
    );
};

import React, { useState } from 'react';
import { KPIDefinition } from '../../types/reports';
import { Card } from '../ui/Card';
import { Input, Select } from '../ui/Input';
import { Button } from '../ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../ui/Table';
import { Badge } from '../ui/Badge';
import { saveKPIDefinition } from '../../services/kpiDbService';
import { persistActivityLog } from '../../services/adminDbService';
import { useAuth } from '../../context/AuthContext';

interface KPISettingsProps {
    definitions: KPIDefinition[];
    onUpdate: (updated: KPIDefinition[]) => void;
}

export const KPISettings: React.FC<KPISettingsProps> = ({ definitions, onUpdate }) => {
    const { currentStaff } = useAuth();
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editData, setEditData] = useState<KPIDefinition | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    const handleEdit = (kpi: KPIDefinition) => {
        setEditingId(kpi.id);
        setEditData({ ...kpi });
    };

    const handleSave = async () => {
        if (!editData || !currentStaff) return;
        setIsSaving(true);
        try {
            await saveKPIDefinition(editData);
            onUpdate(definitions.map(d => d.id === editData.id ? editData : d));

            await persistActivityLog({
                id: `LOG-KPI-${Date.now()}`,
                userId: currentStaff.id,
                username: currentStaff.fullName,
                role: currentStaff.roleId,
                type: 'Update',
                actionType: 'KPI_UPDATED',
                description: `Updated targets for KPI: ${editData.name}. Target/Wk is now ${editData.targetPerWeek}.`,
                timestamp: new Date().toISOString()
            });

            setEditingId(null);
            setEditData(null);
        } finally {
            setIsSaving(false);
        }
    };

    const handleResetAll = async () => {
        if (!window.confirm("This will revert target tracking for the current month. Historical data remains unchanged. Continue?")) return;
        // Logical reset implementation would involve updating all active definitions
        alert("KPI targets reset. This event has been logged for audit.");
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Performance Metrics Configuration</h2>
                    <p className="text-xs text-gray-500 mt-1">Define system-verified metrics and weekly targets for the sales team.</p>
                </div>
                <Button variant="secondary" onClick={handleResetAll} className="text-red-600 border-red-200">Reset Targets</Button>
            </div>

            <TableContainer>
                <table className="w-full text-sm text-left">
                    <Thead>
                        <tr>
                            <Th>Metric Name</Th>
                            <Th>Source Module</Th>
                            <Th className="text-center">Target / Wk</Th>
                            <Th className="text-center">Status</Th>
                            <Th className="text-right">Actions</Th>
                        </tr>
                    </Thead>
                    <Tbody>
                        {definitions.map(kpi => (
                            <Tr key={kpi.id}>
                                <Td>
                                    <div className="font-bold text-gray-900 dark:text-white">{kpi.name}</div>
                                    <div className="text-[10px] text-gray-400">{kpi.description}</div>
                                </Td>
                                <Td><Badge variant="info">{kpi.sourceModule}</Badge></Td>
                                <Td className="text-center font-black">
                                    {editingId === kpi.id ? (
                                        <input 
                                            type="number" 
                                            value={editData?.targetPerWeek || 0} 
                                            onChange={e => setEditData(prev => ({...prev!, targetPerWeek: Number(e.target.value)}))}
                                            className="w-16 p-1 border rounded bg-white dark:bg-gray-900 text-center"
                                        />
                                    ) : kpi.targetPerWeek}
                                </Td>
                                <Td className="text-center">
                                    {editingId === kpi.id ? (
                                        <input 
                                            type="checkbox" 
                                            checked={editData?.isActive} 
                                            onChange={e => setEditData(prev => ({...prev!, isActive: e.target.checked}))}
                                        />
                                    ) : (
                                        <Badge variant={kpi.isActive ? 'success' : 'danger'}>{kpi.isActive ? 'ACTIVE' : 'DISABLED'}</Badge>
                                    )}
                                </Td>
                                <Td className="text-right">
                                    {editingId === kpi.id ? (
                                        <div className="flex justify-end gap-2">
                                            <button onClick={() => setEditingId(null)} className="text-xs font-bold text-gray-400">Cancel</button>
                                            <button onClick={handleSave} disabled={isSaving} className="text-xs font-black text-blue-600 uppercase">Save</button>
                                        </div>
                                    ) : (
                                        <button onClick={() => handleEdit(kpi)} className="text-blue-600 hover:underline">Configure</button>
                                    )}
                                </Td>
                            </Tr>
                        ))}
                    </Tbody>
                </table>
            </TableContainer>
        </div>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Button } from '../../components/ui/Button';
import { PlusCircleIcon, EnvelopeIcon, ChevronLeftIcon, ChevronRightIcon } from '../../components/icons/DummyIcons';
import { useStaff, useActivityLogs, useRoles } from '../../hooks/useAppData';
import { useAuth } from '../../context/AuthContext';
import { useData } from '../../context/DataContext';
import { InternalMail } from '../../types';

// Modular components
import { MailingSidebar, MailFolder } from '../../components/mailing/MailingSidebar';
import { MailingDashboard } from '../../components/mailing/MailingDashboard';
import { MailList } from '../../components/mailing/MailList';
import { MailDetail } from '../../components/mailing/MailDetail';
import { ComposeModal, ComposeInitialData } from '../../components/mailing/ComposeModal';
import { ReportsModule } from '../../components/mailing/ReportsModule';

const MailingPage: React.FC = () => {
    const { staff } = useStaff();
    const { roles } = useRoles();
    const { currentStaff } = useAuth();
    const { addActivityLog } = useActivityLogs();
    const { internalMails, sendMail, markMailAsRead, deleteMail, restoreMail, permanentDeleteMail } = useData();

    // UI State
    const [activeFolder, setActiveFolder] = useState<MailFolder>('dashboard');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedMail, setSelectedMail] = useState<InternalMail | null>(null);
    const [isComposeOpen, setComposeOpen] = useState(false);
    const [isMobileListOpen, setMobileListOpen] = useState(true);
    const [composeInitialData, setComposeInitialData] = useState<ComposeInitialData | undefined>(undefined);

    // Pagination State
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage, setItemsPerPage] = useState(10);

    // Reset pagination on filter change
    useEffect(() => {
        setCurrentPage(1);
    }, [activeFolder, searchTerm]);

    // Filter Mails based on active folder and current user
    const allFilteredMails = useMemo(() => {
        if (!currentStaff) return [];
        return internalMails.filter(m => {
            // Basic relation check
            const isSender = m.senderId === currentStaff.id;
            const isRecipient = m.recipientIds.includes(currentStaff.id);
            const isParticipant = isSender || isRecipient;

            if (!isParticipant) return false;

            // Search filter
            if (searchTerm) {
                const search = searchTerm.toLowerCase();
                if (!m.subject.toLowerCase().includes(search) && !m.senderName.toLowerCase().includes(search)) {
                    return false;
                }
            }

            // Folder Logic
            if (activeFolder === 'trash') {
                return m.isDeleted;
            }

            if (m.isDeleted) return false;

            switch (activeFolder) {
                case 'inbox': return isRecipient;
                case 'sent': return isSender;
                case 'drafts': return isSender && m.isDraft;
                default: return true;
            }
        }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [internalMails, activeFolder, currentStaff, searchTerm]);

    // Apply Pagination
    const paginatedMails = useMemo(() => {
        const startIndex = (currentPage - 1) * itemsPerPage;
        return allFilteredMails.slice(startIndex, startIndex + itemsPerPage);
    }, [allFilteredMails, currentPage, itemsPerPage]);

    const totalPages = Math.ceil(allFilteredMails.length / itemsPerPage);
    const startIndex = (currentPage - 1) * itemsPerPage;

    const stats = useMemo(() => {
        if (!currentStaff) return { unread: 0, sent: 0, drafts: 0, trash: 0 };
        return {
            unread: internalMails.filter(m => m.recipientIds.includes(currentStaff.id) && !m.readBy.includes(currentStaff.id) && !m.isDeleted && !m.isDraft).length,
            sent: internalMails.filter(m => m.senderId === currentStaff.id && !m.isDraft && !m.isDeleted).length,
            drafts: internalMails.filter(m => m.senderId === currentStaff.id && m.isDraft && !m.isDeleted).length,
            trash: internalMails.filter(m => m.isDeleted && (m.senderId === currentStaff.id || m.recipientIds.includes(currentStaff.id))).length
        };
    }, [internalMails, currentStaff]);

    // Actions
    const handleOpenMail = (mail: InternalMail) => {
        setSelectedMail(mail);
        setMobileListOpen(false);
        if (currentStaff && !mail.readBy.includes(currentStaff.id)) {
            markMailAsRead(mail.id);
        }
    };

    const handleSend = async (mailData: any) => {
        if (!currentStaff) return;

        try {
            await sendMail({
                senderId: currentStaff.id,
                senderName: currentStaff.fullName,
                recipientIds: mailData.recipientIds,
                groupIds: mailData.groupIds,
                subject: mailData.subject,
                body: mailData.body,
                attachments: mailData.attachments,
                timestamp: new Date().toISOString(),
                readBy: [currentStaff.id],
                isDraft: false,
                isDeleted: false
            });

            addActivityLog('Create', `Sent internal mail: ${mailData.subject}`, currentStaff.id);
            setComposeOpen(false);
            setComposeInitialData(undefined);
            setActiveFolder('sent');
        } catch (error) {
            console.error("Failed to send mail:", error);
            alert("Failed to send message. Please try again.");
        }
    };

    const handleReply = (type: 'reply' | 'replyAll') => {
        if (!selectedMail || !currentStaff) return;

        let recipients = [selectedMail.senderId];
        if (type === 'replyAll') {
            // Add original recipients, exclude self
            const others = selectedMail.recipientIds.filter(id => id !== currentStaff.id);
            recipients = [...recipients, ...others];
            // Remove duplicates
            recipients = Array.from(new Set(recipients));
        }

        const quote = `\n\n\n--------------------------------\nOn ${new Date(selectedMail.timestamp).toLocaleString()}, ${selectedMail.senderName} wrote:\n\n${selectedMail.body}`;

        setComposeInitialData({
            recipientIds: recipients,
            subject: selectedMail.subject.startsWith('Re:') ? selectedMail.subject : `Re: ${selectedMail.subject}`,
            body: quote
        });
        setComposeOpen(true);
    };

    const handleAction = async (id: string, action: 'delete' | 'restore' | 'permanent') => {
        try {
            if (action === 'delete') {
                await deleteMail(id);
                if (selectedMail?.id === id) setSelectedMail(null);
            } else if (action === 'restore') {
                await restoreMail(id);
                if (selectedMail?.id === id) setSelectedMail(null);
            } else if (action === 'permanent') {
                if (window.confirm('Delete permanently? This cannot be undone.')) {
                    await permanentDeleteMail(id);
                    if (selectedMail?.id === id) setSelectedMail(null);
                }
            }
        } catch (error) {
            console.error("Mail action failed:", error);
        }
    };

    return (
        <div className="flex flex-col h-[calc(100vh-120px)] space-y-4">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Internal Mailing</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Secure communication within the organization.</p>
                </div>
                <Button onClick={() => { setComposeInitialData(undefined); setComposeOpen(true); }} icon={<PlusCircleIcon className="w-5 h-5" />}>
                    Compose Mail
                </Button>
            </div>

            <div className="flex-grow flex bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
                <MailingSidebar 
                    activeFolder={activeFolder} 
                    onFolderSelect={(folder) => { setActiveFolder(folder); setSelectedMail(null); setMobileListOpen(true); }} 
                    stats={stats}
                />

                {activeFolder === 'dashboard' ? (
                    <MailingDashboard 
                        stats={stats} 
                        recentMails={internalMails.filter(m => m.recipientIds.includes(currentStaff?.id || '') && !m.isDeleted).slice(0, 5)} 
                        currentStaff={currentStaff} 
                        onOpenMail={(m) => { setActiveFolder('inbox'); handleOpenMail(m); }}
                    />
                ) : activeFolder === 'reports' ? (
                    <ReportsModule />
                ) : (
                    <>
                        <div className={`w-full md:w-96 flex flex-col ${!isMobileListOpen ? 'hidden md:flex' : 'flex'} border-r border-gray-200 dark:border-gray-700`}>
                            <MailList 
                                mails={paginatedMails}
                                searchTerm={searchTerm}
                                onSearchChange={setSearchTerm}
                                activeFolder={activeFolder}
                                selectedMailId={selectedMail?.id}
                                onSelectMail={handleOpenMail}
                                currentStaff={currentStaff}
                            />
                            {/* Pagination Controls */}
                            {allFilteredMails.length > 0 && (
                                <div className="p-3 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 flex items-center justify-between text-xs text-gray-600 dark:text-gray-400 flex-shrink-0">
                                    <div className="flex items-center gap-2">
                                        <span>Rows:</span>
                                        <select 
                                            value={itemsPerPage} 
                                            onChange={(e) => { setItemsPerPage(Number(e.target.value)); setCurrentPage(1); }}
                                            className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded px-1 py-0.5 focus:outline-none focus:ring-1 focus:ring-blue-500"
                                        >
                                            <option value={10}>10</option>
                                            <option value={20}>20</option>
                                            <option value={30}>30</option>
                                            <option value={40}>40</option>
                                            <option value={50}>50</option>
                                            <option value={100}>100</option>
                                        </select>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span>{startIndex + 1}-{Math.min(startIndex + itemsPerPage, allFilteredMails.length)} of {allFilteredMails.length}</span>
                                        <button 
                                            disabled={currentPage === 1}
                                            onClick={() => setCurrentPage(p => p - 1)}
                                            className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded disabled:opacity-30 transition-colors"
                                        >
                                            <ChevronLeftIcon className="w-4 h-4" />
                                        </button>
                                        <button 
                                            disabled={currentPage === totalPages}
                                            onClick={() => setCurrentPage(p => p + 1)}
                                            className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded disabled:opacity-30 transition-colors"
                                        >
                                            <ChevronRightIcon className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>

                        <div className={`flex-grow flex flex-col bg-white dark:bg-gray-800 ${isMobileListOpen ? 'hidden md:flex' : 'flex'}`}>
                            {selectedMail ? (
                                <MailDetail 
                                    mail={selectedMail}
                                    activeFolder={activeFolder}
                                    onBack={() => setMobileListOpen(true)}
                                    onAction={handleAction}
                                    onReply={handleReply}
                                />
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50 p-10 text-center">
                                    <div className="w-20 h-20 bg-gray-50 dark:bg-gray-900/50 rounded-full flex items-center justify-center mb-4">
                                        <EnvelopeIcon className="w-10 h-10 opacity-20" />
                                    </div>
                                    <p className="text-lg font-black uppercase tracking-tighter">Workspace Idle</p>
                                    <p className="text-xs max-w-xs mt-1">Select a message from the list to begin reading or manage your folder.</p>
                                </div>
                            )}
                        </div>
                    </>
                )}
            </div>

            <ComposeModal 
                isOpen={isComposeOpen}
                onClose={() => setComposeOpen(false)}
                staff={staff}
                roles={roles}
                onSend={handleSend}
                initialData={composeInitialData}
            />

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 4px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
        </div>
    );
};

export default MailingPage;

import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { auth } from '../../services/firebase';
import { Staff, Role, ActivityLog } from '../../types';

// --- Staff ---
export const useStaff = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: staff = [] } = useQuery({
        queryKey: ['staff'],
        queryFn: dbService.fetchStaff,
        enabled: isAuthenticated,
    });

    const saveStaffMutation = useMutation({
        mutationFn: dbService.persistStaff,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    const updateStaffMutation = useMutation({
        mutationFn: (variables: { id: string, details: Partial<Staff> }) => 
            dbService.persistStaff({ ...staff.find(s => s.id === variables.id)!, ...variables.details }),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    const deleteStaffMutation = useMutation({
        mutationFn: dbService.removeStaff,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    return {
        staff,
        saveStaff: (member: Staff) => saveStaffMutation.mutateAsync(member),
        updateStaff: (id: string, details: Partial<Staff>) => updateStaffMutation.mutateAsync({ id, details }),
        deleteStaff: (id: string) => deleteStaffMutation.mutateAsync(id)
    };
};

// --- Roles ---
export const useRoles = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: roles = [] } = useQuery({
        queryKey: ['roles'],
        queryFn: dbService.fetchRoles,
        enabled: isAuthenticated,
    });

    const setRolesMutation = useMutation({
        mutationFn: async (updatedRoles: Role[]) => {
            for (const role of updatedRoles) {
                await dbService.persistRole(role);
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['roles'] })
    });

    return {
        roles,
        setRoles: (roles: React.SetStateAction<Role[]>) => {
            if (typeof roles === 'function') {
                const next = roles(queryClient.getQueryData(['roles']) || []);
                setRolesMutation.mutate(next);
            } else {
                setRolesMutation.mutate(roles);
            }
        }
    };
};

// --- Activity Logs ---
export const useActivityLogs = (canFetch: boolean = false) => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    // Fetching is conditional. Users can always 'Create' logs, but only authorized can 'Read' all.
    const { data: activityLogs = [] } = useQuery({
        queryKey: ['activity_logs'],
        queryFn: dbService.fetchActivityLogs,
        enabled: isAuthenticated && canFetch,
        retry: false, // Don't spam if permission is denied
    });

    const addActivityLogMutation = useMutation({
        mutationFn: (variables: { type: any, description: string, userId: string }) => {
            // FIX: Retrieve staff info from query cache to avoid circular dependency with useAuth
            // and satisfy missing property requirements for ActivityLog (username, role, actionType)
            const allStaff: Staff[] = queryClient.getQueryData(['staff']) || [];
            const actor = allStaff.find(s => s.id === variables.userId);

            const logEntry: ActivityLog = {
                id: String(Date.now()),
                timestamp: new Date().toISOString(),
                userId: variables.userId || 'SYSTEM',
                username: actor?.fullName || 'System',
                role: actor?.roleId || 'System',
                type: variables.type,
                actionType: String(variables.type).toUpperCase(),
                description: variables.description
            };
            return dbService.persistActivityLog(logEntry);
        },
        onSuccess: () => {
            if (canFetch) {
                queryClient.invalidateQueries({ queryKey: ['activity_logs'] });
            }
        }
    });

    return {
        activityLogs,
        addActivityLog: (type: any, description: string, userId: string) => 
            addActivityLogMutation.mutateAsync({ type, description, userId })
    };
};

import React, { useMemo, useState } from 'react';
import { Staff, Lead, Client } from '../../types';
import { KPIDefinition } from '../../types/reports';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
// FIX: Removed DocumentCheckIcon (defined locally) and UserPlusIcon (missing in DummyIcons) from the import list. Using UsersIcon instead.
import { CheckCircleIcon, UsersIcon, MapPinIcon, BanknotesIcon } from '../icons/DummyIcons';

interface MyDailyReportProps {
    staff: Staff;
    leads: Lead[];
    clients: Client[];
    definitions: KPIDefinition[];
    onAcknowledge: (id: string, metrics: Record<string, number>) => Promise<void>;
}

export const MyDailyReport: React.FC<MyDailyReportProps> = ({ staff, leads, clients, definitions, onAcknowledge }) => {
    const [isAcknowledging, setIsAcknowledging] = useState(false);
    const [acknowledged, setAcknowledged] = useState(false);

    const todayMetrics = useMemo(() => {
        const todayStr = new Date().toISOString().split('T')[0];
        const activeDefs = definitions.filter(d => d.isActive);

        const metrics: Record<string, number> = {};

        activeDefs.forEach(def => {
            let count = 0;
            if (def.sourceModule === 'Leads') {
                count = leads.filter(l => l.assignedRepId === staff.id && l.comments.some(c => c.date.startsWith(todayStr) && c.outcomeCategory === def.outcomeTag)).length;
            } else if (def.sourceModule === 'SiteVisits') {
                count = leads.filter(l => l.assignedRepId === staff.id && l.comments.some(c => c.date.startsWith(todayStr) && c.isSiteVisitScheduled)).length;
            } else if (def.sourceModule === 'Sales') {
                count = clients.filter(c => c.officeUse.salesRep === staff.fullName && c.regDate === todayStr).length;
            } else if (def.sourceModule === 'Finance') {
                count = clients.filter(c => c.officeUse.salesRep === staff.fullName)
                    .reduce((acc, c) => acc + c.payment.paymentHistory.filter(t => t.date === todayStr && t.status === 'Success').length, 0);
            }
            metrics[def.id] = count;
        });

        return metrics;
    }, [definitions, leads, clients, staff]);

    const handleAcknowledge = async () => {
        setIsAcknowledging(true);
        try {
            await onAcknowledge(staff.id, todayMetrics);
            setAcknowledged(true);
        } finally {
            setIsAcknowledging(false);
        }
    };

    return (
        <div className="max-w-4xl mx-auto space-y-6">
            <div className="flex items-center justify-between">
                <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Today's Activity Recap</h2>
                <p className="text-sm font-bold text-gray-400">{new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' })}</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {definitions.filter(d => d.isActive).map(def => (
                    <Card key={def.id} className="p-6 border-l-4 border-l-blue-600 bg-white dark:bg-gray-800">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{def.name}</p>
                        <div className="flex items-end justify-between">
                            <h3 className="text-3xl font-black text-gray-900 dark:text-white">{todayMetrics[def.id] || 0}</h3>
                            <div className="text-right">
                                <p className="text-[9px] font-bold text-gray-500 uppercase">Weekly Target</p>
                                <p className="text-xs font-black text-blue-600">{def.targetPerWeek}</p>
                            </div>
                        </div>
                    </Card>
                ))}
            </div>

            <Card title="Quick Actions for Daily Registry" className="bg-blue-50/50 dark:bg-blue-900/10 border-dashed border-2">
                <p className="text-sm text-blue-800 dark:text-blue-300 mb-6">These actions contribute directly to your KPI counts. Counts are system-verified and cannot be edited manually.</p>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                    <button className="flex flex-col items-center gap-3 p-4 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-blue-100 hover:border-blue-500 transition-all group">
                        {/* FIX: Using UsersIcon instead of UserPlusIcon */}
                        <div className="p-3 bg-blue-100 rounded-full group-hover:scale-110 transition-transform"><UsersIcon className="w-6 h-6 text-blue-600" /></div>
                        <span className="text-[10px] font-black uppercase tracking-tighter">New Lead</span>
                    </button>
                    <button className="flex flex-col items-center gap-3 p-4 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-blue-100 hover:border-blue-500 transition-all group">
                        <div className="p-3 bg-indigo-100 rounded-full group-hover:scale-110 transition-transform"><DocumentCheckIcon className="w-6 h-6 text-indigo-600" /></div>
                        <span className="text-[10px] font-black uppercase tracking-tighter">Follow-up</span>
                    </button>
                    <button className="flex flex-col items-center gap-3 p-4 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-blue-100 hover:border-blue-500 transition-all group">
                        <div className="p-3 bg-amber-100 rounded-full group-hover:scale-110 transition-transform"><MapPinIcon className="w-6 h-6 text-amber-600" /></div>
                        <span className="text-[10px] font-black uppercase tracking-tighter">Site Visit</span>
                    </button>
                    <button className="flex flex-col items-center gap-3 p-4 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-blue-100 hover:border-blue-500 transition-all group">
                        <div className="p-3 bg-green-100 rounded-full group-hover:scale-110 transition-transform"><BanknotesIcon className="w-6 h-6 text-green-600" /></div>
                        <span className="text-[10px] font-black uppercase tracking-tighter">Payment</span>
                    </button>
                </div>
            </Card>

            <div className="flex justify-center pt-8">
                {acknowledged ? (
                    <div className="flex items-center gap-2 text-green-600 font-bold animate-in zoom-in duration-300">
                        <CheckCircleIcon className="w-6 h-6" />
                        Report Acknowledged
                    </div>
                ) : (
                    <Button 
                        size="lg" 
                        onClick={handleAcknowledge} 
                        isLoading={isAcknowledging}
                        className="px-16 py-4 text-xs font-black uppercase tracking-[0.2em] shadow-xl shadow-blue-600/20"
                    >
                        Acknowledge Daily Performance
                    </Button>
                )}
            </div>
        </div>
    );
};

