import React, { useState, useMemo, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useRoles, useClients, useLeads, useStaff, useActivityLogs } from '../../hooks/useAppData';
import { fetchKPIDefinitions, acknowledgeDailyReport } from '../../services/kpiDbService';
import { KPIDefinition } from '../../types/reports';
import { Card } from '../ui/Card';
import { Badge } from '../ui/Badge';
import { 
    ChartBarIcon, 
    ShieldCheckIcon, 
    MapPinIcon,
    LockClosedIcon,
    ExclamationTriangleIcon
} from '../icons/DummyIcons';

// Sub-Category Views
import { SalesReportsView } from '../reports/SalesReportsView';
import { AdminReportsView } from '../reports/AdminReportsView';
import { SiteReportsView } from '../reports/SiteReportsView';

type ReportCategory = 'SALES' | 'ADMIN' | 'SITE';

export const ReportsModule: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { clients } = useClients();
    const { leads } = useLeads();
    const { staff } = useStaff();
    const { addActivityLog } = useActivityLogs();

    const [activeCategory, setActiveCategory] = useState<ReportCategory | null>(null);
    const [kpiDefinitions, setKpiDefinitions] = useState<KPIDefinition[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff?.roleId)?.name, [roles, currentStaff]);
    const isCEO = userRole === 'CEO';

    // RBAC Configuration
    const categoryConfigs = useMemo(() => [
        { 
            id: 'SALES' as ReportCategory, 
            label: 'Sales Reports', 
            icon: <ChartBarIcon className="w-4 h-4" />,
            allowedRoles: ['CEO', 'Administrator', 'Head of Sales', 'Sales Representative'] 
        },
        { 
            id: 'ADMIN' as ReportCategory, 
            label: 'Admin Reports', 
            icon: <ShieldCheckIcon className="w-4 h-4" />,
            allowedRoles: ['CEO', 'Administrator', 'Chief Accountant'] 
        },
        { 
            id: 'SITE' as ReportCategory, 
            label: 'Site Reports', 
            icon: <MapPinIcon className="w-4 h-4" />,
            allowedRoles: ['CEO', 'Site Manager'] 
        }
    ], []);

    const allowedCategories = useMemo(() => {
        return categoryConfigs.filter(cat => isCEO || (userRole && cat.allowedRoles.includes(userRole)));
    }, [categoryConfigs, userRole, isCEO]);

    // Initial Loading and Landing Logic
    useEffect(() => {
        const load = async () => {
            const defs = await fetchKPIDefinitions();
            setKpiDefinitions(defs);

            // Set default category based on permissions
            if (allowedCategories.length > 0) {
                setActiveCategory(allowedCategories[0].id);
            }

            setIsLoading(false);
        };
        load();
    }, [allowedCategories]);

    const handleCategoryChange = (catId: ReportCategory) => {
        setActiveCategory(catId);
        if (currentStaff) {
            addActivityLog('View', `REPORT_SECTION_VIEWED: User accessed ${catId} category.`, currentStaff.id);
        }
    };

    if (isLoading) return <div className="p-20 text-center font-bold animate-pulse text-gray-400">AUTHORIZING SECURE REPORTS...</div>;

    if (allowedCategories.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center h-full p-12 text-center">
                <LockClosedIcon className="w-16 h-16 text-red-500 mb-4 opacity-20" />
                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase">Access Denied</h3>
                <p className="text-sm text-gray-500 max-w-xs mt-2">No report categories are available for your account role. Contact your supervisor for access.</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full overflow-hidden bg-white dark:bg-gray-800">
            {/* Category Navigation Bar */}
            <div className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-900 border-b border-gray-100 dark:border-gray-700 flex-shrink-0">
                <div className="flex items-center gap-1">
                    {categoryConfigs.map(cat => {
                        const isAllowed = isCEO || (userRole && cat.allowedRoles.includes(userRole));
                        if (!isAllowed) return null;

                        return (
                            <button
                                key={cat.id}
                                onClick={() => handleCategoryChange(cat.id)}
                                className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeCategory === cat.id ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-800'}`}
                            >
                                {cat.icon}
                                {cat.label}
                            </button>
                        );
                    })}
                </div>
                {isCEO && <Badge variant="purple">CEO OVERRIDE ENABLED</Badge>}
            </div>

            {/* Scoped Content Area */}
            <div className="flex-grow overflow-y-auto scrollbar-thin p-6">
                {!activeCategory ? (
                    <div className="flex flex-col items-center justify-center h-full opacity-30">
                        <ExclamationTriangleIcon className="w-12 h-12 mb-4" />
                        <p className="font-bold uppercase tracking-widest">Select a report category</p>
                    </div>
                ) : (
                    <div className="animate-in fade-in duration-500">
                        {activeCategory === 'SALES' && (
                            <SalesReportsView 
                                isCEO={isCEO}
                                currentStaff={currentStaff!}
                                leads={leads}
                                clients={clients}
                                staff={staff}
                                definitions={kpiDefinitions}
                            />
                        )}
                        {activeCategory === 'ADMIN' && (
                            <AdminReportsView 
                                isCEO={isCEO}
                                currentStaff={currentStaff!}
                                staff={staff}
                                roles={roles}
                            />
                        )}
                        {activeCategory === 'SITE' && (
                            <SiteReportsView 
                                isCEO={isCEO}
                                currentStaff={currentStaff!}
                                clients={clients}
                            />
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Staff, Lead, Client } from '../../types';
import { KPIDefinition } from '../../types/reports';
import { MyDailyReport } from './MyDailyReport';
import { MonthlyKPISummary } from './MonthlyKPISummary';
import { TeamKPISummary } from './TeamKPISummary';
import { KPISettings } from './KPISettings';
