import { DocumentTextIcon, ChartBarIcon, UsersIcon, Cog6ToothIcon } from '../icons/DummyIcons';

interface SalesReportsViewProps {
    isCEO: boolean;
    currentStaff: Staff;
    leads: Lead[];
    clients: Client[];
    staff: Staff[];
    definitions: KPIDefinition[];
}

export const SalesReportsView: React.FC<SalesReportsViewProps> = ({ 
    isCEO, currentStaff, leads, clients, staff, definitions 
}) => {
    const [subTab, setSubTab] = useState<'daily' | 'monthly' | 'team' | 'settings'>('daily');

    const tabs = [
        { id: 'daily', label: 'My Progress', icon: <DocumentTextIcon className="w-4 h-4" /> },
        { id: 'monthly', label: 'Personal History', icon: <ChartBarIcon className="w-4 h-4" /> },
        { id: 'team', label: 'Team Comparison', icon: <UsersIcon className="w-4 h-4" />, ceoOnly: true },
        { id: 'settings', label: 'KPI Configuration', icon: <Cog6ToothIcon className="w-4 h-4" />, ceoOnly: true },
    ];

    return (
        <div className="space-y-6">
            <div className="flex border-b border-gray-100 dark:border-gray-700">
                {tabs.map(tab => {
                    if (tab.ceoOnly && !isCEO && currentStaff.roleId !== 'Head of Sales') return null;
                    return (
                        <button
                            key={tab.id}
                            onClick={() => setSubTab(tab.id as any)}
                            className={`px-6 py-3 text-xs font-bold uppercase tracking-tighter border-b-2 transition-all flex items-center gap-2 ${subTab === tab.id ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
                        >
                            {tab.icon}
                            {tab.label}
                        </button>
                    );
                })}
            </div>

            <div className="pt-4">
                {subTab === 'daily' && (
                    <MyDailyReport 
                        staff={currentStaff} 
                        leads={leads} 
                        clients={clients} 
                        definitions={definitions} 
                        onAcknowledge={acknowledgeDailyReport}
                    />
                )}
                {subTab === 'monthly' && (
                    <MonthlyKPISummary 
                        staffId={currentStaff.id}
                        leads={leads}
                        clients={clients}
                        definitions={definitions}
                    />
                )}
                {subTab === 'team' && (
                    <TeamKPISummary 
                        staffList={staff}
                        leads={leads}
                        clients={clients}
                        definitions={definitions}
                    />
                )}
                {subTab === 'settings' && (
                    <KPISettings 
                        definitions={definitions} 
                        onUpdate={() => {}}
                    />
                )}
            </div>
        </div>
    );
};

