interface SiteReportsViewProps {
    isCEO: boolean;
    currentStaff: any;
    clients: Client[];
}

export const SiteReportsView: React.FC<SiteReportsViewProps> = ({ isCEO, clients }) => {
    const siteStats = useMemo(() => {
        const allocated = clients.filter(c => c.allocationStatus === 'ALLOCATED');
        const pending = clients.filter(c => c.paidPercent && c.paidPercent >= 70 && c.allocationStatus !== 'ALLOCATED');

        return { allocated, pending };
    }, [clients]);

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Card title="Physical Allocation Summary" icon={<MapPinIcon className="w-5 h-5 text-red-600" />}>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="p-4 bg-green-50 dark:bg-green-900/10 rounded-xl border border-green-100">
                            <p className="text-[10px] font-black text-green-600 uppercase">Confirmed</p>
                            <p className="text-2xl font-black">{siteStats.allocated.length}</p>
                        </div>
                        <div className="p-4 bg-amber-50 dark:bg-amber-900/10 rounded-xl border border-amber-100">
                            <p className="text-[10px] font-black text-amber-600 uppercase">Awaiting Site Visit</p>
                            <p className="text-2xl font-black">{siteStats.pending.length}</p>
                        </div>
                    </div>
                </Card>
            </div>

            <Card title="Pending Field Verification Queue" icon={<UserCheckIcon className="w-5 h-5 text-blue-600" />}>
                <TableContainer className="border-0 shadow-none">
                    <table className="w-full text-xs text-left">
                        <Thead>
                            <tr>
                                <Th>Client Name</Th>
                                <Th>Location</Th>
                                <Th>Reserved Plot</Th>
                                <Th className="text-right">Paid %</Th>
                            </tr>
                        </Thead>
                        <Tbody>
                            {siteStats.pending.map(c => (
                                <Tr key={c.id}>
                                    <Td className="font-bold">{c.name}</Td>
                                    <Td>{c.location}</Td>
                                    <Td className="font-mono text-blue-600">{c.plot}</Td>
                                    <Td className="text-right font-black">{Math.round(c.paidPercent || 0)}%</Td>
                                </Tr>
                            ))}
                            {siteStats.pending.length === 0 && (
                                <Tr><Td colSpan={4} className="text-center py-10 text-gray-400 italic">Queue is currently clear.</Td></Tr>
                            )}
                        </Tbody>
                    </table>
                </TableContainer>
            </Card>
        </div>
    );
};

