const SupportPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { openModal } = useModal();

    const [documents, setDocuments] = useState<SupportDocument[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [isLoading, setIsLoading] = useState(true);

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff?.roleId)?.name, [roles, currentStaff]);
    const isCEO = userRole === 'CEO' || userRole === 'Administrator';

    useEffect(() => {
        const unsubscribe = listenToSupportDocs((docs) => {
            setDocuments(docs);
            setIsLoading(false);
        });
        return () => unsubscribe();
    }, []);

    const filteredDocs = useMemo(() => {
        return documents.filter(doc => 
            doc.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            doc.fileName.toLowerCase().includes(searchQuery.toLowerCase())
        );
    }, [documents, searchQuery]);

    const handleDownload = (doc: SupportDocument) => {
        if (currentStaff) logDocDownload(doc, currentStaff);
        window.open(doc.fileUrl, '_blank');
    };

    const handleDelete = (doc: SupportDocument) => {
        if (!currentStaff) return;
        if (window.confirm(`Are you sure you want to permanently delete "${doc.title}"?`)) {
            removeSupportDoc(doc.id, doc.title, currentStaff);
        }
    };

    const formatSize = (bytes: number) => {
        if (bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">System Support Assets</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Official documentation and workflow guidelines curated by management.</p>
                </div>
                <div className="flex items-center gap-3">
                    {isCEO && (
                        <Button 
                            onClick={() => openModal(MODAL_TYPES.SUPPORT_UPLOAD)} 
                            icon={<PlusCircleIcon className="w-5 h-5" />}
                        >
                            Upload Asset
                        </Button>
                    )}
                    <div className="flex items-center gap-2 text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 px-4 py-2 rounded-full border border-blue-100 dark:border-blue-800">
                        <QuestionMarkCircleIcon className="w-5 h-5" />
                        <span className="text-sm font-bold uppercase tracking-widest">Help Center</span>
                    </div>
                </div>
            </div>

            <Card className="p-4">
                <div className="relative max-w-md">
                    <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                    <input 
                        type="text" 
                        placeholder="Filter by document title or filename..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                </div>
            </Card>

            <TableContainer>
                <table className="w-full text-sm text-left border-collapse">
                    <Thead>
                        <tr className="bg-gray-50 dark:bg-gray-900 text-gray-400">
                            <Th className="py-4">Document Title & Description</Th>
                            <Th className="hidden lg:table-cell">File Information</Th>
                            <Th className="hidden md:table-cell">Uploaded Date</Th>
                            <Th className="text-right">Actions</Th>
                        </tr>
                    </Thead>
                    <Tbody>
                        {isLoading ? (
                            <Tr><Td colSpan={4} className="py-20 text-center animate-pulse font-bold text-gray-400 uppercase tracking-widest">Fetching Secure Assets...</Td></Tr>
                        ) : filteredDocs.length === 0 ? (
                            <Tr>
                                <Td colSpan={4} className="py-20 text-center">
                                    <DocumentTextIcon className="w-16 h-16 text-gray-100 mx-auto mb-4" />
                                    <p className="text-gray-400 italic">No support documents available matching your criteria.</p>
                                </Td>
                            </Tr>
                        ) : filteredDocs.map(doc => (
                            <Tr key={doc.id} className="group hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                <Td className="py-5">
                                    <div className="flex flex-col">
                                        <span className="font-black text-gray-900 dark:text-white uppercase tracking-tight">{doc.title}</span>
                                        {doc.description && <span className="text-xs text-gray-500 mt-1 line-clamp-1">{doc.description}</span>}
                                        <div className="lg:hidden mt-2 flex items-center gap-2">
                                            <Badge variant="neutral" className="text-[10px]">{doc.fileType.toUpperCase()}</Badge>
                                            <span className="text-[10px] text-gray-400 font-bold">{formatSize(doc.fileSize)}</span>
