                                                >
                                                    <TrashIcon className="w-5 h-5" />
                                                </button>
                                            </>
                                        )}
                                        <button 
                                            onClick={() => handleDownload(doc)}
                                            className="ml-2 flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-black uppercase tracking-widest shadow-md transition-all active:scale-95 group/btn"
                                            title={`Download: ${doc.title}`}
                                        >
                                            <ArrowDownTrayIcon className="w-4 h-4 group-hover/btn:translate-y-0.5 transition-transform" />
                                            <span className="hidden sm:inline">Download</span>
                                        </button>
                                    </div>
                                </Td>
                            </Tr>
                        ))}
                    </Tbody>
                </table>
            </TableContainer>

            <div className="p-6 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-900/30 flex items-center gap-4">
                <LockClosedIcon className="w-8 h-8 text-blue-600 opacity-20" />
