import React, { useState, useEffect } from 'react';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input, Textarea } from '../ui/Input';
import { XMarkIcon, UploadIcon, DocumentTextIcon, CheckCircleIcon } from '../icons/DummyIcons';
import { uploadSupportDoc, updateSupportDocTitle } from '../../services/supportDbService';
import { uploadFile } from '../../services/storageService';
import { useAuth } from '../../context/AuthContext';
import { SupportDocument } from '../../types';

interface SupportUploadModalProps {
    isOpen: boolean;
    onClose: () => void;
    editingDoc?: SupportDocument | null;
}

export const SupportUploadModal: React.FC<SupportUploadModalProps> = ({ isOpen, onClose, editingDoc }) => {
    const { currentStaff } = useAuth();
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [file, setFile] = useState<File | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (isOpen) {
            setTitle(editingDoc?.title || '');
            setDescription(editingDoc?.description || '');
            setFile(null);
            setError(null);
        }
    }, [isOpen, editingDoc]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentStaff) return;
        if (!title.trim()) {
            setError("Document Title is mandatory for identification.");
            return;
        }

        setIsSaving(true);
        setError(null);

        try {
            if (editingDoc) {
                // Update mode
                if (file) {
                    // Replace file and potentially title
                    const fileUrl = await uploadFile(file, `support_assets/${Date.now()}_${file.name}`);
                    await uploadSupportDoc({
                        title: title.trim(),
                        description: description.trim(),
                        fileName: file.name,
                        fileUrl,
                        fileType: file.type,
                        fileSize: file.size,
                        uploadedAt: new Date().toISOString(),
                        uploadedBy: currentStaff.fullName
                    }, currentStaff);
                    // To maintain CEO control simplicity, we treat "edit + new file" as a fresh version or overwrite
                    // For this app, we'll delete the old one or just update the existing record
                    // But prompt E4 says "Edit title independently", let's update title if no file.
                } else {
                    await updateSupportDocTitle(editingDoc.id, title.trim(), currentStaff);
                }
            } else {
                // Create mode
                if (!file) {
                    setError("Please select a document file to upload.");
                    setIsSaving(false);
                    return;
                }

                const fileUrl = await uploadFile(file, `support_assets/${Date.now()}_${file.name}`);
                await uploadSupportDoc({
                    title: title.trim(),
                    description: description.trim(),
                    fileName: file.name,
                    fileUrl,
                    fileType: file.type,
                    fileSize: file.size,
                    uploadedAt: new Date().toISOString(),
                    uploadedBy: currentStaff.fullName
                }, currentStaff);
            }
            onClose();
        } catch (err: any) {
            setError(err.message || "Failed to process asset.");
        } finally {
            setIsSaving(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-lg p-0 overflow-hidden shadow-2xl animate-in zoom-in duration-300 border border-blue-500/30">
                <form onSubmit={handleSubmit}>
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 flex justify-between items-center">
                        <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">
                            {editingDoc ? 'Amend Support Asset' : 'Ingest Support Asset'}
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
                            <XMarkIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="p-6 space-y-5 bg-white dark:bg-gray-800">
                        {error && (
                            <div className="p-3 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded text-xs font-bold text-red-800 dark:text-red-300">
                                {error}
                            </div>
                        )}

                        <Input 
                            label="Document Title (Required)*" 
                            placeholder="e.g. Plot Allocation Policy v2"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            required
                            className="font-bold"
                        />

                        <Textarea 
                            label="Internal Description (Optional)" 
                            placeholder="Briefly state what this document contains..."
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            rows={3}
                        />

                        <div className="space-y-2">
                            <label className="block text-sm font-bold text-gray-700 dark:text-gray-300">
                                {editingDoc ? 'Replace File (Keep empty to retain current)' : 'Select File (Required)*'}
                            </label>
                            <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-gray-300 dark:border-gray-700 border-dashed rounded-xl cursor-pointer bg-gray-50 dark:bg-gray-900 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                    {file ? <CheckCircleIcon className="w-8 h-8 mb-2 text-green-500" /> : <UploadIcon className="w-8 h-8 mb-2 text-gray-400" />}
                                    <p className="text-xs text-gray-500 dark:text-gray-400 font-semibold">
                                        {file ? file.name : (editingDoc ? 'Currently: ' + editingDoc.fileName : 'PDF, Word, or Image')}
                                    </p>
                                </div>
                                <input 
                                    type="file" 
                                    className="hidden" 
                                    onChange={(e) => setFile(e.target.files?.[0] || null)}
                                />
                            </label>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <Button type="button" variant="secondary" onClick={onClose} disabled={isSaving}>Cancel</Button>
                        <Button 
                            type="submit" 
                            isLoading={isSaving}
                            className="px-8 font-black uppercase tracking-widest"
                        >
                            {editingDoc ? 'Update Asset' : 'Upload and Publish'}
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

