service firebase.storage {
  match /b/{bucket}/o {

    // Helper function to check auth
    function isAuthenticated() {
      return request.auth != null;
    }

    // Support documents only
    match /support_assets/{allPaths=**} {
      allow read: if request.auth != null;
      allow write: if request.auth != null
                   && request.auth.token.role == "CEO";
    }

    // --- System Branding (Logos, Favicons) ---
    match /system/branding/{allPaths=**} {
      allow read: if true; 
      allow write: if isAuthenticated();
    }

    // --- Staff Profile Photos ---
    match /staff/{userId}/{allPaths=**} {
      allow read: if isAuthenticated();
      allow write: if isAuthenticated();
    }

    // --- Client Files (Photos, Documents) ---
    match /clients/{clientId}/{allPaths=**} {
      allow read, write: if isAuthenticated();
    }

    // --- Property Documents (Legal, Plans) ---
    match /properties/{propertyId}/{allPaths=**} {
      allow read, write: if isAuthenticated();
    }

    // --- Promotion Banners ---
    match /promotions/{allPaths=**} {
      allow read, write: if isAuthenticated();
    }

    // --- Amendment Request Scans ---
    match /amendments/{allPaths=**} {
      allow read, write: if isAuthenticated();
    }
  }
}

// @ts-ignore
import { createUserWithEmailAndPassword, deleteUser, signOut, signInWithEmailAndPassword } from "firebase/auth";
import { doc, setDoc, serverTimestamp, getDoc } from "firebase/firestore";
import { httpsCallable } from "firebase/functions";
import { secondaryAuth, db, auth, functions } from "./firebase";

/**
 * Normalizes email strings to prevent login mismatches (trailing spaces, casing)
 */
export const normalizeEmail = (email: string) => email.trim().toLowerCase();

/**
 * Authenticates a user with the primary Firebase instance.
 */
export const loginWithEmail = async (email: string, password: string) => {
    try {
        const normalized = normalizeEmail(email);
        const userCredential = await signInWithEmailAndPassword(auth, normalized, password);
        return userCredential.user;
    } catch (error: any) {
        console.error("Authentication Phase Failed:", error.code);
        if (error.code === 'auth/invalid-credential' || error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password') {
            throw new Error("INVALID_CREDENTIALS");
        }
        throw error;
    }
};

/**
 * Sets custom claims for a user via backend Cloud Function.
 * Required for Firebase Storage role-based rules.
 */
export const syncUserCustomClaims = async (uid: string) => {
    try {
        const setClaims = httpsCallable(functions, 'setUserCustomClaims');
        await setClaims({ uid });
    } catch (error) {
        console.error("Failed to sync custom claims:", error);
    }
};

/**
 * Registers a new staff member atomically.
 */
export const registerStaffAccount = async (staffData: {
    email: string;
    password: string;
    fullName: string;
    roleId: string;
    phone?: string;
}) => {
    const email = normalizeEmail(staffData.email);
    let createdUser: any = null;

    try {
        // 1. Create Auth Identity
        const userCredential = await createUserWithEmailAndPassword(secondaryAuth, email, staffData.password);
        createdUser = userCredential.user;

        // 2. Prepare Firestore Profile
        const nameParts = staffData.fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();

        const userProfile = {
            id: createdUser.uid,
            uid: createdUser.uid,
            fullName: staffData.fullName,
            initials,
            email: email,
            phone: staffData.phone || '',
            roleId: staffData.roleId,
            status: 'Active',
            createdAt: serverTimestamp(),
            lastLogin: 'Never'
        };

        // 3. Persist Profile
        await setDoc(doc(db, "user", createdUser.uid), userProfile);

        // 4. Synchronize Custom Claims (Critical for Storage Permissions)
        if (staffData.roleId === 'CEO') {
            await syncUserCustomClaims(createdUser.uid);
        }

        // 5. State Cleanup
        await signOut(secondaryAuth);

        return { success: true, user: createdUser };
    } catch (error: any) {
        console.error("Atomic Registration Failure:", error);
        if (createdUser) {
            try {
                await deleteUser(createdUser);
            } catch (cleanupError) {
                console.error("Integrity Error: Orphaned Auth account exists.", cleanupError);
            }
        }
        throw error;
    }
};

/**
 * Updates a staff member's password.
 */
export const updateStaffPassword = async (uid: string, password: string) => {
    try {
        const updatePasswordFunc = httpsCallable(functions, 'updateUserPassword');
        await updatePasswordFunc({ uid, password });
        return { success: true };
    } catch (error: any) {
        console.error("Password Update Failed:", error);
        throw new Error(error.message || "Failed to update password via secure backend.");
    }
};

import React, { useState, useEffect } from 'react';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input, Textarea } from '../ui/Input';
import { XMarkIcon, UploadIcon, DocumentTextIcon, CheckCircleIcon } from '../icons/DummyIcons';
import { uploadSupportDoc, updateSupportDocTitle } from '../../services/supportDbService';
import { uploadFile } from '../../services/storageService';
import { useAuth } from '../../context/AuthContext';
import { SupportDocument } from '../../types';
import { auth } from '../../services/firebase';

interface SupportUploadModalProps {
    isOpen: boolean;
    onClose: () => void;
    editingDoc?: SupportDocument | null;
}

export const SupportUploadModal: React.FC<SupportUploadModalProps> = ({ isOpen, onClose, editingDoc }) => {
    const { currentStaff } = useAuth();
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [file, setFile] = useState<File | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (isOpen) {
            setTitle(editingDoc?.title || '');
            setDescription(editingDoc?.description || '');
            setFile(null);
            setError(null);
        }
    }, [isOpen, editingDoc]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        // Step 1: Authentication Phase Gate
        if (!auth.currentUser) {
            setError("You must be signed in to upload documents.");
            return;
        }

        if (!currentStaff) return;

        if (!title.trim()) {
            setError("Document Title is mandatory for identification.");
            return;
        }

        setIsSaving(true);
        setError(null);

        try {
            if (editingDoc) {
                // Update mode
                if (file) {
                    const fileUrl = await uploadFile(file, `support_assets/${Date.now()}_${file.name}`);
                    await uploadSupportDoc({
                        title: title.trim(),
                        description: description.trim(),
                        fileName: file.name,
                        fileUrl,
                        fileType: file.type,
                        fileSize: file.size,
                        uploadedAt: new Date().toISOString(),
                        uploadedBy: currentStaff.fullName
                    }, currentStaff);
                } else {
                    await updateSupportDocTitle(editingDoc.id, title.trim(), currentStaff);
                }
            } else {
                // Create mode
                if (!file) {
                    setError("Please select a document file to upload.");
                    setIsSaving(false);
                    return;
                }

                // Authority Check: Storage Permissions reside in custom claims
                const fileUrl = await uploadFile(file, `support_assets/${Date.now()}_${file.name}`);
                await uploadSupportDoc({
                    title: title.trim(),
                    description: description.trim(),
                    fileName: file.name,
                    fileUrl,
                    fileType: file.type,
                    fileSize: file.size,
                    uploadedAt: new Date().toISOString(),
                    uploadedBy: currentStaff.fullName
                }, currentStaff);
            }
            onClose();
        } catch (err: any) {
            if (err.code === 'storage/unauthorized') {
                setError("Access Denied: Only the CEO can upload support documents. If you are the CEO, please sign out and sign in again to refresh your credentials.");
            } else {
                setError(err.message || "Failed to process asset.");
            }
        } finally {
            setIsSaving(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-lg p-0 overflow-hidden shadow-2xl animate-in zoom-in duration-300 border border-blue-500/30">
                <form onSubmit={handleSubmit}>
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 flex justify-between items-center">
                        <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">
                            {editingDoc ? 'Amend Support Asset' : 'Ingest Support Asset'}
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
                            <XMarkIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="p-6 space-y-5 bg-white dark:bg-gray-800">
                        {error && (
                            <div className="p-3 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded text-xs font-bold text-red-800 dark:text-red-300 leading-relaxed">
                                {error}
                            </div>
                        )}

                        <Input 
                            label="Document Title (Required)*" 
                            placeholder="e.g. Plot Allocation Policy v2"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            required
                            className="font-bold"
                            disabled={isSaving}
                        />

                        <Textarea 
                            label="Internal Description (Optional)" 
                            placeholder="Briefly state what this document contains..."
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            rows={3}
                            disabled={isSaving}
                        />

                        <div className="space-y-2">
                            <label className="block text-sm font-bold text-gray-700 dark:text-gray-300">
                                {editingDoc ? 'Replace File (Keep empty to retain current)' : 'Select File (Required)*'}
                            </label>
                            <label className={`flex flex-col items-center justify-center w-full h-32 border-2 border-gray-300 dark:border-gray-700 border-dashed rounded-xl transition-colors ${isSaving ? 'cursor-not-allowed opacity-50' : 'cursor-pointer bg-gray-50 dark:bg-gray-900 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>
                                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                    {file ? <CheckCircleIcon className="w-8 h-8 mb-2 text-green-500" /> : <UploadIcon className="w-8 h-8 mb-2 text-gray-400" />}
                                    <p className="text-xs text-gray-500 dark:text-gray-400 font-semibold">
                                        {file ? file.name : (editingDoc ? 'Currently: ' + editingDoc.fileName : 'PDF, Word, or Image')}
                                    </p>
                                </div>
                                <input 
                                    type="file" 
                                    className="hidden" 
                                    onChange={(e) => setFile(e.target.files?.[0] || null)}
                                    disabled={isSaving}
                                />
                            </label>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <Button type="button" variant="secondary" onClick={onClose} disabled={isSaving}>Cancel</Button>
                        <Button 
                            type="submit" 
                            isLoading={isSaving}
                            className="px-8 font-black uppercase tracking-widest"
                        >
                            {editingDoc ? 'Update Asset' : 'Upload and Publish'}
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

