    const [isRefreshingToken, setIsRefreshingToken] = useState(true);

    // AUTHORITY RULE: Strict CEO Gating
    // Uses roleId directly for deterministic check to avoid async name-lookup delays
    const isCEO = currentStaff?.roleId === 'CEO';

    useEffect(() => {
        // Sync Phase: Force refresh token to pick up new Custom Claims (role: "CEO")
        const syncPermissions = async () => {
            if (auth.currentUser) {
                try {
                    await auth.currentUser.getIdToken(true);
                } catch (e) {
                    console.error("Permission sync failed", e);
                }
            }
            setIsRefreshingToken(false);
        };

        syncPermissions();

        const unsubscribe = listenToSupportDocs((docs) => {
            setDocuments(docs);
            setIsLoading(false);
        });
        return () => unsubscribe();
    }, []);

    const filteredDocs = useMemo(() => {
        return documents.filter(doc => 
            doc.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            doc.fileName.toLowerCase().includes(searchQuery.toLowerCase())
        );
    }, [documents, searchQuery]);

