export const persistActivityLog = async (log: ActivityLog) => {
    await setDoc(doc(db, LOGS_COL, String(log.id)), sanitizeData(log));
};

export const fetchRoles = async () => {
    const snapshot = await getDocs(collection(db, ROLES_COL));
    return snapshot.docs.map(doc => doc.data() as Role);
};
export const persistRole = async (role: Role) => {
    await setDoc(doc(db, ROLES_COL, String(role.id)), sanitizeData(role));
};
export const fetchCompanySettings = async (): Promise<CompanySettings> => {
    const docSnap = await getDoc(doc(db, SETTINGS_COL, 'main'));
    return docSnap.exists() ? docSnap.data() as CompanySettings : COMPANY_SETTINGS;
};
export const persistCompanySettings = async (settings: CompanySettings) => {
    await setDoc(doc(db, SETTINGS_COL, 'main'), sanitizeData(settings));
};
export const listenToRolePermissions = (onUpdate: (perms: RolePermission[]) => void) => {
    return onSnapshot(collection(db, PERMISSIONS_COL), (snapshot) => {
        const allPerms: RolePermission[] = [];
        snapshot.docs.forEach(doc => {
            const data = doc.data();
            if (data.modules) {
                Object.entries(data.modules).forEach(([moduleId, permissions]) => {
                    allPerms.push({ roleId: doc.id, moduleId: moduleId as AppModuleName, permissions: permissions as PermissionSet });
                });
            }
        });
        onUpdate(allPerms);
    });
};
export const updateRolePermissionInDb = async (roleId: string, moduleId: string, permission: string, value: boolean) => {
    await updateDoc(doc(db, PERMISSIONS_COL, roleId), { [`modules.${moduleId}.${permission}`]: value });
};
export const initRolePermissions = async (roleId: string) => {
    const defaultPermissions: Record<string, PermissionSet> = {};
    APP_MODULES.forEach(m => { defaultPermissions[m.id] = { view: false, create: false, edit: false, delete: false, approve: false }; });
    await setDoc(doc(db, PERMISSIONS_COL, roleId), { modules: defaultPermissions }, { merge: true });
};

import { db } from './firebase';
import { collection, addDoc, updateDoc, doc, deleteDoc, onSnapshot, query, where, arrayUnion } from 'firebase/firestore';
import { InternalMail } from '../types';
import { sanitizeData } from './utils';

const MAILS_COL = 'internal_mails';

export const sendInternalMail = async (mailData: Omit<InternalMail, 'id'>) => {
    // Ensure participants array is populated for querying
    const participants = Array.from(new Set([mailData.senderId, ...mailData.recipientIds]));

    // Sanitize data before sending to Firestore
    const cleanedMailData = sanitizeData({
        ...mailData,
        participants,
        timestamp: new Date().toISOString()
    });

    await addDoc(collection(db, MAILS_COL), cleanedMailData);
};

export const listenToInbox = (userId: string, onUpdate: (mails: InternalMail[]) => void) => {
    const q = query(
        collection(db, MAILS_COL),
        where('participants', 'array-contains', userId)
    );

    return onSnapshot(q, (snapshot) => {
        const mails = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as InternalMail));
        mails.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        onUpdate(mails);
    }, (error) => {
        console.error("Error listening to mails:", error);
    });
};

export const markMailRead = async (mailId: string, userId: string) => {
    const ref = doc(db, MAILS_COL, mailId);
    await updateDoc(ref, {
        readBy: arrayUnion(userId)
    });
};

export const toggleMailDeleteStatus = async (mailId: string, isDeleted: boolean) => {
    const ref = doc(db, MAILS_COL, mailId);
    await updateDoc(ref, { isDeleted });
};

export const permanentlyDeleteMail = async (mailId: string) => {
    await deleteDoc(doc(db, MAILS_COL, mailId));
};

import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { auth } from '../../services/firebase';
import { AmendmentRequest, CompanySettings } from '../../types';
import { sanitizeData } from '../../services/utils';

// --- Amendments ---
export const useAmendments = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: amendments = [] } = useQuery({
        queryKey: ['amendments'],
        queryFn: dbService.fetchAmendments,
        enabled: isAuthenticated,
    });

    const setAmendmentListMutation = useMutation({
        mutationFn: async (updated: AmendmentRequest[]) => {
            for (const item of updated) {
                await dbService.persistAmendment(item);
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['amendments'] })
    });

    return {
        amendments,
        setAmendmentList: (amendments: React.SetStateAction<AmendmentRequest[]>) => {
            if (typeof amendments === 'function') {
                const next = amendments(queryClient.getQueryData(['amendments']) || []);
                setAmendmentListMutation.mutate(next);
            } else {
                setAmendmentListMutation.mutate(amendments);
            }
        }
    };
};

// --- Company Settings ---
const SETTINGS_STORAGE_KEY = 'faim_app_settings_cache';

const getStoredSettings = (): CompanySettings | undefined => {
    if (typeof window === 'undefined') return undefined;
    try {
        const stored = localStorage.getItem(SETTINGS_STORAGE_KEY);
        return stored ? JSON.parse(stored) : undefined;
    } catch (e) {
        console.warn("Failed to load cached settings", e);
        return undefined;
    }
};

export const useCompanySettings = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: companySettings = { name: 'FAIM' } } = useQuery({
        queryKey: ['company_settings'],
        queryFn: async () => {
            const settings = await dbService.fetchCompanySettings();
            // Sanitize before stringifying for LocalStorage
            localStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(sanitizeData(settings)));
            return settings;
        },
        initialData: getStoredSettings(),
        enabled: true, 
        staleTime: 1000 * 60 * 5,
    });

    const setCompanySettingsMutation = useMutation({
        mutationFn: async (settings: React.SetStateAction<CompanySettings>) => {
            const next = typeof settings === 'function' 
                ? settings(queryClient.getQueryData(['company_settings']) || { name: 'FAIM' }) 
                : settings;

            // Sanitize before stringifying for LocalStorage
            localStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(sanitizeData(next)));

            await dbService.persistCompanySettings(next);
            return next;
        },
        onSuccess: (data) => {
            queryClient.setQueryData(['company_settings'], data);
            queryClient.invalidateQueries({ queryKey: ['company_settings'] });
        }
    });

    return {
        companySettings,
        setCompanySettings: (settings: React.SetStateAction<CompanySettings>) => 
            setCompanySettingsMutation.mutateAsync(settings)
    };
};

import React, { useState, useMemo } from 'react';
