                                </div>
                            </div>

                            <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3 flex-shrink-0">
                                <Button type="button" variant="secondary" onClick={() => setModalOpen(false)}>Cancel</Button>
                                <Button type="submit" form="new-event-form" isLoading={isSaving}>Save and Broadcast</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

export default EventsPage;

/**
 * Centralized sanitizer to prevent "cyclic object value" and "Converting circular structure to JSON" errors.
 * Ensures data is safe for Firestore persistence and JSON.stringify (LocalStorage).
 */
export const sanitizeData = (data: any, seen = new WeakSet()): any => {
    // Handle primitives and null/undefined
    if (data === null || typeof data !== 'object') {
        return data === undefined ? null : data;
    }

    // Break circular references
    if (seen.has(data)) {
        return "[Circular Reference]";
    }

    // Handle common non-plain objects
    if (data instanceof Date) {
        return data.toISOString();
    }

    if (data instanceof Error) {
        return {
            name: data.name,
            message: data.message,
            stack: data.stack
        };
    }

    // Track this object to detect cycles
    seen.add(data);

    // Handle Arrays
    if (Array.isArray(data)) {
        return data.map(item => sanitizeData(item, seen));
    }

    // Handle Blobs/Files (cannot be serialized to Firestore directly)
    if (typeof Blob !== 'undefined' && data instanceof Blob) {
        // FIX: Cast to any because 'name' exists on File (which is a subclass of Blob) but is not defined on the base Blob type in TypeScript.
        const fileName = (data as any).name || 'binary data';
        return `[File/Blob: ${fileName}]`;
    }

    // Plain Objects
    const sanitizedObj: any = {};

    // Only process enumerable own properties
    Object.keys(data).forEach(key => {
        const value = data[key];

        // Skip functions and React internals
        if (typeof value === 'function' || key.startsWith('$$') || key.startsWith('_')) {
            return;
        }

        sanitizedObj[key] = sanitizeData(value, seen);
    });

    return sanitizedObj;
};

