service cloud.firestore {
  match /databases/{database}/documents {

    // --- Helper Functions ---

    function isUserAuthenticated() {
      return request.auth != null && request.auth.uid != null;
    }

    function getRole() {
      return isUserAuthenticated() && exists(/databases/$(database)/documents/user/$(request.auth.uid)) 
        ? get(/databases/$(database)/documents/user/$(request.auth.uid)).data.roleId 
        : null;
    }

    function isCEO() {
      return getRole() == 'CEO';
    }

    function can(module, action) {
      let role = getRole();
      return role != null && 
             exists(/databases/$(database)/documents/role_permissions/$(role)) && 
             get(/databases/$(database)/documents/role_permissions/$(role)).data.modules[module][action] == true;
    }

    // --- Collection Rules ---

    match /settings/{docId} {
      allow read: if true; 
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /user/{userId} {
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated() && (isCEO() || can('Settings', 'create'));
      allow update: if isUserAuthenticated() && (request.auth.uid == userId || isCEO() || can('Settings', 'edit'));
      allow delete: if isUserAuthenticated() && (isCEO() || can('Settings', 'delete'));
    }

    match /roles/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /role_permissions/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isUserAuthenticated() && (isCEO() || can('Settings', 'edit'));
    }

    match /activity_logs/{logId} {
      // Allow read for authenticated users to avoid glitches, logic can filter in UI
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated();
      allow update, delete: if false;
