import { db, auth } from './firebase';
import { collection, getDocs, doc, setDoc, deleteDoc, query, orderBy, onSnapshot } from 'firebase/firestore';
import { SupportDocument, Staff } from '../types';
import { persistActivityLog } from './adminDbService';
// @ts-ignore
import { onAuthStateChanged } from 'firebase/auth';

const DOCS_COL = 'support_documents';

export const fetchSupportDocuments = async (): Promise<SupportDocument[]> => {
    const q = query(collection(db, DOCS_COL), orderBy('uploadedAt', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => doc.data() as SupportDocument);
};

export const listenToSupportDocs = (onUpdate: (docs: SupportDocument[]) => void) => {
    let unsubscribeSnapshot: (() => void) | null = null;

    // Use auth observer to ensure we only listen when actually authenticated
    const unsubscribeAuth = onAuthStateChanged(auth, (user: any) => {
        if (user) {
            const q = query(collection(db, DOCS_COL), orderBy('uploadedAt', 'desc'));
            unsubscribeSnapshot = onSnapshot(q, 
                (snapshot) => {
                    onUpdate(snapshot.docs.map(d => d.data() as SupportDocument));
                },
                (error) => {
                    console.error("Support listener failure:", error);
                }
            );
        } else {
            if (unsubscribeSnapshot) {
                unsubscribeSnapshot();
                unsubscribeSnapshot = null;
            }
        }
    });

    return () => {
        unsubscribeAuth();
        if (unsubscribeSnapshot) unsubscribeSnapshot();
    };
};

export const uploadSupportDoc = async (docData: Omit<SupportDocument, 'id'>, user: Staff) => {
    if (!docData.title) throw new Error("Document title is mandatory.");

    const docId = `SDOC-${Date.now()}`;
    const newDoc: SupportDocument = { ...docData, id: docId };

    await setDoc(doc(db, DOCS_COL, docId), newDoc);

    await persistActivityLog({
        id: `LOG-SDOC-${Date.now()}`,
        userId: user.id,
        username: user.fullName,
        role: user.roleId,
        type: 'Create',
        actionType: 'SUPPORT_DOC_UPLOADED',
        entityType: 'SupportDoc',
        entityId: docId,
        description: `CEO uploaded new support document: "${newDoc.title}"`,
        timestamp: new Date().toISOString()
    });

    return newDoc;
};

export const updateSupportDocTitle = async (docId: string, newTitle: string, user: Staff) => {
    const ref = doc(db, DOCS_COL, docId);
    await setDoc(ref, { title: newTitle }, { merge: true });

    await persistActivityLog({
        id: `LOG-SDOC-${Date.now()}`,
        userId: user.id,
        username: user.fullName,
        role: user.roleId,
        type: 'Update',
        actionType: 'SUPPORT_DOC_TITLE_UPDATED',
        entityType: 'SupportDoc',
        entityId: docId,
        description: `Support document title updated to: "${newTitle}"`,
        timestamp: new Date().toISOString()
    });
};

export const logDocDownload = async (document: SupportDocument, user: Staff) => {
    await persistActivityLog({
        id: `LOG-SDOC-DL-${Date.now()}`,
        userId: user.id,
        username: user.fullName,
        role: user.roleId,
        type: 'Download',
        actionType: 'SUPPORT_DOC_DOWNLOADED',
        entityType: 'SupportDoc',
        entityId: document.id,
        description: `User downloaded support document: "${document.title}"`,
        timestamp: new Date().toISOString()
    });
};

export const removeSupportDoc = async (docId: string, title: string, user: Staff) => {
    await deleteDoc(doc(db, DOCS_COL, docId));

    await persistActivityLog({
        id: `LOG-SDOC-DEL-${Date.now()}`,
        userId: user.id,
        username: user.fullName,
        role: user.roleId,
        type: 'Delete',
        actionType: 'SUPPORT_DOC_DELETED',
        entityType: 'SupportDoc',
        entityId: docId,
        description: `CEO deleted support document: "${title}"`,
        timestamp: new Date().toISOString()
    });
};

import { db, functions, auth } from './firebase';
import { collection, doc, getDocs, setDoc, query, orderBy, onSnapshot, where, limit, updateDoc } from 'firebase/firestore';
import { httpsCallable } from 'firebase/functions';
import { MessageTemplate, MessageJob, MessagingProvider, CommunicationPreference, Client } from '../types';
// @ts-ignore
import { onAuthStateChanged } from 'firebase/auth';

const TEMPLATES_COL = 'message_templates';
const JOBS_COL = 'message_jobs';
const PREFS_COL = 'client_communication_preferences';
const PROVIDERS_COL = 'messaging_providers';

/**
 * Enqueue a message via secure backend proxy.
 * Prevents duplicates via deterministic ID generation.
 */
export const enqueueMessage = async (params: {
    clientId: string;
    eventType: string;
    eventUniqueId: string;
    metadata?: Record<string, any>;
}) => {
    const enqueueFunc = httpsCallable(functions, 'enqueueAutomatedMessage');
    return await enqueueFunc(params);
};

export const listenToMessageJobs = (onUpdate: (jobs: MessageJob[]) => void) => {
    let unsubscribeSnapshot: (() => void) | null = null;

    const unsubscribeAuth = onAuthStateChanged(auth, (user: any) => {
        if (user) {
            const q = query(collection(db, JOBS_COL), orderBy('createdAt', 'desc'), limit(100));
            unsubscribeSnapshot = onSnapshot(q, 
                (snap) => {
                    onUpdate(snap.docs.map(d => ({ id: d.id, ...d.data() } as MessageJob)));
                },
                (error) => {
                    console.error("Jobs listener failure:", error);
                }
            );
        } else {
            if (unsubscribeSnapshot) {
                unsubscribeSnapshot();
                unsubscribeSnapshot = null;
            }
        }
    });

    return () => {
        unsubscribeAuth();
        if (unsubscribeSnapshot) unsubscribeSnapshot();
    };
};

export const listenToTemplates = (onUpdate: (templates: MessageTemplate[]) => void) => {
    let unsubscribeSnapshot: (() => void) | null = null;

    const unsubscribeAuth = onAuthStateChanged(auth, (user: any) => {
        if (user) {
            unsubscribeSnapshot = onSnapshot(collection(db, TEMPLATES_COL), 
                (snap) => {
                    onUpdate(snap.docs.map(d => ({ id: d.id, ...d.data() } as MessageTemplate)));
                },
                (error) => {
                    console.error("Templates listener failure:", error);
                }
            );
        } else {
            if (unsubscribeSnapshot) {
                unsubscribeSnapshot();
                unsubscribeSnapshot = null;
            }
        }
    });

    return () => {
        unsubscribeAuth();
        if (unsubscribeSnapshot) unsubscribeSnapshot();
    };
};

export const saveTemplate = async (template: MessageTemplate) => {
    const ref = doc(db, TEMPLATES_COL, template.id || Date.now().toString());
    await setDoc(ref, { ...template, updatedAt: new Date().toISOString() }, { merge: true });
};

export const fetchProviders = async (): Promise<MessagingProvider[]> => {
    const snap = await getDocs(collection(db, PROVIDERS_COL));
    return snap.docs.map(d => ({ id: d.id, ...d.data() } as MessagingProvider));
};

export const updateProviderStatus = async (id: string, isEnabled: boolean) => {
    await updateDoc(doc(db, PROVIDERS_COL, id), { isEnabled });
};

export const getClientPreference = async (clientId: string): Promise<CommunicationPreference> => {
    const snap = await getDocs(query(collection(db, PREFS_COL), where('clientId', '==', clientId)));
    if (snap.empty) {
        return { clientId, allowSMS: true, allowEmail: true, optedOut: false, preferredChannel: 'SMS' };
    }
    return snap.docs[0].data() as CommunicationPreference;
};

export const updateClientPreference = async (pref: CommunicationPreference) => {
    await setDoc(doc(db, PREFS_COL, pref.clientId), pref, { merge: true });
};

