import React, { useState, useEffect } from 'react';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input, Select, Textarea } from '../ui/Input';
import { XMarkIcon, CheckCircleIcon, ExclamationTriangleIcon } from '../icons/DummyIcons';
import { MessageTemplate } from '../../types';
import { saveTemplate } from '../../services/messagingDbService';

interface MessageTemplateModalProps {
    isOpen: boolean;
    onClose: () => void;
    editingTemplate?: MessageTemplate | null;
}

export const MessageTemplateModal: React.FC<MessageTemplateModalProps> = ({ isOpen, onClose, editingTemplate }) => {
    const [formData, setFormData] = useState<Omit<MessageTemplate, 'id' | 'updatedAt'>>({
        name: '',
        channel: 'SMS',
        eventType: 'PAYMENT_RECEIVED',
        isEnabled: true,
        body: ''
    });
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (isOpen) {
            if (editingTemplate) {
                setFormData({
                    name: editingTemplate.name,
                    channel: editingTemplate.channel,
                    eventType: editingTemplate.eventType,
                    isEnabled: editingTemplate.isEnabled,
                    body: editingTemplate.body
                });
            } else {
                setFormData({
                    name: '',
                    channel: 'SMS',
                    eventType: 'PAYMENT_RECEIVED',
                    isEnabled: true,
                    body: ''
                });
            }
            setError(null);
        }
    }, [isOpen, editingTemplate]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (!formData.name.trim() || !formData.body.trim()) {
            setError("Template Name and Message Body are required.");
            return;
        }

        setIsSaving(true);
        try {
            const templateToSave: MessageTemplate = {
                ...formData,
                id: editingTemplate?.id || `TEMP-${Date.now()}`,
                updatedAt: new Date().toISOString()
            };
            await saveTemplate(templateToSave);
            onClose();
        } catch (err: any) {
            setError(err.message || "Failed to save template.");
        } finally {
            setIsSaving(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-xl p-0 overflow-hidden shadow-2xl animate-in zoom-in duration-300 border border-blue-500/30">
                <form onSubmit={handleSubmit}>
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 flex justify-between items-center">
                        <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">
                            {editingTemplate ? 'Modify Template' : 'Define New Template'}
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
                            <XMarkIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="p-6 space-y-5 bg-white dark:bg-gray-800">
                        {error && (
                            <div className="p-3 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded text-xs font-bold text-red-800 dark:text-red-300">
                                <ExclamationTriangleIcon className="w-4 h-4 inline mr-2" />
                                {error}
                            </div>
                        )}

                        <Input 
                            label="Template Friendly Name*" 
                            placeholder="e.g. 70% Qualification SMS"
                            value={formData.name}
                            onChange={(e) => setFormData({...formData, name: e.target.value})}
                            required
                            disabled={isSaving}
                        />

                        <div className="grid grid-cols-2 gap-4">
                            <Select 
                                label="Channel Type*" 
                                value={formData.channel}
                                onChange={(e) => setFormData({...formData, channel: e.target.value as any})}
                                disabled={isSaving}
                            >
                                <option value="SMS">SMS Gateway</option>
                                <option value="EMAIL">Corporate Email</option>
                                <option value="WHATSAPP">WhatsApp Business</option>
                            </Select>

                            <Select 
                                label="Trigger Event*" 
                                value={formData.eventType}
                                onChange={(e) => setFormData({...formData, eventType: e.target.value as any})}
                                disabled={isSaving}
                            >
                                <option value="PAYMENT_RECEIVED">Payment Received</option>
                                <option value="INSTALMENT_REMINDER">Instalment Reminder</option>
                                <option value="MONTHLY_SUMMARY">Monthly Summary</option>
                                <option value="BIRTHDAY">Client Birthday</option>
                                <option value="QUALIFIED_70">70% Qualification</option>
                                <option value="ALLOCATION_DONE">Allocation Complete</option>
                            </Select>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-black text-gray-400 uppercase">Message Body*</label>
                            <Textarea 
                                value={formData.body}
                                onChange={(e) => setFormData({...formData, body: e.target.value})}
                                placeholder="Write your message... Use {clientName} for dynamic substitution."
                                rows={6}
                                disabled={isSaving}
                                className="font-medium text-sm"
                            />
                        </div>

                        <label className="flex items-center gap-3 cursor-pointer group">
                            <input 
                                type="checkbox" 
                                checked={formData.isEnabled}
                                onChange={(e) => setFormData({...formData, isEnabled: e.target.checked})}
                                disabled={isSaving}
                                className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                            />
                            <span className="text-sm font-bold text-gray-700 dark:text-gray-300 group-hover:text-blue-600 transition-colors">
                                Enable Template for Automation
                            </span>
                        </label>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <Button type="button" variant="secondary" onClick={onClose} disabled={isSaving}>Cancel</Button>
                        <Button 
                            type="submit" 
                            isLoading={isSaving}
                            className="px-8 font-black uppercase tracking-widest"
                            icon={<CheckCircleIcon className="w-4 h-4" />}
                        >
                            {editingTemplate ? 'Update Template' : 'Create Template'}
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Badge } from '../components/ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { 
    ChatBubbleLeftEllipsisIcon, 
    EnvelopeIcon, 
    Cog6ToothIcon, 
    ClockIcon, 
    CheckCircleIcon, 
    ExclamationTriangleIcon,
    ArrowPathIcon,
    FunnelIcon,
    PlusCircleIcon
} from '../components/icons/DummyIcons';
import { useAuth } from '../context/AuthContext';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';
import { 
    listenToMessageJobs, 
    listenToTemplates, 
    fetchProviders, 
    updateProviderStatus, 
    saveTemplate 
} from '../services/messagingDbService';
import { MessageJob, MessageTemplate, MessagingProvider } from '../types';

const MessagingPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { openModal } = useModal();
    const [activeTab, setActiveTab] = useState<'log' | 'templates' | 'providers'>('log');
    const [jobs, setJobs] = useState<MessageJob[]>([]);
    const [templates, setTemplates] = useState<MessageTemplate[]>([]);
    const [providers, setProviders] = useState<MessagingProvider[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const isCEO = currentStaff?.roleId === 'CEO' || currentStaff?.roleId === 'Administrator';

    useEffect(() => {
        const unsubJobs = listenToMessageJobs(setJobs);
        const unsubTemps = listenToTemplates(setTemplates);

        fetchProviders().then(p => {
            setProviders(p);
            setIsLoading(false);
        });

        return () => {
            unsubJobs();
            unsubTemps();
        };
    }, []);

    const stats = useMemo(() => {
        const today = new Date().toISOString().split('T')[0];
        const todayJobs = jobs.filter(j => j.createdAt.startsWith(today));
        const delivered = todayJobs.filter(j => j.status === 'DELIVERED').length;
        const failed = todayJobs.filter(j => j.status === 'FAILED').length;
        return {
            sentToday: todayJobs.length,
            deliveryRate: todayJobs.length > 0 ? Math.round((delivered / todayJobs.length) * 100) : 100,
            failedToday: failed
        };
    }, [jobs]);

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Messaging Control Center</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1 font-medium">Deterministic client communication engine and audit trail.</p>
                </div>
                <div className="flex items-center gap-3">
                    <div className="bg-white dark:bg-gray-800 px-4 py-2 rounded-xl border border-gray-200 dark:border-gray-700 flex items-center gap-6 shadow-sm">
                        <div className="text-center">
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Sent Today</p>
                            <p className="text-lg font-black text-blue-600">{stats.sentToday}</p>
                        </div>
                        <div className="text-center">
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Delivery Rate</p>
                            <p className="text-lg font-black text-green-600">{stats.deliveryRate}%</p>
                        </div>
                        <div className="text-center">
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Failed</p>
                            <p className="text-lg font-black text-red-500">{stats.failedToday}</p>
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex border-b border-gray-200 dark:border-gray-700">
                <button 
                    onClick={() => setActiveTab('log')}
                    className={`px-6 py-3 font-black text-xs uppercase tracking-widest border-b-2 transition-all ${activeTab === 'log' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-700'}`}
                >
                    Communication Log
                </button>
                <button 
                    onClick={() => setActiveTab('templates')}
                    className={`px-6 py-3 font-black text-xs uppercase tracking-widest border-b-2 transition-all ${activeTab === 'templates' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-700'}`}
                >
                    Message Templates
                </button>
                {isCEO && (
                    <button 
                        onClick={() => setActiveTab('providers')}
                        className={`px-6 py-3 font-black text-xs uppercase tracking-widest border-b-2 transition-all ${activeTab === 'providers' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-700'}`}
                    >
                        Provider Config
                    </button>
                )}
            </div>

            {activeTab === 'log' && (
                <div className="space-y-4">
                    <Card className="p-4 bg-gray-50 dark:bg-gray-900/50 border-dashed">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-4">
                                <FunnelIcon className="w-5 h-5 text-gray-400" />
                                <span className="text-sm font-bold text-gray-600">Filters: All Channels | All Statuses</span>
                            </div>
                            <Button variant="secondary" size="sm" icon={<ArrowPathIcon className="w-4 h-4" />}>Refresh Feed</Button>
                        </div>
                    </Card>

                    <TableContainer>
                        <table className="w-full text-sm text-left">
                            <Thead>
                                <tr>
                                    <Th>Recipient</Th>
                                    <Th>Event / Trigger</Th>
                                    <Th>Message Preview</Th>
                                    <Th className="text-center">Status</Th>
                                    <Th className="text-right">Timestamp</Th>
                                </tr>
                            </Thead>
                            <Tbody>
                                {jobs.length === 0 ? (
                                    <Tr><Td colSpan={5} className="py-20 text-center text-gray-400 italic">No communication history recorded.</Td></Tr>
                                ) : (
                                    jobs.map(job => (
                                        <Tr key={job.id}>
                                            <Td>
                                                <div className="font-bold text-gray-900 dark:text-white">{job.clientName}</div>
                                                <div className="text-[10px] font-mono text-gray-500">{job.to}</div>
                                            </Td>
                                            <Td>
                                                <Badge variant="info" className="text-[10px] font-black uppercase tracking-tighter">{job.eventType}</Badge>
                                            </Td>
                                            <Td className="max-w-xs truncate text-gray-600 dark:text-gray-400 italic">"{job.messagePreview}"</Td>
                                            <Td className="text-center">
                                                <Badge variant={job.status === 'DELIVERED' ? 'success' : job.status === 'FAILED' ? 'danger' : 'warning'}>
                                                    {job.status}
                                                </Badge>
                                            </Td>
                                            <Td className="text-right">
                                                <div className="flex flex-col items-end">
                                                    <span className="font-bold text-gray-700 dark:text-gray-300">{new Date(job.createdAt).toLocaleDateString()}</span>
                                                    <span className="text-[10px] text-gray-400 uppercase">{new Date(job.createdAt).toLocaleTimeString()}</span>
                                                </div>
                                            </Td>
                                        </Tr>
                                    ))
                                )}
                            </Tbody>
                        </table>
                    </TableContainer>
                </div>
            )}

            {activeTab === 'templates' && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {templates.map(temp => (
                        <Card key={temp.id} title={temp.name} action={<Badge variant={temp.isEnabled ? 'success' : 'neutral'}>{temp.isEnabled ? 'Active' : 'Disabled'}</Badge>}>
                            <div className="space-y-4">
                                <div className="p-3 bg-gray-50 dark:bg-gray-900 rounded-lg border border-gray-200 dark:border-gray-700 min-h-[100px]">
                                    <p className="text-xs text-gray-600 dark:text-gray-400 whitespace-pre-wrap">{temp.body}</p>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">{temp.eventType}</span>
                                    <button 
                                        disabled={!isCEO}
                                        onClick={() => openModal(MODAL_TYPES.MESSAGE_TEMPLATE, { editingTemplate: temp })}
                                        title={!isCEO ? "Insufficient permissions." : "Edit template content"}
                                        className="text-sm font-bold text-blue-600 hover:underline disabled:opacity-30 disabled:cursor-not-allowed"
                                    >
                                        Edit Content
                                    </button>
                                </div>
                            </div>
                        </Card>
                    ))}

                    <button 
                        disabled={!isCEO || isLoading}
                        onClick={() => openModal(MODAL_TYPES.MESSAGE_TEMPLATE, { editingTemplate: null })}
                        title={!isCEO ? "Insufficient permissions. CEO/Admin only." : (isLoading ? "Loading templates..." : "Create new message template")}
                        className={`flex flex-col items-center justify-center p-8 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-xl hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all group ${!isCEO || isLoading ? 'opacity-50 cursor-not-allowed grayscale' : ''}`}
                    >
                        <PlusCircleIcon className={`w-10 h-10 mb-2 ${!isCEO || isLoading ? 'text-gray-200' : 'text-gray-300 group-hover:text-blue-500'}`} />
                        <span className={`text-sm font-black uppercase tracking-widest ${!isCEO || isLoading ? 'text-gray-300' : 'text-gray-400 group-hover:text-blue-600'}`}>
                            {isLoading ? 'Synchronizing...' : 'New Template'}
                        </span>
                    </button>
                </div>
            )}

            {activeTab === 'providers' && (
                <div className="max-w-2xl mx-auto space-y-6">
                    {providers.map(provider => (
                        <Card key={provider.id}>
                            <div className="flex items-center justify-between mb-6">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center text-blue-600 font-black italic">mN</div>
                                    <div>
                                        <h3 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">{provider.name}</h3>
                                        <p className="text-xs text-gray-500 uppercase font-bold tracking-widest">Gateway Strategy: {provider.type}</p>
                                    </div>
                                </div>
                                <label className="relative inline-flex items-center cursor-pointer">
                                    <input 
                                        type="checkbox" 
                                        checked={provider.isEnabled} 
                                        onChange={(e) => updateProviderStatus(provider.id, e.target.checked)}
                                        className="sr-only peer" 
                                    />
                                    <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                                </label>
                            </div>

                            <div className="grid grid-cols-2 gap-4 pt-6 border-t border-gray-100 dark:border-gray-700">
                                <div>
                                    <p className="text-[10px] font-black text-gray-400 uppercase mb-1">API Status</p>
                                    <div className="flex items-center gap-2 text-green-600 font-bold text-sm">
                                        <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
                                        Functional
                                    </div>
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Authenticated Sender ID</p>
                                    <p className="text-sm font-black text-gray-900 dark:text-white uppercase tracking-tighter">{provider.senderId}</p>
                                </div>
                            </div>
                        </Card>
                    ))}

                    <div className="p-6 bg-amber-50 dark:bg-amber-900/10 rounded-2xl border border-amber-200 dark:border-amber-900 flex items-start gap-4">
                        <ExclamationTriangleIcon className="w-6 h-6 text-amber-600 shrink-0" />
                        <div>
                            <h4 className="text-sm font-black text-amber-800 dark:text-amber-300 uppercase tracking-tighter">Security Protocol</h4>
                            <p className="text-xs text-amber-700 dark:text-amber-400 mt-1 leading-relaxed">
                                Provider API Keys are stored in the secure environment vault. 
                                Modification requires manual intervention by the Platform Architect for security integrity.
                            </p>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

