import { db } from './firebase';
import { 
    collection, getDocs, doc, setDoc, addDoc, 
    query, where, orderBy, onSnapshot, updateDoc, 
    serverTimestamp, deleteDoc, limit 
} from 'firebase/firestore';
import { 
    MessageTemplate, 
    MessageOutbox, 
    MessageHistory, 
    ClientMessagingPreference 
} from '../types/messaging';
import { Client } from '../types';

const TEMPLATES_COL = 'messaging_templates';
const OUTBOX_COL = 'messaging_outbox';
const HISTORY_COL = 'messaging_history';
const PREFS_COL = 'messaging_client_preferences';

// --- Templates ---
export const listenToTemplates = (callback: (templates: MessageTemplate[]) => void) => {
    return onSnapshot(collection(db, TEMPLATES_COL), (snapshot) => {
        callback(snapshot.docs.map(d => ({ id: d.id, ...d.data() } as MessageTemplate)));
    });
};

export const saveTemplate = async (template: MessageTemplate) => {
    await setDoc(doc(db, TEMPLATES_COL, template.id), {
        ...template,
        updatedAt: new Date().toISOString()
    });
};

// --- Manual Send / Outbox ---
export const queueMessage = async (message: Omit<MessageOutbox, 'id' | 'createdAt' | 'updatedAt'>) => {
    const now = new Date().toISOString();
    const docRef = await addDoc(collection(db, OUTBOX_COL), {
        ...message,
        createdAt: now,
        updatedAt: now
    });

    // Immutable History Log (Simulation of dispatch)
    if (message.status === 'SENT') {
        await addDoc(collection(db, HISTORY_COL), {
            messageId: docRef.id,
            clientId: message.clientId,
            channel: message.channel,
            category: message.category,
            recipient: message.toPhone || message.toEmail || 'Unknown',
            messagePreview: message.messageBodyFinal.substring(0, 100),
            status: 'SENT',
            timestamp: now,
            senderName: message.createdBy
        });
    }
};

/**
 * AUTOMATED TRIGGER: Payment Confirmation
 * Resolves templates and preferences to dispatch a receipt message.
 */
export const triggerPaymentConfirmation = async (client: Client, amount: number, staffName: string) => {
    try {
        // 1. Compliance Check
        const prefs = await getClientPreferences(client.id);
        if (prefs?.optedOut) return;

        // 2. Template Resolution
        const q = query(
            collection(db, TEMPLATES_COL), 
            where('category', '==', 'Payment Received'), 
            where('isEnabled', '==', true),
            limit(1)
        );
        const snap = await getDocs(q);
        if (snap.empty) return;

        const template = snap.docs[0].data() as MessageTemplate;

        // 3. Resolve Placeholders
        const formatGhc = (v: number) => `GHC ${new Intl.NumberFormat('en-GH').format(v)}`;
        const body = template.body
            .replace(/{ClientName}/g, client.name)
            .replace(/{Amount}/g, formatGhc(amount))
            .replace(/{Balance}/g, formatGhc(client.payment.balance))
            .replace(/{Project}/g, client.location);

        // 4. Dispatch
        await queueMessage({
            channel: template.channel,
            clientId: client.id,
            toPhone: client.phone,
            toEmail: client.email,
            category: 'Payment Received',
            templateId: template.id,
            messageBodyFinal: body,
            status: 'SENT',
            createdBy: staffName,
            notes: `Automated receipt for payment of ${formatGhc(amount)}`
        });
    } catch (e) {
        console.error("Messaging trigger failed:", e);
    }
};

// --- History ---
export const listenToMessageHistory = (callback: (history: MessageHistory[]) => void) => {
    const q = query(collection(db, HISTORY_COL), orderBy('timestamp', 'desc'));
    return onSnapshot(q, (snapshot) => {
        callback(snapshot.docs.map(d => ({ id: d.id, ...d.data() } as MessageHistory)));
    });
};

// --- Preferences ---
export const getClientPreferences = async (clientId: number): Promise<ClientMessagingPreference | null> => {
    const q = query(collection(db, PREFS_COL), where('clientId', '==', clientId));
    const snap = await getDocs(q);
    if (snap.empty) return null;
    return snap.docs[0].data() as ClientMessagingPreference;
};

export const updateClientPreferences = async (prefs: ClientMessagingPreference) => {
    const docId = `PREF_${prefs.clientId}`;
    await setDoc(doc(db, PREFS_COL, docId), {
        ...prefs,
        updatedAt: new Date().toISOString()
    });
};

// --- CEO Hub Stats ---
export const fetchMessagingStats = async () => {
    const today = new Date().toISOString().split('T')[0];
    const q = query(collection(db, HISTORY_COL), where('timestamp', '>=', today));
    const snap = await getDocs(q);

    return {
        sentToday: snap.size,
        failures: snap.docs.filter(d => d.data().status === 'FAILED').length
    };
};

import React, { useState } from 'react';
import { Client } from '../../types';
import { XMarkIcon, ExclamationTriangleIcon, ChatBubbleLeftEllipsisIcon } from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';

interface RecordPaymentModalProps {
    isOpen: boolean;
    onClose: () => void;
    client: Client;
    onSave: (paymentData: any) => Promise<void> | void;
}

export const RecordPaymentModal: React.FC<RecordPaymentModalProps> = ({ isOpen, onClose, client, onSave }) => {
    const [amount, setAmount] = useState('');
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>('Land');
    const [sendSms, setSendSms] = useState(true);

    // UI State for Submission Flow
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (!amount || parseFloat(amount) <= 0) {
            setError("Please enter a valid amount.");
            return;
        }

        setIsSubmitting(true);
        try {
            // Await the save operation provided by parent
            await onSave({
                amount: parseFloat(amount),
                method,
                receiptNumber,
                type,
                sendSms,
                date: new Date().toISOString().split('T')[0]
            });

            // On Success: Automatically close the window
            onClose();
        } catch (err: any) {
            // On Failure: Keep window open and show error
            console.error("Payment Submission Error:", err);
            setError(err.message || "Failed to post transaction. Please verify your connection.");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/60 z-[100] flex justify-center items-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <Card className="w-full max-w-md p-0 overflow-hidden shadow-2xl animate-in zoom-in duration-300">
                <form onSubmit={handleSubmit}>
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900">
                        <div className="flex flex-col">
                            <h3 className="font-bold text-gray-900 dark:text-white uppercase tracking-tight">Record New Payment</h3>
                            <p className="text-[10px] text-gray-500 font-medium uppercase">{client.name}</p>
                        </div>
                        <button 
                            type="button" 
                            onClick={onClose} 
                            disabled={isSubmitting}
                            className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
                        >
                            <XMarkIcon className="w-6 h-6"/>
                        </button>
                    </div>

                    <div className="p-6 space-y-4 bg-white dark:bg-gray-800">
                        {error && (
                            <div className="p-3 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded flex gap-2 animate-in slide-in-from-top-1">
                                <ExclamationTriangleIcon className="w-5 h-5 text-red-600 shrink-0" />
                                <p className="text-xs text-red-800 dark:text-red-200 font-medium">{error}</p>
                            </div>
                        )}

                        <Input 
                            label="Amount (GHC)*" 
                            type="number" 
                            value={amount} 
                            onChange={e => setAmount(e.target.value)} 
                            required 
                            disabled={isSubmitting}
                            className="font-bold text-lg"
                        />

                        <div className="grid grid-cols-1 gap-4">
                            <Select 
                                label="Payment Method*" 
                                value={method} 
                                onChange={e => setMethod(e.target.value as any)} 
                                required 
                                disabled={isSubmitting}
                            >
                                <option>Bank Transfer</option>
                                <option>MoMo</option>
                                <option>Cash</option>
                                <option>Cheque</option>
                                <option>Other</option>
                            </Select>

                            <Select 
                                label="Transaction Type*" 
                                value={type} 
                                onChange={e => setType(e.target.value as any)} 
                                required 
                                disabled={isSubmitting}
                            >
                                <option value="Land">Land Payment</option>
                                <option value="Indenture">Indenture / Documentation</option>
                                <option value="Commission">Commission Payout</option>
                            </Select>
                        </div>

                        <Input 
                            label="Receipt Number*" 
                            value={receiptNumber} 
                            onChange={e => setReceiptNumber(e.target.value)} 
                            required 
                            disabled={isSubmitting}
                            placeholder="e.g. REC-100234"
                            className="font-mono uppercase"
                        />

                        <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                            <label className="flex items-center gap-3 cursor-pointer group">
                                <div className={`w-10 h-6 flex items-center bg-gray-200 dark:bg-gray-700 rounded-full p-1 transition-all ${sendSms ? 'bg-blue-600' : ''}`}>
                                    <div className={`bg-white w-4 h-4 rounded-full shadow-md transform transition-transform ${sendSms ? 'translate-x-4' : ''}`} />
                                </div>
                                <input 
                                    type="checkbox" 
                                    className="hidden" 
                                    checked={sendSms} 
                                    onChange={e => setSendSms(e.target.checked)} 
                                />
                                <span className="text-xs font-bold text-gray-500 dark:text-gray-400 flex items-center gap-1.5 group-hover:text-blue-600 transition-colors">
                                    <ChatBubbleLeftEllipsisIcon className="w-4 h-4" />
                                    Send Confirmation Message
                                </span>
                            </label>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <button 
                            type="button" 
                            onClick={onClose}
                            disabled={isSubmitting}
                            className="px-4 py-2 text-sm font-bold text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-200 transition-colors disabled:opacity-50"
                        >
                            Cancel
                        </button>
                        <Button 
                            type="submit" 
                            variant="success"
                            isLoading={isSubmitting}
                            className="font-black uppercase tracking-widest px-6"
                        >
                            Post Transaction
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    DocumentTextIcon,
    ChartBarIcon,
    DocumentDuplicateIcon
} from '../components/icons/DummyIcons';
import { Button } from '../components/ui/Button';
import { Select } from '../components/ui/Input';
import { NotificationCenter } from '../components/NotificationCenter';
import { AccountOverview } from '../components/account/AccountOverview';
import { AccountHistory } from '../components/account/AccountHistory';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useProperties, useMilestones } from '../hooks/useAppData';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';
import { AccountStatementModal } from '../components/financials/AccountStatementModal';
import { triggerPaymentConfirmation } from '../services/messagingDbService';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect?: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
  overrideClientId?: number | null;
  isEmbedded?: boolean;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage, overrideClientId = null, isEmbedded = false
}) => {
  const { properties } = useProperties();
  const { saveMilestone } = useMilestones();
  const { openModal } = useModal();
  const [viewMode, setViewMode] = useState<'list' | 'alerts'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(overrideClientId);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isStatementModalOpen, setStatementModalOpen] = useState(false);

  useEffect(() => {
    if (overrideClientId !== null) {
      setSelectedClientId(overrideClientId);
    }
  }, [overrideClientId]);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (selectedClientId || clientForInvoice?.id))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);
  const isHeadOfAccounts = useMemo(() => currentStaff.roleId === 'Chief Accountant', [currentStaff]);

  // Rule: Statement access is restricted
  const canGenerateStatement = useMemo(() => isCEO || isHeadOfAccounts, [isCEO, isHeadOfAccounts]);

  const canMakePayment = useMemo(() => {
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  const originalPricePerPlot = useMemo(() => {
    if (!selectedClient) return 0;
    const matchingProperty = properties.find(p => p.location === selectedClient.location);
    return matchingProperty ? matchingProperty.price : 0;
  }, [selectedClient, properties]);

  const discountAmount = selectedClient?.payment.promoDetails ? (originalPricePerPlot * 0.1) : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land';
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async (customMonths?: number, financialSnapshot?: any) => {
    if (!selectedClient) return;

    const monthsCount = installmentOption === 'Other' ? (customMonths || 1) : parseInt(installmentOption);

    if (installmentOption !== 'Outright' && (!monthsCount || monthsCount <= 0)) {
        alert("Please provide a valid number of months.");
        return;
    }

    setIsSaving(true);
    try {
        const finalPlanType = installmentOption === 'Outright' ? 'Outright' : `${monthsCount} Months`;

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: finalPlanType,
                total: financialSnapshot?.contractTotalAfterDiscount || priceAfterDiscount,
                balance: (financialSnapshot?.contractTotalAfterDiscount || priceAfterDiscount) - selectedClient.payment.paid,
                ...financialSnapshot // Persist all snapshot fields (emi, discount, etc)
            }
        };

        // SCHEDULE GENERATION LOGIC (FIRST TIME ONLY)
        const storageKey = `expected_schedule_${selectedClient.id}`;
        const existingSchedule = localStorage.getItem(storageKey);

        if (!existingSchedule && installmentOption !== 'Outright') {
            const expectedAmount = updatedClient.payment.total / monthsCount;
            const schedule = [];
            let currentDate = new Date();

            if (selectedClient.regDate) {
                currentDate = new Date(selectedClient.regDate);
            }

            for (let i = 1; i <= monthsCount; i++) {
                currentDate.setMonth(currentDate.getMonth() + 1);
                schedule.push({
                    id: `EXP-${selectedClient.id}-${i}`,
                    date: currentDate.toISOString().split('T')[0],
                    amount: expectedAmount,
                    type: 'EXPECTED PAYMENT',
                    description: `Month ${i} of ${monthsCount}`
                });
            }
            localStorage.setItem(storageKey, JSON.stringify(schedule));
        }

        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const newPaid = client.payment.paid + newTransaction.amount;
    const newBalance = client.payment.balance - newTransaction.amount;

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: newPaid,
            balance: newBalance,
        }
    };

    const savedClient = await onSaveClient(updatedClient);

    // INTEGRATION HOOK: Automated Receipt Messaging
    if (paymentData.sendSms && savedClient) {
        triggerPaymentConfirmation(savedClient, newTransaction.amount, currentStaff.fullName);
    }

    if (newBalance <= 0) {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PLR',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Full payment for land received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }

    if (paymentData.type === 'Indenture') {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PFI',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Payment for indenture documents received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }
  };

  const openPaymentModal = () => {
      if(selectedClient) {
          openModal(MODAL_TYPES.RECORD_PAYMENT, {
              client: selectedClient,
              onSave: (data: any) => handleRecordPayment(selectedClient, data)
          });
      }
  };

  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  return (
    <div className={`flex flex-col ${isEmbedded ? 'h-auto' : 'h-[calc(100vh-120px)]'} space-y-6`}>
      {!isEmbedded && (
        <div className="flex flex-wrap items-center justify-between gap-4">
