export const fetchCompanySettings = async (): Promise<CompanySettings> => {
    try {
        const docRef = doc(db, SETTINGS_COL, 'main');
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
            return { ...COMPANY_SETTINGS, ...docSnap.data() } as CompanySettings;
        } else {
            return COMPANY_SETTINGS;
        }
    } catch (error) {
        console.error("Error fetching company settings:", error);
        return COMPANY_SETTINGS;
    }
};
export const persistCompanySettings = async (settings: CompanySettings) => {
    await setDoc(doc(db, SETTINGS_COL, 'main'), sanitizeData(settings));
};

// --- Seeding ---
export const seedDatabase = async () => {
    const batch = writeBatch(db);

    const propertiesSnap = await getDocs(collection(db, PROPERTIES_COL));
    const shouldSeedData = propertiesSnap.empty;

    if (shouldSeedData) {
        PROPERTIES.forEach(p => batch.set(doc(db, PROPERTIES_COL, String(p.id)), sanitizeData(p)));
        INVOICES.forEach(i => batch.set(doc(db, INVOICES_COL, String(i.id)), sanitizeData(i)));
        PROMOTIONS.forEach(p => batch.set(doc(db, PROMOTIONS_COL, String(p.id)), sanitizeData(p)));
        ROLES.forEach(r => batch.set(doc(db, ROLES_COL, String(r.id)), sanitizeData(r)));
        AMENDMENT_REQUESTS.forEach(a => batch.set(doc(db, AMENDMENTS_COL, String(a.id)), sanitizeData(a)));
        batch.set(doc(db, SETTINGS_COL, 'main'), sanitizeData(COMPANY_SETTINGS));
    }

    const ceoPermissionsRef = doc(db, PERMISSIONS_COL, 'CEO');
    try {
        const ceoPermissionsSnap = await getDoc(ceoPermissionsRef);
        const shouldSeedPermissions = !ceoPermissionsSnap.exists();

        if (shouldSeedPermissions) {
            const permissionsByRole: Record<string, any> = {};

            // Standard Modules
            ROLE_PERMISSIONS.forEach(rp => {
                if (!permissionsByRole[rp.roleId]) permissionsByRole[rp.roleId] = {};
                permissionsByRole[rp.roleId][rp.moduleId] = rp.permissions;
            });

            // Add Messaging to Roles
            const rolesList = ['CEO', 'Administrator', 'Front Desk Executive', 'Chief Accountant', 'Head of Sales', 'Sales Representative'];
            rolesList.forEach(roleId => {
                if (!permissionsByRole[roleId]) permissionsByRole[roleId] = {};

                const isPowerUser = roleId === 'CEO' || roleId === 'Administrator';
                permissionsByRole[roleId]['Messaging'] = {
                    view: true,
                    create: isPowerUser,
                    edit: isPowerUser,
                    delete: isPowerUser,
                    approve: isPowerUser
                };
            });

            Object.entries(permissionsByRole).forEach(([roleId, modules]) => {
                batch.set(doc(db, PERMISSIONS_COL, roleId), { modules });
            });
        }

        if (shouldSeedData || shouldSeedPermissions) {
            await batch.commit();
        }
    } catch (e) {
        console.error("Seeding check failed:", e);
    }
};

import { db } from './firebase';
import { 
    collection, getDocs, doc, setDoc, addDoc, 
    query, where, orderBy, onSnapshot, updateDoc, 
    serverTimestamp, deleteDoc, limit 
} from 'firebase/firestore';
import { 
    MessageTemplate, 
    MessageOutbox, 
    MessageHistory, 
    ClientMessagingPreference 
} from '../types/messaging';
import { Client } from '../types';

const TEMPLATES_COL = 'messaging_templates';
const OUTBOX_COL = 'messaging_outbox';
const HISTORY_COL = 'messaging_history';
const PREFS_COL = 'messaging_client_preferences';

// --- Templates ---
export const listenToTemplates = (callback: (templates: MessageTemplate[]) => void) => {
    return onSnapshot(collection(db, TEMPLATES_COL), (snapshot) => {
        callback(snapshot.docs.map(d => ({ id: d.id, ...d.data() } as MessageTemplate)));
    });
};

export const saveTemplate = async (template: MessageTemplate) => {
    await setDoc(doc(db, TEMPLATES_COL, template.id), {
        ...template,
        updatedAt: new Date().toISOString()
    });
};

// --- Manual Send / Outbox ---
export const queueMessage = async (message: Omit<MessageOutbox, 'id' | 'createdAt' | 'updatedAt'>) => {
    const now = new Date().toISOString();
    const docRef = await addDoc(collection(db, OUTBOX_COL), {
        ...message,
        createdAt: now,
        updatedAt: now
    });

    // Immutable History Log (Simulation of dispatch)
    if (message.status === 'SENT' || message.status === 'QUEUED') {
        await addDoc(collection(db, HISTORY_COL), {
            messageId: docRef.id,
            clientId: message.clientId,
            channel: message.channel,
            category: message.category,
            recipient: message.toPhone || message.toEmail || 'Unknown',
            messagePreview: message.messageBodyFinal.substring(0, 100),
            status: 'SENT',
            timestamp: now,
            senderName: message.createdBy,
            notes: message.notes // Preserving dedupe keys in notes
        });
    }
};

/**
 * AUTOMATED TRIGGER: Payment Confirmation
 */
export const triggerPaymentConfirmation = async (client: Client, amount: number, staffName: string) => {
    try {
        const prefs = await getClientPreferences(client.id);
        if (prefs?.optedOut) return;

        const q = query(
            collection(db, TEMPLATES_COL), 
            where('category', '==', 'Payment Received'), 
            where('isEnabled', '==', true),
            limit(1)
        );
        const snap = await getDocs(q);
        if (snap.empty) return;

        const template = snap.docs[0].data() as MessageTemplate;

        const formatGhc = (v: number) => `GHC ${new Intl.NumberFormat('en-GH').format(v)}`;
        const body = template.body
            .replace(/{ClientName}/g, client.name)
            .replace(/{Amount}/g, formatGhc(amount))
            .replace(/{Balance}/g, formatGhc(client.payment.balance))
            .replace(/{Project}/g, client.location);

        await queueMessage({
            channel: template.channel,
            clientId: client.id,
            toPhone: client.phone,
            toEmail: client.email,
            category: 'Payment Received',
            templateId: template.id,
            messageBodyFinal: body,
            status: 'SENT',
            createdBy: staffName,
            notes: `Automated receipt for payment of ${formatGhc(amount)}`
        });
    } catch (e) {
        console.error("Messaging trigger failed:", e);
    }
};

/**
 * BACKGROUND SCHEDULER: Instalment Reminders
 * Checks for upcoming payments and sends reminders 7 days and 48 hours prior.
 */
export const processInstalmentReminders = async (clients: Client[], staffName: string) => {
    try {
        // 1. Resolve Template
        const q = query(
            collection(db, TEMPLATES_COL), 
            where('category', '==', 'Instalment Reminder'), 
            where('isEnabled', '==', true),
            limit(1)
        );
        const tempSnap = await getDocs(q);
        if (tempSnap.empty) return;
        const template = tempSnap.docs[0].data() as MessageTemplate;

        const now = new Date();
        const todayStr = now.toISOString().split('T')[0];

        for (const client of clients) {
            // Check Preferences
            const prefs = await getClientPreferences(client.id);
            if (prefs?.optedOut) continue;

            // Fetch Schedule (Surgical: Read existing expected schedule)
            const storageKey = `expected_schedule_${client.id}`;
            const rawSchedule = localStorage.getItem(storageKey);
            if (!rawSchedule) continue;

            const schedule = JSON.parse(rawSchedule);

            for (const item of schedule) {
                const dueDate = new Date(item.date);
                const diffTime = dueDate.getTime() - now.getTime();
                const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                let reminderType: '7D' | '48H' | null = null;
                if (diffDays === 7) reminderType = '7D';
                else if (diffDays === 2) reminderType = '48H';

                if (reminderType) {
                    const dedupeKey = `REMID_${client.id}_${item.date}_${reminderType}`;

                    // 2. Dedupe Check
                    const historyQ = query(
                        collection(db, HISTORY_COL),
                        where('notes', '==', dedupeKey)
                    );
                    const historySnap = await getDocs(historyQ);
                    if (!historySnap.empty) continue;

                    // 3. Construct Message
                    const formatGhc = (v: number) => `GHC ${new Intl.NumberFormat('en-GH').format(v)}`;
                    let body = template.body
                        .replace(/{ClientName}/g, client.name)
                        .replace(/{DueDate}/g, item.date)
                        .replace(/{AmountDue}/g, formatGhc(item.amount))
                        .replace(/{Balance}/g, formatGhc(client.payment.balance));

                    // 4. Queue
                    await queueMessage({
                        channel: template.channel,
                        clientId: client.id,
                        toPhone: client.phone,
                        toEmail: client.email,
                        category: 'Instalment Reminder',
                        templateId: template.id,
                        messageBodyFinal: body,
                        status: 'SENT',
                        createdBy: staffName,
                        notes: dedupeKey // Store dedupe key in notes
                    });
                }
            }
        }
    } catch (e) {
        console.error("Instalment Reminder processing failed:", e);
    }
};

