export interface SMSConfig {
    provider: 'mNotify' | 'Hubtel' | 'Twilio' | 'Other';
    apiKey: string;
    senderId: string;
    baseUrl: string;
    clientId?: string;
    clientSecret?: string;
    isConnected: boolean;
}

const CONFIG_DOC = 'settings/sms_gateway';

export const getSMSConfig = async (): Promise<SMSConfig | null> => {
    const snap = await getDoc(doc(db, CONFIG_DOC));
    return snap.exists() ? snap.data() as SMSConfig : null;
};

export const saveSMSConfig = async (config: SMSConfig) => {
    await setDoc(doc(db, CONFIG_DOC), { ...config, updatedAt: new Date().toISOString() });
};

/**
 * Strategy-based SMS Dispatch
 */
export const sendSMS = async (to: string, message: string): Promise<{ success: boolean; error?: string }> => {
    const config = await getSMSConfig();

    if (!config || !config.isConnected) {
        return { success: false, error: 'SMS connection is not set up.' };
    }

    try {
        // Implementation for mNotify / generic REST API
        const payload = {
            recipient: [to],
            sender: config.senderId,
            message: message,
            is_schedule: false
        };

        const response = await fetch(config.baseUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${config.apiKey}` },
            body: JSON.stringify(payload)
        });

        if (!response.ok) throw new Error('Gateway response failed');

        return { success: true };
    } catch (e: any) {
        console.error("SMS Conduit Error:", e);
        return { success: false, error: e.message };
    }
};

