export type EventType = 'CLIENT_CREATED' | 'CLIENT_UPDATED_MERGED';

interface NotifyParams {
    event: EventType;
    client: Client;
    actor: Staff;
}

export const dispatchWorkflowNotifications = async ({ event, client, actor }: NotifyParams) => {
    const usersSnap = await getDocs(collection(db, 'user'));
    const permsSnap = await getDocs(collection(db, 'role_permissions'));

    const users = usersSnap.docs.map(d => d.data() as Staff);
    const perms = permsSnap.docs.map(d => d.data() as any);

    const notifications = users.filter(u => u.id !== actor.id).map(recipient => {
        const userPerms = perms.find(p => p.id === recipient.roleId);
        const canViewClient = userPerms?.modules?.['Clients']?.view === true;
        const isChiefAccountant = recipient.roleId === 'Chief Accountant';

        let title = event === 'CLIENT_CREATED' ? 'New Client Added' : 'Client Record Merged';
        let message = '';
        let ctaLabel = undefined;
        let ctaRoute = undefined;

        if (isChiefAccountant) {
            message = `Account [${client.initials}-${client.id}] requires financial setup.`;
            ctaLabel = 'Add Client Payment';
            ctaRoute = `/clients/${client.id}/financials`;
        } else if (canViewClient) {
            message = `${event === 'CLIENT_CREATED' ? 'Created' : 'Updated'}: ${client.name} (ID: ${client.id})`;
        } else {
            message = event === 'CLIENT_CREATED' ? 'A new client record was added to the system.' : 'An existing client record was updated.';
        }

        return {
            recipientUserId: recipient.id,
            actorUserId: actor.id,
            type: event,
            clientId: client.id,
            visibilityLevel: canViewClient || isChiefAccountant ? 'DETAILED' : 'GENERIC',
            title,
            message,
            ctaLabel,
            ctaRoute,
            read: false,
            timestamp: new Date().toISOString()
        };
    });

    const batchPromises = notifications.map(n => addDoc(collection(db, 'notifications'), n));
    await Promise.all(batchPromises);
};

import { db } from './firebase';
import { collection, getDocs, doc, setDoc, query, where, limit } from 'firebase/firestore';
import { Client } from '../types';

const CLIENTS_COL = 'clients';

const normalizePhone = (p: string) => p.replace(/\D/g, '').slice(-9);
const normalizeEmail = (e: string) => e.trim().toLowerCase();

/**
 * Deterministic Merge Logic
 * Ensures no duplicates are created and no blank fields overwrite valid data.
 */
export const atomicSaveClient = async (clientData: Partial<Client>): Promise<{ client: Client; event: 'CLIENT_CREATED' | 'CLIENT_UPDATED_MERGED'; changedFields: string[] }> => {
    const email = normalizeEmail(clientData.email || '');
    const phone = normalizePhone(clientData.phone || '');

    // 1. Identity Check
    const q = query(collection(db, CLIENTS_COL), where('email', '==', email), limit(1));
    const snap = await getDocs(q);
    let existing = snap.empty ? null : snap.docs[0].data() as Client;

    if (!existing && phone) {
        const q2 = query(collection(db, CLIENTS_COL), where('phone', '==', clientData.phone), limit(1));
        const snap2 = await getDocs(q2);
        if (!snap2.empty) existing = snap2.docs[0].data() as Client;
    }

    if (existing) {
        const changedFields: string[] = [];
        const merged: Client = { ...existing };

        Object.keys(clientData).forEach((key) => {
            const val = (clientData as any)[key];
            if (val && val !== (existing as any)[key]) {
                (merged as any)[key] = val;
                changedFields.push(key);
            }
        });

        await setDoc(doc(db, CLIENTS_COL, String(merged.id)), merged);
        return { client: merged, event: 'CLIENT_UPDATED_MERGED', changedFields };
    } else {
        // Create new
        const newClient = clientData as Client;
        await setDoc(doc(db, CLIENTS_COL, String(newClient.id)), newClient);
        return { client: newClient, event: 'CLIENT_CREATED', changedFields: [] };
    }
};

