import { useMutation, useQueryClient, useInfiniteQuery, useQuery } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { atomicSaveClient } from '../../services/clientDbService';
import { dispatchWorkflowNotifications } from '../../services/notificationService';
import { sendSMS } from '../../services/smsService';
import { auth } from '../../services/firebase';
import { Client, MilestoneRecord } from '../../types';
import { useAuth } from '../../context/AuthContext';

// FIX: Implemented full useClients hook with pagination and search
export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const { currentStaff } = useAuth();
    const isAuthenticated = !!auth.currentUser;

    const {
        data,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
        isLoading
    } = useInfiniteQuery({
        queryKey: ['clients', searchTerm],
        queryFn: ({ pageParam }) => 
            searchTerm 
                ? dbService.searchClients(searchTerm).then(data => ({ data, lastDoc: null }))
                : dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc,
        enabled: isAuthenticated,
    });

    const clients = data?.pages.flatMap(page => page.data) || [];

    const saveClientMutation = useMutation({
        mutationFn: async (clientData: Client) => {
            // 1. Atomic DB Write (Dedup + Merge)
            const { client, event, changedFields } = await atomicSaveClient(clientData);

            // 2. Internal Notifications (Async)
            if (currentStaff) {
                dispatchWorkflowNotifications({ event, client, actor: currentStaff });
            }

            // 3. Client SMS (Conditional)
            const isContactChange = changedFields.some(f => ['phone', 'email', 'name'].includes(f));
            if (event === 'CLIENT_CREATED' || isContactChange) {
                const smsMessage = event === 'CLIENT_CREATED' 
                    ? `Hello ${client.otherNames}, your client profile has been created successfully. We will contact you shortly. — FAIM`
                    : `Hello ${client.otherNames}, your profile details have been updated successfully. — FAIM`;

                sendSMS(client.phone, smsMessage);
            }

            return client;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return {
        clients,
        isLoading,
        hasNextPage,
        fetchNextPage,
        isFetchingNextPage,
        saveClient: (client: Client) => saveClientMutation.mutateAsync(client),
        deleteClient: (id: number) => deleteClientMutation.mutateAsync(id)
    };
};

// FIX: Added useMilestones hook to support documentation tracking
export const useMilestones = (clientId?: number) => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: milestones = [] } = useQuery({
        queryKey: ['milestones', clientId],
        queryFn: () => dbService.fetchMilestones(clientId),
        enabled: isAuthenticated,
    });

    const saveMilestoneMutation = useMutation({
        mutationFn: dbService.persistMilestone,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['milestones'] })
    });

    return {
        milestones,
        saveMilestone: (milestone: MilestoneRecord) => saveMilestoneMutation.mutateAsync(milestone)
    };
};

import { db } from './firebase';
import { collection, addDoc, getDocs, query, where } from 'firebase/firestore';
import { Staff, Client, RolePermission } from '../types';

export type EventType = 'CLIENT_CREATED' | 'CLIENT_UPDATED_MERGED';

interface NotifyParams {
    event: EventType;
    client: Client;
    actor: Staff;
}

export const dispatchWorkflowNotifications = async ({ event, client, actor }: NotifyParams) => {
    try {
        const usersSnap = await getDocs(collection(db, 'user'));
        const permsSnap = await getDocs(collection(db, 'role_permissions'));

        const users = usersSnap.docs.map(d => d.data() as Staff);
        const perms = permsSnap.docs.map(d => d.data() as any);

        const notificationPromises = users.filter(u => u.id !== actor.id).map(recipient => {
            const userPerms = perms.find(p => p.id === recipient.roleId);
            // Safety check for module existence in older records
            const modules = userPerms?.modules || {};
            const canViewClient = modules['Clients']?.view === true;
            const isChiefAccountant = recipient.roleId === 'Chief Accountant';

            let title = event === 'CLIENT_CREATED' ? 'New Client Added' : 'Client Record Merged';
            let message = '';
            let ctaLabel = '';
            let ctaRoute = '';

            if (isChiefAccountant) {
                message = `Account [${client.initials}-${client.id}] requires financial setup.`;
                ctaLabel = 'Add Client Payment';
                ctaRoute = `/clients/${client.id}/financials`;
            } else if (canViewClient) {
                message = `${event === 'CLIENT_CREATED' ? 'Created' : 'Updated'}: ${client.name} (ID: ${client.id})`;
            } else {
                message = event === 'CLIENT_CREATED' ? 'A new client record was added to the system.' : 'An existing client record was updated.';
            }

            // Deterministically construct payload to avoid 'undefined' values in addDoc
            const payload: any = {
                recipientUserId: recipient.id,
                actorUserId: actor.id,
                type: event,
                clientId: client.id,
                visibilityLevel: (canViewClient || isChiefAccountant) ? 'DETAILED' : 'GENERIC',
                title,
                message,
                read: false,
                timestamp: new Date().toISOString()
            };

            if (ctaLabel) payload.ctaLabel = ctaLabel;
            if (ctaRoute) payload.ctaRoute = ctaRoute;

            return addDoc(collection(db, 'notifications'), payload);
        });

        await Promise.all(notificationPromises);
    } catch (e) {
        console.error("Workflow notification dispatch failed:", e);
    }
};

