import { db } from './firebase';
import { collection, addDoc, getDocs, query, where } from 'firebase/firestore';
import { Staff, Client, RolePermission } from '../types';

export type EventType = 'CLIENT_CREATED' | 'CLIENT_UPDATED_MERGED';

interface NotifyParams {
    event: EventType;
    client: Client;
    actor: Staff;
}

export const dispatchWorkflowNotifications = async ({ event, client, actor }: NotifyParams) => {
    try {
        const usersSnap = await getDocs(collection(db, 'user')).catch(() => null);
        const permsSnap = await getDocs(collection(db, 'role_permissions')).catch(() => null);

        if (!usersSnap) return;

        const users = usersSnap.docs.map(d => d.data() as Staff);
        const perms = permsSnap ? permsSnap.docs.map(d => ({ id: d.id, ...d.data() } as any)) : [];

        const notifications = users.filter(u => u.id !== actor.id).map(recipient => {
            const userPerms = perms.find((p: any) => p.id === recipient.roleId);
            const canViewClient = userPerms?.modules?.['Clients']?.view === true;
            const isChiefAccountant = recipient.roleId === 'Chief Accountant';

            let title = event === 'CLIENT_CREATED' ? 'New Client Added' : 'Client Record Merged';
            let message = '';
            let ctaLabel = '';
            let ctaRoute = '';

            if (isChiefAccountant) {
                message = `Account [${client.initials}-${client.id}] requires financial setup.`;
                ctaLabel = 'Add Client Payment';
                ctaRoute = `/clients/${client.id}/financials`;
            } else if (canViewClient) {
                message = `${event === 'CLIENT_CREATED' ? 'Created' : 'Updated'}: ${client.name} (ID: ${client.id})`;
            } else {
                message = event === 'CLIENT_CREATED' ? 'A new client record was added to the system.' : 'An existing client record was updated.';
            }

            const payload: any = {
                recipientUserId: recipient.id,
                actorUserId: actor.id,
                type: event,
                clientId: client.id,
                visibilityLevel: canViewClient || isChiefAccountant ? 'DETAILED' : 'GENERIC',
                title,
                message,
                read: false,
                timestamp: new Date().toISOString()
            };

            // Firestore addDoc fails on undefined. Only add if truthy.
            if (ctaLabel) payload.ctaLabel = ctaLabel;
            if (ctaRoute) payload.ctaRoute = ctaRoute;

            return payload;
        });

        const batchPromises = notifications.map(n => addDoc(collection(db, 'notifications'), n));
        await Promise.all(batchPromises);
    } catch (e) {
        console.error("Non-blocking notification error:", e);
    }
};

import React, { useMemo } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { auth } from '../../services/firebase';
import { Staff, Role, ActivityLog } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { usePermissions } from '../../context/DataContext';

// --- Staff ---
export const useStaff = () => {
    const queryClient = useQueryClient();
    const { currentStaff } = useAuth();
    const { rolePermissions } = usePermissions();
    const isAuthenticated = !!auth.currentUser;

    const canView = useMemo(() => {
        if (!currentStaff) return false;
        if (currentStaff.roleId === 'CEO') return true;
        const perms = rolePermissions.find(rp => rp.roleId === currentStaff.roleId && rp.moduleId === 'Settings');
        return !!perms?.permissions?.view;
    }, [currentStaff, rolePermissions]);

    const { data: staff = [], isLoading } = useQuery({
        queryKey: ['staff'],
        queryFn: dbService.fetchStaff,
        enabled: isAuthenticated && canView,
    });

    const saveStaffMutation = useMutation({
        mutationFn: dbService.persistStaff,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    const updateStaffMutation = useMutation({
        mutationFn: (variables: { id: string, details: Partial<Staff> }) => 
            dbService.persistStaff({ ...staff.find(s => s.id === variables.id)!, ...variables.details }),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    const deleteStaffMutation = useMutation({
        mutationFn: dbService.removeStaff,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] })
    });

    return {
        staff,
        isLoading,
        saveStaff: (member: Staff) => saveStaffMutation.mutateAsync(member),
        updateStaff: (id: string, details: Partial<Staff>) => updateStaffMutation.mutateAsync({ id, details }),
        deleteStaff: (id: string) => deleteStaffMutation.mutateAsync(id)
    };
};

// --- Roles ---
export const useRoles = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: roles = [] } = useQuery({
        queryKey: ['roles'],
        queryFn: dbService.fetchRoles,
        enabled: isAuthenticated,
    });

    const setRolesMutation = useMutation({
        mutationFn: async (updatedRoles: Role[]) => {
            for (const role of updatedRoles) {
                await dbService.persistRole(role);
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['roles'] })
    });

    return {
        roles,
        setRoles: (roles: React.SetStateAction<Role[]>) => {
            if (typeof roles === 'function') {
                const next = roles(queryClient.getQueryData(['roles']) || []);
                setRolesMutation.mutate(next);
            } else {
                setRolesMutation.mutate(roles);
            }
        }
    };
};

