    }

    function getRole() {
      let userDocPath = /databases/$(database)/documents/user/$(request.auth.uid);
      return exists(userDocPath) ? get(userDocPath).data.roleId : null;
    }

    function isCEO() {
      return isUserAuthenticated() && getRole() == 'CEO';
    }

    function can(module, action) {
      let role = getRole();
      let permDocPath = /databases/$(database)/documents/role_permissions/$(role);

      return role != null && 
             exists(permDocPath) && 
             get(permDocPath).data.modules[module][action] == true;
    }

    // --- Field Integrity Checks ---

    function isUpdatingRestrictedClientFields() {
      let restricted = ['plot', 'location', 'payment', 'allocationStatus', 'paidPercent'];
      return request.resource.data.diff(resource.data).affectedKeys().hasAny(restricted);
    }

    function isUpdatingRestrictedPropertyFields() {
      let restricted = ['price', 'costPrice', 'inventory', 'isArchived'];
      return request.resource.data.diff(resource.data).affectedKeys().hasAny(restricted);
    }

    // --- Collection Rules ---

    match /settings/{docId} {
      allow read: if true; 
      allow write: if isCEO(); // Rule 3: CEO only direct write
    }

    match /user/{userId} {
      allow read: if isUserAuthenticated();
      allow create: if isCEO(); // Rule 3: CEO only
      allow update: if isUserAuthenticated() && (request.auth.uid == userId || isCEO());
      allow delete: if isCEO();
    }

    match /roles/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO();
    }

    match /role_permissions/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO();
    }

    match /activity_logs/{logId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Settings', 'view'));
      allow create: if isUserAuthenticated();
      allow update, delete: if false;
    }

    match /clients/{clientId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Clients', 'create'));
      allow update: if isUserAuthenticated() && (
        isCEO() || (
          can('Clients', 'edit') && !isUpdatingRestrictedClientFields()
        )
      );
      allow delete: if isCEO();
    }

    match /leads/{leadId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Leads Management', 'edit'));
      allow delete: if isCEO();
    }

    match /properties/{propertyId} {
      allow read: if isUserAuthenticated(); 
      allow create: if isCEO();
      allow update: if isUserAuthenticated() && (
        isCEO() || (
          can('CEO Hub', 'edit') && !isUpdatingRestrictedPropertyFields()
        )
      );
      allow delete: if isCEO();
    }

    match /invoices/{invoiceId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Account Management', 'view') || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Account Management', 'create'));
      allow update: if isUserAuthenticated() && (isCEO() || can('Account Management', 'edit'));
      allow delete: if isCEO();
    }

    match /promotions/{promoId} {
      allow read: if isUserAuthenticated();
      allow create: if isCEO() || can('Promotions', 'create');
      allow update: if isCEO() || can('Promotions', 'edit');
      allow delete: if isCEO();
    }

    match /amendments/{docId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('Clients', 'view'));
      allow create: if isUserAuthenticated() && (isCEO() || can('Clients', 'edit'));
      allow update: if isUserAuthenticated() && (
        isCEO() || (
          // Non-CEO can edit their own pending requests but NOT approve
          request.auth.uid == resource.data.requestingStaffId && 
          request.resource.data.officeUse.status == 'Pending'
        )
      ); 
      allow delete: if isCEO();
    }

    match /milestones/{milestoneId} {
      allow read, write: if isUserAuthenticated();
    }

    match /internal_mails/{mailId} {
      allow read: if isUserAuthenticated() && (isCEO() || (exists(resource.data.participants) && request.auth.uid in resource.data.participants));
      allow create: if isUserAuthenticated();
      allow update: if isUserAuthenticated() && (isCEO() || (exists(resource.data.participants) && request.auth.uid in resource.data.participants));
      allow delete: if isUserAuthenticated() && (isCEO() || request.auth.uid == resource.data.senderId);
    }

    match /notifications/{notifId} {
      allow read: if isUserAuthenticated() && (request.auth.uid == resource.data.recipientUserId || isCEO());
      allow create: if isUserAuthenticated();
      allow update: if isUserAuthenticated() && (request.auth.uid == resource.data.recipientUserId || isCEO());
      allow delete: if isCEO();
    }

    match /messaging_templates/{docId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO();
    }

    match /messaging_history/{docId} {
      allow read: if isUserAuthenticated() && (isCEO() || can('CEO Hub', 'view'));
      allow create: if isUserAuthenticated();
    }

    match /messaging_outbox/{docId} {
      allow read, write: if isUserAuthenticated() && (isCEO() || can('Clients', 'edit'));
    }

    match /messaging_client_preferences/{docId} {
      allow read, write: if isUserAuthenticated();
    }
  }
}

