    }

    function isAdmin() {
      return isUserAuthenticated() && getRole() == 'Administrator';
    }

    function isSalesHead() {
        return isUserAuthenticated() && getRole() == 'Head of Sales';
    }

    function isFrontDesk() {
        return isUserAuthenticated() && getRole() == 'Front Desk Executive';
    }

    // --- Field Sensitivity Logic ---

    function isUpdatingOnlyBio() {
      let bioFields = [
        'name', 'surname', 'otherNames', 'initials', 'phone', 'email', 
        'dateOfBirth', 'gender', 'photo', 'professionalDetails', 
        'witness', 'nextOfKin', 'indenture', 'isComplete', 'filledFormPdf'
      ];
      return request.resource.data.diff(resource.data).affectedKeys().hasOnly(bioFields);
    }

    function isUpdatingOnlyPayment() {
      let paymentFields = ['payment', 'paidPercent', 'stage'];
      return request.resource.data.diff(resource.data).affectedKeys().hasOnly(paymentFields);
    }

    // --- Collection Rules ---

    match /settings/{docId} {
      allow read: if true; 
      allow write: if isCEO(); 
    }

    match /user/{userId} {
      allow read: if isUserAuthenticated();
      allow create: if isCEO(); 
      allow update: if isUserAuthenticated() && (request.auth.uid == userId || isCEO() || isAdmin());
      allow delete: if isCEO();
    }

    match /roles/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO();
    }

    match /role_permissions/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO();
    }

    match /clients/{clientId} {
      allow read: if isUserAuthenticated();
      allow create: if isCEO() || isAdmin() || isFrontDesk() || isSalesHead();
      allow update: if isCEO() || 
                    (isAccountant() && isUpdatingOnlyPayment()) || 
                    ((isFrontDesk() || isSalesHead() || isAdmin()) && isUpdatingOnlyBio());
      allow delete: if isCEO();
    }

    match /invoices/{invoiceId} {
      allow read: if isUserAuthenticated();
      allow create: if isCEO() || isAccountant();
      allow update: if isCEO() || isAccountant();
      allow delete: if isCEO();
    }

    match /properties/{propertyId} {
      allow read: if isUserAuthenticated(); 
      allow create: if isCEO(); // Excludes Admin/Accountant from CEO Hub writes
      allow update: if isCEO(); 
      allow delete: if isCEO();
    }

    match /amendments/{docId} {
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated(); // Any role can request an amendment
      allow update: if isCEO(); // Governance: Sole Approver
      allow delete: if isCEO();
    }

    match /activity_logs/{logId} {
      allow read: if isCEO() || isAdmin();
      allow create: if isUserAuthenticated();
    }

    match /internal_mails/{mailId} {
      allow read: if isUserAuthenticated() && (isCEO() || request.auth.uid in resource.data.participants);
      allow create: if isUserAuthenticated();
    }

    match /leads/{leadId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO() || isAdmin() || isSalesHead() || isFrontDesk() || getRole() == 'Sales Representative';
    }
  }
}

import { useMemo } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { auth } from '../../services/firebase';
import { Invoice } from '../../types';
import { useAuth } from '../../context/AuthContext';

// --- Invoices ---
export const useInvoices = () => {
    const queryClient = useQueryClient();
    const { currentStaff } = useAuth();
    const isAuthenticated = !!auth.currentUser;

    const canManageFinance = useMemo(() => {
        if (!currentStaff) return false;
        return ['CEO', 'Chief Accountant'].includes(currentStaff.roleId);
    }, [currentStaff]);

    const { data: invoices = [] } = useQuery({
        queryKey: ['invoices'],
        queryFn: dbService.fetchInvoices,
        enabled: isAuthenticated,
    });

    const saveInvoiceMutation = useMutation({
        mutationFn: (invoice: Invoice) => {
            if (!canManageFinance) throw new Error("GOVERNANCE_VIOLATION: Role lacks financial write authority.");
            return dbService.persistInvoice(invoice);
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['invoices'] })
    });

    return {
        invoices,
        canManageFinance,
        saveInvoice: (invoice: Invoice) => saveInvoiceMutation.mutateAsync(invoice)
    };
};

