rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- Governance Helper Functions ---

    function isUserAuthenticated() {
      return request.auth != null;
    }

    function getUserData() {
      return get(/databases/$(database)/documents/user/$(request.auth.uid)).data;
    }

    function getRole() {
      return isUserAuthenticated() ? getUserData().roleId : null;
    }

    function isCEO() {
      return isUserAuthenticated() && getRole() == 'CEO';
    }

    function isChiefAccountant() {
      return isUserAuthenticated() && getRole() == 'Chief Accountant';
    }

    function isAdmin() {
      return isUserAuthenticated() && getRole() == 'Administrator';
    }

    // --- Directory Isolation ---

    match /user/{userId} {
      // Users can always read their own profile
      allow get: if isUserAuthenticated() && request.auth.uid == userId;
      // Privileged roles can list/read all staff
      allow list, get: if isCEO() || isAdmin();

      allow create: if isCEO(); 
      allow update: if isUserAuthenticated() && (request.auth.uid == userId || isCEO());
      allow delete: if isCEO();
    }

    // Opaque Workflow Trigger Collection
    match /workflow_triggers/{triggerId} {
      allow read: if isUserAuthenticated() && (
        isCEO() || 
        (getRole() == 'Chief Accountant' && resource.data.event == 'CLIENT_CREATED') ||
        (getRole() == 'Administrator' && resource.data.event == 'CLIENT_QUALIFIED')
      );
      // Any authenticated user can publish a trigger without knowing the recipients
      allow create: if isUserAuthenticated();
      allow update, delete: if isCEO();
    }

    match /clients/{clientId} {
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated();
      // LEGACY-GOV-1.1: Allow Chief Accountant to update financial ledgers directly
      allow update: if isCEO() || isChiefAccountant();
      allow delete: if isCEO();
    }

    match /amendments/{docId} {
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated();
      allow update, delete: if isCEO(); 
    }

    match /internal_mails/{mailId} {
      // Restricted to participants only. Participants array contains sender and recipient UIDs.
      allow read: if isUserAuthenticated() && (isCEO() || request.auth.uid in resource.data.participants);
      allow create: if isUserAuthenticated();
      allow update: if isUserAuthenticated() && request.auth.uid in resource.data.participants;
    }

    // Default catch-all
    match /{path=**} {
      allow read, write: if isCEO();
    }
  }
}

import { useMutation, useQueryClient, useInfiniteQuery, useQuery } from '@tanstack/react-query';
import * as dbService from '../../services/dbService';
import { atomicSaveClient } from '../../services/clientDbService';
import { dispatchWorkflowNotifications } from '../../services/notificationService';
import { sendSMS } from '../../services/smsService';
import { auth } from '../../services/firebase';
import { Client, MilestoneRecord, AmendmentRequest } from '../../types';
import { useAuth } from '../../context/AuthContext';

export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const { currentStaff } = useAuth();
    const isAuthenticated = !!auth.currentUser;

    const {
        data,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
        isLoading
    } = useInfiniteQuery({
        queryKey: ['clients', searchTerm],
        queryFn: ({ pageParam }) => 
            searchTerm 
                ? dbService.searchClients(searchTerm).then(data => ({ data, lastDoc: null }))
                : dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc,
        enabled: isAuthenticated,
    });

    const clients = data?.pages.flatMap(page => page.data) || [];

    const saveClientMutation = useMutation({
        mutationFn: async (clientData: Client) => {
            const isCEO = currentStaff?.roleId === 'CEO';
            const isChiefAccountant = currentStaff?.roleId === 'Chief Accountant';

            const existingClient = clients.find(c => c.id === clientData.id);

            if (existingClient && !isCEO) {
                // GOVERNANCE: Amendments must be routed through approval ledger
                const diff: any = {};
                Object.keys(clientData).forEach(key => {
                    const k = key as keyof Client;
                    if (JSON.stringify(clientData[k]) !== JSON.stringify(existingClient[k])) {
                        diff[k] = true;
                    }
                });

                if (Object.keys(diff).length > 0) {
                    // LEGACY-GOV-1.1: Check if changes are strictly financial
                    const hasNonFinancialDiffs = !!(
                        diff.name || diff.surname || diff.phone || diff.email || 
                        diff.dateOfBirth || diff.nextOfKin || diff.location || 
                        diff.plot || diff.indenture
                    );

                    // If Chief Accountant is editing ONLY financial data, bypass amendment request
                    if (isChiefAccountant && !hasNonFinancialDiffs) {
                        // Proceed to atomic save directly
                    } else {
                        const amendmentId = `CRQ-${Date.now()}`;
                        const changeRequest: AmendmentRequest = {
                            id: amendmentId,
                            clientId: clientData.id,
                            clientFullName: clientData.name,
                            clientPurchaseRef: `${clientData.initials}-${clientData.id}`,
                            requestDate: new Date().toISOString().split('T')[0],
                            requestingStaffId: currentStaff!.id,
                            scannedForm: null,
                            amendmentTypes: {
                                personalDetails: !!(diff.name || diff.surname || diff.phone || diff.email || diff.dateOfBirth),
                                nextOfKin: !!diff.nextOfKin,
                                propertyReallocation: !!(diff.location || diff.plot),
                                paymentPlan: !!diff.payment,
                                indenture: !!diff.indenture
                            },
                            //@ts-ignore
                            pendingData: clientData,
                            officeUse: {
                                receivedBy: currentStaff!.fullName,
                                dateReceived: new Date().toISOString().split('T')[0],
                                status: 'Pending',
                                remarks: `Governance: Redirected to CEO Approval.`
                            }
                        };

                        await dbService.persistAmendment(changeRequest);
                        throw new Error("APPROVAL_REQUIRED: Unauthorized direct mutation blocked. Change Request submitted.");
                    }
                }
                if (!isChiefAccountant && Object.keys(diff).length === 0) {
                    return existingClient;
                }
            }

            // Evaluation of Qualification Threshold (70%)
            const total = clientData.payment.total || 0;
            const paid = clientData.payment.paid || 0;
            const isQualified = total > 0 && (paid / total) >= 0.7;

            // 1. Atomic DB Write
            const { client, event } = await atomicSaveClient(clientData);

            // 2. Deterministic Workflow Triggers
            if (event === 'CLIENT_CREATED') {
                dispatchWorkflowNotifications({ event: 'CLIENT_CREATED', client });
            }

            if (isQualified && (!existingClient || (existingClient.payment.paid / existingClient.payment.total) < 0.7)) {
                dispatchWorkflowNotifications({ event: 'CLIENT_QUALIFIED', client });
            }

            return client;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return {
        clients,
        isLoading,
        hasNextPage,
        fetchNextPage,
        isFetchingNextPage,
        saveClient: (client: Client) => saveClientMutation.mutateAsync(client),
        deleteClient: (id: number) => deleteClientMutation.mutateAsync(id)
    };
};

export const useMilestones = (clientId?: number) => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: milestones = [] } = useQuery({
        queryKey: ['milestones', clientId],
        queryFn: () => dbService.fetchMilestones(clientId),
        enabled: isAuthenticated,
    });

    const saveMilestoneMutation = useMutation({
        mutationFn: dbService.persistMilestone,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['milestones'] })
    });

    return {
        milestones,
        saveMilestone: (milestone: MilestoneRecord) => saveMilestoneMutation.mutateAsync(milestone)
    };
};

