import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    DocumentTextIcon,
    ChartBarIcon,
    DocumentDuplicateIcon
} from '../components/icons/DummyIcons';
import { Button } from '../components/ui/Button';
import { Select } from '../components/ui/Input';
import { NotificationCenter } from '../components/NotificationCenter';
import { AccountOverview } from '../components/account/AccountOverview';
import { AccountHistory } from '../components/account/AccountHistory';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useProperties, useMilestones } from '../hooks/useAppData';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';
import { AccountStatementModal } from '../components/financials/AccountStatementModal';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect?: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
  overrideClientId?: number | null;
  isEmbedded?: boolean;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage, overrideClientId = null, isEmbedded = false
}) => {
  const { properties } = useProperties();
  const { saveMilestone } = useMilestones();
  const { openModal } = useModal();
  const [viewMode, setViewMode] = useState<'list' | 'alerts'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(overrideClientId);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isStatementModalOpen, setStatementModalOpen] = useState(false);

  useEffect(() => {
    if (overrideClientId !== null) {
      setSelectedClientId(overrideClientId);
    }
  }, [overrideClientId]);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (selectedClientId || clientForInvoice?.id))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);
  const isHeadOfAccounts = useMemo(() => currentStaff.roleId === 'Chief Accountant', [currentStaff]);

  // Rule: Statement access is restricted strictly to CEO and Chief Accountant
  const canGenerateStatement = useMemo(() => isCEO || isHeadOfAccounts, [isCEO, isHeadOfAccounts]);

  const canMakePayment = useMemo(() => {
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  const originalPricePerPlot = useMemo(() => {
    if (!selectedClient) return 0;
    const matchingProperty = properties.find(p => p.location === selectedClient.location);
    return matchingProperty ? matchingProperty.price : 0;
  }, [selectedClient, properties]);

  const discountAmount = selectedClient?.payment.promoDetails ? (originalPricePerPlot * 0.1) : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land';
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async (customMonths?: number, financialSnapshot?: any) => {
    if (!selectedClient) return;

    const monthsCount = installmentOption === 'Other' ? (customMonths || 1) : parseInt(installmentOption);

    if (installmentOption !== 'Outright' && (!monthsCount || monthsCount <= 0)) {
        alert("Please provide a valid number of months.");
        return;
    }

    setIsSaving(true);
    try {
        const finalPlanType = installmentOption === 'Outright' ? 'Outright' : `${monthsCount} Months`;

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: finalPlanType,
                total: financialSnapshot?.contractTotalAfterDiscount || priceAfterDiscount,
                balance: (financialSnapshot?.contractTotalAfterDiscount || priceAfterDiscount) - selectedClient.payment.paid,
                ...financialSnapshot // Persist all snapshot fields (emi, discount, etc)
            }
        };

        // SCHEDULE GENERATION LOGIC (FIRST TIME ONLY)
        const storageKey = `expected_schedule_${selectedClient.id}`;
        const existingSchedule = localStorage.getItem(storageKey);

        if (!existingSchedule && installmentOption !== 'Outright') {
            const expectedAmount = updatedClient.payment.total / monthsCount;
            const schedule = [];
            let currentDate = new Date();

            if (selectedClient.regDate) {
                currentDate = new Date(selectedClient.regDate);
            }

            for (let i = 1; i <= monthsCount; i++) {
                currentDate.setMonth(currentDate.getMonth() + 1);
                schedule.push({
                    id: `EXP-${selectedClient.id}-${i}`,
                    date: currentDate.toISOString().split('T')[0],
                    amount: expectedAmount,
                    type: 'EXPECTED PAYMENT',
                    description: `Month ${i} of ${monthsCount}`
                });
            }
            localStorage.setItem(storageKey, JSON.stringify(schedule));
        }

        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const newPaid = client.payment.paid + newTransaction.amount;
    const newBalance = client.payment.balance - newTransaction.amount;

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: newPaid,
            balance: newBalance,
        }
    };

    await onSaveClient(updatedClient);

    if (newBalance <= 0) {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PLR',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Full payment for land received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }

    if (paymentData.type === 'Indenture') {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PFI',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Payment for indenture documents received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }
  };

  const openPaymentModal = () => {
      if(selectedClient) {
          openModal(MODAL_TYPES.RECORD_PAYMENT, {
              client: selectedClient,
              onSave: (data: any) => handleRecordPayment(selectedClient, data)
          });
      }
  };

  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  return (
    <div className={`flex flex-col ${isEmbedded ? 'h-auto' : 'h-[calc(100vh-120px)]'} space-y-6`}>
      {!isEmbedded && (
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
              <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
              <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm font-medium">Standard bookkeeping ledger and transactional audit.</p>
          </div>
          <div className="flex gap-3">
            {/* Governance Gate: Button is only active for CEO and Chief Accountant */}
            {canGenerateStatement && (
              <Button 
                variant="secondary"
                disabled={!selectedClient}
                className="bg-indigo-50 border-indigo-200 text-indigo-700 dark:bg-indigo-900/20 dark:border-indigo-800 dark:text-indigo-400 font-bold"
                onClick={() => setStatementModalOpen(true)}
                icon={<DocumentDuplicateIcon className="w-5 h-5" />}
              >
                Official Statement
              </Button>
            )}
            <Button 
              variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
              onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
              icon={<BellIcon className="w-5 h-5" />}
              className="relative"
            >
                Role Alerts
                {roleAlerts.length > 0 && (
                    <span className="absolute -top-1 -right-1 flex h-4 w-4">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                    </span>
                )}
            </Button>
            <Button variant="secondary" onClick={() => setActivePage('Analytics & Reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
                Business Analysis
            </Button>
          </div>
        </div>
      )}

      <div className="flex-grow flex gap-6 overflow-hidden">
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          {!isEmbedded && (
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
               <Select 
                label="Select Account" 
                value={selectedClientId || ''} 
                onChange={(e) => {
                    setSelectedClientId(Number(e.target.value));
                    setClientForInvoice(null);
                }}
              >
                <option value="">-- Choose Client --</option>
                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </Select>
            </div>
          )}
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName}
                    onReschedule={() => {}}
                    onMarkRead={(id) => setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40 py-20">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">
                    {isEmbedded ? 'Client data unavailable.' : 'Select a Client to view financial records'}
                  </p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <AccountOverview
                    selectedClient={selectedClient}
                    originalPricePerPlot={originalPricePerPlot}
                    discountAmount={discountAmount}
                    priceAfterDiscount={priceAfterDiscount}
                    installmentOption={installmentOption}
                    setInstallmentOption={setInstallmentOption}
                    onInitialSave={handleInitialSave}
                    isSaving={isSaving}
                />
            ) : (
                <AccountHistory 
                    selectedClient={selectedClient}
                    canMakePayment={canMakePayment}
                    isCEO={isCEO}
                    onMakePayment={openPaymentModal}
                    onAuthorizeAmendment={() => setActivePage('Amendment Form', selectedClient)}
                    paymentAggregation={paymentAggregation}
                />
            )}
        </div>
      </div>

      {isStatementModalOpen && selectedClient && (
          <AccountStatementModal 
            isOpen={isStatementModalOpen}
            onClose={() => setStatementModalOpen(false)}
            client={selectedClient}
            properties={properties}
          />
      )}
    </div>
  );
};

export default AccountManagementPage;

import React, { useState, useMemo } from 'react';
import { Client, Property, PaymentTransaction } from '../../types';
import { XMarkIcon, PrinterIcon, PaperAirplaneIcon, BuildingLibraryIcon, BanknotesIcon, ChartBarIcon } from '../icons/DummyIcons';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../ui/Table';
import { useData } from '../../context/DataContext';
import { useAuth } from '../../context/AuthContext';

interface AccountStatementModalProps {
    isOpen: boolean;
    onClose: () => void;
    client: Client;
    properties: Property[];
    setActivePage: (page: string, context?: any) => void;
}

export const AccountStatementModal: React.FC<AccountStatementModalProps> = ({ isOpen, onClose, client, properties, setActivePage }) => {
    const { currentStaff } = useAuth();
    const [startDate, setStartDate] = useState(() => {
        const d = new Date();
        d.setMonth(0); d.setDate(1); // Default to Jan 1st
        return d.toISOString().split('T')[0];
    });
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [includePlots, setIncludePlots] = useState(true);
    const [isMailing, setIsMailing] = useState(false);

    const propertyInfo = useMemo(() => 
        properties.find(p => p.location === client.location)
    , [properties, client.location]);

    // Financial Calculation Logic: Chronological Ledger with specific Land-Sale columns
    const statementData = useMemo(() => {
        const start = new Date(startDate);
        const end = new Date(endDate);
        const today = new Date();

        // 1. Sort history chronologically
        const fullHistory = [...client.payment.paymentHistory].sort((a, b) => 
            new Date(a.date).getTime() - new Date(b.date).getTime()
        );

        let runningBalance = client.payment.total;
        const ledgerEntries: any[] = [];
        let totalPaidInPeriod = 0;

        // Base entry logic - Merge installments with history
        // If history is empty, we show the initial expectation
        if (fullHistory.length === 0) {
            ledgerEntries.push({
                type: 'Initial Deposit',
                expectedDate: client.regDate,
                actualDate: '',
                amount: 0,
                status: new Date(client.regDate) < today ? 'Overdue' : 'Pending',
                balance: runningBalance
            });
        } else {
            fullHistory.forEach((txn, idx) => {
                runningBalance -= txn.amount;
                const txnDate = new Date(txn.date);

                // Determine Row Type
                const rowType = idx === 0 ? 'Initial Deposit' : 'Instalment Payment';

                // Determine Status
                let status = 'Paid';
                if (txn.status === 'Failed') status = 'Adjustment';
                else if (txn.amount > (client.payment.total / 12)) status = 'Advance'; // Simplified logic for demo

                if (txnDate >= start && txnDate <= end) {
                    totalPaidInPeriod += txn.amount;
                }

                ledgerEntries.push({
                    type: rowType,
                    expectedDate: client.regDate, // Simplified: using regDate as expected for first, ideally map to installments array
                    actualDate: txn.date,
                    amount: txn.amount,
                    status: status,
                    balance: runningBalance
                });
            });
        }

        return {
            ledgerEntries,
            totalPaidInPeriod,
            closingBalance: runningBalance
        };
    }, [client, startDate, endDate]);

    // Role-Based Action Permissions: Authority Locked to CEO and Chief Accountant only
    const roleId = currentStaff?.roleId || '';
    const isAuthorized = ['CEO', 'Chief Accountant'].includes(roleId);

    const canExport = isAuthorized;
    const canMail = isAuthorized;

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const getStatusBadge = (status: string) => {
        switch (status) {
            case 'Paid': return <Badge variant="success">Paid</Badge>;
            case 'Partial': return <Badge variant="warning">Partial</Badge>;
            case 'Overdue': return <Badge variant="danger">Overdue</Badge>;
            case 'Advance': return <Badge variant="purple">Advance</Badge>;
            default: return <Badge variant="neutral">{status}</Badge>;
        }
    };

    const handlePrint = () => {
        if (!canExport) return;

        // Governance: Set document title to control generated PDF filename
        const originalTitle = document.title;
        const dateStamp = new Date().toISOString().split('T')[0];
        const formattedName = client.name.replace(/\s+/g, '_');
        document.title = `Statement_${formattedName}_${client.id}_${dateStamp}`;

        window.print();

        // Restore title for UI consistency
        document.title = originalTitle;
    };

    const handleSendMail = () => {
        if (!canMail) return;
        setIsMailing(true);

        const dateStamp = new Date().toISOString().split('T')[0];
        const filename = `Statement_${client.name.replace(/\s+/g, '_')}_${client.id}_${dateStamp}.pdf`;

        // Redirect to Mailing page with pre-filled state
        setActivePage('Mailing', {
            initialCompose: {
                subject: `Client Statement – ${client.name} (${dateStamp})`,
                body: `Dear Team,\n\nPlease find attached the account statement for ${client.name} for the period ${startDate} to ${endDate}.\n\nTotal Paid: ${formatCurrency(statementData.totalPaidInPeriod)}\nOutstanding Balance: ${formatCurrency(client.payment.balance)}\n\nStatement attached.`,
                attachments: [
                    {
                        name: filename,
                        url: '#system-generated', // Mock URL as we don't have a PDF generation service in this sandbox
                        type: 'application/pdf',
                        size: 102400 // Mock 100KB
                    }
                ]
            }
        });

        onClose();
        setIsMailing(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/90 z-[100] flex justify-center items-center p-4 backdrop-blur-sm overflow-hidden">
            <Card className="w-full max-w-5xl h-[95vh] p-0 flex flex-col shadow-2xl border-0 overflow-hidden bg-white">
                {/* Query & Action Bar - Hidden in Print */}
                <div className="p-4 border-b border-gray-100 bg-gray-50 flex flex-wrap items-center justify-between gap-4 print:hidden shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Start</span>
                            <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="text-xs p-1 rounded border border-gray-200" />
                        </div>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">End</span>
                            <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="text-xs p-1 rounded border border-gray-200" />
                        </div>
                        <label className="flex items-center gap-2 cursor-pointer">
                            <input type="checkbox" checked={includePlots} onChange={e => setIncludePlots(e.target.checked)} className="rounded" />
                            <span className="text-xs text-gray-600 font-bold uppercase">Show Plot Details</span>
                        </label>
                    </div>
                    <div className="flex gap-2">
                        <Button 
                            variant="secondary" 
                            size="sm" 
                            icon={<PrinterIcon className="w-4 h-4" />} 
                            onClick={handlePrint}
                            disabled={!canExport}
                            title={!canExport ? "Insufficient permissions to export" : ""}
                        >
                            Export PDF
                        </Button>
                        <Button 
                            variant="secondary" 
                            size="sm" 
                            icon={<PaperAirplaneIcon className="w-4 h-4 -rotate-45" />} 
                            onClick={handleSendMail} 
                            isLoading={isMailing}
                            disabled={!canMail}
                            title={!canMail ? "Insufficient permissions to mail financial docs" : ""}
                        >
                            Internal Mail
                        </Button>
                        <button onClick={onClose} className="p-1 hover:bg-gray-200 rounded-full transition-colors"><XMarkIcon className="w-6 h-6" /></button>
                    </div>
                </div>

                {/* THE STATEMENT AREA */}
                <div id="printable-statement" className="flex-grow p-10 overflow-y-auto scrollbar-thin text-slate-900">
                    <div className="max-w-4xl mx-auto space-y-10 min-h-full flex flex-col">

                        {/* I. Header */}
