                                    </Thead>
                                    <Tbody>
                                        {statementData.ledgerEntries.map((entry: any, idx: number) => (
                                            <Tr key={idx} className="border-b border-slate-100 last:border-0 hover:bg-slate-50/50 transition-colors">
                                                <Td className="px-4 py-4 font-bold">{entry.type}</Td>
