                                            </Tr>
                                        ))}
                                        {statementData.ledgerEntries.length === 0 && (
                                            <Tr>
                                                <Td colSpan={6} className="px-4 py-16 text-center text-slate-400 italic">
                                                    System Audit: No financial transactions found for this account.
                                                </Td>
                                            </Tr>
                                        )}
                                    </Tbody>
                                </table>
                            </div>
                        </div>

                        {/* V. Closing Summary */}
                        <div className="pt-10 border-t-4 border-slate-900 flex flex-col md:flex-row justify-between items-start gap-8 shrink-0">
                            <div className="space-y-4 flex-grow">
                                <div className="flex items-center gap-2 text-indigo-600">
                                    <ChartBarIcon className="w-5 h-5" />
                                    <h4 className="text-xs font-black uppercase tracking-widest">Period Audit Summary</h4>
