import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PurchaseSaleManagementPage from './pages/PurchaseSaleManagementPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import MappingsPage from './pages/MappingsPage';
import SupportPage from './pages/SupportPage';
import MessagingPage from './pages/MessagingPage';

// Team Module Pages
import LeadsManagementPage from './pages/LeadsManagementPage';
import MailingPage from './pages/team/MailingPage';
import LeavePage from './pages/team/LeavePage';
import EventsPage from './pages/team/EventsPage';
import AnnouncementsPage from './pages/team/AnnouncementsPage';

import { DataProvider, usePermissions } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { ModalProvider } from './context/ModalContext';
import { ModalManager } from './components/ModalManager';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { 
    useClients, useProperties, useInvoices, useStaff, useLeads, 
    usePromotions, useActivityLogs, useRoles, useAmendments, useCompanySettings 
} from './hooks/useAppData';
import { LoaderIcon } from './components/icons/LoaderIcon';
import { ShieldCheckIcon, LockClosedIcon } from './components/icons/DummyIcons';

const queryClient = new QueryClient();

const AuthenticatedApp: React.FC = () => {
    const { clients, saveClient, deleteClient } = useClients();
    const { properties, saveProperty } = useProperties();
    const { invoices, saveInvoice } = useInvoices();
    const { staff, updateStaff } = useStaff(); 
    const { leads, saveLead, deleteLead } = useLeads();
    const { promotions, savePromotion, deletePromotion } = usePromotions();
    const { activityLogs, addActivityLog } = useActivityLogs();
    const { roles, setRoles } = useRoles();
    const { amendments, setAmendmentList } = useAmendments();
    const { companySettings, setCompanySettings } = useCompanySettings();
    const { rolePermissions } = usePermissions();

    const { currentStaff, logout } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);
        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });
        return userPermissions;
    }, [currentStaff, rolePermissions]);

    const hasAccessToDashboard = useMemo(() => {
        return !!staffPermissions['Dashboard']?.view;
    }, [staffPermissions]);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        // Deep linking logic for Account Management
        if (page === 'Account Management' && context && (context.id || context.clientId)) {
            setClientForInvoice(context);
        }

        setActivePage(page);
        setPageContext(context);
    };

    // Restricted View for accounts without role permissions configured
    if (!hasAccessToDashboard && activePage === 'Dashboard') {
        return (
            <Layout 
                activePage={activePage} 
                setActivePage={handleSetPage} 
                currentStaff={currentStaff!} 
                onLogout={logout}
                staffPermissions={staffPermissions}
                companySettings={companySettings}
            >
                <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-8 bg-white dark:bg-gray-800 rounded-2xl border-2 border-dashed border-gray-100 dark:border-gray-700">
                    <div className="w-20 h-20 bg-amber-50 dark:bg-amber-900/20 rounded-full flex items-center justify-center mb-6">
                        <ShieldCheckIcon className="w-10 h-10 text-amber-600" />
                    </div>
                    <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Pending Configuration</h2>
                    <p className="mt-2 text-gray-500 dark:text-gray-400 max-w-md">Your identity is verified, but your specific role access permissions are not yet configured. Please contact the System Administrator to finalize your account setup.</p>
                </div>
            </Layout>
        );
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard': return <Dashboard />;
            case 'Clients': return <ClientsPage clients={clients} onSaveClient={saveClient} onDeleteClient={deleteClient} properties={properties} milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]} onClientSelect={(client) => handleSetPage('Client Details', client)} setActivePage={handleSetPage} setClientForInvoice={setClientForInvoice} invoices={invoices} addActivityLog={handleAddActivityLog} />;
            case 'Client Details': return <ClientDetailPage client={pageContext} properties={properties} onBack={() => handleSetPage('Clients')} currentStaff={currentStaff!} roles={roles} setActivePage={handleSetPage} />;
            case 'Account Management': return <AccountManagementPage clients={clients} onSaveClient={saveClient} invoices={invoices} onSaveInvoice={saveInvoice} clientForInvoice={clientForInvoice} setClientForInvoice={setClientForInvoice} receiptPattern={null} setReceiptPattern={() => {}} setReceiptAlerts={() => {}} currentStaff={currentStaff!} roles={roles} setActivePage={handleSetPage} />;
            case 'Leads & Follow-Ups': return <LeadsManagementPage onSaveLead={saveLead} onDeleteLead={deleteLead} clients={clients} onSaveClient={saveClient} staffList={staff} roles={roles} properties={properties} milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]} currentStaff={currentStaff!} addActivityLog={handleAddActivityLog} />;
            case 'Mailing': return <MailingPage initialCompose={pageContext?.initialCompose} />;
            case 'Leave': return <LeavePage />;
            case 'Events': return <EventsPage />;
            case 'Announcements': return <AnnouncementsPage />;
            case 'Messaging': return <MessagingPage />;
            case 'Settings': return <SettingsPage currentStaff={currentStaff!} staff={staff} roles={roles} setRoles={setRoles} onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)} companySettings={companySettings} setCompanySettings={setCompanySettings} onUpdateStaff={updateStaff} />;
            case 'CEO Hub': return <CEOHub setActivePage={handleSetPage} properties={properties} clients={clients} invoices={invoices} staff={staff} roles={roles} onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)} addActivityLog={handleAddActivityLog} />;
            case 'Properties': return <PropertiesPage properties={properties} currentStaff={currentStaff!} initialProperty={pageContext} onBack={() => handleSetPage('Purchase & Sale Management')} />;
            case 'New Land Acquisition': return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
            case 'Purchase & Sale Management': return <PurchaseSaleManagementPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} currentStaff={currentStaff!} setActivePage={handleSetPage} />;
            case 'Promotions': return <PromotionsPage promotions={promotions} onSavePromotion={savePromotion} onDeletePromotion={deletePromotion} properties={properties} showForm={true} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
            case 'Administration': return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Human Resources': return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts': return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot': return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation': return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings': return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form': return <AmendmentFormPage client={pageContext} onBack={() => handleSetPage('Client Details', pageContext)} onSave={async (data, updatedClient) => { setAmendmentList(prev => [data, ...prev]); await saveClient(updatedClient); handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`); alert('Amendment processed successfully!'); handleSetPage('Client Details', updatedClient); }} currentStaff={currentStaff!} />;
            case 'Analytics & Reports': return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports': return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity': return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Support': return <SupportPage />;
            default: return <Dashboard />;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff!} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
            <ModalManager />
        </Layout>
    );
};

const AppContent: React.FC = () => {
    const { loading, sessionStatus, currentStaff, login, authError } = useAuth();
    const { companySettings } = useCompanySettings();

    // Effect to update favicon and page title
    useEffect(() => {
        if (companySettings.name) {
            document.title = `${companySettings.name} - Enterprise Dashboard`;
        }
        if (companySettings.favicon) {
            let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
            if (!link) {
                link = document.createElement('link');
                link.rel = 'icon';
                document.getElementsByTagName('head')[0].appendChild(link);
            }
            link.href = companySettings.favicon;
        }
    }, [companySettings.name, companySettings.favicon]);

    // Application Lifecycle Guard
    if (loading || sessionStatus === 'authenticating' || sessionStatus === 'resolving_profile' || sessionStatus === 'bootstrapping') {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-950">
                <LoaderIcon className="w-12 h-12 text-blue-600 animate-spin mb-4" />
                <p className="text-sm font-bold text-gray-400 uppercase tracking-widest animate-pulse">
                    {sessionStatus === 'bootstrapping' ? 'Initializing profile...' : 'Authorizing access...'}
                </p>
            </div>
        );
    }

    // Auth Error or Missing Profile Gating
    if (!currentStaff) {
        return (
            <LoginPage 
                onLogin={login} 
                companySettings={companySettings} 
                externalError={authError} 
            />
        );
    }

    return <AuthenticatedApp />;
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <ModalProvider>
                    <AuthProvider>
                        <DataProvider>
                            <AppContent />
                        </DataProvider>
                    </AuthProvider>
                </ModalProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Button } from '../../components/ui/Button';
import { PlusCircleIcon, EnvelopeIcon, ChevronLeftIcon, ChevronRightIcon } from '../../components/icons/DummyIcons';
import { useStaff, useActivityLogs, useRoles } from '../../hooks/useAppData';
import { useAuth } from '../../context/AuthContext';
import { useData } from '../../context/DataContext';
import { InternalMail } from '../../types';

// Modular components
import { MailingSidebar, MailFolder } from '../../components/mailing/MailingSidebar';
import { MailingDashboard } from '../../components/mailing/MailingDashboard';
import { MailList } from '../../components/mailing/MailList';
import { MailDetail } from '../../components/mailing/MailDetail';
import { ComposeModal, ComposeInitialData } from '../../components/mailing/ComposeModal';

interface MailingPageProps {
    initialCompose?: ComposeInitialData;
}

const MailingPage: React.FC<MailingPageProps> = ({ initialCompose }) => {
    const { staff } = useStaff();
    const { roles } = useRoles();
    const { currentStaff } = useAuth();
    const { addActivityLog } = useActivityLogs();
    const { internalMails, sendMail, markMailAsRead, deleteMail, restoreMail, permanentDeleteMail } = useData();

    // UI State
    const [activeFolder, setActiveFolder] = useState<MailFolder>('dashboard');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedMail, setSelectedMail] = useState<InternalMail | null>(null);
    const [isComposeOpen, setComposeOpen] = useState(false);
    const [isMobileListOpen, setMobileListOpen] = useState(true);
    const [composeInitialData, setComposeInitialData] = useState<ComposeInitialData | undefined>(initialCompose);

    // Effect to handle initial compose data on mount
    useEffect(() => {
        if (initialCompose) {
            setComposeInitialData(initialCompose);
            setComposeOpen(true);
        }
    }, [initialCompose]);

    // Pagination State
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage, setItemsPerPage] = useState(10);

    // Reset pagination on filter change
    useEffect(() => {
        setCurrentPage(1);
    }, [activeFolder, searchTerm]);

    // Filter Mails based on active folder and current user
    const allFilteredMails = useMemo(() => {
        if (!currentStaff) return [];
        return internalMails.filter(m => {
            // Basic relation check
            const isSender = m.senderId === currentStaff.id;
            const isRecipient = m.recipientIds.includes(currentStaff.id);
            const isParticipant = isSender || isRecipient;

            if (!isParticipant) return false;

            // Search filter
            if (searchTerm) {
                const search = searchTerm.toLowerCase();
                if (!m.subject.toLowerCase().includes(search) && !m.senderName.toLowerCase().includes(search)) {
                    return false;
                }
            }

            // Folder Logic
            if (activeFolder === 'trash') {
                return m.isDeleted;
            }

            if (m.isDeleted) return false;

            switch (activeFolder) {
                case 'inbox': return isRecipient;
                case 'sent': return isSender;
                case 'drafts': return isSender && m.isDraft;
                default: return true;
            }
        }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [internalMails, activeFolder, currentStaff, searchTerm]);

    // Apply Pagination
    const paginatedMails = useMemo(() => {
        const startIndex = (currentPage - 1) * itemsPerPage;
        return allFilteredMails.slice(startIndex, startIndex + itemsPerPage);
    }, [allFilteredMails, currentPage, itemsPerPage]);

    const totalPages = Math.ceil(allFilteredMails.length / itemsPerPage);
    const startIndex = (currentPage - 1) * itemsPerPage;

    const stats = useMemo(() => {
        if (!currentStaff) return { unread: 0, sent: 0, drafts: 0, trash: 0 };
        return {
            unread: internalMails.filter(m => m.recipientIds.includes(currentStaff.id) && !m.readBy.includes(currentStaff.id) && !m.isDeleted && !m.isDraft).length,
            sent: internalMails.filter(m => m.senderId === currentStaff.id && !m.isDraft && !m.isDeleted).length,
            drafts: internalMails.filter(m => m.senderId === currentStaff.id && m.isDraft && !m.isDeleted).length,
            trash: internalMails.filter(m => m.isDeleted && (m.senderId === currentStaff.id || m.recipientIds.includes(currentStaff.id))).length
        };
    }, [internalMails, currentStaff]);

    // Actions
    const handleOpenMail = (mail: InternalMail) => {
        setSelectedMail(mail);
        setMobileListOpen(false);
        if (currentStaff && !mail.readBy.includes(currentStaff.id)) {
            markMailAsRead(mail.id);
        }
    };

    const handleSend = async (mailData: any) => {
        if (!currentStaff) return;

        try {
            await sendMail({
                senderId: currentStaff.id,
                senderName: currentStaff.fullName,
                recipientIds: mailData.recipientIds,
                groupIds: mailData.groupIds,
                subject: mailData.subject,
                body: mailData.body,
                attachments: mailData.attachments,
                timestamp: new Date().toISOString(),
                readBy: [currentStaff.id],
                isDraft: false,
                isDeleted: false
            });

            addActivityLog('Create', `Sent internal mail: ${mailData.subject}`, currentStaff.id);
            setComposeOpen(false);
            setComposeInitialData(undefined);
            setActiveFolder('sent');
        } catch (error) {
            console.error("Failed to send mail:", error);
            alert("Failed to send message. Please try again.");
        }
    };

    const handleReply = (type: 'reply' | 'replyAll') => {
        if (!selectedMail || !currentStaff) return;

        let recipients = [selectedMail.senderId];
        if (type === 'replyAll') {
            // Add original recipients, exclude self
            const others = selectedMail.recipientIds.filter(id => id !== currentStaff.id);
            recipients = [...recipients, ...others];
            // Remove duplicates
            recipients = Array.from(new Set(recipients));
        }

        const quote = `\n\n\n--------------------------------\nOn ${new Date(selectedMail.timestamp).toLocaleString()}, ${selectedMail.senderName} wrote:\n\n${selectedMail.body}`;

        setComposeInitialData({
            recipientIds: recipients,
            subject: selectedMail.subject.startsWith('Re:') ? selectedMail.subject : `Re: ${selectedMail.subject}`,
            body: quote
        });
        setComposeOpen(true);
    };

    const handleAction = async (id: string, action: 'delete' | 'restore' | 'permanent') => {
        try {
            if (action === 'delete') {
                await deleteMail(id);
                if (selectedMail?.id === id) setSelectedMail(null);
            } else if (action === 'restore') {
                await restoreMail(id);
                if (selectedMail?.id === id) setSelectedMail(null);
            } else if (action === 'permanent') {
                if (window.confirm('Delete permanently? This cannot be undone.')) {
                    await permanentDeleteMail(id);
                    if (selectedMail?.id === id) setSelectedMail(null);
                }
            }
        } catch (error) {
            console.error("Mail action failed:", error);
        }
    };

    return (
        <div className="flex flex-col h-[calc(100vh-120px)] space-y-4">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Internal Mailing</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Secure communication within the organization.</p>
                </div>
                <Button onClick={() => { setComposeInitialData(undefined); setComposeOpen(true); }} icon={<PlusCircleIcon className="w-5 h-5" />}>
                    Compose Mail
                </Button>
            </div>

            <div className="flex-grow flex bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
                <MailingSidebar 
                    activeFolder={activeFolder} 
                    onFolderSelect={(folder) => { setActiveFolder(folder); setSelectedMail(null); setMobileListOpen(true); }} 
                    stats={stats}
                />

                {activeFolder === 'dashboard' ? (
                    <MailingDashboard 
                        stats={stats} 
                        recentMails={internalMails.filter(m => m.recipientIds.includes(currentStaff?.id || '') && !m.isDeleted).slice(0, 5)} 
                        currentStaff={currentStaff} 
                        onOpenMail={(m) => { setActiveFolder('inbox'); handleOpenMail(m); }}
                    />
                ) : (
                    <>
                        <div className={`w-full md:w-96 flex flex-col ${!isMobileListOpen ? 'hidden md:flex' : 'flex'} border-r border-gray-200 dark:border-gray-700`}>
                            <MailList 
                                mails={paginatedMails}
                                searchTerm={searchTerm}
                                onSearchChange={setSearchTerm}
                                activeFolder={activeFolder}
                                selectedMailId={selectedMail?.id}
                                onSelectMail={handleOpenMail}
                                currentStaff={currentStaff}
                            />
                            {/* Pagination Controls */}
                            {allFilteredMails.length > 0 && (
                                <div className="p-3 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 flex items-center justify-between text-xs text-gray-600 dark:text-gray-400 flex-shrink-0">
                                    <div className="flex items-center gap-2">
                                        <span>Rows:</span>
                                        <select 
                                            value={itemsPerPage} 
                                            onChange={(e) => { setItemsPerPage(Number(e.target.value)); setCurrentPage(1); }}
                                            className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded px-1 py-0.5 focus:outline-none focus:ring-1 focus:ring-blue-500"
                                        >
                                            <option value={10}>10</option>
                                            <option value={20}>20</option>
                                            <option value={30}>30</option>
                                            <option value={40}>40</option>
                                            <option value={50}>50</option>
                                            <option value={100}>100</option>
                                        </select>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span>{startIndex + 1}-{Math.min(startIndex + itemsPerPage, allFilteredMails.length)} of {allFilteredMails.length}</span>
                                        <button 
                                            disabled={currentPage === 1}
                                            onClick={() => setCurrentPage(p => p - 1)}
                                            className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded disabled:opacity-30 transition-colors"
                                        >
                                            <ChevronLeftIcon className="w-4 h-4" />
                                        </button>
                                        <button 
                                            disabled={currentPage === totalPages}
                                            onClick={() => setCurrentPage(p => p + 1)}
                                            className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded disabled:opacity-30 transition-colors"
                                        >
                                            <ChevronRightIcon className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>

                        <div className={`flex-grow flex flex-col bg-white dark:bg-gray-800 ${isMobileListOpen ? 'hidden md:flex' : 'flex'}`}>
                            {selectedMail ? (
                                <MailDetail 
                                    mail={selectedMail}
                                    activeFolder={activeFolder}
                                    onBack={() => setMobileListOpen(true)}
                                    onAction={handleAction}
                                    onReply={handleReply}
                                />
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50 p-10 text-center">
                                    <div className="w-20 h-20 bg-gray-50 dark:bg-gray-900/50 rounded-full flex items-center justify-center mb-4">
                                        <EnvelopeIcon className="w-10 h-10 opacity-20" />
                                    </div>
                                    <p className="text-lg font-black uppercase tracking-tighter">Workspace Idle</p>
                                    <p className="text-xs max-w-xs mt-1">Select a message from the list to begin reading or manage your folder.</p>
                                </div>
                            )}
                        </div>
                    </>
                )}
            </div>

            <ComposeModal 
                isOpen={isComposeOpen}
                onClose={() => { setComposeOpen(false); setComposeInitialData(undefined); }}
                staff={staff}
                roles={roles}
                onSend={handleSend}
                initialData={composeInitialData}
            />

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 4px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
        </div>
    );
};

export default MailingPage;

import React, { useState, useRef, useEffect } from 'react';
import { Staff, Role } from '../../types';
import { XMarkIcon, PaperClipIcon, PaperAirplaneIcon, ChevronDownIcon, CheckCircleIcon } from '../icons/DummyIcons';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Badge } from '../ui/Badge';
import { uploadFile } from '../../services/storageService';

export interface ComposeInitialData {
    recipientIds?: string[];
    subject?: string;
    body?: string;
    attachments?: { name: string; url: string; type: string; size: number }[];
}

interface ComposeModalProps {
    isOpen: boolean;
    onClose: () => void;
    staff: Staff[];
    roles: Role[];
    onSend: (data: any) => void;
    initialData?: ComposeInitialData;
}

export const ComposeModal: React.FC<ComposeModalProps> = ({ isOpen, onClose, staff, roles, onSend, initialData }) => {
    const [targetType, setTargetType] = useState<'individual' | 'group'>('individual');
    const [recipientIds, setRecipientIds] = useState<string[]>([]);
    const [groupIds, setGroupIds] = useState<string[]>([]);
    const [subject, setSubject] = useState('');
    const [body, setBody] = useState('');
    const [pendingFiles, setPendingFiles] = useState<File[]>([]);
    const [initialAttachments, setInitialAttachments] = useState<{ name: string; url: string; type: string; size: number }[]>([]);
    const [isProcessing, setIsProcessing] = useState(false);

    // Dropdown State
    const [isRecipientDropdownOpen, setRecipientDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    // Initialize state when modal opens, potentially with reply or statement data
    useEffect(() => {
        if (isOpen) {
            if (initialData) {
                setRecipientIds(initialData.recipientIds || []);
                setSubject(initialData.subject || '');
                setBody(initialData.body || '');
                setInitialAttachments(initialData.attachments || []);
                setTargetType('individual');
                setGroupIds([]);
            } else {
                setRecipientIds([]);
                setSubject('');
                setBody('');
                setInitialAttachments([]);
                setGroupIds([]);
                setTargetType('individual');
            }
            setPendingFiles([]);
        }
    }, [isOpen, initialData]);

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setRecipientDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    if (!isOpen) return null;

    const toggleRecipient = (id: string) => {
        setRecipientIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsProcessing(true);
        try {
            const uploadedFiles = await Promise.all(
                pendingFiles.map(async (file) => {
                    const url = await uploadFile(file, `internal_mail/tmp/${Date.now()}_${file.name}`);
                    return { name: file.name, url, size: file.size, type: file.type };
                })
            );

            // Merge with system-generated attachments (initialAttachments)
            const attachmentData = [...initialAttachments, ...uploadedFiles];

            // Resolve recipients if group is selected
            let finalRecipientIds = [...recipientIds];
            if (targetType === 'group') {
                if (groupIds.includes('ALL_STAFF')) {
                    finalRecipientIds = staff.map(s => s.id);
                } else {
                    finalRecipientIds = staff.filter(s => groupIds.includes(s.roleId)).map(s => s.id);
                }
            }

            // Basic validation
            if (finalRecipientIds.length === 0 && groupIds.length === 0) {
                alert("Please select at least one recipient.");
                setIsProcessing(false);
                return;
            }

            onSend({ recipientIds: finalRecipientIds, groupIds, subject, body, attachments: attachmentData });
        } catch (e) {
            console.error(e);
            setIsProcessing(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            {/* Direct div container to control flex layout without Card padding interference */}
            <div className="w-full max-w-3xl bg-white dark:bg-gray-800 rounded-xl shadow-2xl flex flex-col max-h-[85vh] overflow-hidden border border-gray-200 dark:border-gray-700">
                <form onSubmit={handleSubmit} className="flex flex-col h-full overflow-hidden">
                    {/* Fixed Header */}
                    <div className="p-5 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900 shrink-0">
                        <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Draft Correspondence</h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    {/* Scrollable Content Area */}
                    <div className="p-6 space-y-5 overflow-y-auto scrollbar-thin flex-grow bg-white dark:bg-gray-800 min-h-0">
                        <div className="flex gap-4 border-b border-gray-100 dark:border-gray-700 pb-4">
                            <button type="button" onClick={() => setTargetType('individual')} className={`text-xs font-black uppercase tracking-widest pb-1 ${targetType === 'individual' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-400'}`}>To Individual</button>
                            <button type="button" onClick={() => setTargetType('group')} className={`text-xs font-black uppercase tracking-widest pb-1 ${targetType === 'group' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-400'}`}>To Group</button>
                        </div>

                        {targetType === 'individual' ? (
                            <div className="space-y-1 relative" ref={dropdownRef}>
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Select Recipients*</label>
                                <button
                                    type="button"
                                    onClick={() => setRecipientDropdownOpen(!isRecipientDropdownOpen)}
                                    className="w-full p-2.5 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl text-sm text-left flex justify-between items-center hover:border-blue-500 transition-colors"
                                >
                                    <span className={`truncate ${recipientIds.length === 0 ? 'text-gray-400' : 'text-gray-900 dark:text-white'}`}>
                                        {recipientIds.length > 0
                                            ? `${recipientIds.length} Recipient${recipientIds.length > 1 ? 's' : ''} Selected`
                                            : 'Choose staff members...'}
                                    </span>
                                    <ChevronDownIcon className={`w-4 h-4 text-gray-500 transition-transform ${isRecipientDropdownOpen ? 'rotate-180' : ''}`} />
                                </button>

                                {isRecipientDropdownOpen && (
                                    <div className="absolute z-50 mt-1 w-full bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-xl max-h-60 overflow-y-auto scrollbar-thin">
                                        {staff.map(s => (
                                            <div 
                                                key={s.id} 
                                                onClick={() => toggleRecipient(s.id)} 
                                                className="flex items-center justify-between p-3 hover:bg-gray-50 dark:hover:bg-gray-700 cursor-pointer border-b border-gray-100 dark:border-gray-800 last:border-0"
                                            >
                                                <div className="flex items-center gap-3 overflow-hidden">
                                                    <div className={`w-4 h-4 rounded border flex items-center justify-center transition-colors ${recipientIds.includes(s.id) ? 'bg-blue-600 border-blue-600' : 'border-gray-300 dark:border-gray-600'}`}>
                                                        {recipientIds.includes(s.id) && <svg className="w-3 h-3 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><polyline points="20 6 9 17 4 12"></polyline></svg>}
                                                    </div>
                                                    <span className="text-sm text-gray-700 dark:text-gray-200 truncate">{s.fullName} ({s.email})</span>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                                <div className="flex flex-wrap gap-2 mt-2">
                                    {recipientIds.map(id => {
                                        const user = staff.find(s => s.id === id);
                                        if (!user) return null;
                                        return (
                                            <Badge key={id} variant="neutral" className="flex items-center gap-1">
                                                {user.fullName}
                                                <button type="button" onClick={() => toggleRecipient(id)} className="hover:text-red-500"><XMarkIcon className="w-3.5 h-3.5" /></button>
                                            </Badge>
                                        )
                                    })}
                                </div>
                            </div>
                        ) : (
                            <div className="space-y-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Select User Groups*</label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl text-sm min-h-[100px] focus:ring-2 focus:ring-blue-500"
                                    value={groupIds}
                                    onChange={(e) => setGroupIds(Array.from(e.target.selectedOptions).map(o => (o as HTMLOptionElement).value))}
                                >
                                    <option value="ALL_STAFF">ALL STAFF</option>
                                    {roles.map(r => <option key={r.id} value={r.id}>DEPT: {r.name.toUpperCase()}</option>)}
                                </select>
                            </div>
                        )}

                        <Input label="Subject Line*" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Main purpose of message..." required />

                        <div className="space-y-1">
                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Message Body* (Rich Text Supported)</label>
                            <textarea 
                                value={body} 
                                onChange={e => setBody(e.target.value)} 
                                rows={8} 
                                className="w-full p-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl text-sm focus:ring-2 focus:ring-blue-500"
                                placeholder="Type your internal message here..."
                                required 
                            />
                        </div>

                        <div className="p-4 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-700">
                            <p className="text-[10px] font-black text-gray-400 uppercase mb-3 tracking-widest">Internal Attachments</p>
                            <div className="flex flex-wrap gap-2 mb-4">
                                {/* System-Generated Attachments (Pre-filled) */}
                                {initialAttachments.map((f, i) => (
                                    <Badge key={`init-${i}`} variant="success" className="flex items-center gap-2 font-bold px-3 py-1.5 ring-1 ring-green-200">
                                        <span className="truncate max-w-[150px]">{f.name} (Auto)</span>
                                        <button type="button" onClick={() => setInitialAttachments(prev => prev.filter((_, idx) => idx !== i))} className="hover:text-red-500 transition-colors"><XMarkIcon className="w-3.5 h-3.5" /></button>
                                    </Badge>
                                ))}

                                {/* User-Uploaded Files */}
                                {pendingFiles.map((f, i) => (
                                    <Badge key={`pending-${i}`} variant="info" className="flex items-center gap-2 font-bold px-3 py-1.5">
                                        <span className="truncate max-w-[150px]">{f.name}</span>
                                        <button type="button" onClick={() => setPendingFiles(prev => prev.filter((_, idx) => idx !== i))} className="hover:text-red-500"><XMarkIcon className="w-3.5 h-3.5" /></button>
                                    </Badge>
                                ))}
                            </div>
                            <label className="inline-flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-lg text-xs font-black uppercase tracking-widest cursor-pointer hover:bg-gray-100 border border-gray-200 dark:border-gray-700 shadow-sm transition-all">
                                <PaperClipIcon className="w-4 h-4 text-blue-600" /> Add Resource
                                <input type="file" multiple className="sr-only" onChange={e => e.target.files && setPendingFiles(prev => [...prev, ...Array.from(e.target.files!)])} />
                            </label>
                        </div>
                    </div>

                    {/* Fixed Footer with Send Button */}
                    <div className="p-5 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3 shrink-0">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit" isLoading={isProcessing} icon={<PaperAirplaneIcon className="w-5 h-5 -rotate-45" />}>Send Message</Button>
                    </div>
                </form>
            </div>
        </div>
    );
};

