import React, { useMemo } from 'react';
import { Client } from '../../types';
import { PlusCircleIcon, ShieldCheckIcon, ArrowTrendingUpIcon } from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../../components/ui/Table';

interface AccountHistoryProps {
    selectedClient: Client;
    canMakePayment: boolean;
    isCEO: boolean;
    isAccountant: boolean;
    onMakePayment: () => void;
    onAuthorizeAmendment: () => void;
    onOpenRefund: () => void;
    paymentAggregation: { land: number; indenture: number };
}

export const AccountHistory: React.FC<AccountHistoryProps> = ({
    selectedClient,
    canMakePayment,
    isCEO,
    isAccountant,
    onMakePayment,
    onAuthorizeAmendment,
    onOpenRefund,
    paymentAggregation
}) => {
    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const canManageRefund = isCEO || isAccountant;

    const mergedLedger = useMemo(() => {
        // 1. Get real transactions
        const history = selectedClient.payment.paymentHistory.map(txn => ({
            ...txn,
            isExpected: false,
            displayType: (txn as any).type || 'Land'
        }));

        // 2. Get expected schedule from localStorage
        const storageKey = `expected_schedule_${selectedClient.id}`;
        const rawSchedule = localStorage.getItem(storageKey);
        const schedule = rawSchedule ? JSON.parse(rawSchedule).map((item: any) => ({
            ...item,
            isExpected: true,
            displayType: 'EXPECTED PAYMENT',
            status: 'Pending'
        })) : [];

        // 3. Merge and sort chronologically
        const combined = [...history, ...schedule].sort((a, b) => 
            new Date(a.date).getTime() - new Date(b.date).getTime()
        );

        return combined;
    }, [selectedClient]);

    return (
        <div className="space-y-6 animate-in fade-in duration-300">
            <Card title="Transactional Ledger History" action={
                <div className="flex gap-2">
                    <Button 
                        variant="secondary" 
                        size="sm" 
                        onClick={onOpenRefund}
                        icon={<ArrowTrendingUpIcon className="w-4 h-4 rotate-180" />}
                    >
                        {canManageRefund ? 'Manage Refund' : 'View Refund Status'}
                    </Button>
                    <Button 
                        variant="primary" 
                        size="sm" 
                        disabled={!canMakePayment}
                        onClick={onMakePayment}
                        icon={<PlusCircleIcon className="w-4 h-4" />}
                        title={!canMakePayment ? "Insufficient permissions" : "Post new payment"}
                    >
                        Make Payment
                    </Button>
                    <Button 
                        variant="secondary" 
                        size="sm" 
                        disabled={!isCEO}
                        onClick={onAuthorizeAmendment}
                        icon={<ShieldCheckIcon className="w-4 h-4" />}
                    >
                        Authorize Amendment
                    </Button>
                </div>
            }>
                <TableContainer className="border-0 shadow-none">
                    <table className="w-full text-sm text-left">
                        <Thead>
                            <tr>
                                <Th>Type</Th>
                                <Th>Actual Date</Th>
                                <Th>Scheduled Date</Th>
                                <Th className="text-right">Amount</Th>
                                <Th className="text-center">Status</Th>
                                <Th className="text-right">Description</Th>
                            </tr>
                        </Thead>
                        <Tbody>
                            {mergedLedger.length === 0 ? (
                                <Tr>
                                    <Td colSpan={6} className="text-center py-12 text-gray-400 italic">No transactional records found.</Td>
                                </Tr>
                            ) : (
                                mergedLedger.map((item, idx) => {
                                    const isFuture = new Date(item.date) > new Date();

                                    return (
                                        <Tr key={item.id || idx} className={item.isExpected ? 'opacity-70 border-dashed bg-blue-50/10 dark:bg-blue-900/5' : ''}>
                                            <Td className={`font-bold ${item.isExpected ? 'text-blue-500 italic' : 'text-gray-600 dark:text-gray-400'}`}>
                                                {item.displayType}
                                            </Td>
                                            <Td className="font-mono text-gray-600 dark:text-gray-400">
                                                {item.isExpected ? '—' : (item.date || '—')}
                                            </Td>
                                            <Td className={`font-bold ${item.isExpected ? 'text-blue-600' : 'text-gray-900 dark:text-white'}`}>
                                                {item.date || '—'}
                                            </Td>
                                            <Td className={`text-right font-black ${item.isExpected ? 'text-blue-400' : 'text-green-600'}`}>
                                                {formatCurrency(item.amount)}
                                            </Td>
                                            <Td className="text-center">
                                                <Badge variant={item.isExpected ? 'neutral' : (isFuture ? 'info' : 'success')}>
                                                    {item.isExpected ? 'EXPECTED' : (isFuture ? 'SCHEDULED' : 'PAID')}
                                                </Badge>
                                            </Td>
                                            <Td className="text-right font-medium text-gray-500">
                                                {item.isExpected ? item.description : (item.receiptNumber || 'Ref Entry')}
                                            </Td>
                                        </Tr>
                                    );
                                })
                            )}
                        </Tbody>
                    </table>
                </TableContainer>

                <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4 border-t border-gray-100 dark:border-gray-700 pt-6">
                    <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-100 dark:border-blue-900/50">
                        <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Total Land Payments Made</p>
                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(paymentAggregation.land)}</p>
                    </div>
                    <div className="p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-xl border border-emerald-100 dark:border-emerald-900/50">
                        <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Total Indenture Payments Made</p>
                        <p className="text-xl font-black text-emerald-700 dark:text-blue-300">{formatCurrency(paymentAggregation.indenture)}</p>
                    </div>
                </div>
            </Card>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Client, RefundPlan } from '../../types';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input, Textarea } from '../ui/Input';
import { Badge } from '../ui/Badge';
import { ExclamationTriangleIcon, CheckCircleIcon, ArrowTrendingUpIcon } from '../icons/DummyIcons';

interface RefundPlanFormProps {
    client: Client;
    canEdit: boolean;
    onSave: (plan: RefundPlan) => Promise<void>;
    isSaving: boolean;
    userName: string;
}

export const RefundPlanForm: React.FC<RefundPlanFormProps> = ({ client, canEdit, onSave, isSaving, userName }) => {
    const [formData, setFormData] = useState<Partial<RefundPlan>>({
        totalAmount: 0,
        schedulePattern: '',
        startDate: '',
        endDate: '',
        isCompleted: false
    });

    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (client.refundPlan) {
            setFormData(client.refundPlan);
        } else {
            setFormData({
                totalAmount: client.payment.paid, // Default to total paid
                schedulePattern: '',
                startDate: new Date().toISOString().split('T')[0],
                endDate: '',
                isCompleted: false
            });
        }
    }, [client]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (!formData.startDate || !formData.endDate) {
            setError("Start and End dates are mandatory.");
            return;
        }

        if (new Date(formData.endDate) <= new Date(formData.startDate)) {
            setError("Refund End Date must be after the Start Date.");
            return;
        }

        if (!formData.totalAmount || formData.totalAmount <= 0) {
            setError("Please specify a valid refund amount.");
            return;
        }

        try {
            await onSave({
                ...formData,
                totalAmount: Number(formData.totalAmount),
                createdAt: formData.createdAt || new Date().toISOString(),
                createdBy: formData.createdBy || userName,
            } as RefundPlan);
            alert("Refund plan updated successfully.");
        } catch (err: any) {
            setError(err.message || "Failed to save refund plan.");
        }
    };

    const handleMarkComplete = async () => {
        if (!confirm("Are you sure you want to mark this refund as FINALIZED? This will lock the plan.")) return;

        await onSave({
            ...formData,
            isCompleted: true,
            completedAt: new Date().toISOString(),
            closedBy: userName
        } as RefundPlan);
    };

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    return (
        <div className="space-y-6 animate-in fade-in duration-300">
            <Card title="Refund Liquidation Plan" action={
                formData.isCompleted ? <Badge variant="success">Refund Finalized</Badge> : (client.refundPlan ? <Badge variant="warning">Plan Active</Badge> : <Badge variant="neutral">No Plan</Badge>)
            }>
                <form onSubmit={handleSubmit} className="space-y-6">
                    {error && (
                        <div className="p-3 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded flex gap-2">
                            <ExclamationTriangleIcon className="w-5 h-5 text-red-600 shrink-0" />
                            <p className="text-sm text-red-800 dark:text-red-200">{error}</p>
                        </div>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <Input 
                            label="Total Refund Amount (GHS)*" 
                            type="number" 
                            value={formData.totalAmount} 
                            onChange={e => setFormData({...formData, totalAmount: Number(e.target.value)})}
                            disabled={!canEdit || formData.isCompleted}
                            className="font-black text-lg"
                        />
                        <div className="space-y-1">
                            <label className="text-xs font-black text-gray-400 uppercase">Current Account Standing</label>
                            <div className="p-2.5 bg-gray-50 dark:bg-gray-900 rounded-lg border border-gray-100 dark:border-gray-800 text-sm font-bold">
                                Total Paid to Date: <span className="text-blue-600">{formatCurrency(client.payment.paid)}</span>
                            </div>
                        </div>
                        <Input 
                            label="Refund Start Date*" 
                            type="date" 
                            value={formData.startDate} 
                            onChange={e => setFormData({...formData, startDate: e.target.value})}
                            disabled={!canEdit || formData.isCompleted}
                        />
                        <Input 
                            label="Projected End Date*" 
                            type="date" 
                            value={formData.endDate} 
                            onChange={e => setFormData({...formData, endDate: e.target.value})}
                            disabled={!canEdit || formData.isCompleted}
                        />
                    </div>

                    <Textarea 
                        label="Repayment Schedule Pattern" 
                        value={formData.schedulePattern} 
                        onChange={e => setFormData({...formData, schedulePattern: e.target.value})}
                        disabled={!canEdit || formData.isCompleted}
                        placeholder="e.g. ₵5,000 monthly over 10 months via Bank Transfer."
                        rows={4}
                    />

                    {canEdit && !formData.isCompleted && (
                        <div className="flex justify-between items-center pt-6 border-t border-gray-100 dark:border-gray-700">
                            <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase">
                                <ArrowTrendingUpIcon className="w-4 h-4 rotate-180" />
                                Audit: Initialized by {formData.createdBy || userName}
                            </div>
                            <div className="flex gap-3">
                                {client.refundPlan && (
                                    <Button 
                                        type="button" 
                                        variant="success" 
                                        onClick={handleMarkComplete}
                                        icon={<CheckCircleIcon className="w-4 h-4" />}
                                    >
                                        Mark as Completed
                                    </Button>
                                )}
                                <Button type="submit" isLoading={isSaving}>
                                    {client.refundPlan ? 'Update Plan' : 'Commit Refund Plan'}
                                </Button>
                            </div>
                        </div>
                    )}
                </form>
            </Card>

            <div className="p-4 bg-amber-50 dark:bg-amber-900/10 rounded-xl border border-amber-100 dark:border-amber-900 flex items-start gap-4">
                <ExclamationTriangleIcon className="w-6 h-6 text-amber-600 shrink-0 mt-0.5" />
                <div>
                    <p className="text-xs font-bold text-amber-800 dark:text-amber-300 uppercase tracking-widest">Financial Governance Protocol</p>
                    <p className="text-xs text-amber-700 dark:text-amber-400 mt-1 leading-relaxed">
                        A refund plan does not delete historical payment transactions. It tracks the liability of the company back to the client. Full reconciliation must be verified by the CEO before final closing.
                    </p>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification, RefundPlan } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    DocumentTextIcon,
    ChartBarIcon,
    DocumentDuplicateIcon,
    ArrowTrendingUpIcon
} from '../components/icons/DummyIcons';
import { Button } from '../components/ui/Button';
import { Select } from '../components/ui/Input';
import { NotificationCenter } from '../components/NotificationCenter';
import { AccountOverview } from '../components/account/AccountOverview';
import { AccountHistory } from '../components/account/AccountHistory';
import { RefundPlanForm } from '../components/account/RefundPlanForm';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useProperties, useMilestones } from '../hooks/useAppData';
import { useModal } from '../context/ModalContext';
import { MODAL_TYPES } from '../components/ModalManager';
import { AccountStatementModal } from '../components/financials/AccountStatementModal';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect?: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
  overrideClientId?: number | null;
  isEmbedded?: boolean;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage, overrideClientId = null, isEmbedded = false
}) => {
  const { properties } = useProperties();
  const { saveMilestone } = useMilestones();
  const { openModal } = useModal();
  const [viewMode, setViewMode] = useState<'list' | 'alerts'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history' | 'refund'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(overrideClientId);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isStatementModalOpen, setStatementModalOpen] = useState(false);

  useEffect(() => {
    if (overrideClientId !== null) {
      setSelectedClientId(overrideClientId);
    }
  }, [overrideClientId]);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (selectedClientId || clientForInvoice?.id))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);
  const isAccountant = useMemo(() => currentStaff.roleId === 'Chief Accountant', [currentStaff]);

  // Rule: Statement access is restricted strictly to CEO and Chief Accountant
  const canGenerateStatement = useMemo(() => isCEO || isAccountant, [isCEO, isAccountant]);

  const canMakePayment = useMemo(() => {
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  const originalPricePerPlot = useMemo(() => {
    if (!selectedClient) return 0;
    const matchingProperty = properties.find(p => p.location === selectedClient.location);
    return matchingProperty ? matchingProperty.price : 0;
  }, [selectedClient, properties]);

  const discountAmount = selectedClient?.payment.promoDetails ? (originalPricePerPlot * 0.1) : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land';
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async (customMonths?: number, financialSnapshot?: any) => {
    if (!selectedClient) return;

    const monthsCount = installmentOption === 'Other' ? (customMonths || 1) : parseInt(installmentOption);

    if (installmentOption !== 'Outright' && (!monthsCount || monthsCount <= 0)) {
        alert("Please provide a valid number of months.");
        return;
    }

    setIsSaving(true);
    try {
        const finalPlanType = installmentOption === 'Outright' ? 'Outright' : `${monthsCount} Months`;

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: finalPlanType,
                total: financialSnapshot?.contractTotalAfterDiscount || priceAfterDiscount,
                balance: (financialSnapshot?.contractTotalAfterDiscount || priceAfterDiscount) - selectedClient.payment.paid,
                ...financialSnapshot // Persist all snapshot fields (emi, discount, etc)
            }
        };

        // SCHEDULE GENERATION LOGIC (FIRST TIME ONLY)
        const storageKey = `expected_schedule_${selectedClient.id}`;
        const existingSchedule = localStorage.getItem(storageKey);

        if (!existingSchedule && installmentOption !== 'Outright') {
            const expectedAmount = updatedClient.payment.total / monthsCount;
            const schedule = [];
            let currentDate = new Date();

            if (selectedClient.regDate) {
                currentDate = new Date(selectedClient.regDate);
            }

            for (let i = 1; i <= monthsCount; i++) {
                currentDate.setMonth(currentDate.getMonth() + 1);
                schedule.push({
                    id: `EXP-${selectedClient.id}-${i}`,
                    date: currentDate.toISOString().split('T')[0],
                    amount: expectedAmount,
                    type: 'EXPECTED PAYMENT',
                    description: `Month ${i} of ${monthsCount}`
                });
            }
            localStorage.setItem(storageKey, JSON.stringify(schedule));
        }

        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const newPaid = client.payment.paid + newTransaction.amount;
    const newBalance = client.payment.balance - newTransaction.amount;

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: newPaid,
            balance: newBalance,
        }
    };

    await onSaveClient(updatedClient);

    if (newBalance <= 0) {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PLR',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Full payment for land received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }

    if (paymentData.type === 'Indenture') {
        saveMilestone({
            clientId: client.id,
            milestoneCode: 'PFI',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Payment for indenture documents received.'
        }).catch(e => console.warn("Background Milestone update failed:", e));
    }
  };

  const handleSaveRefundPlan = async (plan: RefundPlan) => {
    if (!selectedClient) return;
    setIsSaving(true);
    try {
        const updatedClient = {
            ...selectedClient,
            refundPlan: plan,
            status: plan.isCompleted ? 'Refunded' as const : 'Active Client' as const
        };
        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const openPaymentModal = () => {
      if(selectedClient) {
          openModal(MODAL_TYPES.RECORD_PAYMENT, {
              client: selectedClient,
              onSave: (data: any) => handleRecordPayment(selectedClient, data)
          });
      }
  };

  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  return (
    <div className={`flex flex-col ${isEmbedded ? 'h-auto' : 'h-[calc(100vh-120px)]'} space-y-6`}>
      {!isEmbedded && (
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
              <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
              <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm font-medium">Standard bookkeeping ledger and transactional audit.</p>
          </div>
          <div className="flex gap-3">
            {/* Governance Gate: Button is only active for CEO and Chief Accountant */}
            {canGenerateStatement && (
              <Button 
                variant="secondary"
                disabled={!selectedClient}
                className="bg-indigo-50 border-indigo-200 text-indigo-700 dark:bg-indigo-900/20 dark:border-indigo-800 dark:text-indigo-400 font-bold"
                onClick={() => setStatementModalOpen(true)}
                icon={<DocumentDuplicateIcon className="w-5 h-5" />}
              >
                Official Statement
              </Button>
            )}
            <Button 
              variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
              onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
              icon={<BellIcon className="w-5 h-5" />}
              className="relative"
            >
                Role Alerts
                {roleAlerts.length > 0 && (
                    <span className="absolute -top-1 -right-1 flex h-4 w-4">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                    </span>
                )}
            </Button>
            <Button variant="secondary" onClick={() => setActivePage('Analytics & Reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
                Business Analysis
            </Button>
          </div>
        </div>
      )}

      <div className="flex-grow flex gap-6 overflow-hidden">
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          {!isEmbedded && (
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
               <Select 
                label="Select Account" 
                value={selectedClientId || ''} 
                onChange={(e) => {
                    setSelectedClientId(Number(e.target.value));
                    setClientForInvoice(null);
                }}
              >
                <option value="">-- Choose Client --</option>
                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </Select>
            </div>
          )}
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
            {selectedClient && (
              <button 
                onClick={() => setActiveSubModule('refund')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'refund' ? 'bg-amber-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
              >
                <ArrowTrendingUpIcon className="w-5 h-5 rotate-180" />
                Refunds
              </button>
            )}
          </nav>
        </div>

        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName}
                    onReschedule={() => {}}
                    onMarkRead={(id) => setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40 py-20">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">
                    {isEmbedded ? 'Client data unavailable.' : 'Select a Client to view financial records'}
                  </p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <AccountOverview
                    selectedClient={selectedClient}
                    originalPricePerPlot={originalPricePerPlot}
                    discountAmount={discountAmount}
                    priceAfterDiscount={priceAfterDiscount}
                    installmentOption={installmentOption}
                    setInstallmentOption={setInstallmentOption}
                    onInitialSave={handleInitialSave}
                    isSaving={isSaving}
                />
            ) : activeSubModule === 'history' ? (
                <AccountHistory 
                    selectedClient={selectedClient}
                    canMakePayment={canMakePayment}
                    isCEO={isCEO}
                    isAccountant={isAccountant}
                    onMakePayment={openPaymentModal}
                    onAuthorizeAmendment={() => setActivePage('Amendment Form', selectedClient)}
                    onOpenRefund={() => setActiveSubModule('refund')}
                    paymentAggregation={paymentAggregation}
                />
            ) : (
                <RefundPlanForm 
                    client={selectedClient}
                    canEdit={isCEO || isAccountant}
                    userName={currentStaff.fullName}
                    isSaving={isSaving}
                    onSave={handleSaveRefundPlan}
                />
            )}
        </div>
      </div>

      {isStatementModalOpen && selectedClient && (
          <AccountStatementModal 
            isOpen={isStatementModalOpen}
            onClose={() => setStatementModalOpen(false)}
            client={selectedClient}
            properties={properties}
            setActivePage={setActivePage}
          />
      )}
    </div>
  );
};

export default AccountManagementPage;

import React from 'react';
import { Client, Milestone } from '../types';
import { EyeIcon, PencilIcon, CheckCircleIcon, ExclamationTriangleIcon, TrashIcon } from './icons/DummyIcons';

interface ClientListItemProps {
  client: Client;
  onViewDetails: (client: Client) => void;
  onEdit: (client: Client) => void;
  onDelete: (clientId: number) => void;
  milestones: Milestone[];
  style?: React.CSSProperties; // For virtualization positioning
  isExpanded?: boolean;
  onToggleExpand?: () => void;
}

const getStatusColor = (status: string) => {
  switch (status) {
    case 'Active Client':
      return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
    case 'Refunded':
      return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200';
    case 'Refund Ongoing':
      return 'bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200';
    case 'Refund Scheduled':
      return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200';
    case 'Reallocated':
      return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200';
    default:
      return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300';
  }
};

const formatCurrency = (amount: number) => {
    return `₵${new Intl.NumberFormat('en-GH').format(amount)}`;
};

const ClientListItem: React.FC<ClientListItemProps> = ({ 
    client, 
    onViewDetails, 
    onEdit, 
    onDelete, 
    style
}) => {
  const getDisplayStatus = () => {
    if (client.refundPlan) {
        if (client.refundPlan.isCompleted) return 'Refunded';
        if (client.refundPlan.isCancelled) return 'Active Client';

        const today = new Date().toISOString().split('T')[0];
        if (today < client.refundPlan.startDate) return 'Refund Scheduled';
        return 'Refund Ongoing';
    }
    return client.status;
  };

  const displayStatus = getDisplayStatus();

  return (
    <div style={style} className="px-2">
        <div className="bg-white dark:bg-gray-900/50 py-2 px-4 border-b border-gray-100 dark:border-gray-800 grid grid-cols-12 gap-4 items-center hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors h-full">
            {/* Client & Phone */}
            <div className="col-span-12 md:col-span-4 flex items-center gap-3">
                <div 
                    title={client.isComplete ? 'Complete' : 'Incomplete'}
                    className={`w-9 h-9 rounded-full flex items-center justify-center font-bold flex-shrink-0 text-xs text-white ${client.isComplete ? 'bg-green-500' : 'bg-red-500'}`}
                >
                    {client.initials}
                </div>
                <div className="flex-grow min-w-0">
                    <p className="text-base font-bold text-gray-900 dark:text-white flex items-center gap-1.5 truncate">
                        {client.name}
                        <span title={client.isComplete ? "Complete" : "Incomplete"}>
                            {client.isComplete 
                                ? <CheckCircleIcon className="w-4 h-4 text-green-500" /> 
                                : <ExclamationTriangleIcon className="w-4 h-4 text-red-500" />}
                        </span>
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400 font-medium">{client.phone}</p>
                </div>
            </div>

            {/* Location */}
            <div className="col-span-12 md:col-span-4 text-sm">
                <p className="font-semibold text-gray-700 dark:text-gray-200 truncate" title={client.location}>
                    {client.location}
                </p>
                <p className="text-xs text-gray-400 truncate">{client.plot}</p>
            </div>

            {/* Status */}
            <div className="col-span-6 md:col-span-2 text-center">
                <span className={`px-3 py-1 text-[10px] font-black uppercase tracking-tighter rounded-full whitespace-nowrap ${getStatusColor(displayStatus)}`}>
                    {displayStatus}
                </span>
            </div>

            {/* Financials (Outstanding Only) */}
            <div className="col-span-12 md:col-span-1 text-sm">
                <p className="font-black text-gray-800 dark:text-gray-200 text-right">{formatCurrency(client.payment.balance)}</p>
            </div>

            {/* Actions */}
            <div className="col-span-12 md:col-span-1 flex items-center gap-1 justify-end">
                <button onClick={() => onViewDetails(client)} className="text-gray-400 hover:text-blue-600 p-1.5 rounded-full transition-colors" title="View">
                    <EyeIcon className="w-5 h-5"/>
                </button>
                <button onClick={() => onEdit(client)} className="text-gray-400 hover:text-green-600 p-1.5 rounded-full transition-colors" title="Edit">
                    <PencilIcon className="w-5 h-5"/>
                </button>
                <button onClick={() => onDelete(client.id)} className="text-gray-400 hover:text-red-600 p-1.5 rounded-full transition-colors" title="Delete">
                    <TrashIcon className="w-5 h-5"/>
                </button>
            </div>
        </div>
    </div>
  );
};

export default ClientListItem;

export type ActivityLogType = 'Login' | 'Logout' | 'Create' | 'Update' | 'Delete' | 'View' | 'Import';

export interface ActivityLog {
    id: number;
    userId: string;
    type: ActivityLogType;
    description: string;
    timestamp: string;
}

