export const SMSGatewaySettings: React.FC = () => {
    const [config, setConfig] = useState<SMSConfig>({
        provider: 'Disabled',
        apiKey: '',
        senderId: '',
        baseUrl: 'https://api.mnotify.com/api/sms/send',
        isConnected: false,
        updatedAt: ''
    });
