import React, { useState, useMemo } from 'react';
import { Client, RefundRecord } from '../../types';
import { XMarkIcon, ExclamationTriangleIcon, UploadIcon, LockClosedIcon } from '../icons/DummyIcons';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input, Select, Textarea } from '../ui/Input';
import { uploadFile } from '../../services/storageService';

interface RefundRequestModalProps {
    isOpen: boolean;
    onClose: () => void;
    client: Client;
    onSave: (data: RefundRecord) => Promise<void>;
    userName: string;
    userRole: string;
}

export const RefundRequestModal: React.FC<RefundRequestModalProps> = ({ 
    isOpen, onClose, client, onSave, userName, userRole 
}) => {
    const [formData, setFormData] = useState({
        reason: '',
        channel: 'Bank Transfer' as any,
        otherCosts: 0,
        instalmentPeriod: 1,
        withholdingApplied: true
    });

    const [signedForm, setSignedForm] = useState<File | null>(null);
    const [refundLetter, setRefundLetter] = useState<File | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const totalPaid = client.payment.paid;

    const financialBreakdown = useMemo(() => {
        const withholding = formData.withholdingApplied ? totalPaid * 0.25 : 0;
        const other = Number(formData.otherCosts) || 0;
        const refundable = Math.max(0, totalPaid - withholding - other);

        return { withholding, other, refundable };
    }, [totalPaid, formData]);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (!signedForm || !refundLetter) {
            setError("Both the Signed Refund Form and Refund Letter are mandatory (PDF only).");
            return;
        }

        if (financialBreakdown.refundable <= 0) {
            setError("The total refundable amount must be greater than zero.");
            return;
        }

        setIsSubmitting(true);
        try {
            const formUrl = await uploadFile(signedForm, `refunds/${client.id}/form_${Date.now()}.pdf`);
            const letterUrl = await uploadFile(refundLetter, `refunds/${client.id}/letter_${Date.now()}.pdf`);

            const record: RefundRecord = {
                id: `REF-${client.id}-${Date.now()}`,
                clientId: client.id,
                reason: formData.reason,
                channel: formData.channel,
                otherCosts: formData.otherCosts,
                instalmentPeriod: formData.instalmentPeriod,
                withholdingApplied: formData.withholdingApplied,
                withholdingAmount: financialBreakdown.withholding,
                totalPaidAtRequest: totalPaid,
                refundableAmount: financialBreakdown.refundable,
                outstandingRefundBalance: financialBreakdown.refundable,
                signedFormUrl: formUrl,
                refundLetterUrl: letterUrl,
                status: 'Refund Requested',
                requestedBy: userName,
                requestedByRole: userRole,
                timestamp: new Date().toISOString()
            };

            await onSave(record);
            onClose();
        } catch (err: any) {
            setError(err.message || "Failed to submit request.");
        } finally {
            setIsSubmitting(false);
        }
    };

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <Card className="w-full max-w-2xl p-0 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                <form onSubmit={handleSubmit} className="flex flex-col h-full">
                    <div className="p-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 flex justify-between items-center shrink-0">
                        <div>
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Refund Request Initiation</h3>
                            <p className="text-[10px] text-gray-500 font-bold uppercase">{client.name} (Ref: {client.initials}-{client.id})</p>
                        </div>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    <div className="p-6 space-y-6 overflow-y-auto scrollbar-thin flex-grow bg-white dark:bg-gray-800">
                        {error && (
                            <div className="p-4 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded flex gap-3 animate-in slide-in-from-top-1">
                                <ExclamationTriangleIcon className="w-6 h-6 text-red-600 shrink-0 mt-0.5" />
                                <p className="text-sm text-red-800 dark:text-red-200 font-medium leading-relaxed">{error}</p>
                            </div>
                        )}

                        <div className="grid grid-cols-2 gap-4">
                            <div className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-800">
                                <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Total Paid (Ledger)</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{formatCurrency(totalPaid)}</p>
                            </div>
                            <div className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-800">
                                <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Account Balance</p>
                                <p className="text-lg font-black text-red-600">{formatCurrency(client.payment.balance)}</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <Select label="Refund Channel*" value={formData.channel} onChange={e => setFormData({...formData, channel: e.target.value as any})} required>
                                <option>Bank Transfer</option>
                                <option>Mobile Money</option>
                                <option>Cheque</option>
                                <option>Other</option>
                            </Select>
                            <Input label="Period (Months)*" type="number" value={formData.instalmentPeriod} onChange={e => setFormData({...formData, instalmentPeriod: Number(e.target.value)})} min="1" required />
                            <Input label="Other Costs (GHC)" type="number" value={formData.otherCosts} onChange={e => setFormData({...formData, otherCosts: Number(e.target.value)})} />
                            <div className="flex items-center gap-3 pt-6">
                                <input type="checkbox" id="withholding" checked={formData.withholdingApplied} onChange={e => setFormData({...formData, withholdingApplied: e.target.checked})} className="w-5 h-5 rounded text-blue-600 focus:ring-blue-500" />
                                <label htmlFor="withholding" className="text-sm font-bold text-gray-700 dark:text-gray-300 cursor-pointer">Apply 25% Withholding Tax</label>
                            </div>
                        </div>

                        <Textarea label="Reason for Refund Request*" rows={3} value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} required placeholder="Provide detailed justification..." />

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase block mb-1.5">Signed Refund Form (PDF)*</label>
                                <label className={`flex flex-col items-center justify-center w-full h-32 border-2 border-dashed rounded-xl cursor-pointer transition-all ${signedForm ? 'bg-green-50 border-green-200 dark:bg-green-900/10' : 'bg-gray-50 border-gray-200 dark:bg-gray-900/50 hover:border-blue-400'}`}>
                                    <div className="flex flex-col items-center justify-center p-4 text-center">
                                        <UploadIcon className={`w-8 h-8 mb-2 ${signedForm ? 'text-green-500' : 'text-gray-400'}`} />
                                        <p className="text-xs font-bold text-gray-500">{signedForm ? signedForm.name : 'Select PDF File'}</p>
                                    </div>
                                    <input type="file" className="hidden" accept="application/pdf" onChange={e => setSignedForm(e.target.files?.[0] || null)} />
                                </label>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase block mb-1.5">Refund Application Letter (PDF)*</label>
