                    </div>
                </form>
            </Card>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { Client, RefundRecord } from '../../types';
import { XMarkIcon, ExclamationTriangleIcon, UploadIcon, LockClosedIcon } from '../icons/DummyIcons';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input, Select, Textarea } from '../ui/Input';
import { uploadFile } from '../../services/storageService';

interface RefundRequestModalProps {
    isOpen: boolean;
    onClose: () => void;
    client: Client;
    onSave: (data: RefundRecord) => Promise<void>;
    userName: string;
    userRole: string;
}

export const RefundRequestModal: React.FC<RefundRequestModalProps> = ({ 
    isOpen, onClose, client, onSave, userName, userRole 
}) => {
    const [formData, setFormData] = useState({
        reason: '',
        channel: 'Bank Transfer' as any,
        otherCosts: 0,
        instalmentPeriod: 1,
        withholdingApplied: true
    });

    const [signedForm, setSignedForm] = useState<File | null>(null);
    const [refundLetter, setRefundLetter] = useState<File | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const totalPaid = client.payment.paid;

    const financialBreakdown = useMemo(() => {
        const withholding = formData.withholdingApplied ? totalPaid * 0.25 : 0;
        const other = Number(formData.otherCosts) || 0;
        const refundable = Math.max(0, totalPaid - withholding - other);

        return { withholding, other, refundable };
    }, [totalPaid, formData]);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        // MANDATORY FIELD VALIDATION
        if (!formData.reason.trim()) {
            setError("A valid reason for refund must be provided.");
            return;
        }

        if (!signedForm || !refundLetter) {
            setError("Both the Signed Refund Form and Refund Letter are mandatory (PDF only).");
            return;
        }

        if (financialBreakdown.refundable <= 0) {
            setError("The total refundable amount must be greater than zero.");
            return;
        }

        setIsSubmitting(true);
        try {
            // Upload mandatory documents first
            const formUrl = await uploadFile(signedForm, `refunds/${client.id}/form_${Date.now()}.pdf`);
            const letterUrl = await uploadFile(refundLetter, `refunds/${client.id}/letter_${Date.now()}.pdf`);

            // Use deterministic ID based on client ID to update any existing pending record
            const record: RefundRecord = {
                id: `REF-${client.id}`,
                clientId: client.id,
                reason: formData.reason,
                channel: formData.channel,
                otherCosts: formData.otherCosts,
                instalmentPeriod: formData.instalmentPeriod,
                withholdingApplied: formData.withholdingApplied,
                withholdingAmount: financialBreakdown.withholding,
                totalPaidAtRequest: totalPaid,
                refundableAmount: financialBreakdown.refundable,
                outstandingRefundBalance: financialBreakdown.refundable,
                signedFormUrl: formUrl,
                refundLetterUrl: letterUrl,
                status: 'Refund Requested',
                requestedBy: userName,
                requestedByRole: userRole,
                timestamp: new Date().toISOString()
            };

            // CRITICAL: Await successful database write before closing UI
            await onSave(record);

            // On Success: Close the modal
            onClose();
        } catch (err: any) {
            console.error("Refund Save Error:", err);
            setError(err.message || "Refund request failed to save. Please verify your connection.");
            setIsSubmitting(false); // Re-enable the button to allow retry
        }
    };

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <Card className="w-full max-w-2xl p-0 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                <form onSubmit={handleSubmit} className="flex flex-col h-full">
                    <div className="p-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 flex justify-between items-center shrink-0">
                        <div>
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Refund Request Initiation</h3>
                            <p className="text-[10px] text-gray-500 font-bold uppercase">{client.name} (Ref: {client.initials}-{client.id})</p>
                        </div>
                        <button type="button" onClick={onClose} disabled={isSubmitting} className="text-gray-400 hover:text-gray-600 transition-colors"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    <div className="p-6 space-y-6 overflow-y-auto scrollbar-thin flex-grow bg-white dark:bg-gray-800">
                        {error && (
                            <div className="p-4 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded flex gap-3 animate-in slide-in-from-top-1">
                                <ExclamationTriangleIcon className="w-6 h-6 text-red-600 shrink-0 mt-0.5" />
                                <p className="text-sm text-red-800 dark:text-red-200 font-medium leading-relaxed">{error}</p>
                            </div>
                        )}

                        <div className="grid grid-cols-2 gap-4">
                            <div className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-800">
                                <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Total Paid (Ledger)</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{formatCurrency(totalPaid)}</p>
                            </div>
                            <div className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-800">
                                <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Account Balance</p>
                                <p className="text-lg font-black text-red-600">{formatCurrency(client.payment.balance)}</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <Select label="Refund Channel*" value={formData.channel} onChange={e => setFormData({...formData, channel: e.target.value as any})} required disabled={isSubmitting}>
                                <option>Bank Transfer</option>
                                <option>Mobile Money</option>
                                <option>Cheque</option>
                                <option>Other</option>
                            </Select>
                            <Input label="Period (Months)*" type="number" value={formData.instalmentPeriod} onChange={e => setFormData({...formData, instalmentPeriod: Number(e.target.value)})} min="1" required disabled={isSubmitting} />
                            <Input label="Other Costs for Refund (GHC)*" type="number" value={formData.otherCosts} onChange={e => setFormData({...formData, otherCosts: Number(e.target.value)})} disabled={isSubmitting} />
                            <div className="flex items-center gap-3 pt-6">
                                <input type="checkbox" id="withholding" checked={formData.withholdingApplied} onChange={e => setFormData({...formData, withholdingApplied: e.target.checked})} disabled={isSubmitting} className="w-5 h-5 rounded text-blue-600 focus:ring-blue-500" />
                                <label htmlFor="withholding" className="text-sm font-bold text-gray-700 dark:text-gray-300 cursor-pointer">Apply 25% Withholding Tax</label>
                            </div>
                        </div>

                        <Textarea label="Reason for Refund Request*" rows={3} value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} required disabled={isSubmitting} placeholder="Provide detailed justification..." />

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase block mb-1.5">Signed Refund Form (PDF)*</label>
                                <label className={`flex flex-col items-center justify-center w-full h-32 border-2 border-dashed rounded-xl cursor-pointer transition-all ${signedForm ? 'bg-green-50 border-green-200 dark:bg-green-900/10' : 'bg-gray-50 border-gray-200 dark:bg-gray-900/50 hover:border-blue-400'}`}>
                                    <div className="flex flex-col items-center justify-center p-4 text-center">
                                        <UploadIcon className={`w-8 h-8 mb-2 ${signedForm ? 'text-green-500' : 'text-gray-400'}`} />
                                        <p className="text-xs font-bold text-gray-500">{signedForm ? signedForm.name : 'Select PDF File'}</p>
                                    </div>
                                    <input type="file" className="hidden" accept="application/pdf" disabled={isSubmitting} onChange={e => setSignedForm(e.target.files?.[0] || null)} />
                                </label>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase block mb-1.5">Refund Application Letter (PDF)*</label>
                                <label className={`flex flex-col items-center justify-center w-full h-32 border-2 border-dashed rounded-xl cursor-pointer transition-all ${refundLetter ? 'bg-green-50 border-green-200 dark:bg-green-900/10' : 'bg-gray-50 border-gray-200 dark:bg-gray-900/50 hover:border-blue-400'}`}>
                                    <div className="flex flex-col items-center justify-center p-4 text-center">
                                        <UploadIcon className={`w-8 h-8 mb-2 ${refundLetter ? 'text-green-500' : 'text-gray-400'}`} />
                                        <p className="text-xs font-bold text-gray-500">{refundLetter ? refundLetter.name : 'Select PDF File'}</p>
                                    </div>
                                    <input type="file" className="hidden" accept="application/pdf" disabled={isSubmitting} onChange={e => setRefundLetter(e.target.files?.[0] || null)} />
                                </label>
                            </div>
                        </div>

                        <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-100 dark:border-blue-800 space-y-3">
                            <h4 className="text-xs font-black text-blue-800 dark:text-blue-300 uppercase tracking-widest flex items-center gap-2">
                                <LockClosedIcon className="w-4 h-4" /> Final Refundable Calculation
                            </h4>
                            <div className="space-y-2 text-sm">
                                <div className="flex justify-between text-blue-700 dark:text-blue-400">
                                    <span>Total Amount Paid (Base)</span>
                                    <span className="font-bold">{formatCurrency(totalPaid)}</span>
                                </div>
                                {formData.withholdingApplied && (
                                    <div className="flex justify-between text-red-600 dark:text-red-400">
                                        <span>25% Withholding Deduction</span>
                                        <span className="font-bold">-{formatCurrency(financialBreakdown.withholding)}</span>
                                    </div>
                                )}
                                {formData.otherCosts > 0 && (
                                    <div className="flex justify-between text-red-600 dark:text-red-400">
                                        <span>Other Deductible Costs</span>
                                        <span className="font-bold">-{formatCurrency(financialBreakdown.other)}</span>
                                    </div>
                                )}
                                <div className="pt-2 border-t border-blue-200 dark:border-blue-800 flex justify-between text-lg font-black text-blue-900 dark:text-white">
                                    <span>FINAL REFUNDABLE SUM</span>
                                    <span>{formatCurrency(financialBreakdown.refundable)}</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3 shrink-0">
                        <button type="button" onClick={onClose} disabled={isSubmitting} className="px-6 py-2 text-sm font-bold text-gray-500 hover:text-gray-800 transition-colors">Abort</button>
                        <Button type="submit" isLoading={isSubmitting} className="px-8 font-black uppercase tracking-widest text-xs">Commit Request</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

import React, { useMemo } from 'react';
import { Client, RefundRecord, RefundTransaction } from '../../types';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../ui/Table';
import { 
    ExclamationTriangleIcon, 
    CheckCircleIcon, 
    ArrowTrendingUpIcon, 
    PlusCircleIcon,
    DocumentTextIcon,
    LockClosedIcon,
    BanknotesIcon,
    InformationCircleIcon
} from '../icons/DummyIcons';
import { useRefunds, useClients } from '../../hooks/useAppData';
import { useModal } from '../../context/ModalContext';
import { MODAL_TYPES } from '../ModalManager';

interface RefundPlanFormProps {
    client: Client;
    canEdit: boolean;
    userName: string;
}

export const RefundPlanForm: React.FC<RefundPlanFormProps> = ({ client, canEdit, userName }) => {
    const { refundRecord, transactions, requestRefund, postTransaction } = useRefunds(client.id);
    const { saveClient } = useClients();
    const { openModal } = useModal();

    const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

    const handleInitiateRequest = () => {
        openModal(MODAL_TYPES.REFUND_REQUEST, {
            client,
            userName,
            userRole: canEdit ? 'Chief Accountant / CEO' : 'Staff',
            onSave: async (record: RefundRecord) => {
                // CRITICAL: Sequentially persist the refund request then update the client status
                await requestRefund(record);
                await saveClient({ 
                    ...client, 
                    status: 'Refunded', 
                    refundStatus: 'Refund Requested' 
                });
            }
        });
    };

    const handlePostPayment = () => {
        if (!refundRecord) return;
        openModal(MODAL_TYPES.REFUND_PAYMENT, {
            client,
            refundRecord,
            userName,
            onSave: async (txn: RefundTransaction) => {
                await postTransaction(txn);

                const newTotalPaid = client.payment.paid - txn.amount;
                const newBalance = client.payment.balance + txn.amount;

                await saveClient({
                    ...client,
                    refundStatus: (refundRecord.outstandingRefundBalance - txn.amount) <= 0 ? 'Refund Completed' : 'Refund Ongoing',
                    payment: {
                        ...client.payment,
                        paid: newTotalPaid,
                        balance: newBalance
                    }
                });
            }
        });
    };

    const isRequestActive = !!refundRecord;

    return (
        <div className="space-y-6 animate-in fade-in duration-300">
            {/* 1. Refund Request Details Summary Panel */}
            <Card title="Refund Request Details" action={
                <Badge variant={refundRecord?.status === 'Refund Completed' ? 'success' : isRequestActive ? 'warning' : 'neutral'}>
                    {refundRecord?.status || 'No Active Request'}
                </Badge>
            }>
                <div className="space-y-6">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                        <div className="space-y-1">
                            <p className="text-sm font-bold text-gray-700 dark:text-gray-300">
                                {isRequestActive ? 'A formal refund process is active for this account.' : 'Initialize the refund process based on governance protocols.'}
                            </p>
                            <p className="text-xs text-gray-500">All refunds require signed physical documentation scans.</p>
                        </div>
                        {canEdit && !isRequestActive && (
                            <Button 
                                onClick={handleInitiateRequest}
                                icon={<PlusCircleIcon className="w-5 h-5" />}
                                className="px-8 font-black uppercase tracking-widest text-xs shadow-lg"
                            >
                                Request Refund
                            </Button>
                        )}
                    </div>

                    {isRequestActive && (
                        <div className="space-y-6">
                            {/* Detailed Breakdown Grid */}
                            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 p-5 bg-gray-50 dark:bg-gray-900/50 rounded-2xl border border-gray-200 dark:border-gray-800">
                                <div>
                                    <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Total Paid (At Request)</p>
                                    <p className="text-lg font-bold text-gray-900 dark:text-white">{formatCurrency(refundRecord.totalPaidAtRequest)}</p>
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-gray-400 uppercase mb-1">25% Withholding</p>
                                    <p className="text-lg font-bold text-red-600">
                                        {refundRecord.withholdingApplied ? formatCurrency(refundRecord.withholdingAmount) : 'Not Applied'}
                                    </p>
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Other Deductible Costs</p>
                                    <p className="text-lg font-bold text-red-600">{formatCurrency(refundRecord.otherCosts)}</p>
                                </div>
                                <div className="bg-blue-50 dark:bg-blue-900/20 p-2 rounded-xl border border-blue-100 dark:border-blue-900/30">
                                    <p className="text-[10px] font-black text-blue-500 uppercase mb-1">Final Refundable Sum</p>
                                    <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(refundRecord.refundableAmount)}</p>
                                </div>
                            </div>

                            {/* Logistics & Balance Grid */}
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                <div className="p-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm">
                                    <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Refund Logistics</p>
                                    <div className="space-y-1">
                                        <p className="text-sm font-bold text-gray-700 dark:text-gray-200">Channel: <span className="font-normal">{refundRecord.channel}</span></p>
                                        <p className="text-sm font-bold text-gray-700 dark:text-gray-200">Period: <span className="font-normal">{refundRecord.instalmentPeriod} Months</span></p>
                                    </div>
                                </div>
                                <div className="p-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm">
                                    <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Payout Status</p>
                                    <div className="space-y-1">
                                        <p className="text-sm font-bold text-green-600">Settled: {formatCurrency(refundRecord.refundableAmount - refundRecord.outstandingRefundBalance)}</p>
                                        <p className="text-sm font-bold text-red-600">Outstanding: {formatCurrency(refundRecord.outstandingRefundBalance)}</p>
                                    </div>
                                </div>
                                <div className="p-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm flex items-center gap-3">
                                    <InformationCircleIcon className="w-8 h-8 text-indigo-500 opacity-20" />
                                    <div>
                                        <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Request Metadata</p>
                                        <p className="text-[10px] text-gray-500 font-medium italic">Requested by {refundRecord.requestedBy} on {new Date(refundRecord.timestamp).toLocaleDateString()}</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </Card>

            {/* 2. Mandatory Documentation Access */}
            {isRequestActive && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="p-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl flex items-center justify-between shadow-sm">
                        <div className="flex items-center gap-3">
                            <DocumentTextIcon className="w-6 h-6 text-blue-500" />
                            <div>
                                <p className="text-xs font-bold text-gray-800 dark:text-white">Signed Refund Form</p>
                                <p className="text-[10px] text-gray-500 uppercase font-black">Verified & Uploaded</p>
                            </div>
                        </div>
                        <a href={refundRecord.signedFormUrl} target="_blank" rel="noopener noreferrer" className="text-xs font-black text-blue-600 hover:underline">VIEW PDF</a>
                    </div>
                    <div className="p-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl flex items-center justify-between shadow-sm">
                        <div className="flex items-center gap-3">
                            <DocumentTextIcon className="w-6 h-6 text-indigo-500" />
                            <div>
                                <p className="text-xs font-bold text-gray-800 dark:text-white">Refund Application Letter</p>
                                <p className="text-[10px] text-gray-500 uppercase font-black">Verified & Uploaded</p>
                            </div>
                        </div>
                        <a href={refundRecord.refundLetterUrl} target="_blank" rel="noopener noreferrer" className="text-xs font-black text-blue-600 hover:underline">VIEW PDF</a>
                    </div>
                </div>
            )}

            {/* 3. Refund Payout Ledger (Separate from standard ledger) */}
            <Card title="Refund Payout Ledger" action={
                canEdit && isRequestActive && refundRecord.status !== 'Refund Completed' && (
                    <Button 
                        size="sm" 
                        variant="success" 
                        onClick={handlePostPayment}
                        icon={<BanknotesIcon className="w-4 h-4" />}
                    >
                        Make Refund Payment
                    </Button>
                )
            }>
                <TableContainer className="border-0 shadow-none">
                    <table className="w-full text-sm text-left">
                        <Thead>
                            <tr>
                                <Th>Payout Date</Th>
                                <Th className="text-right">Amount</Th>
                                <Th>Channel</Th>
                                <Th>Reference</Th>
                                <Th>Entered By</Th>
                                <Th className="text-right">System Timestamp</Th>
                            </tr>
                        </Thead>
                        <Tbody>
                            {transactions.length === 0 ? (
                                <Tr>
                                    <Td colSpan={6} className="text-center py-12 text-gray-400 italic">No refund payouts recorded yet.</Td>
                                </Tr>
                            ) : (
                                transactions.map(txn => (
                                    <Tr key={txn.id}>
                                        <Td className="font-bold text-gray-700 dark:text-gray-300">{txn.date}</Td>
                                        <Td className="text-right font-black text-red-600">{formatCurrency(txn.amount)}</Td>
                                        <Td><Badge variant="neutral">{txn.channel}</Badge></Td>
                                        <Td className="font-mono text-xs uppercase text-gray-500">{txn.reference}</Td>
                                        <Td className="text-xs font-bold text-gray-600">{txn.enteredBy}</Td>
                                        <Td className="text-right font-mono text-[10px] text-gray-400">
                                            {new Date(txn.timestamp).toLocaleString()}
                                        </Td>
                                    </Tr>
                                ))
                            )}
                        </Tbody>
                    </table>
                </TableContainer>
            </Card>

            <div className="p-4 bg-amber-50 dark:bg-amber-900/10 rounded-xl border border-amber-100 dark:border-amber-900 flex items-start gap-4">
                <ExclamationTriangleIcon className="w-6 h-6 text-amber-600 shrink-0 mt-0.5" />
                <div>
                    <p className="text-xs font-bold text-amber-800 dark:text-amber-300 uppercase tracking-widest">Financial Integrity Clause</p>
                    <p className="text-xs text-amber-700 dark:text-amber-400 mt-1 leading-relaxed">
                        Initiating a refund implies account closure. Once the refund balance reaches zero, the account will be marked as "Refund Completed" and locked. Historical payment transactions are retained for audit reconciliation.
                    </p>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { Client, RefundRecord } from '../../types';
