                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3 shrink-0">
                        <button type="button" onClick={onClose} disabled={isSubmitting} className="px-6 py-2 text-sm font-bold text-gray-500 hover:text-gray-800 transition-colors">Abort</button>
                        <Button type="submit" isLoading={isSubmitting} className="px-8 font-black uppercase tracking-widest text-xs">Commit Request</Button>
