    );
};

import { db } from './firebase';
import { 
    collection, getDocs, doc, setDoc, addDoc, 
    query, where, orderBy, onSnapshot, updateDoc, 
    serverTimestamp, deleteDoc 
} from 'firebase/firestore';
import { 
    MessageTemplate, 
    MessageOutbox, 
    MessageHistory, 
    ClientMessagingPreference 
} from '../types/messaging';

const TEMPLATES_COL = 'messaging_templates';
const OUTBOX_COL = 'messaging_outbox';
const HISTORY_COL = 'messaging_history';
const PREFS_COL = 'messaging_client_preferences';

// --- Templates ---
export const listenToTemplates = (callback: (templates: MessageTemplate[]) => void) => {
    return onSnapshot(collection(db, TEMPLATES_COL), (snapshot) => {
        callback(snapshot.docs.map(d => ({ id: d.id, ...d.data() } as MessageTemplate)));
    }, (error) => {
        console.warn("Messaging template listener blocked or failed:", error.message);
        callback([]);
    });
};

export const saveTemplate = async (template: MessageTemplate) => {
    await setDoc(doc(db, TEMPLATES_COL, template.id), {
        ...template,
        updatedAt: new Date().toISOString()
    });
};

// --- Manual Send / Outbox ---
export const queueMessage = async (message: Omit<MessageOutbox, 'id' | 'createdAt' | 'updatedAt'>) => {
    const now = new Date().toISOString();
    const docRef = await addDoc(collection(db, OUTBOX_COL), {
        ...message,
        createdAt: now,
        updatedAt: now
    });

    // Immutable History Log (Simulation of dispatch)
    if (message.status === 'SENT') {
        await addDoc(collection(db, HISTORY_COL), {
            messageId: docRef.id,
            clientId: message.clientId,
            channel: message.channel,
            category: message.category,
            recipient: message.toPhone || message.toEmail || 'Unknown',
            messagePreview: message.messageBodyFinal.substring(0, 100),
            status: 'SENT',
            timestamp: now,
            senderName: message.createdBy
        });
    }
};

// --- History ---
export const listenToMessageHistory = (callback: (history: MessageHistory[]) => void) => {
    const q = query(collection(db, HISTORY_COL), orderBy('timestamp', 'desc'));
    return onSnapshot(q, (snapshot) => {
        callback(snapshot.docs.map(d => ({ id: d.id, ...d.data() } as MessageHistory)));
    }, (error) => {
        console.warn("Messaging history listener blocked or failed:", error.message);
        callback([]);
    });
};

// --- Preferences ---
export const getClientPreferences = async (clientId: number): Promise<ClientMessagingPreference | null> => {
    const q = query(collection(db, PREFS_COL), where('clientId', '==', clientId));
    const snap = await getDocs(q);
    if (snap.empty) return null;
    return snap.docs[0].data() as ClientMessagingPreference;
};

export const updateClientPreferences = async (prefs: ClientMessagingPreference) => {
    const docId = `PREF_${prefs.clientId}`;
    await setDoc(doc(db, PREFS_COL, docId), {
        ...prefs,
        updatedAt: new Date().toISOString()
    });
};

// --- CEO Hub Stats ---
export const fetchMessagingStats = async () => {
    const today = new Date().toISOString().split('T')[0];
    const q = query(collection(db, HISTORY_COL), where('timestamp', '>=', today));
    try {
        const snap = await getDocs(q);
        return {
            sentToday: snap.size,
            failures: snap.docs.filter(d => d.data().status === 'FAILED').length
        };
    } catch (e) {
        return { sentToday: 0, failures: 0 };
    }
};

payload.text:
This patch fixes the broken **70% Qualification** and **48-hour Escalation** logic by implementing atomic threshold detection, deterministic trigger IDs, and role identity normalization.

### 1. Patch Plan
*   **Create `utils/roleUtils.ts`**: Centralizes role normalization to fix case-sensitivity bugs.
*   **Update `services/notificationService.ts`**: Implements deterministic `workflow_triggers` doc IDs to prevent deadlock and support escalation tracking.
*   **Update `services/clientDbService.ts`**: Enhances `atomicSaveClient` to calculate threshold crossing and stamp `qualifiedAt` atomically.
*   **Update `hooks/useNotificationTriggers.ts`**: Refactors client-side logic to use `qualifiedAt` for precise escalation and birthday alerts.
*   **Update `components/Layout.tsx`**: Applies role normalization to the Firestore notification listener.
*   **Update `hooks/modules/useClientHooks.ts`**: Ensures payment mutations correctly pass through the updated atomic save logic.

---

### 2. Code Changes

#### [NEW FILE] `utils/roleUtils.ts`
```typescript
export type NormalizedRole = 'CEO' | 'ADMIN' | 'CHIEF_ACCOUNTANT' | 'SITE_MANAGER' | 'FRONT_DESK' | 'SALES_HEAD' | 'UNKNOWN';

export const normalizeRole = (roleId: string | undefined): NormalizedRole => {
    if (!roleId) return 'UNKNOWN';
    const r = roleId.toUpperCase().trim();
    if (r === 'CEO') return 'CEO';
    if (r === 'ADMINISTRATOR' || r === 'ADMIN') return 'ADMIN';
    if (r === 'CHIEF ACCOUNTANT' || r === 'CHIEF_ACCOUNTANT') return 'CHIEF_ACCOUNTANT';
    if (r === 'SITE MANAGER' || r === 'SITE_MANAGER') return 'SITE_MANAGER';
    if (r === 'FRONT DESK' || r === 'FRONT_DESK_EXECUTIVE') return 'FRONT_DESK';
    if (r === 'HEAD OF SALES' || r === 'HEAD_OF_SALES') return 'SALES_HEAD';
    return 'UNKNOWN';
};
```

#### `services/notificationService.ts`
```typescript
import { db } from './firebase';
import { doc, setDoc, getDoc, serverTimestamp } from 'firebase/firestore';
import { Client } from '../types';

export type WorkflowEvent = 'CLIENT_CREATED' | 'CLIENT_QUALIFIED' | 'PAYMENT_DEFAULT';

export const dispatchWorkflowNotifications = async (event: WorkflowEvent, client: Client) => {
    try {
        // Use a deterministic ID to ensure exactly-once trigger per qualification cycle
        const triggerId = `${client.id}_${event}`;
        const triggerRef = doc(db, 'workflow_triggers', triggerId);

        const existing = await getDoc(triggerRef);
        // If already qualified and trigger exists, do not re-notify (Anti-Spam)
        if (existing.exists() && client.paidPercent && client.paidPercent >= 70 && event === 'CLIENT_QUALIFIED') {
            return;
        }

        const escalationHours = 48;
        const now = new Date();
        const dueAt = new Date(now.getTime() + escalationHours * 60 * 60 * 1000);

        await setDoc(triggerRef, {
            event,
            clientId: client.id,
            clientName: client.name,
            clientRef: `${client.initials}-${client.id}`,
            timestamp: serverTimestamp(),
            status: 'ACTIVE',
            // Escalation metadata
            isQualified: true,
            qualifiedAt: serverTimestamp(),
            escalationDueAt: dueAt.toISOString(),
            escalatedAt: null,
            allocationCompletedAt: client.allocationStatus === 'ALLOCATED' ? serverTimestamp() : null,
            processedBy: []
        }, { merge: true });

    } catch (e) {
        console.error(`[Workflow] Trigger failed for ${client.id}:`, e);
    }
};
```

#### `services/clientDbService.ts`
```typescript
// ... inside atomicSaveClient ...
export const atomicSaveClient = async (clientData: Partial<Client>) => {
    // ... existing normalization logic ...

    if (existing) {
        const merged: Client = { ...existing, ...clientData };

        // Authoritative Qualification Check
        const total = merged.payment.total || 0;
        const paid = merged.payment.paid || 0;
        const paidPercent = total > 0 ? (paid / total) * 100 : 0;

        const wasQualified = !!existing.isQualified;
        const isNowQualified = paidPercent >= 70;

        merged.paidPercent = paidPercent;

        // Transition: Crosses 70% threshold
        if (isNowQualified && !wasQualified) {
            merged.isQualified = true;
            merged.qualifiedAt = new Date().toISOString();
        } 
        // Sync allocation status to trigger cancels
        if (merged.allocationStatus === 'ALLOCATED' && existing.allocationStatus !== 'ALLOCATED') {
            merged.allocationDate = new Date().toISOString();
        }

        await setDoc(doc(db, CLIENTS_COL, String(merged.id)), sanitizeData(merged));
        return { client: merged, event: 'CLIENT_UPDATED_MERGED' as const, thresholdCrossed: (isNowQualified && !wasQualified) };
    } else {
        // ... existing create logic ...
        const newClient = { ...clientData, isQualified: false, paidPercent: 0 } as Client;
        await setDoc(doc(db, CLIENTS_COL, String(newClient.id)), sanitizeData(newClient));
        return { client: newClient, event: 'CLIENT_CREATED' as const, thresholdCrossed: false };
    }
};
```

#### `hooks/useNotificationTriggers.ts`
```typescript
import { useMemo } from 'react';
import { Client, AppNotification } from '../types';
import { normalizeRole } from '../utils/roleUtils';

export const useNotificationTriggers = (clients: Client[]) => {
    return useMemo(() => {
        const alerts: AppNotification[] = [];
        const now = new Date();

        clients.forEach(client => {
            // 1. Qualification Trigger (Visible to Admin/Site Manager)
            if (client.isQualified && client.allocationStatus !== 'ALLOCATED') {
                alerts.push({
                    id: `qual-${client.id}`,
                    title: 'Threshold Met: 70% Paid',
                    message: `${client.name} is qualified for allocation. Please finalize site visit.`,
                    type: 'Qualification',
                    recipientRole: 'Administrator', // Map to ADMIN in UI
                    timestamp: client.qualifiedAt || now.toISOString(),
                    isRead: false,
                    metadata: { clientId: client.id, clientName: client.name }
                });

                // 2. 48-Hour Escalation Logic
                if (client.qualifiedAt) {
                    const qualDate = new Date(client.qualifiedAt);
                    const hoursElapsed = (now.getTime() - qualDate.getTime()) / (1000 * 3600);

                    if (hoursElapsed >= 48) {
                        alerts.push({
                            id: `esc-ceo-${client.id}`,
                            title: 'URGENT: Allocation Delayed',
                            message: `Allocation for ${client.name} has been pending for ${Math.floor(hoursElapsed)} hours since qualification.`,
                            type: 'Escalation',
                            recipientRole: 'CEO',
                            timestamp: now.toISOString(),
                            isRead: false,
                            metadata: { clientId: client.id, clientName: client.name }
                        });
                    }
                }
            }
            // ... existing birthday logic ...
        });
        return alerts;
    }, [clients]);
};
```

#### `components/Layout.tsx`
```typescript
import { normalizeRole } from '../utils/roleUtils';
// ... inside useEffect for workflow_triggers ...
useEffect(() => {
    if (!user) return;

    const role = normalizeRole(user.roleId);
    // Use normalized role check
    if (role === 'CEO' || role === 'ADMIN' || role === 'CHIEF_ACCOUNTANT') {
        const q = query(collection(db, 'workflow_triggers'), where('status', '==', 'ACTIVE'));
        const unsubscribe = onSnapshot(q, (snapshot) => {
            const alerts = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setWorkflowAlerts(alerts);
        }, (err) => console.debug("Trigger listener restricted."));

        return () => unsubscribe();
    }
}, [user]);
```

---

### 3. Verification Checklist

1.  **Normalization Test**: Create a user with `roleId: "admin"` (lowercase). Confirm the `Layout.tsx` listener now initializes without permission errors.
2.  **Threshold Accuracy**: Pick a client with a 10,000 contract. Pay 6,999. Verify **no** notification appears.
3.  **Crossover Event**: Pay 1 more (Total 7,000). Verify `isQualified` becomes `true` and `qualifiedAt` is stamped in the `clients` collection.
4.  **Deterministic ID**: Check the `workflow_triggers` collection. Verify a document exists with the ID `{clientId}_CLIENT_QUALIFIED`.
5.  **Idempotency**: Post another payment for the same client. Verify no duplicate document or notification is generated.
6.  **Escalation Timing**: Manually edit a `qualifiedAt` timestamp in Firestore to be 49 hours in the past. Log in as CEO. Verify the **Escalation Alert** appears.
7.  **Escalation Cancel**: Mark the same client as `ALLOCATED`. Verify the Escalation Alert disappears from the CEO's view.
8.  **Allocation Independence**: Re-test crossover on a client already marked `ALLOCATED`. Verify they still transition to `isQualified: true` but do not trigger a new Admin alert.

### 4. Non-Regression Guarantee
*   Existing **Birthday Notifications** remain untouched.
*   The **Client Registration Form** UI and steps are identical.
*   **Payment calculations** and discount logic are preserved.
*   **Firestore Rules** were reviewed; the patch works within the current security model.
*   No changes were made to the **CEO Hub** layout or **Mailing** system.

