import { Client } from '../types';

export type WorkflowEvent = 'CLIENT_CREATED' | 'CLIENT_QUALIFIED' | 'PAYMENT_DEFAULT';

interface NotifyParams {
    event: WorkflowEvent;
    client: Client;
}

/**
 * Opaque Workflow Publisher
 * Uses deterministic document IDs to ensure idempotency and bypass 
 * collection listing permission requirements.
 */
export const dispatchWorkflowNotifications = async ({ event, client }: NotifyParams) => {
    try {
        // ID Format: {clientId}_{eventName}
        // This ensures a specific event only triggers once per client/cycle
        const triggerId = `${client.id}_${event}`;
        const triggerRef = doc(db, 'workflow_triggers', triggerId);

        // 1. Check for duplicate suppression
        if (event === 'CLIENT_QUALIFIED') {
            const existing = await getDoc(triggerRef);
            // Only block if doc exists AND the client is already marked qualified in state
            if (existing.exists() && client.isQualified) {
                return;
            }
        }

        // 2. Write Trigger doc
        await setDoc(triggerRef, {
            id: triggerId,
            event,
            clientId: client.id,
            clientName: client.name,
            clientRef: `${client.initials}-${client.id}`,
            timestamp: serverTimestamp(),
            status: 'ACTIVE',
            processedBy: []
        }, { merge: true });

        console.debug(`[Workflow] Trigger ${event} dispatched for ${client.name}`);

    } catch (e) {
        console.error("Workflow Trigger Dispatch Failure:", e);
    }
};

import { db } from './firebase';
import { collection, getDocs, doc, setDoc, query, where, limit, deleteDoc, orderBy, startAfter, QueryDocumentSnapshot, DocumentData, addDoc, updateDoc, serverTimestamp } from 'firebase/firestore';
import { Client, MilestoneRecord, RefundRecord, RefundTransaction, RefundStatus } from '../types';

const CLIENTS_COL = 'clients';
const REFUNDS_COL = 'refunds';
const REFUND_TXN_COL = 'refund_transactions';

const normalizePhone = (p: string) => p.replace(/\D/g, '').slice(-9);
const normalizeEmail = (e: string) => e.trim().toLowerCase();

// Helper to sanitize data for Firestore (handle undefined and circular refs)
const sanitizeData = (data: any, seen = new WeakSet()): any => {
    if (data === null || typeof data !== 'object') {
        return data === undefined ? null : data;
    }
    if (seen.has(data)) return "[Circular]";
    if (data instanceof Date) return data.toISOString();
    if (Array.isArray(data)) {
        seen.add(data);
        return data.map(item => sanitizeData(item, seen));
    }

    const sanitizedObj: any = {};
    seen.add(data);
    Object.keys(data).forEach(key => {
        const value = data[key];
        if (typeof value !== 'function' && value !== undefined) {
            sanitizedObj[key] = sanitizeData(value, seen);
        }
    });
    return sanitizedObj;
};

/**
 * Deterministic Merge Logic
 * Ensures no duplicates are created and handles threshold crossing atomically.
 */
export const atomicSaveClient = async (clientData: Partial<Client>): Promise<{ client: Client; event: 'CLIENT_CREATED' | 'CLIENT_UPDATED_MERGED'; changedFields: string[] }> => {
    const email = normalizeEmail(clientData.email || '');
    const phone = normalizePhone(clientData.phone || '');

    // 1. Identity Check
    const q = query(collection(db, CLIENTS_COL), where('email', '==', email), limit(1));
    const snap = await getDocs(q);
    let existing = snap.empty ? null : snap.docs[0].data() as Client;

    if (!existing && phone) {
        const q2 = query(collection(db, CLIENTS_COL), where('phone', '==', clientData.phone), limit(1));
        const snap2 = await getDocs(q2);
        if (!snap2.empty) existing = snap2.docs[0].data() as Client;
    }

    if (existing) {
        const changedFields: string[] = [];
        const merged: Client = { ...existing };

        Object.keys(clientData).forEach((key) => {
            const val = (clientData as any)[key];
            if (val !== undefined && val !== (existing as any)[key]) {
                (merged as any)[key] = val;
                changedFields.push(key);
            }
        });

        // AUTHORITY: Calculate threshold crossing atomically
        const total = merged.payment.total || 0;
        const paid = merged.payment.paid || 0;
        const paidPercent = total > 0 ? (paid / total) * 100 : 0;

        merged.paidPercent = paidPercent;

        if (paidPercent >= 70 && !existing.isQualified) {
            merged.isQualified = true;
            // Using ISO string for consistent frontend duration calculations
            merged.qualifiedAt = new Date().toISOString();
        }

        await setDoc(doc(db, CLIENTS_COL, String(merged.id)), sanitizeData(merged));
        return { client: merged, event: 'CLIENT_UPDATED_MERGED', changedFields };
    } else {
        // Create new
        const newClient = {
            ...clientData,
            isQualified: false,
            paidPercent: 0,
            status: 'Active Client'
        } as Client;
        await setDoc(doc(db, CLIENTS_COL, String(newClient.id)), sanitizeData(newClient));
        return { client: newClient, event: 'CLIENT_CREATED', changedFields: [] };
    }
};

export const fetchClientsPaginated = async (lastDoc: QueryDocumentSnapshot<DocumentData> | null, pageSize: number = 20) => {
    try {
        let q = query(collection(db, CLIENTS_COL), orderBy('id', 'desc'), limit(pageSize));
        if (lastDoc) {
            q = query(collection(db, CLIENTS_COL), orderBy('id', 'desc'), startAfter(lastDoc), limit(pageSize));
        }
        const snapshot = await getDocs(q);
        const data = snapshot.docs.map(doc => doc.data() as Client);
        const lastVisible = snapshot.docs[snapshot.docs.length - 1];
        return { data, lastDoc: lastVisible };
    } catch (error) {
        console.error("Error fetching paginated clients:", error);
        return { data: [], lastDoc: null };
    }
};

export const searchClients = async (searchTerm: string) => {
    try {
        const q = query(
            collection(db, CLIENTS_COL),
            where('name', '>=', searchTerm),
            where('name', '<=', searchTerm + '\uf8ff'),
            limit(50)
        );
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => doc.data() as Client);
    } catch (error) {
        console.error("Error searching clients:", error);
        return [];
    }
};

export const removeClient = async (id: number) => {
    await deleteDoc(doc(db, CLIENTS_COL, String(id)));
};

export const fetchMilestones = async (clientId?: number) => {
    try {
        const q = clientId 
            ? query(collection(db, 'milestones'), where('clientId', '==', clientId))
            : query(collection(db, 'milestones'));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as MilestoneRecord));
    } catch (error) {
        console.error("Error fetching milestones:", error);
        return [];
    }
};

export const persistMilestone = async (milestone: MilestoneRecord) => {
    const id = milestone.id || `MS-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    await setDoc(doc(db, 'milestones', id), sanitizeData(milestone));
};

export const fetchClients = async () => {
    const snapshot = await getDocs(collection(db, CLIENTS_COL));
    return snapshot.docs.map(doc => doc.data() as Client);
};

export const persistClient = async (client: Client) => {
    await setDoc(doc(db, CLIENTS_COL, String(client.id)), sanitizeData(client));
};

/**
 * Updates only the refundStatus field of a client.
 * Dedicated safe path that bypasses restricted field governance.
 */
export const updateClientRefundStatusInDb = async (clientId: number, refundStatus: RefundStatus) => {
    const ref = doc(db, CLIENTS_COL, String(clientId));
    await updateDoc(ref, { refundStatus });
};

// --- Refund Service Layer ---

export const persistRefundRequest = async (refund: RefundRecord) => {
    await setDoc(doc(db, REFUNDS_COL, refund.id), sanitizeData(refund));
};

export const fetchRefundRecord = async (clientId: number): Promise<RefundRecord | null> => {
    const q = query(collection(db, REFUNDS_COL), where('clientId', '==', clientId), limit(1));
    const snap = await getDocs(q);
    return snap.empty ? null : snap.docs[0].data() as RefundRecord;
};

export const persistRefundTransaction = async (txn: RefundTransaction) => {
    await setDoc(doc(db, REFUND_TXN_COL, txn.id), sanitizeData(txn));
};

export const fetchRefundTransactions = async (clientId: number): Promise<RefundTransaction[]> => {
    const q = query(collection(db, REFUND_TXN_COL), where('clientId', '==', clientId), orderBy('timestamp', 'desc'));
    const snap = await getDocs(q);
    return snap.docs.map(doc => doc.data() as RefundTransaction);
};

import { useMemo } from 'react';
import { Client, AppNotification } from '../types';
import { normalizeRole } from '../utils/roleUtils';

export const useNotificationTriggers = (clients: Client[]) => {
    const notifications = useMemo(() => {
        const alerts: AppNotification[] = [];
        const now = new Date();

        // Deterministic Accra Date Calculation
        const accraDateStr = new Intl.DateTimeFormat('en-GB', { 
            timeZone: 'Africa/Accra', 
            year: 'numeric', month: '2-digit', day: '2-digit' 
        }).format(now);

        const [day, month, year] = accraDateStr.split('/');
        const todayMonthDay = `${month}-${day}`;
        const todayFull = `${year}-${month}-${day}`;

        clients.forEach(client => {
            // --- SECTION 1: BIRTHDAY CHECK ---
            if (client.dateOfBirth) {
                try {
                    const dobParts = client.dateOfBirth.split('-');
                    if (dobParts.length === 3) {
                        const dobMonthDay = `${dobParts[1]}-${dobParts[2]}`;
                        if (dobMonthDay === todayMonthDay) {
                            alerts.push({
                                id: `bday-${client.id}-${todayFull}`,
                                title: 'Client Birthday Today 🎉',
                                message: `${client.name} is celebrating a birthday today. Please call or text to wish them a happy birthday.`,
                                type: 'Birthday',
                                recipientRole: 'ALL_USERS',
                                timestamp: now.toISOString(),
                                isRead: false,
                                metadata: { 
                                    clientId: client.id, 
                                    clientName: client.name,
                                    eventType: 'CLIENT_BIRTHDAY'
                                }
                            });
                        }
                    }
                } catch (e) {
                    console.warn(`Malformed DOB for client ${client.id}: ${client.dateOfBirth}`);
                }
            }

            // --- SECTION 2: 70% QUALIFICATION & ESCALATION ---
            const isAllocated = client.allocationStatus === 'ALLOCATED';

            if (client.isQualified && !isAllocated) {
                // Initial Qualification Alert for Administrators
                alerts.push({
                    id: `qual-init-${client.id}`,
                    title: 'Threshold Met: 70% Paid',
                    message: `${client.name} is qualified for allocation. Please finalize site visit and confirm plot assignment.`,
                    type: 'Qualification',
                    recipientRole: 'Administrator',
                    timestamp: client.qualifiedAt || now.toISOString(),
                    isRead: false,
                    metadata: { 
                        clientId: client.id, 
                        clientName: client.name, 
                        eventType: 'ALLOCATION_70_PERCENT_QUALIFIED' 
                    }
                });

                // 48-Hour Escalation Logic for CEO
                if (client.qualifiedAt) {
                    const qualDate = new Date(client.qualifiedAt);
                    const hoursElapsed = (now.getTime() - qualDate.getTime()) / (1000 * 3600);

                    if (hoursElapsed >= 48) {
                        alerts.push({
                            id: `qual-esc-ceo-${client.id}`,
                            title: 'URGENT: Allocation Delayed',
                            message: `Allocation for ${client.name} has been pending for ${Math.floor(hoursElapsed)} hours since meeting the 70% threshold.`,
                            type: 'Escalation',
                            recipientRole: 'CEO',
                            timestamp: now.toISOString(),
                            isRead: false,
                            metadata: { 
                                clientId: client.id, 
                                clientName: client.name, 
                                qualifiedAt: client.qualifiedAt,
                                eventType: 'ALLOCATION_NOT_DONE_48H' 
                            }
                        });
                    }
                }
            }

            // --- SECTION 3: DEFAULT ESCALATION ---
            const lastPaymentDate = client.payment.paymentHistory.length > 0 
                ? new Date(client.payment.paymentHistory[client.payment.paymentHistory.length - 1].date)
                : new Date(client.regDate);
            const monthsSinceLastPayment = (now.getTime() - lastPaymentDate.getTime()) / (1000 * 60 * 60 * 24 * 30);

            if (monthsSinceLastPayment >= 3 && client.payment.balance > 0) {
                alerts.push({
                    id: `def-esc-acc-${client.id}`,
                    title: 'Payment Default Escalation',
                    message: `${client.name} has defaulted for 3 months. Review required.`,
                    type: 'Default',
                    recipientRole: 'Chief Accountant',
                    timestamp: now.toISOString(),
                    isRead: false,
                    metadata: { clientId: client.id, clientName: client.name }
                });
            }
        });

        return alerts;
    }, [clients]);

    return notifications;
};

export type NormalizedRole = 'CEO' | 'ADMIN' | 'CHIEF_ACCOUNTANT' | 'SITE_MANAGER' | 'FRONT_DESK' | 'SALES_HEAD' | 'SALES_REP' | 'UNKNOWN';

export const normalizeRole = (roleId: string | undefined): NormalizedRole => {
    if (!roleId) return 'UNKNOWN';
    const r = roleId.toUpperCase().trim();
    if (r === 'CEO') return 'CEO';
    if (r === 'ADMINISTRATOR' || r === 'ADMIN') return 'ADMIN';
    if (r === 'CHIEF ACCOUNTANT' || r === 'CHIEF_ACCOUNTANT') return 'CHIEF_ACCOUNTANT';
    if (r === 'SITE MANAGER' || r === 'SITE_MANAGER') return 'SITE_MANAGER';
    if (r === 'FRONT DESK EXECUTIVE' || r === 'FRONT DESK' || r === 'FRONT_DESK') return 'FRONT_DESK';
    if (r === 'HEAD OF SALES' || r === 'HEAD_OF_SALES') return 'SALES_HEAD';
    if (r === 'SALES REPRESENTATIVE' || r === 'SALES_REP') return 'SALES_REP';
    return 'UNKNOWN';
};

