rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- Governance Helper Functions ---

    function isUserAuthenticated() {
      return request.auth != null;
    }

    function getUserData() {
      return get(/databases/$(database)/documents/user/$(request.auth.uid)).data;
    }

    function getRole() {
      return isUserAuthenticated() ? getUserData().roleId : null;
    }

    function isCEO() {
      return isUserAuthenticated() && getRole() == 'CEO';
    }

    function isChiefAccountant() {
      return isUserAuthenticated() && getRole() == 'Chief Accountant';
    }

    function isAdmin() {
      return isUserAuthenticated() && (getRole() == 'Administrator' || getRole() == 'Administrator');
    }

    // --- Directory & Profile Isolation ---

    match /user/{userId} {
      allow get: if isUserAuthenticated() && request.auth.uid == userId;
      allow list, get: if isCEO() || isAdmin();
      allow create: if isCEO(); 
      allow update: if isUserAuthenticated() && (request.auth.uid == userId || isCEO());
      allow delete: if isCEO();
    }

    match /role_permissions/{roleId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO();
    }

    // --- Operational Collections ---

    match /refunds/{refundId} {
        allow read: if isUserAuthenticated();
        allow write: if isCEO() || isChiefAccountant();
    }

    match /refund_transactions/{txnId} {
        allow read: if isUserAuthenticated();
        allow create: if isCEO() || isChiefAccountant();
        allow update, delete: if isCEO();
    }

    match /workflow_triggers/{triggerId} {
      // Permission Fix: Allow individual 'get' for dispatch logic verification.
      // Keep 'list' restricted to governance roles.
      allow get: if isUserAuthenticated();
      allow list: if isUserAuthenticated() && (isCEO() || isAdmin() || isChiefAccountant());
      allow create: if isUserAuthenticated();
      allow update, delete: if isCEO();
    }

    match /activity_logs/{logId} {
      allow read: if isUserAuthenticated() && (isCEO() || isAdmin() || isChiefAccountant());
      allow create: if isUserAuthenticated();
      allow update, delete: if isCEO();
    }

    match /clients/{clientId} {
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated();
      allow update: if isCEO() || isChiefAccountant() || isAdmin() || getRole() == 'Front Desk Executive';
      allow delete: if isCEO();
    }

    match /milestones/{docId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO() || isChiefAccountant() || isAdmin();
    }

    match /leads/{leadId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO() || isAdmin() || getRole() == 'Head of Sales' || getRole() == 'Sales Representative';
    }

    match /properties/{propId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO() || isAdmin();
    }

    match /invoices/{invId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO() || isChiefAccountant();
    }

    match /promotions/{promoId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO() || isAdmin();
    }

    match /amendments/{docId} {
      allow read: if isUserAuthenticated();
      allow create: if isUserAuthenticated();
      allow update, delete: if isCEO(); 
    }

    match /internal_mails/{mailId} {
      allow read: if isUserAuthenticated() && (isCEO() || request.auth.uid in resource.data.participants);
      allow create: if isUserAuthenticated();
      allow update: if isUserAuthenticated() && request.auth.uid in resource.data.participants;
    }

    // --- Messaging & System Conduit ---

    match /messaging_templates/{docId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO() || isAdmin();
    }

    match /messaging_history/{docId} {
      allow read: if isUserAuthenticated() && (isCEO() || isAdmin());
      allow create: if isUserAuthenticated();
    }

    match /messaging_client_preferences/{docId} {
      allow read, write: if isUserAuthenticated();
    }

    match /sms_logs/{docId} {
      allow read: if isCEO();
      allow create: if isUserAuthenticated();
    }

    match /settings/{docId} {
      allow read: if isUserAuthenticated();
      allow write: if isCEO();
    }

    match /{path=**} {
      allow read, write: if isCEO();
    }
  }
}

import { db } from './firebase';
import { doc, setDoc, getDoc, serverTimestamp } from 'firebase/firestore';
import { Client } from '../types';

export type WorkflowEvent = 'CLIENT_CREATED' | 'CLIENT_QUALIFIED' | 'PAYMENT_DEFAULT';

interface NotifyParams {
    event: WorkflowEvent;
    client: Client;
}

/**
 * Opaque Workflow Publisher
 * Uses deterministic document IDs to ensure idempotency and bypass 
 * collection listing permission requirements.
 */
export const dispatchWorkflowNotifications = async ({ event, client }: NotifyParams) => {
    try {
        // ID Format: {clientId}_{eventName}
        // This ensures a specific event only triggers once per client/cycle
        const triggerId = `${client.id}_${event}`;
        const triggerRef = doc(db, 'workflow_triggers', triggerId);

        // Deterministic Duplication Check:
        // Use getDoc instead of getDocs/query to avoid "Missing Permissions" for non-admin roles
        const existing = await getDoc(triggerRef);

        // Qualification Rule: Fire only if not already qualified in current context
        if (event === 'CLIENT_QUALIFIED' && existing.exists() && client.isQualified) {
            return;
        }

        // Creation Rule: Fire only once
        if (event === 'CLIENT_CREATED' && existing.exists()) {
            return;
        }

        // Calculation of escalation window (48 hours)
        const now = new Date();
        const dueAt = new Date(now.getTime() + 48 * 60 * 60 * 1000);

        await setDoc(triggerRef, {
            id: triggerId,
            event,
            clientId: client.id,
            clientName: client.name,
            clientRef: `${client.initials}-${client.id}`,
            timestamp: serverTimestamp(),
            status: 'ACTIVE',
            // Metadata for escalation logic
            qualifiedAt: event === 'CLIENT_QUALIFIED' ? serverTimestamp() : null,
            escalationDueAt: event === 'CLIENT_QUALIFIED' ? dueAt.toISOString() : null,
            escalatedAt: null,
            allocationCompletedAt: client.allocationStatus === 'ALLOCATED' ? serverTimestamp() : null,
            processedBy: []
        }, { merge: true });

        console.debug(`[Workflow] Trigger ${event} dispatched for ${client.name}`);

    } catch (e) {
        console.error("Workflow Trigger Dispatch Failure:", e);
    }
};

import { db } from './firebase';
import { collection, getDocs, doc, setDoc, query, where, limit, deleteDoc, orderBy, startAfter, QueryDocumentSnapshot, DocumentData, addDoc, updateDoc, serverTimestamp } from 'firebase/firestore';
import { Client, MilestoneRecord, RefundRecord, RefundTransaction, RefundStatus } from '../types';

const CLIENTS_COL = 'clients';
const REFUNDS_COL = 'refunds';
const REFUND_TXN_COL = 'refund_transactions';

const normalizePhone = (p: string) => p.replace(/\D/g, '').slice(-9);
const normalizeEmail = (e: string) => e.trim().toLowerCase();

// Helper to sanitize data for Firestore (handle undefined and circular refs)
const sanitizeData = (data: any, seen = new WeakSet()): any => {
    if (data === null || typeof data !== 'object') {
        return data === undefined ? null : data;
    }
    if (seen.has(data)) return "[Circular]";
    if (data instanceof Date) return data.toISOString();
    if (Array.isArray(data)) {
        seen.add(data);
        return data.map(item => sanitizeData(item, seen));
    }

    const sanitizedObj: any = {};
    seen.add(data);
    Object.keys(data).forEach(key => {
        const value = data[key];
        if (typeof value !== 'function' && value !== undefined) {
            sanitizedObj[key] = sanitizeData(value, seen);
        }
    });
    return sanitizedObj;
};

/**
 * Deterministic Merge Logic
 * Ensures no duplicates are created and handles threshold crossing atomically.
 */
export const atomicSaveClient = async (clientData: Partial<Client>): Promise<{ client: Client; event: 'CLIENT_CREATED' | 'CLIENT_UPDATED_MERGED'; changedFields: string[] }> => {
    const email = normalizeEmail(clientData.email || '');
    const phone = normalizePhone(clientData.phone || '');

    // 1. Identity Check
    const q = query(collection(db, CLIENTS_COL), where('email', '==', email), limit(1));
    const snap = await getDocs(q);
    let existing = snap.empty ? null : snap.docs[0].data() as Client;

    if (!existing && phone) {
        const q2 = query(collection(db, CLIENTS_COL), where('phone', '==', clientData.phone), limit(1));
        const snap2 = await getDocs(q2);
        if (!snap2.empty) existing = snap2.docs[0].data() as Client;
    }

    if (existing) {
        const changedFields: string[] = [];
        const merged: Client = { ...existing };

        Object.keys(clientData).forEach((key) => {
            const val = (clientData as any)[key];
            if (val !== undefined && val !== (existing as any)[key]) {
                (merged as any)[key] = val;
                changedFields.push(key);
            }
        });

        // AUTHORITY: Calculate threshold crossing atomically using latest totals
        const total = merged.payment.total || 0;
        const paid = merged.payment.paid || 0;
        const paidPercent = total > 0 ? (paid / total) * 100 : 0;

        const wasQualified = !!existing.isQualified;
        const isNowQualified = paidPercent >= 70;

        merged.paidPercent = paidPercent;

        // Transition Detection
        if (isNowQualified && !wasQualified) {
            merged.isQualified = true;
            merged.qualifiedAt = new Date().toISOString();
        } else if (!isNowQualified && wasQualified) {
            // Optional: Support reversal if payment is deleted/rolled back
            merged.isQualified = false;
            merged.qualifiedAt = undefined;
        }

        // Completion Sync
        if (merged.allocationStatus === 'ALLOCATED' && existing.allocationStatus !== 'ALLOCATED') {
            merged.status = 'Active Client'; // Or specific 'Allocated' status if supported
        }

        await setDoc(doc(db, CLIENTS_COL, String(merged.id)), sanitizeData(merged));
        return { client: merged, event: 'CLIENT_UPDATED_MERGED', changedFields };
    } else {
        // Create new
        const newClient = {
            ...clientData,
            isQualified: false,
            paidPercent: 0,
            status: 'Active Client'
        } as Client;
        await setDoc(doc(db, CLIENTS_COL, String(newClient.id)), sanitizeData(newClient));
        return { client: newClient, event: 'CLIENT_CREATED', changedFields: [] };
    }
};

export const fetchClientsPaginated = async (lastDoc: QueryDocumentSnapshot<DocumentData> | null, pageSize: number = 20) => {
    try {
        let q = query(collection(db, CLIENTS_COL), orderBy('id', 'desc'), limit(pageSize));
        if (lastDoc) {
            q = query(collection(db, CLIENTS_COL), orderBy('id', 'desc'), startAfter(lastDoc), limit(pageSize));
        }
        const snapshot = await getDocs(q);
        const data = snapshot.docs.map(doc => doc.data() as Client);
        const lastVisible = snapshot.docs[snapshot.docs.length - 1];
        return { data, lastDoc: lastVisible };
    } catch (error) {
        console.error("Error fetching paginated clients:", error);
        return { data: [], lastDoc: null };
    }
};

