import { db } from './firebase';
import { collection, doc, runTransaction, serverTimestamp, addDoc } from 'firebase/firestore';
import { Client, PaymentTransaction, Invoice } from '../types';

const CLIENTS_COL = 'clients';
const AUDIT_COL = 'workflow_audit';
const TRIGGERS_COL = 'workflow_triggers';

/**
 * Authoritative Payment & Workflow Transaction
 * Handles: Payment Write -> Client Update -> 70% Detection -> Notification Dispatch -> Audit Log
 */
export const recordPaymentAtomic = async (
    clientId: number, 
    paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: string },
    operatorName: string
) => {
    const auditData: any = {
        clientId,
        postedAmount: paymentData.amount,
        createdAt: new Date().toISOString(),
        triggerAttempted: false,
        triggerWritten: false,
        notificationWritten: false,
        errorStage: null,
        errorMessage: null
    };

    try {
        await runTransaction(db, async (transaction) => {
            const clientRef = doc(db, CLIENTS_COL, String(clientId));
            const clientSnap = await transaction.get(clientRef);

            if (!clientSnap.exists()) {
                throw new Error("CLIENT_NOT_FOUND");
            }

            const client = clientSnap.data() as Client;

            // 1. Authoritative Calculations
            const contractNet = client.payment.total || 0;
            const previousTotalPaid = client.payment.paid || 0;
            const newTotalPaid = previousTotalPaid + paymentData.amount;
            const paidPercent = contractNet > 0 ? (newTotalPaid / contractNet) * 100 : 0;

            const prevQualified = !!client.isQualified;
            const newQualified = paidPercent >= 70;
            const thresholdCrossing = newQualified && !prevQualified;

            auditData.contractNet = contractNet;
            auditData.previousTotalPaid = previousTotalPaid;
            auditData.newTotalPaid = newTotalPaid;
            auditData.paidPercent = paidPercent;
            auditData.prevQualified = prevQualified;
            auditData.newQualified = newQualified;

            // 2. Write Payment Transaction
            const txnId = `TXN-${Date.now()}`;
            const txnRef = doc(collection(db, `clients/${clientId}/payments`)); // Subcollection if used, or just metadata

            // 3. Update Client Record
            const clientUpdates: any = {
                'payment.paid': newTotalPaid,
                'payment.balance': contractNet - newTotalPaid,
                'paidPercent': paidPercent,
                'payment.paymentHistory': [...(client.payment.paymentHistory || []), { ...paymentData, id: txnId, status: 'Success' }]
            };

            if (thresholdCrossing) {
                clientUpdates.isQualified = true;
                clientUpdates.qualifiedAt = new Date().toISOString();
                auditData.triggerAttempted = true;
            }

            transaction.update(clientRef, clientUpdates);

            // 4. Handle Workflow Trigger (Deterministic ID)
            if (thresholdCrossing) {
                const triggerId = `${clientId}_CLIENT_QUALIFIED`;
                const triggerRef = doc(db, TRIGGERS_COL, triggerId);

                transaction.set(triggerRef, {
                    id: triggerId,
                    event: 'CLIENT_QUALIFIED',
                    clientId: client.id,
                    clientName: client.name,
                    clientRef: `${client.initials}-${client.id}`,
                    timestamp: serverTimestamp(),
                    status: 'ACTIVE',
                    qualifiedAt: clientUpdates.qualifiedAt,
                    processedBy: []
                }, { merge: true });

                auditData.triggerWritten = true;
                auditData.notificationWritten = true; // Trigger doc serves as notification source
            }
        });

        // 5. Success Audit
        await addDoc(collection(db, AUDIT_COL), { ...auditData, status: 'SUCCESS' });
        return { success: true };

    } catch (error: any) {
        console.error("[Transaction Failed]", error);
        // 6. Failure Audit (Flight Recorder)
        await addDoc(collection(db, AUDIT_COL), { 
            ...auditData, 
            status: 'FAILED', 
            errorStage: auditData.triggerAttempted ? "TRIGGER_WRITE" : "PAYMENT_WRITE",
            errorMessage: error.message?.substring(0, 200)
        });
        throw error;
    }
};

