import { db } from './firebase';
import { collection, doc, runTransaction, serverTimestamp, addDoc } from 'firebase/firestore';
import { Client, PaymentTransaction, Invoice } from '../types';

const CLIENTS_COL = 'clients';
const AUDIT_COL = 'workflow_audit';
const TRIGGERS_COL = 'workflow_triggers';

/**
 * Authoritative Payment & Workflow Transaction
 * Handles: Payment Write -> 70% Qualification Check -> Workflow Trigger -> Audit Log
 */
export const recordPaymentAtomic = async (
    clientId: number, 
    paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: string },
    operatorName: string
) => {
    const auditData: any = {
        clientId,
        postedAmount: paymentData.amount,
        createdAt: new Date().toISOString(),
        triggerAttempted: false,
        triggerWritten: false,
        errorStage: null,
        errorMessage: null
    };

    try {
        await runTransaction(db, async (transaction) => {
            const clientRef = doc(db, CLIENTS_COL, String(clientId));
            const clientSnap = await transaction.get(clientRef);

            if (!clientSnap.exists()) {
                throw new Error("CLIENT_NOT_FOUND");
            }

            const client = clientSnap.data() as Client;
            const contractTotal = client.payment.total || 0;

            // Guard: Null or Zero contract total
            if (contractTotal <= 0) {
                transaction.update(clientRef, {
                    'payment.paid': (client.payment.paid || 0) + paymentData.amount,
                    'payment.balance': contractTotal - ((client.payment.paid || 0) + paymentData.amount),
                    'payment.paymentHistory': [...(client.payment.paymentHistory || []), { ...paymentData, id: `TXN-${Date.now()}`, status: 'POSTED' }]
                });
                return;
            }

            // 1. Authoritative Sum Calculation (Only POSTED or CONFIRMED)
            // FIX: Reconciled status comparison with the expanded PaymentTransaction status union to resolve overlap errors.
            const sumPosted = (client.payment.paymentHistory || [])
                .filter(p => p.status === 'POSTED' || p.status === 'CONFIRMED' || p.status === 'Success')
                .reduce((sum, p) => sum + p.amount, 0);

            const newTotalPosted = sumPosted + paymentData.amount;
            const qualificationThreshold = contractTotal * 0.70;

            const isCrossingThreshold = newTotalPosted >= qualificationThreshold && !client.hasQualified70;

            auditData.contractTotal = contractTotal;
            auditData.totalPosted = newTotalPosted;
            auditData.isCrossing = isCrossingThreshold;

            // 2. Prepare Updates
            const txnId = `TXN-${Date.now()}`;
            const clientUpdates: any = {
                'payment.paid': (client.payment.paid || 0) + paymentData.amount,
                'payment.balance': contractTotal - ((client.payment.paid || 0) + paymentData.amount),
                'paidPercent': (newTotalPosted / contractTotal) * 100,
                'payment.paymentHistory': [...(client.payment.paymentHistory || []), { ...paymentData, id: txnId, status: 'POSTED' }]
            };

            // 3. Deterministic Qualification State
            if (isCrossingThreshold) {
                clientUpdates.hasQualified70 = true;
                clientUpdates.qualificationDate = new Date().toISOString();
                clientUpdates.isQualified = true; // Sync for backward compatibility
                clientUpdates.qualifiedAt = clientUpdates.qualificationDate;
                auditData.triggerAttempted = true;

                // 4. Single Event Trigger for Administrator
                const triggerId = `${clientId}_CLIENT_QUALIFIED`;
                const triggerRef = doc(db, TRIGGERS_COL, triggerId);

                transaction.set(triggerRef, {
                    id: triggerId,
                    event: 'CLIENT_QUALIFIED',
                    clientId: client.id,
                    clientName: client.name,
                    clientRef: `${client.initials}-${client.id}`,
                    timestamp: serverTimestamp(),
                    status: 'ACTIVE',
                    recipientRole: 'Administrator', // Target Restriction
                    message: "Client qualifies for allocation.",
                    processedBy: []
                }, { merge: true });

                auditData.triggerWritten = true;
            }

            transaction.update(clientRef, clientUpdates);
        });

        await addDoc(collection(db, AUDIT_COL), { ...auditData, status: 'SUCCESS' });
        return { success: true };

    } catch (error: any) {
        await addDoc(collection(db, AUDIT_COL), { 
            ...auditData, 
            status: 'FAILED', 
            errorStage: auditData.triggerAttempted ? "TRIGGER_WRITE" : "PAYMENT_WRITE",
            errorMessage: error.message?.substring(0, 200)
        });
        throw error;
    }
};

